import React, { useState, useEffect, useMemo } from 'react';
import { Grade, Term, LessonDefinition, LessonPlanData, Subject, UserProfile } from '../types';
import { SCHEMES_OF_WORK } from '../data/maths';
import { PRETECH_SCHEMES } from '../data/pretech';
import { CREATIVE_ARTS_SCHEMES } from '../data/creative_arts';
import { CRE_SCHEMES } from '../data/cre';
import { INTEGRATED_SCIENCE_SCHEMES } from '../data/integrated_science';
import { SCIENCE_TECHNOLOGY_SCHEMES } from '../data/science_technology';
import { SOCIAL_STUDIES_SCHEMES } from '../data/social_studies';
import { AGRICULTURE_NUTRITION_SCHEMES } from '../data/agriculture_nutrition';
import { ENGLISH_SCHEMES } from '../data/english';
import { KISWAHILI_SCHEMES } from '../data/kiswahili';
import { generateLessonPlan, generateSimplifiedNotes, generatePracticeQuestions } from '../services/geminiService';
import { savePlan } from '../services/storageService';
import { Loader2, BookOpen, AlertCircle, Upload, Paperclip, X } from 'lucide-react';

interface Props {
  userProfile?: UserProfile | null;
  onPlanGenerated: (data: LessonPlanData) => void;
}

const LessonGenerator: React.FC<Props> = ({ userProfile, onPlanGenerated }) => {
  const [formData, setFormData] = useState({
    teacherName: userProfile?.name || '',
    schoolName: userProfile?.school || '',
    date: new Date().toISOString().split('T')[0],
    grade: Grade.GRADE_7,
    term: Term.TERM_1,
    roll: 40,
    subject: Subject.MATHEMATICS,
    customContext: '',
    images: [] as string[] // Array of base64 strings
  });

  // Effect to update form if profile changes (e.g. from dashboard)
  useEffect(() => {
    if (userProfile) {
        setFormData(prev => ({
            ...prev,
            teacherName: userProfile.name,
            schoolName: userProfile.school
        }));
    }
  }, [userProfile]);

  const [selectedStrand, setSelectedStrand] = useState<string>('');
  const [selectedSubStrand, setSelectedSubStrand] = useState<string>('');
  const [selectedLesson, setSelectedLesson] = useState<LessonDefinition | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Derived data based on Grade and Subject selection
  const gradeData = useMemo(() => {
    if (formData.subject === Subject.MATHEMATICS) {
      return SCHEMES_OF_WORK[formData.grade] || [];
    } else if (formData.subject === Subject.PRETECHNICAL_STUDIES) {
      return PRETECH_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.CREATIVE_ARTS) {
      return CREATIVE_ARTS_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.CHRISTIAN_RELIGIOUS_EDUCATION) {
      return CRE_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.INTEGRATED_SCIENCE) {
      return INTEGRATED_SCIENCE_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.SCIENCE_AND_TECHNOLOGY) {
      return SCIENCE_TECHNOLOGY_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.SOCIAL_STUDIES) {
      return SOCIAL_STUDIES_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.AGRICULTURE_AND_NUTRITION) {
      return AGRICULTURE_NUTRITION_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.ENGLISH) {
      return ENGLISH_SCHEMES[formData.grade] || [];
    } else if (formData.subject === Subject.KISWAHILI) {
      return KISWAHILI_SCHEMES[formData.grade] || [];
    }
    return [];
  }, [formData.grade, formData.subject]);

  const strands = useMemo(() => {
    return Array.from(new Set(gradeData.map(l => l.strand)));
  }, [gradeData]);

  const subStrands = useMemo(() => {
    return Array.from(new Set(gradeData.filter(l => l.strand === selectedStrand).map(l => l.subStrand)));
  }, [gradeData, selectedStrand]);

  const lessons = useMemo(() => {
    return gradeData.filter(l => l.strand === selectedStrand && l.subStrand === selectedSubStrand);
  }, [gradeData, selectedStrand, selectedSubStrand]);

  // Reset downstream selections when upstream changes
  useEffect(() => { setSelectedStrand(''); setSelectedSubStrand(''); setSelectedLesson(null); }, [formData.grade, formData.subject]);
  useEffect(() => { setSelectedSubStrand(''); setSelectedLesson(null); }, [selectedStrand]);
  useEffect(() => { setSelectedLesson(null); }, [selectedSubStrand]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files) {
          if (formData.images.length + files.length > 5) {
              alert("You can upload a maximum of 5 images.");
              return;
          }

          Array.from(files).forEach((file: File) => {
              const reader = new FileReader();
              reader.onloadend = () => {
                  if (typeof reader.result === 'string') {
                      setFormData(prev => ({ ...prev, images: [...prev.images, reader.result as string] }));
                  }
              };
              reader.readAsDataURL(file);
          });
      }
  };

  const removeImage = (index: number) => {
      setFormData(prev => ({
          ...prev,
          images: prev.images.filter((_, i) => i !== index)
      }));
  };

  const cleanTopic = (topic: string) => topic.replace(/^Lesson \d+:\s*/i, '');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedLesson) {
        setError("Please select a specific lesson.");
        return;
    }
    setError(null);
    setLoading(true);

    try {
      const cleanLessonDef = { ...selectedLesson, topic: cleanTopic(selectedLesson.topic) };

      // 1. Generate Base Plan
      const plan = await generateLessonPlan(formData, cleanLessonDef);

      // 2. Generate Notes (500 words) and Questions in parallel
      const [notes, questions] = await Promise.all([
          generateSimplifiedNotes(plan, 500),
          generatePracticeQuestions(plan)
      ]);

      // Add ID, timestamp, notes and questions
      const completePlan = {
        ...plan,
        learnerNotes: notes,
        structuredQuestions: questions,
        topic: cleanTopic(plan.topic), // Ensure topic is clean in final plan too
        id: crypto.randomUUID(),
        createdAt: new Date().toISOString()
      };

      // Automatically save if user is logged in
      if (userProfile) {
        try {
          savePlan(completePlan);
        } catch (saveError) {
          console.error("Auto-save failed:", saveError);
        }
      }

      onPlanGenerated(completePlan);
    } catch (err: any) {
      setError(err.message || "An error occurred generating the plan.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-md border border-gray-200 overflow-hidden no-print">
      <div className="bg-gray-50 px-6 py-4 border-b border-gray-200 flex items-center gap-2">
        <BookOpen className="text-teal-600 w-5 h-5" />
        <h2 className="text-lg font-semibold text-gray-800">Lesson Plan Generator</h2>
      </div>

      <form onSubmit={handleSubmit} className="p-6 md:p-8 space-y-8">

        {/* Top Table-like Section */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-6">

            {/* Teacher & School */}
            <div className="space-y-4">
                <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">Teacher</label>
                    <input 
                        required
                        type="text" 
                        value={formData.teacherName}
                        onChange={e => setFormData({...formData, teacherName: e.target.value})}
                        className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border bg-gray-50"
                        placeholder="Enter Name"
                    />
                </div>
                <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">School</label>
                    <input 
                        required
                        type="text" 
                        value={formData.schoolName}
                        onChange={e => setFormData({...formData, schoolName: e.target.value})}
                        className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border bg-gray-50"
                        placeholder="Enter School"
                    />
                </div>
            </div>

            {/* Date, Subject, Time */}
            <div className="space-y-4">
                 <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">Date</label>
                    <input 
                        type="date" 
                        value={formData.date}
                        onChange={e => setFormData({...formData, date: e.target.value})}
                        className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                    />
                </div>
                 <div className="flex flex-col md:flex-row md:items-center gap-2">
                    <label className="text-sm font-medium text-gray-600 w-24">Subject</label>
                    <select 
                        value={formData.subject}
                        onChange={e => setFormData({...formData, subject: e.target.value as Subject})}
                        className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                    >
                        {Object.values(Subject).map(s => <option key={s} value={s}>{s}</option>)}
                    </select>
                </div>
            </div>
        </div>

        {/* Separator */}
        <div className="h-px bg-gray-200 w-full"></div>

        {/* Class Details Grid */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
            <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Grade</label>
                <select 
                    value={formData.grade}
                    onChange={e => setFormData({...formData, grade: e.target.value as Grade})}
                    className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                >
                    {Object.values(Grade).map(g => <option key={g} value={g}>{g}</option>)}
                </select>
            </div>
            <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Term</label>
                <select 
                    value={formData.term}
                    onChange={e => setFormData({...formData, term: e.target.value as Term})}
                    className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                >
                    {Object.values(Term).map(t => <option key={t} value={t}>{t}</option>)}
                </select>
            </div>
             <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Roll (Class Size)</label>
                <input 
                    type="number"
                    value={formData.roll}
                    onChange={e => setFormData({...formData, roll: parseInt(e.target.value)})}
                    className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border"
                />
            </div>
            <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Time</label>
                <div className="w-full py-2 px-3 bg-gray-100 rounded-md text-gray-700 border border-gray-200">
                    40 Minutes
                </div>
            </div>
        </div>

        {/* Cascading Content Selection */}
        <div className="bg-teal-50 p-6 rounded-lg border border-teal-100 space-y-6">
            <h3 className="text-teal-800 font-medium border-b border-teal-200 pb-2">Curriculum Content Selector</h3>

            {gradeData.length === 0 ? (
                <div className="text-center text-gray-500 py-4">No lesson data available for {formData.subject} - {formData.grade}</div>
            ) : (
                <>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                            <label className="block text-sm font-medium text-teal-800 mb-2">Select Strand</label>
                            <select 
                                value={selectedStrand}
                                onChange={e => setSelectedStrand(e.target.value)}
                                className="w-full rounded-md border-teal-200 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 px-3 border bg-white"
                                disabled={strands.length === 0}
                            >
                                <option value="">-- Choose Strand --</option>
                                {strands.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-teal-800 mb-2">Select Sub-strand</label>
                            <select 
                                value={selectedSubStrand}
                                onChange={e => setSelectedSubStrand(e.target.value)}
                                className="w-full rounded-md border-teal-200 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 px-3 border bg-white"
                                disabled={!selectedStrand}
                            >
                                <option value="">-- Choose Sub-strand --</option>
                                {subStrands.map(ss => <option key={ss} value={ss}>{ss}</option>)}
                            </select>
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-teal-800 mb-2">Select Lesson</label>
                        <select 
                            value={selectedLesson ? JSON.stringify(selectedLesson) : ""}
                            onChange={e => {
                                if(e.target.value) setSelectedLesson(JSON.parse(e.target.value));
                            }}
                            className="w-full rounded-md border-teal-200 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 px-3 border bg-white"
                            disabled={!selectedSubStrand}
                        >
                            <option value="">-- Choose Lesson --</option>
                            {lessons.map((l, idx) => (
                                <option key={idx} value={JSON.stringify(l)}>{cleanTopic(l.topic)}</option>
                            ))}
                        </select>
                    </div>

                    {selectedLesson && (
                        <div className="mt-4 p-4 bg-white/60 rounded border border-teal-200 text-sm text-teal-900">
                            <p><strong>Preview Learning Outcome:</strong> {selectedLesson.learningOutcomes[0]}</p>
                        </div>
                    )}
                </>
            )}
        </div>

        {/* Custom Context & Resources */}
        <div className="border border-gray-200 rounded-lg p-6 bg-gray-50">
            <h3 className="text-gray-800 font-medium mb-4 flex items-center gap-2">
                <Paperclip className="w-4 h-4 text-gray-500" />
                Additional Context & Resources (Optional)
            </h3>

            <div className="space-y-4">
                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Teacher Notes / Custom Context</label>
                    <textarea 
                        className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 p-3 text-sm"
                        rows={3}
                        placeholder="Paste any specific notes, classroom context, or additional requirements here..."
                        value={formData.customContext}
                        onChange={(e) => setFormData({...formData, customContext: e.target.value})}
                    ></textarea>
                </div>

                <div>
                    <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Upload Photos (Max 5)</label>
                    <div className="flex items-center gap-4">
                        <label className="cursor-pointer bg-white border border-gray-300 hover:bg-gray-50 px-4 py-2 rounded-md shadow-sm text-sm font-medium text-gray-700 flex items-center gap-2 transition-colors">
                            <Upload className="w-4 h-4" />
                            Select Images
                            <input 
                                type="file" 
                                accept="image/*" 
                                multiple 
                                className="hidden" 
                                onChange={handleImageUpload}
                                disabled={formData.images.length >= 5}
                            />
                        </label>
                        <span className="text-xs text-gray-500">{formData.images.length} / 5 uploaded</span>
                    </div>

                    {formData.images.length > 0 && (
                        <div className="flex gap-2 mt-3 overflow-x-auto pb-2">
                            {formData.images.map((img, idx) => (
                                <div key={idx} className="relative w-16 h-16 shrink-0 border border-gray-200 rounded-md overflow-hidden group">
                                    <img src={img} alt={`Upload ${idx+1}`} className="w-full h-full object-cover" />
                                    <button 
                                        type="button"
                                        onClick={() => removeImage(idx)}
                                        className="absolute top-0 right-0 bg-red-500 text-white p-0.5 rounded-bl opacity-0 group-hover:opacity-100 transition-opacity"
                                    >
                                        <X className="w-3 h-3" />
                                    </button>
                                </div>
                            ))}
                        </div>
                    )}
                </div>
            </div>
        </div>

        {error && (
            <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded flex items-center gap-3">
                <AlertCircle className="text-red-500" />
                <p className="text-red-700">{error}</p>
            </div>
        )}

        {/* Actions */}
        <div className="flex gap-4 pt-2">
            <button 
                type="button" 
                className="px-6 py-3 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-500"
                onClick={() => {
                   setFormData({...formData, teacherName: '', schoolName: '', customContext: '', images: []});
                   setSelectedStrand('');
                }}
            >
                Reset Form
            </button>
            <button 
                type="submit" 
                disabled={loading || !selectedLesson}
                className="flex-1 flex justify-center items-center gap-2 px-6 py-3 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-teal-600 hover:bg-teal-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-500 disabled:opacity-50 disabled:cursor-not-allowed transition-all"
            >
                {loading ? (
                    <>
                        <Loader2 className="animate-spin h-5 w-5" />
                        Generating Plan, Notes & Quiz...
                    </>
                ) : (
                    "Generate Lesson Plan"
                )}
            </button>
        </div>

      </form>
    </div>
  );
};

export default LessonGenerator;

import React, { useRef, useState, useEffect } from 'react';
import { LessonPlanData, Classroom, Assignment, SharedNote, QuizQuestion } from '../types';
import { Printer, Download, ArrowLeft, FileText, HelpCircle, Loader2, Save, Layout, Lock, Link, X, Copy, Check, Send, Share2, Upload, Plus, Image, RefreshCw } from 'lucide-react';
import { generateSimplifiedNotes, generatePracticeQuestions, generateStructuredQuestions } from '../services/geminiService';
import { savePlan, getCurrentUser, getClassrooms, saveAssignment, shareNoteToClassroom } from '../services/storageService';

interface Props {
  plan: LessonPlanData;
  onBack: () => void;
}

const LessonPlanDisplay: React.FC<Props> = ({ plan, onBack }) => {
  const componentRef = useRef<HTMLDivElement>(null);

  const [currentPlan, setCurrentPlan] = useState<LessonPlanData>(plan);
  const [activeTab, setActiveTab] = useState<'plan' | 'notes' | 'questions'>('plan');

  const [loadingNotes, setLoadingNotes] = useState(false);
  const [loadingQuestions, setLoadingQuestions] = useState(false);

  const [isGuest, setIsGuest] = useState(false);

  // Notes Configuration
  const [noteWordCount, setNoteWordCount] = useState<number>(500); // Default to 500 now
  const [customNoteInput, setCustomNoteInput] = useState('');
  const [uploadedNoteImages, setUploadedNoteImages] = useState<string[]>([]);

  // Question Configuration
  const [showAddQuestionModal, setShowAddQuestionModal] = useState(false);
  const [newQuestionText, setNewQuestionText] = useState('');
  const [newQuestionImage, setNewQuestionImage] = useState<string | null>(null);

  // Assign/Share State
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [showShareNotesModal, setShowShareNotesModal] = useState(false);
  const [userClassrooms, setUserClassrooms] = useState<Classroom[]>([]);
  const [selectedClassId, setSelectedClassId] = useState<string>('');
  const [assigningStatus, setAssigningStatus] = useState<'idle' | 'assigning' | 'assigned'>('idle');
  const [sharingStatus, setSharingStatus] = useState<'idle' | 'sharing' | 'shared'>('idle');

  useEffect(() => {
    setCurrentPlan(plan);
    const user = getCurrentUser();
    setIsGuest(!user);
    if (user) {
        setUserClassrooms(getClassrooms());
    }
  }, [plan]);

  const handlePrint = () => {
    window.print();
  };

  // Helper to remove Lesson prefix and markdown
  const cleanTopic = (topic: string) => topic.replace(/^Lesson \d+:\s*/i, '');
  const cleanText = (text: string) => text.replace(/[*#]/g, '');

  const handleDownload = (section: 'plan' | 'notes' | 'questions') => {
    if (isGuest) {
        alert("Please sign in or create an account to download content.");
        return;
    }

    const isKiswahili = currentPlan.subject === 'Kiswahili';

    let title = '';
    let bodyContent = '';
    let fileNameSuffix = '';

    // STRICT FORMATTING FOR WORD EXPORT
    const metadataTable = `
      <table style="width: 100%; border-collapse: collapse; margin-bottom: 10px; font-size: 10pt; font-family: Arial, sans-serif; border: 1px solid #000;">
        <tr>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">Teacher</td>
          <td style="border: 1px solid #000; padding: 4px; width: 25%;">${currentPlan.teacherName}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">School</td>
          <td style="border: 1px solid #000; padding: 4px; width: 25%;">${currentPlan.schoolName}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">Date</td>
          <td style="border: 1px solid #000; padding: 4px; width: 10%;">${currentPlan.date}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold; width: 10%;">Subject</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.subject}</td>
        </tr>
        <tr>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Grade</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.grade}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Term</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.term}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Roll</td>
          <td style="border: 1px solid #000; padding: 4px;">${currentPlan.roll}</td>
          <td style="border: 1px solid #000; padding: 4px; font-weight: bold;">Time</td>
          <td style="border: 1px solid #000; padding: 4px;">40 min</td>
        </tr>
      </table>
    `;

    const displayTopic = cleanTopic(currentPlan.topic);

    if (section === 'plan') {
        title = `Lesson Plan - ${currentPlan.date}`;
        fileNameSuffix = 'Plan';
        bodyContent = `
          ${metadataTable}

          <div style="font-family: Arial, sans-serif; font-size: 10pt;">
            <p style="margin: 3px 0;"><strong>Strand:</strong> ${currentPlan.strand}</p>
            <p style="margin: 3px 0;"><strong>Sub-strand:</strong> ${currentPlan.subStrand}</p>
            <p style="margin: 10px 0; font-weight: bold; text-transform: uppercase;">${displayTopic.toUpperCase()}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">SPECIFIC LEARNING OUTCOMES</p>
            <ul style="margin-top: 0; padding-left: 20px; list-style-type: disc;">
                ${currentPlan.learningOutcomes.map(o => `<li>${o}</li>`).join('')}
            </ul>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">KEY INQUIRY QUESTIONS</p>
            <ul style="margin-top: 0; padding-left: 20px; list-style-type: disc;">
                ${currentPlan.keyInquiryQuestions.map(q => `<li>${q}</li>`).join('')}
            </ul>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">LEARNING RESOURCES</p>
            <p style="margin-top: 0;">${currentPlan.learningResources.join(", ")}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">INTRODUCTION (5 MIN)</p>
            <p style="margin-top: 0;">${currentPlan.introduction}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">LESSON DEVELOPMENT (25 MIN)</p>
            <p style="margin-top: 0; margin-bottom: 4px;"><strong>Step 1:</strong> ${currentPlan.developmentSteps.step1}</p>
            <p style="margin-top: 0; margin-bottom: 4px;"><strong>Step 2:</strong> ${currentPlan.developmentSteps.step2}</p>
            <p style="margin-top: 0; margin-bottom: 4px;"><strong>Step 3:</strong> ${currentPlan.developmentSteps.step3}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">EXTENDED ACTIVITIES</p>
            <p style="margin-top: 0;">${currentPlan.extendedActivities}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">CONCLUSION (5 MIN)</p>
            <p style="margin-top: 0;">${currentPlan.conclusion}</p>

            <p style="margin-top: 10px; margin-bottom: 2px; font-weight: bold; text-transform: uppercase;">REFLECTION</p>
            <div style="height: 60px; border: 1px solid #000; width: 100%;"></div>
          </div>
        `;
    } else if (section === 'notes') {
        // Notes export keeps simple format
        title = 'Learner Notes';
        fileNameSuffix = 'Notes';
        const teacherAdded = currentPlan.teacherNotes ? currentPlan.teacherNotes.map(n => `<p><strong>${n.title}</strong><br/>${n.content}</p>`).join('') : '';
        bodyContent = `
            ${metadataTable}
            <h2 style="text-transform: uppercase; font-size: 12pt;">Simplified Learner Notes</h2>
            <div style="font-family: Arial, sans-serif; font-size: 10pt;">
                ${cleanText(currentPlan.learnerNotes || '').replace(/\n/g, '<br/>')}
            </div>
            ${teacherAdded ? `<h3 style="margin-top:15px;">Teacher's Additions</h3>${teacherAdded}` : ''}
        `;
    } else if (section === 'questions') {
        // Questions export keeps simple format
        title = 'Practice Questions';
        fileNameSuffix = 'Questions';

        let questionsText = '';
        if (currentPlan.structuredQuestions) {
            questionsText = currentPlan.structuredQuestions.map((q, i) => {
                let qText = `<p><strong>${i+1}. ${q.question}</strong></p>`;
                if (q.type === 'mcq' && q.options) {
                    qText += `<ul style="list-style-type: none; padding-left: 10px;">${q.options.map((opt, oi) => `<li>${String.fromCharCode(65+oi)}) ${opt}</li>`).join('')}</ul>`;
                } else if (q.type === 'structured') {
                    qText += `<p>___________________________________________________</p>`;
                }
                return qText;
            }).join('');
        }

        bodyContent = `
            ${metadataTable}
            <h2 style="text-transform: uppercase; font-size: 12pt;">Practice Questions</h2>
            <div style="font-family: Arial, sans-serif; font-size: 10pt;">
                ${questionsText || 'No questions available.'}
            </div>
        `;
    }

    const content = `
      <html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
        <head>
          <meta charset="utf-8">
          <title>${title}</title>
          <style>
            body { font-family: 'Arial', sans-serif; font-size: 10pt; }
          </style>
        </head>
        <body>
          ${bodyContent}
        </body>
      </html>
    `;

    const blob = new Blob(['\ufeff', content], { type: 'application/msword' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${fileNameSuffix}-${currentPlan.date}-${currentPlan.subject}.doc`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleGenerateNotes = async () => {
    setLoadingNotes(true);
    try {
      const generatedNotes = await generateSimplifiedNotes(currentPlan, noteWordCount);
      const updatedPlan = { ...currentPlan, learnerNotes: generatedNotes };
      setCurrentPlan(updatedPlan);
      if (!isGuest) {
          savePlan(updatedPlan);
      }
    } catch (error) {
      alert("Failed to generate notes. Please try again.");
    } finally {
      setLoadingNotes(false);
    }
  };

  const handleGenerateQuestions = async () => {
    setLoadingQuestions(true);
    try {
      const generatedQuestions = await generatePracticeQuestions(currentPlan);
      const updatedPlan = { 
          ...currentPlan, 
          structuredQuestions: generatedQuestions 
      };

      setCurrentPlan(updatedPlan);
      if (!isGuest) {
          savePlan(updatedPlan);
      }
    } catch (error) {
      alert("Failed to generate questions. Please try again.");
    } finally {
      setLoadingQuestions(false);
    }
  };

  const handleAddStructuredQuestions = async () => {
      setLoadingQuestions(true);
      try {
          const newQuestions = await generateStructuredQuestions(currentPlan);
          // Append to existing questions
          const existingQs = currentPlan.structuredQuestions || [];
          // Adjust IDs
          const startId = existingQs.length > 0 ? Math.max(...existingQs.map(q => q.id)) + 1 : 1;
          const adjustedNewQs = newQuestions.map((q, idx) => ({ ...q, id: startId + idx }));

          const updatedPlan = {
              ...currentPlan,
              structuredQuestions: [...existingQs, ...adjustedNewQs]
          };

          setCurrentPlan(updatedPlan);
          if (!isGuest) {
              savePlan(updatedPlan);
          }
      } catch (error) {
          alert("Failed to add structured questions.");
      } finally {
          setLoadingQuestions(false);
      }
  };

  // --- Image Upload Logic for Notes ---
  const handleNoteImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const files = e.target.files;
      if (files) {
          Array.from(files).forEach((file: File) => {
              const reader = new FileReader();
              reader.onloadend = () => {
                  if (typeof reader.result === 'string') {
                      setUploadedNoteImages(prev => [...prev, reader.result as string]);
                  }
              };
              reader.readAsDataURL(file);
          });
      }
  };

  const handleAddCustomNote = () => {
      if (!customNoteInput.trim() && uploadedNoteImages.length === 0) return;

      const newNote: SharedNote = {
          id: crypto.randomUUID(),
          title: "Teacher's Addition",
          content: customNoteInput,
          dateShared: new Date().toISOString(),
          subject: currentPlan.subject,
          images: uploadedNoteImages
      };

      const updatedNotes = currentPlan.teacherNotes ? [...currentPlan.teacherNotes, newNote] : [newNote];
      const updatedPlan = { ...currentPlan, teacherNotes: updatedNotes };

      setCurrentPlan(updatedPlan);
      if (!isGuest) savePlan(updatedPlan);

      setCustomNoteInput('');
      setUploadedNoteImages([]);
  };

  // --- Question Image Upload Logic ---
  const handleQuestionImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onloadend = () => {
              if (typeof reader.result === 'string') {
                  setNewQuestionImage(reader.result);
              }
          };
          reader.readAsDataURL(file);
      }
  };

  const handleAddManualQuestion = () => {
      if (!newQuestionText.trim() && !newQuestionImage) return;

      const existingQs = currentPlan.structuredQuestions || [];
      const newId = existingQs.length > 0 ? Math.max(...existingQs.map(q => q.id)) + 1 : 1;

      const newQ: QuizQuestion = {
          id: newId,
          type: 'structured', // Default to structured for manual entry unless specific UI allows choice
          question: newQuestionText,
          image: newQuestionImage || undefined,
          correctAnswer: 'Manual Marking', // Placeholder
          explanation: 'Added by teacher'
      };

      const updatedPlan = {
          ...currentPlan,
          structuredQuestions: [...existingQs, newQ]
      };

      setCurrentPlan(updatedPlan);
      if (!isGuest) savePlan(updatedPlan);

      setNewQuestionText('');
      setNewQuestionImage(null);
      setShowAddQuestionModal(false);
  };

  const handleAssignToClass = () => {
    if (isGuest) {
      alert("Please sign in to assign work to classes.");
      return;
    }
    if (!currentPlan.structuredQuestions || currentPlan.structuredQuestions.length === 0) {
      alert("Please generate or add practice questions first.");
      return;
    }
    if (userClassrooms.length === 0) {
        alert("You have no active classrooms. Go to your Dashboard to create one.");
        return;
    }
    setShowAssignModal(true);
  };

  const handleShareNotes = () => {
      if (isGuest) {
          alert("Please sign in to share notes.");
          return;
      }
      if (!currentPlan.learnerNotes && (!currentPlan.teacherNotes || currentPlan.teacherNotes.length === 0)) {
          alert("Please generate or add notes first.");
          return;
      }
      if (userClassrooms.length === 0) {
          alert("You have no active classrooms. Go to your Dashboard to create one.");
          return;
      }
      setShowShareNotesModal(true);
  };

  const confirmAssignment = () => {
      if (!selectedClassId) return;
      setAssigningStatus('assigning');

      const assignment: Assignment = {
          id: crypto.randomUUID(),
          classroomId: selectedClassId,
          subject: currentPlan.subject,
          grade: currentPlan.grade, // Added grade for regeneration context
          topic: cleanTopic(currentPlan.topic),
          questions: currentPlan.structuredQuestions || [],
          createdAt: new Date().toISOString()
      };

      saveAssignment(assignment);

      setTimeout(() => {
          setAssigningStatus('assigned');
          setTimeout(() => {
              setShowAssignModal(false);
              setAssigningStatus('idle');
              setSelectedClassId('');
          }, 1500);
      }, 1000);
  };

  const confirmShareNotes = () => {
      if (!selectedClassId) return;
      setSharingStatus('sharing');

      // Share AI notes
      if (currentPlan.learnerNotes) {
          const sharedNote: SharedNote = {
              id: crypto.randomUUID(),
              title: cleanTopic(currentPlan.topic),
              content: cleanText(currentPlan.learnerNotes || ''),
              dateShared: new Date().toISOString(),
              subject: currentPlan.subject
          };
          shareNoteToClassroom(selectedClassId, sharedNote);
      }

      // Share Teacher Added Notes
      if (currentPlan.teacherNotes) {
          currentPlan.teacherNotes.forEach(note => {
              // Ensure ID is unique for shared instance
              const noteToShare = { ...note, id: crypto.randomUUID(), dateShared: new Date().toISOString() };
              shareNoteToClassroom(selectedClassId, noteToShare);
          });
      }

      setTimeout(() => {
          setSharingStatus('shared');
          setTimeout(() => {
              setShowShareNotesModal(false);
              setSharingStatus('idle');
              setSelectedClassId('');
          }, 1500);
      }, 1000);
  };

  return (
    <div className="space-y-6">
      {/* Top Action Bar */}
      <div className="bg-white p-4 rounded-lg shadow border border-gray-200 flex flex-wrap gap-4 justify-between items-center no-print sticky top-0 z-20">
        <button onClick={onBack} className="flex items-center gap-2 text-gray-600 hover:text-gray-900 transition-colors">
            <ArrowLeft className="w-5 h-5" />
            <span>Back</span>
        </button>

        <div className="flex flex-wrap gap-3">
             <button 
                onClick={handlePrint}
                className="flex items-center gap-2 bg-slate-800 text-white px-4 py-2 rounded-md hover:bg-slate-700 transition-colors shadow-sm"
            >
                <Printer className="w-4 h-4" />
                Print / PDF
            </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-gray-200 no-print mb-6 overflow-x-auto">
        <button
            onClick={() => setActiveTab('plan')}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 border-b-2 transition-colors whitespace-nowrap ${activeTab === 'plan' ? 'border-teal-600 text-teal-700 bg-teal-50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
        >
            <Layout className="w-4 h-4" /> Lesson Plan
        </button>
        <button
            onClick={() => setActiveTab('notes')}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 border-b-2 transition-colors whitespace-nowrap ${activeTab === 'notes' ? 'border-teal-600 text-teal-700 bg-teal-50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
        >
            <FileText className="w-4 h-4" /> Learner Notes
        </button>
        <button
            onClick={() => setActiveTab('questions')}
            className={`px-6 py-3 font-medium text-sm flex items-center gap-2 border-b-2 transition-colors whitespace-nowrap ${activeTab === 'questions' ? 'border-teal-600 text-teal-700 bg-teal-50' : 'border-transparent text-gray-500 hover:text-gray-700 hover:bg-gray-50'}`}
        >
            <HelpCircle className="w-4 h-4" /> Practice Questions
        </button>
      </div>

      {/* Content Area */}
      <div id="lesson-plan-content" ref={componentRef} className="bg-white p-8 md:p-12 shadow-lg border border-gray-200 mx-auto max-w-4xl print:shadow-none print:border-none print:w-full print:max-w-none print:p-0 print:m-0 font-sans">

        {/* Lesson Plan Text Content - Strict Layout */}
        {(activeTab === 'plan' || typeof window !== 'undefined' && window.matchMedia('print').matches) && (
            <div className={`${activeTab !== 'plan' ? 'hidden print:block' : ''}`}>
                {/* Strict Table Layout for Header */}
                <div className="border border-black mb-6 text-sm">
                    <div className="grid grid-cols-8 border-b border-black divide-x divide-black">
                        <div className="col-span-1 p-2 font-bold bg-white">Teacher</div>
                        <div className="col-span-2 p-2">{currentPlan.teacherName}</div>
                        <div className="col-span-1 p-2 font-bold bg-white">School</div>
                        <div className="col-span-2 p-2">{currentPlan.schoolName}</div>
                        <div className="col-span-1 p-2 font-bold bg-white">Date</div>
                        <div className="col-span-1 p-2">{currentPlan.date}</div>
                        <div className="col-span-1 p-2 font-bold bg-white">Subject</div>
                        <div className="col-span-2 p-2">{currentPlan.subject}</div>
                    </div>
                    <div className="grid grid-cols-8 divide-x divide-black">
                        <div className="col-span-1 p-2 font-bold bg-white">Grade</div>
                        <div className="col-span-1 p-2">{currentPlan.grade}</div>
                        <div className="col-span-1 p-2 font-bold bg-white">Term</div>
                        <div className="col-span-1 p-2">{currentPlan.term}</div>
                        <div className="col-span-1 p-2 font-bold bg-white">Roll</div>
                        <div className="col-span-1 p-2">{currentPlan.roll}</div>
                        <div className="col-span-1 p-2 font-bold bg-white">Time</div>
                        <div className="col-span-1 p-2">40 min</div>
                    </div>
                </div>

                <div className="space-y-4 text-black text-sm">
                    <div>
                        <p><strong>Strand:</strong> {currentPlan.strand}</p>
                        <p><strong>Sub-strand:</strong> {currentPlan.subStrand}</p>
                        <p className="font-bold uppercase mt-2">{cleanTopic(currentPlan.topic).toUpperCase()}</p>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">SPECIFIC LEARNING OUTCOMES</h3>
                        <ul className="list-disc pl-5">
                            {currentPlan.learningOutcomes.map((outcome, i) => <li key={i}>{outcome}</li>)}
                        </ul>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">KEY INQUIRY QUESTIONS</h3>
                        <ul className="list-disc pl-5">
                            {currentPlan.keyInquiryQuestions.map((q, i) => <li key={i}>{q}</li>)}
                        </ul>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">LEARNING RESOURCES</h3>
                        <p>{currentPlan.learningResources.join(", ")}</p>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">INTRODUCTION (5 MIN)</h3>
                        <p>{currentPlan.introduction}</p>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">LESSON DEVELOPMENT (25 MIN)</h3>
                        <div className="space-y-2">
                            <p><strong>Step 1:</strong> {currentPlan.developmentSteps.step1}</p>
                            <p><strong>Step 2:</strong> {currentPlan.developmentSteps.step2}</p>
                            <p><strong>Step 3:</strong> {currentPlan.developmentSteps.step3}</p>
                        </div>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">EXTENDED ACTIVITIES</h3>
                        <p>{currentPlan.extendedActivities}</p>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">CONCLUSION (5 MIN)</h3>
                        <p>{currentPlan.conclusion}</p>
                    </div>

                    <div>
                        <h3 className="font-bold uppercase mb-1">REFLECTION</h3>
                        <div className="h-16 border border-black w-full"></div>
                    </div>

                    {/* Bottom Download Button for Plan */}
                    <div className="mt-8 flex justify-center no-print">
                        <button 
                            onClick={() => handleDownload('plan')}
                            disabled={isGuest}
                            className={`flex items-center gap-2 px-6 py-3 rounded-md transition-colors shadow-sm font-medium ${isGuest ? 'bg-gray-300 text-gray-500 cursor-not-allowed' : 'bg-teal-600 text-white hover:bg-teal-700'}`}
                            title={isGuest ? "Sign in to download" : "Download Word Document"}
                        >
                            {isGuest ? <Lock className="w-5 h-5" /> : <Download className="w-5 h-5" />}
                            {isGuest ? "Sign In to Download" : "Download Lesson Plan (Word)"}
                        </button>
                    </div>
                </div>
            </div>
        )}

        {/* Notes View */}
        {(activeTab === 'notes' || typeof window !== 'undefined' && window.matchMedia('print').matches && (currentPlan.learnerNotes || currentPlan.teacherNotes)) && (
            <div className={`${activeTab !== 'notes' ? 'hidden print:block print:break-before-page' : ''}`}>
                <div className="flex justify-between items-center mb-4 border-b pb-2">
                    <h2 className="text-xl font-bold text-teal-900">Simplified Learner Notes</h2>
                    <div className="flex gap-2 no-print">
                         <div className="flex items-center gap-2">
                            <span className="text-xs text-gray-500">Length:</span>
                            <select 
                                value={noteWordCount} 
                                onChange={(e) => setNoteWordCount(parseInt(e.target.value))}
                                className="text-xs border border-gray-300 rounded p-1"
                            >
                                <option value="350">Short (350)</option>
                                <option value="500">Standard (500)</option>
                                <option value="700">Detailed (700)</option>
                            </select>
                            <button onClick={handleGenerateNotes} disabled={loadingNotes} className="text-xs bg-white border border-teal-600 text-teal-600 px-3 py-1 rounded hover:bg-teal-50 flex items-center gap-1 font-bold">
                                {loadingNotes ? <Loader2 className="w-3 h-3 animate-spin"/> : <RefreshCw className="w-3 h-3"/>} Regenerate
                            </button>
                         </div>
                    </div>
                </div>

                {currentPlan.learnerNotes || currentPlan.teacherNotes ? (
                    <div className="space-y-8">
                        {currentPlan.learnerNotes && (
                            <div className="prose max-w-none whitespace-pre-wrap text-sm bg-gray-50 p-6 rounded-lg border border-gray-200 print:bg-transparent print:border-none print:p-0">
                                {cleanText(currentPlan.learnerNotes)}
                            </div>
                        )}

                        {currentPlan.teacherNotes && currentPlan.teacherNotes.length > 0 && (
                            <div className="mt-6">
                                <h3 className="font-bold text-gray-700 mb-3">Teacher's Additions / Uploads</h3>
                                {currentPlan.teacherNotes.map((note, idx) => (
                                    <div key={idx} className="mb-4 p-4 border border-gray-100 rounded-lg bg-white">
                                        {note.content && <p className="text-sm text-gray-800 whitespace-pre-wrap mb-2">{note.content}</p>}
                                        {note.images && note.images.length > 0 && (
                                            <div className="flex gap-2 flex-wrap">
                                                {note.images.map((img, imgIdx) => (
                                                    <img key={imgIdx} src={img} alt="Uploaded note" className="h-32 w-auto object-cover rounded border border-gray-200" />
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                        )}

                        {/* Add Custom Note UI - No Print */}
                        <div className="no-print bg-slate-50 p-4 rounded-lg border border-slate-200 mt-6">
                            <h4 className="font-bold text-sm text-gray-700 mb-2">Add Custom Note / Upload Images</h4>
                            <textarea 
                                value={customNoteInput} 
                                onChange={(e) => setCustomNoteInput(e.target.value)} 
                                className="w-full p-2 border border-gray-300 rounded text-sm mb-2" 
                                placeholder="Type additional notes here..." 
                                rows={3}
                            />
                            <div className="flex items-center gap-2 mb-2">
                                <label className="cursor-pointer bg-white border border-gray-300 hover:bg-gray-50 px-3 py-1.5 rounded text-xs font-medium text-gray-700 flex items-center gap-1 transition-colors">
                                    <Upload className="w-3 h-3" /> Upload Images
                                    <input type="file" accept="image/*" multiple className="hidden" onChange={handleNoteImageUpload} />
                                </label>
                                <span className="text-xs text-gray-500">{uploadedNoteImages.length} images selected</span>
                            </div>
                            <button onClick={handleAddCustomNote} className="bg-slate-800 text-white px-4 py-1.5 rounded text-xs font-bold hover:bg-slate-700">Add to Notes</button>
                        </div>

                        {/* Bottom Buttons for Notes */}
                        <div className="flex flex-wrap justify-center gap-4 no-print mt-6">
                            <button 
                                onClick={() => handleDownload('notes')}
                                disabled={isGuest}
                                className={`flex items-center gap-2 px-6 py-3 rounded-md transition-colors shadow-sm font-medium ${isGuest ? 'bg-gray-300 text-gray-500 cursor-not-allowed' : 'bg-teal-600 text-white hover:bg-teal-700'}`}
                            >
                                {isGuest ? <Lock className="w-5 h-5" /> : <Download className="w-5 h-5" />}
                                {isGuest ? "Sign In to Download" : "Download Notes (Word)"}
                            </button>
                            <button 
                                onClick={handleShareNotes} 
                                disabled={isGuest} 
                                className={`flex items-center gap-2 px-6 py-3 rounded-md transition-colors shadow-sm font-medium border ${isGuest ? 'bg-gray-100 text-gray-400 border-gray-200 cursor-not-allowed' : 'bg-white text-teal-700 border-teal-600 hover:bg-teal-50'}`}
                            >
                                {isGuest ? <Lock className="w-5 h-5" /> : <Share2 className="w-5 h-5" />}
                                {isGuest ? "Sign In to Share" : "Share to Class"}
                            </button>
                        </div>
                    </div>
                ) : (
                    <div className="text-center py-12 bg-gray-50 rounded border border-dashed border-gray-300 no-print">
                        <p className="text-gray-500 mb-4">No notes generated yet.</p>

                        <div className="flex flex-col items-center gap-4">
                            <div className="flex items-center gap-2">
                                <label className="text-sm font-medium text-gray-600">Length (Words):</label>
                                <select 
                                    value={noteWordCount} 
                                    onChange={(e) => setNoteWordCount(parseInt(e.target.value))}
                                    className="rounded border border-gray-300 py-1 px-3 text-sm focus:ring-teal-500 focus:border-teal-500"
                                >
                                    <option value="350">350 (Short)</option>
                                    <option value="500">500 (Standard)</option>
                                    <option value="700">700 (Detailed)</option>
                                </select>
                            </div>

                            <button onClick={handleGenerateNotes} disabled={loadingNotes} className="inline-flex items-center gap-2 bg-teal-600 text-white px-6 py-2 rounded-md hover:bg-teal-700">
                                {loadingNotes ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileText className="w-4 h-4" />} Generate Notes
                            </button>
                        </div>
                    </div>
                )}
            </div>
        )}

        {/* Questions View */}
        {(activeTab === 'questions' || typeof window !== 'undefined' && window.matchMedia('print').matches && currentPlan.structuredQuestions) && (
            <div className={`${activeTab !== 'questions' ? 'hidden print:block print:break-before-page' : ''}`}>
                <div className="flex justify-between items-center mb-4 border-b pb-2">
                    <h2 className="text-xl font-bold text-teal-900">Practice Questions</h2>
                    <div className="flex gap-2 no-print">
                        <button onClick={() => setShowAddQuestionModal(true)} className="flex items-center gap-1 text-xs font-bold bg-slate-100 text-slate-700 px-3 py-1.5 rounded hover:bg-slate-200">
                            <Plus className="w-3 h-3" /> Add Manual Question
                        </button>
                    </div>
                </div>

                {currentPlan.structuredQuestions && currentPlan.structuredQuestions.length > 0 ? (
                    <div className="space-y-8">
                        <div className="space-y-6">
                            {currentPlan.structuredQuestions.map((q, idx) => (
                                <div key={idx} className="bg-gray-50 p-4 rounded-lg border border-gray-200 print:bg-transparent print:border-none print:p-0">
                                    <p className="font-bold text-sm mb-2">{idx + 1}. {q.question}</p>
                                    {q.image && (
                                        <div className="mb-2">
                                            <img src={q.image} alt={`Question ${idx + 1}`} className="max-h-48 w-auto border border-gray-300 rounded" />
                                        </div>
                                    )}

                                    {q.type === 'mcq' && q.options ? (
                                        <ul className="list-[upper-alpha] pl-5 space-y-1 text-sm">
                                            {q.options.map((opt, i) => (
                                                <li key={i}>{opt}</li>
                                            ))}
                                        </ul>
                                    ) : (
                                        // Structured question space
                                        <div className="mt-2 h-20 border-b border-gray-300 print:block hidden"></div>
                                    )}
                                    {/* Answer Key (Hidden in Print unless specified, shown on screen for teacher) */}
                                    <div className="mt-2 pt-2 border-t border-gray-200 text-xs text-green-700 font-medium print:hidden">
                                        Answer: {q.correctAnswer}
                                    </div>
                                </div>
                            ))}
                        </div>

                        <div className="flex flex-wrap justify-center gap-4 no-print border-t pt-6">
                            <button onClick={handleGenerateQuestions} disabled={loadingQuestions} className="inline-flex items-center gap-2 bg-white border border-teal-600 text-teal-600 px-4 py-2 rounded-md hover:bg-teal-50 text-xs font-bold">
                                {loadingQuestions ? <Loader2 className="w-3 h-3 animate-spin" /> : <RefreshCw className="w-3 h-3" />} Regenerate MCQs
                            </button>
                            <button onClick={handleAddStructuredQuestions} disabled={loadingQuestions} className="inline-flex items-center gap-2 bg-white border border-blue-600 text-blue-600 px-4 py-2 rounded-md hover:bg-blue-50 text-xs font-bold">
                                {loadingQuestions ? <Loader2 className="w-3 h-3 animate-spin" /> : <Plus className="w-3 h-3" />} Add 5 Structured Qs
                            </button>

                            <div className="w-full h-px bg-gray-200 my-2"></div>

                            <button onClick={handleDownload('questions')} disabled={isGuest} className={`flex items-center gap-2 px-6 py-3 rounded-md transition-colors shadow-sm font-medium ${isGuest ? 'bg-gray-300 text-gray-500 cursor-not-allowed' : 'bg-teal-600 text-white hover:bg-teal-700'}`}>
                                {isGuest ? <Lock className="w-5 h-5" /> : <Download className="w-5 h-5" />}
                                {isGuest ? "Sign In to Download" : "Download Questions (Word)"}
                            </button>
                            <button onClick={handleAssignToClass} disabled={isGuest} className={`flex items-center gap-2 px-6 py-3 rounded-md transition-colors shadow-sm font-medium border ${isGuest ? 'bg-gray-100 text-gray-400 border-gray-200 cursor-not-allowed' : 'bg-white text-teal-700 border-teal-600 hover:bg-teal-50'}`}>
                                {isGuest ? <Lock className="w-5 h-5" /> : <Send className="w-5 h-5" />}
                                {isGuest ? "Sign In to Assign" : "Assign to Class"}
                            </button>
                        </div>
                    </div>
                ) : (
                    <div className="text-center py-12 bg-gray-50 rounded border border-dashed border-gray-300 no-print">
                        <p className="text-gray-500 mb-4">No questions generated yet.</p>
                        <div className="flex gap-4 justify-center">
                            <button onClick={handleGenerateQuestions} disabled={loadingQuestions} className="inline-flex items-center gap-2 bg-teal-600 text-white px-6 py-2 rounded-md hover:bg-teal-700">
                                {loadingQuestions ? <Loader2 className="w-4 h-4 animate-spin" /> : <HelpCircle className="w-4 h-4" />} Generate 10 MCQ Questions
                            </button>
                        </div>
                    </div>
                )}
            </div>
        )}
      </div>

      {/* Assign to Class Modal */}
      {showAssignModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden">
            <div className="flex justify-between items-center p-6 border-b border-gray-200 bg-gray-50">
              <h3 className="text-lg font-bold text-gray-800">Assign to Classroom</h3>
              <button onClick={() => setShowAssignModal(false)} className="text-gray-400 hover:text-gray-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="p-6">
                <p className="text-gray-600 mb-4">Select a class to assign these {currentPlan.structuredQuestions?.length} questions to:</p>
                <div className="space-y-3">
                    {userClassrooms.map(c => (
                        <label key={c.id} className={`flex items-center justify-between p-3 rounded-lg border cursor-pointer transition-all ${selectedClassId === c.id ? 'border-teal-500 bg-teal-50 ring-1 ring-teal-500' : 'border-gray-200 hover:bg-gray-50'}`}>
                            <div>
                                <div className="font-bold text-gray-800">{c.grade} - {c.stream}</div>
                                <div className="text-xs text-gray-500 flex gap-2">
                                    <span>{c.students.length} Students</span>
                                    {c.subjects.includes(currentPlan.subject) ? (
                                        <span className="text-green-600 font-bold">• {currentPlan.subject} Active</span>
                                    ) : (
                                        <span className="text-orange-500">• Adds {currentPlan.subject}</span>
                                    )}
                                </div>
                            </div>
                            <input 
                                type="radio" 
                                name="classroom" 
                                className="text-teal-600 focus:ring-teal-500"
                                checked={selectedClassId === c.id}
                                onChange={() => setSelectedClassId(c.id)}
                            />
                        </label>
                    ))}
                </div>
            </div>

            <div className="p-6 border-t border-gray-200 bg-gray-50 text-right">
              <button 
                onClick={confirmAssignment}
                disabled={!selectedClassId || assigningStatus !== 'idle'}
                className={`w-full py-2.5 rounded-lg font-bold text-white transition-colors flex justify-center items-center gap-2 ${assigningStatus === 'assigned' ? 'bg-green-600' : 'bg-teal-600 hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed'}`}
              >
                {assigningStatus === 'assigning' ? <Loader2 className="w-5 h-5 animate-spin" /> : assigningStatus === 'assigned' ? <Check className="w-5 h-5" /> : null}
                {assigningStatus === 'assigning' ? 'Assigning...' : assigningStatus === 'assigned' ? 'Assigned Successfully!' : 'Confirm Assignment'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Share Notes Modal */}
      {showShareNotesModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden">
            <div className="flex justify-between items-center p-6 border-b border-gray-200 bg-gray-50">
              <h3 className="text-lg font-bold text-gray-800">Share Notes to Class</h3>
              <button onClick={() => setShowShareNotesModal(false)} className="text-gray-400 hover:text-gray-600">
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="p-6">
                <p className="text-gray-600 mb-4">Select a class to share the notes with:</p>
                <div className="space-y-3">
                    {userClassrooms.map(c => (
                        <label key={c.id} className={`flex items-center justify-between p-3 rounded-lg border cursor-pointer transition-all ${selectedClassId === c.id ? 'border-teal-500 bg-teal-50 ring-1 ring-teal-500' : 'border-gray-200 hover:bg-gray-50'}`}>
                            <div>
                                <div className="font-bold text-gray-800">{c.grade} - {c.stream}</div>
                                <div className="text-xs text-gray-500 flex gap-2">
                                    <span>{c.students.length} Students</span>
                                </div>
                            </div>
                            <input 
                                type="radio" 
                                name="classroom_share" 
                                className="text-teal-600 focus:ring-teal-500"
                                checked={selectedClassId === c.id}
                                onChange={() => setSelectedClassId(c.id)}
                            />
                        </label>
                    ))}
                </div>
            </div>

            <div className="p-6 border-t border-gray-200 bg-gray-50 text-right">
              <button 
                onClick={confirmShareNotes}
                disabled={!selectedClassId || sharingStatus !== 'idle'}
                className={`w-full py-2.5 rounded-lg font-bold text-white transition-colors flex justify-center items-center gap-2 ${sharingStatus === 'shared' ? 'bg-green-600' : 'bg-teal-600 hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed'}`}
              >
                {sharingStatus === 'sharing' ? <Loader2 className="w-5 h-5 animate-spin" /> : sharingStatus === 'shared' ? <Check className="w-5 h-5" /> : null}
                {sharingStatus === 'sharing' ? 'Sharing...' : sharingStatus === 'shared' ? 'Shared Successfully!' : 'Confirm Share'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Add Manual Question Modal */}
      {showAddQuestionModal && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white">
                      <h3 className="font-bold">Add Manual Question</h3>
                      <button onClick={() => setShowAddQuestionModal(false)}><X className="w-5 h-5" /></button>
                  </div>
                  <div className="p-6">
                      <div className="mb-4">
                          <label className="block text-sm font-medium text-gray-700 mb-2">Question Text</label>
                          <textarea 
                              rows={3}
                              className="w-full rounded-lg border border-gray-300 p-3 text-sm focus:ring-2 focus:ring-teal-500 focus:border-transparent"
                              placeholder="Type question here..."
                              value={newQuestionText}
                              onChange={(e) => setNewQuestionText(e.target.value)}
                          ></textarea>
                      </div>
                      <div className="mb-4">
                          <label className="block text-sm font-medium text-gray-700 mb-2">Upload Image (Optional)</label>
                          <label className="cursor-pointer bg-white border border-gray-300 hover:bg-gray-50 px-4 py-3 rounded-lg border-dashed flex flex-col items-center justify-center gap-2 transition-colors">
                              {newQuestionImage ? (
                                  <div className="relative">
                                      <img src={newQuestionImage} alt="Preview" className="h-20 w-auto object-cover rounded" />
                                      <button onClick={(e) => {e.preventDefault(); setNewQuestionImage(null);}} className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-0.5"><X className="w-3 h-3"/></button>
                                  </div>
                              ) : (
                                  <>
                                      <Image className="w-6 h-6 text-gray-400" />
                                      <span className="text-xs text-gray-500">Click to upload image</span>
                                  </>
                              )}
                              <input type="file" accept="image/*" className="hidden" onChange={handleQuestionImageUpload} />
                          </label>
                      </div>
                  </div>
                  <div className="p-6 border-t border-gray-100 bg-gray-50 flex justify-end gap-2">
                      <button onClick={() => setShowAddQuestionModal(false)} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded font-medium text-sm">Cancel</button>
                      <button onClick={handleAddManualQuestion} className="px-4 py-2 bg-teal-600 text-white rounded font-bold text-sm hover:bg-teal-700">Add Question</button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default LessonPlanDisplay;

import React, { useState, useEffect } from 'react';
import { Student, Classroom, Assignment, StudentResult, SharedNote, QuizQuestion } from '../types';
import { authenticateStudent, updateStudentName, getAssignmentsByClassId, getStudentResults, saveStudentResult, getStudentNotes } from '../services/storageService';
import { generateSimilarQuestions } from '../services/geminiService';
import { LogIn, BookOpen, CheckCircle, Clock, ChevronRight, FileText, RefreshCw, X, Award, AlertCircle, ArrowLeft, Loader2, Play } from 'lucide-react';

const StudentPortal: React.FC = () => {
  const [view, setView] = useState<'login' | 'dashboard' | 'quiz' | 'revision'>('login');
  const [accessCode, setAccessCode] = useState('');
  const [student, setStudent] = useState<Student | null>(null);
  const [classroom, setClassroom] = useState<Classroom | null>(null);
  const [studentName, setStudentName] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Data
  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [results, setResults] = useState<StudentResult[]>([]);
  const [notes, setNotes] = useState<SharedNote[]>([]);

  // Quiz State
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Revision State
  const [revisionTopic, setRevisionTopic] = useState('');
  const [loadingRevision, setLoadingRevision] = useState(false);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!accessCode) return;

    const result = authenticateStudent(accessCode.toUpperCase());
    if (result) {
      setStudent(result.student);
      setClassroom(result.classroom);
      if (result.student.name) {
        loadStudentData(result.student.code, result.classroom.id);
        setView('dashboard');
      }
    } else {
      setError("Invalid Access Code. Please try again.");
    }
  };

  const handleNameUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (student && classroom && studentName.trim()) {
      const updated = updateStudentName(classroom.id, student.code, studentName);
      if (updated) {
        setStudent(updated);
        loadStudentData(updated.code, classroom.id);
        setView('dashboard');
      }
    }
  };

  const loadStudentData = (code: string, classId: string) => {
    const classAssignments = getAssignmentsByClassId(classId);
    const studentResults = getStudentResults(code);
    const classNotes = getStudentNotes(classId);

    setAssignments(classAssignments);
    setResults(studentResults);
    setNotes(classNotes);
  };

  const startQuiz = (assignment: Assignment) => {
    setActiveAssignment(assignment);
    setQuizQuestions(assignment.questions);
    setCurrentQuestionIndex(0);
    setSelectedAnswers({});
    setView('quiz');
  };

  const handleAnswerSelect = (answer: string) => {
      setSelectedAnswers(prev => ({
          ...prev,
          [currentQuestionIndex]: answer
      }));
  };

  const nextQuestion = () => {
      if (currentQuestionIndex < quizQuestions.length - 1) {
          setCurrentQuestionIndex(prev => prev + 1);
      }
  };

  const prevQuestion = () => {
      if (currentQuestionIndex > 0) {
          setCurrentQuestionIndex(prev => prev - 1);
      }
  };

  const submitQuiz = () => {
      if (!student || !activeAssignment) return;

      setIsSubmitting(true);

      let score = 0;
      quizQuestions.forEach((q, idx) => {
          const userAnswer = selectedAnswers[idx];
          // Check answer (simplified)
          if (userAnswer === q.correctAnswer) {
              score++;
          } else if (q.type === 'structured' && userAnswer?.toLowerCase().trim() === q.correctAnswer.toLowerCase().trim()) {
              score++;
          }
      });

      const result: StudentResult = {
          id: crypto.randomUUID(),
          assignmentId: activeAssignment.id,
          studentCode: student.code,
          studentName: student.name || 'Student',
          score: score,
          total: quizQuestions.length,
          attempts: 1,
          answers: selectedAnswers,
          dateTaken: new Date().toISOString()
      };

      saveStudentResult(result);
      if (classroom) loadStudentData(student.code, classroom.id);

      setIsSubmitting(false);
      setView('dashboard');
      alert(`Quiz Submitted! You scored ${score}/${quizQuestions.length}`);
  };

  const allQuestionsAnswered = quizQuestions.length > 0 && Object.keys(selectedAnswers).length === quizQuestions.length;

  // Login View
  if (view === 'login') {
      return (
          <div className="flex flex-col items-center justify-center min-h-[80vh] p-4">
              <div className="bg-white p-8 rounded-xl shadow-lg w-full max-w-md border border-gray-200">
                  <div className="text-center mb-8">
                      <div className="bg-teal-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                          <BookOpen className="w-8 h-8 text-teal-600" />
                      </div>
                      <h2 className="text-2xl font-bold text-gray-800">Student Portal</h2>
                      <p className="text-gray-500 text-sm">Enter your access code to continue</p>
                  </div>

                  {student && !student.name ? (
                      <form onSubmit={handleNameUpdate} className="space-y-4">
                          <div className="bg-blue-50 p-3 rounded text-sm text-blue-700 mb-4">
                              Welcome! Please set your name to proceed.
                          </div>
                          <div>
                              <label className="block text-sm font-medium text-gray-700 mb-1">Your Full Name</label>
                              <input 
                                  type="text" 
                                  required
                                  className="w-full p-3 rounded border border-gray-300 focus:ring-2 focus:ring-teal-500"
                                  value={studentName}
                                  onChange={e => setStudentName(e.target.value)}
                                  placeholder="e.g. John Kamau"
                              />
                          </div>
                          <button type="submit" className="w-full bg-teal-600 text-white py-3 rounded font-bold hover:bg-teal-700 transition">
                              Complete Setup
                          </button>
                      </form>
                  ) : (
                      <form onSubmit={handleLogin} className="space-y-4">
                          {error && <div className="bg-red-50 text-red-600 p-3 rounded text-sm flex items-center gap-2"><AlertCircle className="w-4 h-4"/> {error}</div>}
                          <div>
                              <label className="block text-sm font-medium text-gray-700 mb-1">Access Code</label>
                              <input 
                                  type="text" 
                                  required
                                  className="w-full p-3 rounded border border-gray-300 focus:ring-2 focus:ring-teal-500 font-mono text-center text-lg uppercase tracking-widest"
                                  value={accessCode}
                                  onChange={e => setAccessCode(e.target.value)}
                                  placeholder="XXXXXX"
                                  maxLength={6}
                              />
                          </div>
                          <button type="submit" className="w-full bg-teal-600 text-white py-3 rounded font-bold hover:bg-teal-700 transition flex justify-center items-center gap-2">
                              <LogIn className="w-5 h-5" /> Enter Class
                          </button>
                      </form>
                  )}
              </div>
          </div>
      );
  }

  // Quiz View
  if (view === 'quiz' && activeAssignment) {
      const question = quizQuestions[currentQuestionIndex];
      return (
          <div className="max-w-3xl mx-auto p-4 md:p-8">
              <div className="bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden">
                  <div className="bg-slate-900 text-white p-6 flex justify-between items-center">
                      <div>
                          <h2 className="font-bold text-lg">{activeAssignment.topic}</h2>
                          <p className="text-slate-400 text-sm">{activeAssignment.subject}</p>
                      </div>
                      <div className="text-right">
                          <span className="text-2xl font-bold">{currentQuestionIndex + 1}</span>
                          <span className="text-slate-500 text-sm"> / {quizQuestions.length}</span>
                      </div>
                  </div>

                  <div className="p-6 md:p-8">
                      <p className="text-lg font-medium text-gray-800 mb-6 leading-relaxed">
                          {question.question}
                      </p>

                      {question.image && (
                          <img src={question.image} alt="Question" className="mb-6 max-h-60 rounded border border-gray-200" />
                      )}

                      {question.type === 'mcq' && question.options ? (
                          <div className="space-y-3">
                              {question.options.map((opt, idx) => (
                                  <label 
                                      key={idx} 
                                      className={`flex items-center p-4 rounded-lg border-2 cursor-pointer transition-all ${selectedAnswers[currentQuestionIndex] === opt ? 'border-teal-500 bg-teal-50 ring-1 ring-teal-500' : 'border-gray-200 hover:border-teal-300 hover:bg-gray-50'}`}
                                  >
                                      <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center mr-4 ${selectedAnswers[currentQuestionIndex] === opt ? 'border-teal-500' : 'border-gray-300'}`}>
                                          {selectedAnswers[currentQuestionIndex] === opt && <div className="w-2.5 h-2.5 rounded-full bg-teal-500" />}
                                      </div>
                                      <span className="text-gray-700">{opt}</span>
                                      <input 
                                          type="radio" 
                                          name={`question-${question.id}`} 
                                          className="hidden"
                                          value={opt}
                                          onChange={() => handleAnswerSelect(opt)}
                                      />
                                  </label>
                              ))}
                          </div>
                      ) : (
                          <textarea 
                              className="w-full p-4 rounded-lg border border-gray-300 focus:ring-2 focus:ring-teal-500 focus:border-teal-500 text-gray-700" 
                              rows={4}
                              placeholder="Type your answer here..."
                              value={selectedAnswers[currentQuestionIndex] || ''}
                              onChange={(e) => handleAnswerSelect(e.target.value)}
                          />
                      )}
                  </div>

                  <div className="p-6 bg-gray-50 border-t border-gray-200 flex justify-between items-center">
                      <div className="flex gap-2">
                          <button 
                              onClick={() => {
                                  if(confirm("Exit quiz? Progress will be lost.")) setView('dashboard');
                              }} 
                              className="text-gray-500 hover:text-red-600 font-medium px-4 py-2 text-sm"
                          >
                              Exit
                          </button>
                          {currentQuestionIndex > 0 && (
                              <button onClick={prevQuestion} className="bg-white border border-gray-300 text-gray-700 px-4 py-2 rounded-lg font-bold hover:bg-gray-50 shadow-sm transition-colors">
                                  Previous
                              </button>
                          )}
                      </div>

                      {currentQuestionIndex < quizQuestions.length - 1 ? (
                          <button onClick={nextQuestion} className="bg-slate-900 text-white px-6 py-2 rounded-lg font-bold hover:bg-slate-800 shadow-sm transition-colors flex items-center gap-2">
                              Next <ChevronRight className="w-4 h-4" />
                          </button>
                      ) : (
                          <div className="flex items-center gap-3">
                              {!allQuestionsAnswered && <span className="text-xs text-red-500 font-medium">Answer all to submit</span>}
                              <button 
                                  onClick={submitQuiz} 
                                  disabled={!allQuestionsAnswered || isSubmitting} 
                                  className="bg-teal-600 text-white px-8 py-2 rounded-lg font-bold hover:bg-teal-700 disabled:opacity-50 disabled:cursor-not-allowed shadow-sm transition-all flex items-center gap-2"
                              >
                                  {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin"/> : <CheckCircle className="w-4 h-4" />}
                                  Submit Quiz
                              </button>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      );
  }

  // Dashboard View
  return (
      <div className="container mx-auto px-4 py-8 max-w-5xl">
          <div className="flex justify-between items-center mb-8">
              <div>
                  <h1 className="text-2xl font-bold text-gray-900">Welcome, {student?.name}</h1>
                  <p className="text-gray-500">{classroom?.grade} - {classroom?.stream}</p>
              </div>
              <div className="bg-teal-50 text-teal-700 px-4 py-2 rounded-full font-mono font-bold border border-teal-200">
                  {student?.code}
              </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
              {/* Assignments Section */}
              <div className="lg:col-span-2 space-y-8">
                  <section>
                      <h3 className="font-bold text-gray-800 text-lg mb-4 flex items-center gap-2">
                          <Clock className="w-5 h-5 text-orange-500" /> Pending Assignments
                      </h3>
                      <div className="grid gap-4">
                          {assignments.filter(a => !results.some(r => r.assignmentId === a.id)).length === 0 ? (
                              <div className="text-gray-400 bg-gray-50 p-6 rounded-lg border border-dashed text-center italic">
                                  No pending assignments. Great job!
                              </div>
                          ) : (
                              assignments.filter(a => !results.some(r => r.assignmentId === a.id)).map(assign => (
                                  <div key={assign.id} className="bg-white p-5 rounded-xl shadow-sm border border-gray-200 flex justify-between items-center hover:border-teal-300 transition-all">
                                      <div>
                                          <h4 className="font-bold text-gray-800">{assign.topic}</h4>
                                          <div className="flex gap-3 text-xs text-gray-500 mt-1">
                                              <span className="bg-gray-100 px-2 py-0.5 rounded">{assign.subject}</span>
                                              <span>{assign.questions.length} Questions</span>
                                          </div>
                                      </div>
                                      <button 
                                          onClick={() => startQuiz(assign)}
                                          className="bg-teal-600 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-teal-700 flex items-center gap-2 shadow-sm"
                                      >
                                          Start <Play className="w-3 h-3 fill-current" />
                                      </button>
                                  </div>
                              ))
                          )}
                      </div>
                  </section>

                  <section>
                      <h3 className="font-bold text-gray-800 text-lg mb-4 flex items-center gap-2">
                          <CheckCircle className="w-5 h-5 text-green-600" /> Completed
                      </h3>
                      <div className="grid gap-4">
                          {results.length === 0 ? (
                              <div className="text-gray-400 bg-gray-50 p-6 rounded-lg border border-dashed text-center italic">
                                  You haven't completed any assignments yet.
                              </div>
                          ) : (
                              results.map(result => {
                                  const assignment = assignments.find(a => a.id === result.assignmentId);
                                  return (
                                      <div key={result.id} className="bg-white p-5 rounded-xl shadow-sm border border-gray-200">
                                          <div className="flex justify-between items-start mb-2">
                                              <h4 className="font-bold text-gray-800">{assignment?.topic || 'Unknown Assignment'}</h4>
                                              <span className={`px-3 py-1 rounded-full text-xs font-bold ${result.score/result.total >= 0.5 ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                                  {Math.round((result.score / result.total) * 100)}%
                                              </span>
                                          </div>
                                          <div className="flex justify-between items-center text-sm">
                                              <span className="text-gray-500">{new Date(result.dateTaken).toLocaleDateString()}</span>
                                              <span className="text-gray-700 font-medium">Score: {result.score}/{result.total}</span>
                                          </div>
                                          {result.feedback && (
                                              <div className="mt-3 bg-blue-50 p-3 rounded-lg text-sm text-blue-800 border border-blue-100">
                                                  <strong>Teacher Feedback:</strong> {result.feedback}
                                              </div>
                                          )}
                                      </div>
                                  );
                              })
                          )}
                      </div>
                  </section>
              </div>

              {/* Sidebar: Notes */}
              <div className="space-y-6">
                  <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200 h-full">
                      <h3 className="font-bold text-gray-800 text-lg mb-4 flex items-center gap-2">
                          <FileText className="w-5 h-5 text-indigo-500" /> Class Notes
                      </h3>
                      <div className="space-y-4 max-h-[500px] overflow-y-auto pr-2">
                          {notes.length === 0 ? (
                              <div className="text-gray-400 text-sm text-center italic py-4">
                                  No notes shared yet.
                              </div>
                          ) : (
                              notes.map(note => (
                                  <div key={note.id} className="border-b border-gray-100 pb-4 last:border-0">
                                      <h4 className="font-bold text-gray-700 text-sm">{note.title}</h4>
                                      <p className="text-xs text-gray-400 mb-2">{new Date(note.dateShared).toLocaleDateString()} • {note.subject}</p>
                                      <div className="bg-gray-50 p-3 rounded text-sm text-gray-600 line-clamp-4 hover:line-clamp-none transition-all cursor-pointer">
                                          {note.content}
                                      </div>
                                  </div>
                              ))
                          )}
                      </div>
                  </div>
              </div>
          </div>
      </div>
  );
};

export default StudentPortal;

import React, { useState, useEffect } from 'react';
import { Student, Classroom, Assignment, StudentResult, SharedNote, QuizQuestion } from '../types';
import { authenticateStudent, updateStudentName, getAssignmentsByClassId, getStudentResults, saveStudentResult, getStudentNotes } from '../services/storageService';
import { generateSimilarQuestions } from '../services/geminiService';
import { LogIn, BookOpen, CheckCircle, Clock, ChevronRight, FileText, RefreshCw, X, Award, AlertCircle, ArrowLeft, Loader2, Play, Star, Zap, Trophy, Target, Sparkles, Flame, Brain } from 'lucide-react';

const StudentPortal: React.FC = () => {
  const [view, setView] = useState<'login' | 'dashboard' | 'quiz' | 'revision'>('login');
  const [accessCode, setAccessCode] = useState('');
  const [student, setStudent] = useState<Student | null>(null);
  const [classroom, setClassroom] = useState<Classroom | null>(null);
  const [studentName, setStudentName] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Data
  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [results, setResults] = useState<StudentResult[]>([]);
  const [notes, setNotes] = useState<SharedNote[]>([]);

  // Quiz State
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Interactive / Gamification State
  const [showMilestone, setShowMilestone] = useState(false);
  const [milestoneMessage, setMilestoneMessage] = useState('');
  const [xp, setXp] = useState(1250); // Mock XP for visual appeal
  const [level, setLevel] = useState(5);

  const MILESTONE_MESSAGES = [
      "You're crushing it! 🚀",
      "Knowledge +100 🧠",
      "Epic move! Keep going! 🔥",
      "Unstoppable! ⚡",
      "Leveling up your brain! 🎮",
      "Pure Genius Energy 🌟",
      "Boom! Another one down! 💥"
  ];

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!accessCode) return;

    const result = authenticateStudent(accessCode.toUpperCase());
    if (result) {
      setStudent(result.student);
      setClassroom(result.classroom);
      if (result.student.name) {
        loadStudentData(result.student.code, result.classroom.id);
        setView('dashboard');
      }
    } else {
      setError("Invalid Access Code. Try again, fam!");
    }
  };

  const handleNameUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (student && classroom && studentName.trim()) {
      const updated = updateStudentName(classroom.id, student.code, studentName);
      if (updated) {
        setStudent(updated);
        loadStudentData(updated.code, classroom.id);
        setView('dashboard');
      }
    }
  };

  const loadStudentData = (code: string, classId: string) => {
    const classAssignments = getAssignmentsByClassId(classId);
    const studentResults = getStudentResults(code);
    const classNotes = getStudentNotes(classId);

    setAssignments(classAssignments);
    setResults(studentResults);
    setNotes(classNotes);

    // Calculate mock Level based on results
    const totalScore = studentResults.reduce((acc, curr) => acc + curr.score, 0);
    setXp(1000 + (totalScore * 50));
    setLevel(Math.floor((1000 + (totalScore * 50)) / 500));
  };

  const startQuiz = (assignment: Assignment) => {
    setActiveAssignment(assignment);
    setQuizQuestions(assignment.questions);
    setCurrentQuestionIndex(0);
    setSelectedAnswers({});
    setView('quiz');
  };

  const handleAnswerSelect = (answer: string) => {
      setSelectedAnswers(prev => ({
          ...prev,
          [currentQuestionIndex]: answer
      }));
  };

  const nextQuestion = () => {
      // Trigger Milestone Pop-up
      const randomMsg = MILESTONE_MESSAGES[Math.floor(Math.random() * MILESTONE_MESSAGES.length)];
      setMilestoneMessage(randomMsg);
      setShowMilestone(true);
  };

  const continueFromMilestone = () => {
      setShowMilestone(false);
      if (currentQuestionIndex < quizQuestions.length - 1) {
          setCurrentQuestionIndex(prev => prev + 1);
      }
  };

  const prevQuestion = () => {
      if (currentQuestionIndex > 0) {
          setCurrentQuestionIndex(prev => prev - 1);
      }
  };

  const submitQuiz = () => {
      if (!student || !activeAssignment) return;

      setIsSubmitting(true);

      let score = 0;
      quizQuestions.forEach((q, idx) => {
          const userAnswer = selectedAnswers[idx];
          // Check answer (simplified)
          if (userAnswer === q.correctAnswer) {
              score++;
          } else if (q.type === 'structured' && userAnswer?.toLowerCase().trim() === q.correctAnswer.toLowerCase().trim()) {
              score++;
          }
      });

      const result: StudentResult = {
          id: crypto.randomUUID(),
          assignmentId: activeAssignment.id,
          studentCode: student.code,
          studentName: student.name || 'Student',
          score: score,
          total: quizQuestions.length,
          attempts: 1,
          answers: selectedAnswers,
          dateTaken: new Date().toISOString()
      };

      saveStudentResult(result);
      if (classroom) loadStudentData(student.code, classroom.id);

      setIsSubmitting(false);
      setView('dashboard'); // Or could go to a 'Result Celebration' view
      // We rely on dashboard updating to show the new result at the top
  };

  const allQuestionsAnswered = quizQuestions.length > 0 && Object.keys(selectedAnswers).length === quizQuestions.length;

  // --- RENDER HELPERS ---

  // Login View (Teen Style)
  if (view === 'login') {
      return (
          <div className="min-h-[90vh] flex flex-col items-center justify-center p-4 bg-gradient-to-br from-indigo-600 via-purple-600 to-pink-500 font-sans">
              <div className="bg-white/10 backdrop-blur-xl p-8 rounded-3xl shadow-2xl w-full max-w-md border border-white/20 text-white">
                  <div className="text-center mb-8">
                      <div className="bg-white/20 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-4 border-2 border-white/50 shadow-[0_0_15px_rgba(255,255,255,0.5)]">
                          <BookOpen className="w-10 h-10 text-white" />
                      </div>
                      <h2 className="text-3xl font-black tracking-tight mb-2">Student Portal</h2>
                      <p className="text-white/80 text-sm font-medium">Unlock your potential 🚀</p>
                  </div>

                  {student && !student.name ? (
                      <form onSubmit={handleNameUpdate} className="space-y-5">
                          <div className="bg-indigo-900/50 p-4 rounded-xl text-sm border border-indigo-400/30">
                              👋 Yo! What should we call you?
                          </div>
                          <div>
                              <input 
                                  type="text" 
                                  required
                                  className="w-full p-4 rounded-xl bg-white/20 border border-white/30 focus:outline-none focus:ring-2 focus:ring-yellow-400 placeholder-white/50 text-white font-bold text-center"
                                  value={studentName}
                                  onChange={e => setStudentName(e.target.value)}
                                  placeholder="Enter your name"
                              />
                          </div>
                          <button type="submit" className="w-full bg-gradient-to-r from-yellow-400 to-orange-500 text-indigo-900 py-4 rounded-xl font-black text-lg hover:scale-[1.02] transition-transform shadow-lg">
                              LET'S GO!
                          </button>
                      </form>
                  ) : (
                      <form onSubmit={handleLogin} className="space-y-6">
                          {error && <div className="bg-red-500/20 text-red-100 p-3 rounded-lg text-sm flex items-center gap-2 border border-red-500/50"><AlertCircle className="w-4 h-4"/> {error}</div>}
                          <div>
                              <label className="block text-xs font-bold uppercase tracking-widest text-white/70 mb-2">Access Code</label>
                              <input 
                                  type="text" 
                                  required
                                  className="w-full p-4 rounded-xl bg-white/20 border border-white/30 focus:outline-none focus:ring-2 focus:ring-yellow-400 placeholder-white/30 font-mono text-center text-2xl uppercase tracking-[0.5em] text-white"
                                  value={accessCode}
                                  onChange={e => setAccessCode(e.target.value)}
                                  placeholder="XXXXXX"
                                  maxLength={6}
                              />
                          </div>
                          <button type="submit" className="w-full bg-white text-indigo-600 py-4 rounded-xl font-black text-lg hover:bg-opacity-90 hover:scale-[1.02] transition-all flex justify-center items-center gap-2 shadow-xl">
                              <LogIn className="w-6 h-6" /> ENTER CLASS
                          </button>
                      </form>
                  )}
              </div>
          </div>
      );
  }

  // Quiz View (Immersive)
  if (view === 'quiz' && activeAssignment) {
      const question = quizQuestions[currentQuestionIndex];
      const progress = ((currentQuestionIndex + 1) / quizQuestions.length) * 100;

      return (
          <div className="min-h-screen bg-slate-900 text-white font-sans relative overflow-hidden">
              {/* Background Elements */}
              <div className="absolute top-0 left-0 w-full h-full overflow-hidden pointer-events-none">
                  <div className="absolute top-[-10%] right-[-10%] w-96 h-96 bg-purple-600/30 rounded-full blur-3xl"></div>
                  <div className="absolute bottom-[-10%] left-[-10%] w-96 h-96 bg-blue-600/30 rounded-full blur-3xl"></div>
              </div>

              {/* Top Bar */}
              <div className="relative z-10 px-4 py-6 md:px-8 flex justify-between items-center bg-white/5 backdrop-blur-sm border-b border-white/10">
                  <div className="flex items-center gap-3">
                      <div className="bg-gradient-to-r from-pink-500 to-rose-500 p-2 rounded-lg">
                          <Target className="w-5 h-5 text-white" />
                      </div>
                      <div>
                          <h2 className="font-bold text-sm md:text-base leading-tight">{activeAssignment.topic}</h2>
                          <p className="text-white/50 text-xs">{activeAssignment.subject}</p>
                      </div>
                  </div>
                  <div className="text-right">
                      <div className="text-2xl font-black font-mono text-transparent bg-clip-text bg-gradient-to-r from-yellow-400 to-orange-400">
                          {currentQuestionIndex + 1}<span className="text-white/30 text-lg">/{quizQuestions.length}</span>
                      </div>
                  </div>
              </div>

              {/* Progress Bar */}
              <div className="w-full h-1.5 bg-white/10">
                  <div className="h-full bg-gradient-to-r from-yellow-400 to-pink-500 transition-all duration-500 ease-out" style={{ width: `${progress}%` }}></div>
              </div>

              {/* Main Content */}
              <div className="relative z-10 max-w-4xl mx-auto p-4 md:p-8 flex flex-col min-h-[calc(100vh-140px)] justify-center">

                  {/* Question Card */}
                  <div className="bg-white/10 backdrop-blur-xl border border-white/20 rounded-3xl p-6 md:p-10 shadow-2xl animate-fade-in-up">
                      <p className="text-lg md:text-2xl font-medium mb-8 leading-relaxed">
                          {question.question}
                      </p>

                      {question.image && (
                          <div className="mb-8 rounded-2xl overflow-hidden border-4 border-white/10 shadow-lg inline-block">
                              <img src={question.image} alt="Question" className="max-h-60 object-cover" />
                          </div>
                      )}

                      {question.type === 'mcq' && question.options ? (
                          <div className="grid gap-4 md:grid-cols-1">
                              {question.options.map((opt, idx) => (
                                  <label 
                                      key={idx} 
                                      className={`group relative flex items-center p-5 rounded-2xl border-2 cursor-pointer transition-all duration-200 
                                      ${selectedAnswers[currentQuestionIndex] === opt 
                                          ? 'border-yellow-400 bg-yellow-400/10' 
                                          : 'border-white/10 bg-white/5 hover:bg-white/10 hover:border-white/30'}`}
                                  >
                                      <div className={`w-8 h-8 rounded-full border-2 flex items-center justify-center mr-5 shrink-0 transition-colors
                                          ${selectedAnswers[currentQuestionIndex] === opt ? 'border-yellow-400 bg-yellow-400 text-slate-900' : 'border-white/30 group-hover:border-white/60'}`}>
                                          {selectedAnswers[currentQuestionIndex] === opt && <CheckCircle className="w-5 h-5" />}
                                      </div>
                                      <span className="text-base md:text-lg font-medium">{opt}</span>
                                      <input 
                                          type="radio" 
                                          name={`question-${question.id}`} 
                                          className="hidden"
                                          value={opt}
                                          onChange={() => handleAnswerSelect(opt)}
                                      />
                                  </label>
                              ))}
                          </div>
                      ) : (
                          <textarea 
                              className="w-full p-6 rounded-2xl bg-white/5 border-2 border-white/10 focus:border-yellow-400 focus:bg-white/10 focus:outline-none text-lg transition-all min-h-[150px]" 
                              placeholder="Type your answer here..."
                              value={selectedAnswers[currentQuestionIndex] || ''}
                              onChange={(e) => handleAnswerSelect(e.target.value)}
                          />
                      )}
                  </div>

                  {/* Navigation Bar */}
                  <div className="mt-8 flex justify-between items-center">
                      <button 
                          onClick={() => {
                              if(confirm("Exit quiz? Progress will be lost.")) setView('dashboard');
                          }} 
                          className="px-6 py-3 rounded-xl font-bold text-white/50 hover:text-white hover:bg-white/10 transition-colors"
                      >
                          Quit
                      </button>

                      <div className="flex gap-4">
                          {currentQuestionIndex > 0 && (
                              <button onClick={prevQuestion} className="px-6 py-3 rounded-xl font-bold bg-white/10 hover:bg-white/20 text-white transition-all">
                                  Back
                              </button>
                          )}

                          {currentQuestionIndex < quizQuestions.length - 1 ? (
                              <button 
                                  onClick={nextQuestion} 
                                  className="px-8 py-3 rounded-xl font-black bg-gradient-to-r from-blue-500 to-indigo-600 hover:scale-105 transition-transform shadow-lg shadow-blue-500/30 flex items-center gap-2"
                              >
                                  NEXT <ChevronRight className="w-5 h-5" />
                              </button>
                          ) : (
                              <button 
                                  onClick={submitQuiz} 
                                  disabled={!allQuestionsAnswered || isSubmitting} 
                                  className="px-10 py-3 rounded-xl font-black bg-gradient-to-r from-green-400 to-emerald-600 hover:scale-105 transition-transform shadow-lg shadow-green-500/30 flex items-center gap-2 disabled:opacity-50 disabled:grayscale"
                              >
                                  {isSubmitting ? <Loader2 className="w-5 h-5 animate-spin"/> : <Award className="w-5 h-5" />}
                                  FINISH
                              </button>
                          )}
                      </div>
                  </div>
                  {!allQuestionsAnswered && currentQuestionIndex === quizQuestions.length - 1 && (
                      <div className="text-right mt-2 text-rose-400 text-sm font-bold animate-pulse">
                          ⚠️ Answer all questions to submit!
                      </div>
                  )}
              </div>

              {/* Milestone Pop-up */}
              {showMilestone && (
                  <div className="fixed inset-0 z-50 flex flex-col items-center justify-center bg-black/80 backdrop-blur-md animate-fade-in">
                      <div className="text-center p-8 scale-110">
                          <div className="text-8xl mb-6 animate-bounce">
                              {['🔥', '🚀', '⭐', '⚡', '🎉'][Math.floor(Math.random() * 5)]}
                          </div>
                          <h2 className="text-4xl md:text-6xl font-black text-transparent bg-clip-text bg-gradient-to-r from-yellow-300 via-orange-400 to-pink-500 mb-6 drop-shadow-lg">
                              {milestoneMessage}
                          </h2>
                          <div className="flex gap-4 justify-center">
                              <button 
                                  onClick={continueFromMilestone}
                                  className="px-10 py-4 bg-white text-indigo-900 rounded-full font-black text-xl hover:scale-110 hover:shadow-[0_0_30px_rgba(255,255,255,0.5)] transition-all"
                              >
                                  CONTINUE
                              </button>
                          </div>
                      </div>
                  </div>
              )}
          </div>
      );
  }

  // Dashboard View (Teen/Gamified)
  return (
      <div className="min-h-screen bg-slate-50 font-sans">
          {/* Header / Stats Bar */}
          <div className="bg-slate-900 text-white pt-8 pb-16 px-4 relative overflow-hidden">
              <div className="absolute top-0 right-0 w-64 h-64 bg-teal-500/20 rounded-full blur-3xl translate-x-1/2 -translate-y-1/2"></div>

              <div className="container mx-auto max-w-5xl relative z-10">
                  <div className="flex flex-col md:flex-row justify-between items-center gap-6">
                      <div className="flex items-center gap-4">
                          <div className="w-16 h-16 bg-gradient-to-br from-pink-500 to-orange-400 rounded-2xl flex items-center justify-center text-3xl font-black shadow-lg transform -rotate-3">
                              {student?.name?.charAt(0) || "S"}
                          </div>
                          <div>
                              <h1 className="text-2xl font-bold">Hi, {student?.name?.split(' ')[0]}! 👋</h1>
                              <p className="text-slate-400 text-sm flex items-center gap-2">
                                  {classroom?.grade} - {classroom?.stream} 
                                  <span className="bg-slate-800 px-2 py-0.5 rounded text-xs font-mono border border-slate-700">{student?.code}</span>
                              </p>
                          </div>
                      </div>

                      {/* Gamified Stats */}
                      <div className="flex gap-3">
                          <div className="bg-slate-800/80 backdrop-blur border border-slate-700 p-3 rounded-xl flex flex-col items-center min-w-[90px]">
                              <div className="text-xs text-slate-400 uppercase font-bold tracking-wider mb-1">Level</div>
                              <div className="text-2xl font-black text-yellow-400 flex items-center gap-1">
                                  {level} <Star className="w-4 h-4 fill-yellow-400" />
                              </div>
                          </div>
                          <div className="bg-slate-800/80 backdrop-blur border border-slate-700 p-3 rounded-xl flex flex-col items-center min-w-[90px]">
                              <div className="text-xs text-slate-400 uppercase font-bold tracking-wider mb-1">XP</div>
                              <div className="text-2xl font-black text-purple-400 flex items-center gap-1">
                                  {xp} <Zap className="w-4 h-4 fill-purple-400" />
                              </div>
                          </div>
                          <div className="bg-slate-800/80 backdrop-blur border border-slate-700 p-3 rounded-xl flex flex-col items-center min-w-[90px]">
                              <div className="text-xs text-slate-400 uppercase font-bold tracking-wider mb-1">Streak</div>
                              <div className="text-2xl font-black text-orange-500 flex items-center gap-1">
                                  3 <Flame className="w-4 h-4 fill-orange-500" />
                              </div>
                          </div>
                      </div>
                  </div>
              </div>
          </div>

          <div className="container mx-auto max-w-5xl px-4 -mt-8 relative z-20">
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

                  {/* Main Content Column */}
                  <div className="lg:col-span-2 space-y-8">
                      {/* Pending Tasks */}
                      <section>
                          <div className="flex items-center justify-between mb-4">
                              <h3 className="font-black text-slate-800 text-lg flex items-center gap-2">
                                  <Target className="w-5 h-5 text-indigo-600" /> 
                                  MISSIONS <span className="bg-indigo-100 text-indigo-700 text-xs px-2 py-0.5 rounded-full">{assignments.filter(a => !results.some(r => r.assignmentId === a.id)).length}</span>
                              </h3>
                          </div>

                          <div className="space-y-4">
                              {assignments.filter(a => !results.some(r => r.assignmentId === a.id)).length === 0 ? (
                                  <div className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200 text-center">
                                      <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-3">
                                          <CheckCircle className="w-8 h-8 text-green-600" />
                                      </div>
                                      <p className="text-slate-600 font-medium">All caught up! You're a legend! 🏆</p>
                                  </div>
                              ) : (
                                  assignments.filter(a => !results.some(r => r.assignmentId === a.id)).map(assign => (
                                      <div key={assign.id} className="bg-white group p-1 rounded-2xl shadow-sm border border-slate-200 hover:shadow-md transition-all hover:-translate-y-1">
                                          <div className="bg-gradient-to-r from-indigo-50 to-white p-5 rounded-xl flex justify-between items-center">
                                              <div>
                                                  <div className="flex items-center gap-2 mb-1">
                                                      <span className="bg-indigo-100 text-indigo-700 text-[10px] font-black uppercase px-2 py-0.5 rounded tracking-wider">{assign.subject}</span>
                                                      <span className="text-xs text-slate-400 font-medium flex items-center gap-1"><Clock className="w-3 h-3" /> New</span>
                                                  </div>
                                                  <h4 className="font-bold text-slate-800 text-lg">{assign.topic}</h4>
                                                  <p className="text-xs text-slate-500 mt-1">{assign.questions.length} Questions • +{assign.questions.length * 10} XP</p>
                                              </div>
                                              <button 
                                                  onClick={() => startQuiz(assign)}
                                                  className="bg-indigo-600 text-white w-12 h-12 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-200 group-hover:scale-110 transition-transform"
                                              >
                                                  <Play className="w-6 h-6 fill-current" />
                                              </button>
                                          </div>
                                      </div>
                                  ))
                              )}
                          </div>
                      </section>

                      {/* Completed / History */}
                      <section>
                          <h3 className="font-black text-slate-800 text-lg mb-4 flex items-center gap-2">
                              <Trophy className="w-5 h-5 text-yellow-500" /> 
                              ACHIEVEMENTS
                          </h3>
                          <div className="grid gap-4">
                              {results.length === 0 ? (
                                  <div className="text-slate-400 text-center py-8 italic border-2 border-dashed border-slate-200 rounded-2xl">
                                      Your trophy case is empty. Start a quiz!
                                  </div>
                              ) : (
                                  results.map(result => {
                                      const assignment = assignments.find(a => a.id === result.assignmentId);
                                      const percentage = Math.round((result.score / result.total) * 100);
                                      return (
                                          <div key={result.id} className="bg-white p-5 rounded-2xl shadow-sm border border-slate-200 flex flex-col gap-3">
                                              <div className="flex justify-between items-start">
                                                  <div>
                                                      <h4 className="font-bold text-slate-800">{assignment?.topic || 'Unknown Mission'}</h4>
                                                      <p className="text-xs text-slate-400">{new Date(result.dateTaken).toLocaleDateString()}</p>
                                                  </div>
                                                  <div className={`px-3 py-1 rounded-lg font-black text-sm ${percentage >= 70 ? 'bg-green-100 text-green-700' : percentage >= 50 ? 'bg-yellow-100 text-yellow-700' : 'bg-red-100 text-red-700'}`}>
                                                      {percentage}%
                                                  </div>
                                              </div>

                                              {/* Progress Bar Visual */}
                                              <div className="w-full bg-slate-100 rounded-full h-2">
                                                  <div className={`h-2 rounded-full ${percentage >= 70 ? 'bg-green-500' : 'bg-orange-500'}`} style={{width: `${percentage}%`}}></div>
                                              </div>

                                              {result.feedback && (
                                                  <div className="bg-blue-50 p-3 rounded-xl border border-blue-100 text-sm text-blue-800 flex gap-3 items-start">
                                                      <div className="bg-blue-200 p-1 rounded-full shrink-0"><Brain className="w-4 h-4 text-blue-700" /></div>
                                                      <div>
                                                          <span className="font-bold text-xs uppercase opacity-70 block mb-1">Sensei Says:</span>
                                                          "{result.feedback}"
                                                      </div>
                                                  </div>
                                              )}
                                          </div>
                                      );
                                  })
                              )}
                          </div>
                      </section>
                  </div>

                  {/* Sidebar Column */}
                  <div className="space-y-6">
                      {/* Shared Notes Card */}
                      <div className="bg-gradient-to-b from-indigo-900 to-slate-900 rounded-3xl p-6 text-white shadow-xl relative overflow-hidden">
                          <div className="absolute top-0 right-0 w-32 h-32 bg-purple-500/30 rounded-full blur-2xl -mr-10 -mt-10"></div>

                          <h3 className="font-bold text-lg mb-4 flex items-center gap-2 relative z-10">
                              <Sparkles className="w-5 h-5 text-yellow-400" /> 
                              Power Ups
                          </h3>

                          <div className="space-y-3 relative z-10 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar">
                              {notes.length === 0 ? (
                                  <p className="text-white/50 text-sm italic">No power-up notes yet.</p>
                              ) : (
                                  notes.map(note => (
                                      <div key={note.id} className="bg-white/10 hover:bg-white/20 transition-colors p-4 rounded-xl border border-white/10 cursor-pointer">
                                          <h4 className="font-bold text-sm text-white mb-1">{note.title}</h4>
                                          <p className="text-[10px] text-white/50 uppercase font-bold tracking-wider mb-2">{note.subject}</p>
                                          <p className="text-xs text-white/80 line-clamp-3 leading-relaxed">
                                              {note.content}
                                          </p>
                                      </div>
                                  ))
                              )}
                          </div>
                      </div>

                      {/* Daily Challenge / Tip */}
                      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-200">
                          <h3 className="font-black text-slate-800 text-sm uppercase tracking-wide mb-3">Daily Tip</h3>
                          <p className="text-sm text-slate-600 leading-relaxed">
                              "Consistency is the key to mastery. Even 15 minutes a day makes you 1% better every time!" 🚀
                          </p>
                      </div>
                  </div>
              </div>
          </div>
      </div>
  );
};

