                        <Plus className="w-4 h-4" /> Add Classroom
                    </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {classrooms.map((room) => (
                        <div key={room.id} className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                            <div className="p-5 border-b border-gray-100 flex justify-between items-start">
                                <div>
                                    <h4 className="text-lg font-bold text-slate-800">{room.grade} <span className="text-gray-400">|</span> {room.stream}</h4>
                                    <div className="flex items-center gap-4 mt-2 text-xs text-gray-500 font-medium uppercase tracking-wide">
                                        <span className="flex items-center gap-1"><Users className="w-3 h-3" /> {room.students.length} Students</span>
                                    </div>
                                </div>
                                <div className="flex gap-2">
                                    <button onClick={() => openClassroomManager(room)} className="p-2 bg-gray-100 hover:bg-gray-200 rounded text-gray-600" title="View Students"><Eye className="w-4 h-4" /></button>
                                    <button onClick={() => handleDeleteClassroom(room.id)} className="p-2 bg-red-50 hover:bg-red-100 rounded text-red-600" title="Delete"><Trash2 className="w-4 h-4" /></button>
                                </div>
                            </div>
                            <div className="p-5 bg-slate-50 min-h-[100px]">
                                <div className="flex justify-between items-center mb-3">
                                    <h5 className="text-xs font-bold text-gray-400 uppercase">Subjects</h5>
                                    {addingSubjectTo === room.id ? (
                                        <div className="flex items-center gap-1">
                                            <select 
                                                value={selectedSubject} 
                                                onChange={(e) => setSelectedSubject(e.target.value as Subject)}
                                                className="text-xs border-gray-300 rounded shadow-sm py-1 w-32"
                                            >
                                                {Object.values(Subject).map(s => <option key={s} value={s}>{s}</option>)}
                                            </select>
                                            <button onClick={() => handleAddSubject(room.id)} className="bg-green-600 text-white p-1 rounded"><Check className="w-3 h-3" /></button>
                                            <button onClick={() => setAddingSubjectTo(null)} className="bg-gray-300 text-gray-700 p-1 rounded"><X className="w-3 h-3" /></button>
                                        </div>
                                    ) : (
                                        <button onClick={() => setAddingSubjectTo(room.id)} className="text-teal-600 text-xs font-bold hover:underline flex items-center gap-1"><Plus className="w-3 h-3" /> Add</button>
                                    )}
                                </div>
                                <div className="flex flex-wrap gap-2">
                                    {room.subjects.length > 0 ? room.subjects.map(sub => (
                                        <span key={sub} className="inline-flex items-center gap-1 bg-white border border-gray-200 text-gray-600 px-2 py-1 rounded text-xs font-medium">
                                            {sub}
                                            <button onClick={() => handleRemoveSubject(room.id, sub)} className="text-gray-400 hover:text-red-500"><X className="w-3 h-3" /></button>
                                        </span>
                                    )) : <span className="text-gray-400 text-xs italic">No subjects added.</span>}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
          )}

          {/* VIEW: PROFILE */}
          {activeView === 'profile' && (
            <div className="max-w-2xl animate-fade-in">
                <h2 className="text-xl text-gray-600 font-light uppercase tracking-wide mb-6">Profile Settings</h2>
                <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                    <form onSubmit={handleSubmitProfile} className="p-8 space-y-6">
                        {message && <div className="bg-green-50 text-green-700 p-3 rounded text-sm">{message}</div>}
                        <div className="grid grid-cols-1 gap-6">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Name</label>
                                <input type="text" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full rounded border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 p-2 border" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">School</label>
                                <input type="text" required value={formData.school} onChange={e => setFormData({...formData, school: e.target.value})} className="w-full rounded border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 p-2 border" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                                <input type="email" readOnly value={formData.email} className="w-full rounded border-gray-300 bg-gray-50 text-gray-500 p-2 border cursor-not-allowed" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Phone</label>
                                <input type="tel" required value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full rounded border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 p-2 border" />
                            </div>
                        </div>
                        <div className="pt-4 text-right">
                            <button type="submit" className="bg-slate-900 text-white px-6 py-2 rounded hover:bg-slate-800 transition-colors">Save Changes</button>
                        </div>
                    </form>
                </div>
            </div>
          )}

        </main>
      </div>

      {/* Add Class Modal */}
      {showAddClassModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white">
                    <h3 className="font-bold">New Classroom</h3>
                    <button onClick={() => setShowAddClassModal(false)}><X className="w-5 h-5" /></button>
                </div>
                <form onSubmit={handleCreateClassroom} className="p-6 space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Grade</label>
                        <select value={newClassGrade} onChange={(e) => setNewClassGrade(e.target.value as Grade)} className="w-full rounded border-gray-300 p-2 border">
                            {Object.values(Grade).map(g => <option key={g} value={g}>{g}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Stream</label>
                        <input type="text" required placeholder="e.g. Blue" value={newClassStream} onChange={(e) => setNewClassStream(e.target.value)} className="w-full rounded border-gray-300 p-2 border" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Roll</label>
                        <input type="number" min="1" max="100" required value={newClassRoll} onChange={(e) => setNewClassRoll(parseInt(e.target.value) || 0)} className="w-full rounded border-gray-300 p-2 border" />
                    </div>
                    <button type="submit" className="w-full bg-teal-600 text-white font-bold py-2 rounded hover:bg-teal-700">Generate</button>
                </form>
            </div>
        </div>
      )}

      {/* Classroom Manager Modal */}
      {managedClassroom && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-4xl overflow-hidden animate-fade-in-up h-[90vh] flex flex-col">
                  {/* Header */}
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white shrink-0">
                      <div>
                          <h3 className="font-bold text-lg">{managedClassroom.grade} - {managedClassroom.stream}</h3>
                          <p className="text-slate-400 text-xs">Classroom Management</p>
                      </div>
                      <button onClick={() => setManagedClassroom(null)} className="hover:bg-slate-700 p-2 rounded transition-colors"><X className="w-5 h-5" /></button>
                  </div>

                  {/* Tabs */}
                  <div className="flex border-b border-gray-200 bg-gray-50">
                      <button 
                          onClick={() => setManageTab('students')}
                          className={`flex-1 py-3 text-sm font-bold border-b-2 transition-colors ${manageTab === 'students' ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                      >
                          Student Codes
                      </button>
                      <button 
                          onClick={() => { setManageTab('performance'); setManageView('subjects'); }}
                          className={`flex-1 py-3 text-sm font-bold border-b-2 transition-colors ${manageTab === 'performance' ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                      >
                          Subject Performance
                      </button>
                      <button 
                          onClick={() => setManageTab('forum')}
                          className={`flex-1 py-3 text-sm font-bold border-b-2 transition-colors ${manageTab === 'forum' ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                      >
                          Discussion Forum
                      </button>
                  </div>

                  {/* Content Area */}
                  <div className="flex-1 overflow-y-auto p-0 bg-white relative">

                      {/* TAB 1: STUDENT CODES */}
                      {manageTab === 'students' && (
                          <div className="p-0">
                              <div className="print-header hidden p-4">
                                  <h1 className="text-xl font-bold">Student Access Codes</h1>
                                  <p>Class: {managedClassroom.grade} - {managedClassroom.stream}</p>
                                  <hr className="my-2"/>
                              </div>
                              <div className="p-4 flex justify-end">
                                  <button onClick={handlePrintCodes} className="bg-slate-100 text-slate-700 px-3 py-1.5 rounded text-sm font-bold hover:bg-slate-200 flex items-center gap-2">
                                      <BookOpen className="w-4 h-4" /> Print Codes
                                  </button>
                              </div>
                              <table className="w-full text-sm text-left">
                                  <thead className="bg-gray-50 text-gray-500 font-bold uppercase text-xs sticky top-0">
                                      <tr>
                                          <th className="px-6 py-3 border-b">Index</th>
                                          <th className="px-6 py-3 border-b">Code</th>
                                          <th className="px-6 py-3 border-b">Name</th>
                                          <th className="px-6 py-3 border-b text-right">Actions</th>
                                      </tr>
                                  </thead>
                                  <tbody className="divide-y divide-gray-100">
                                      {managedClassroom.students.map((student) => (
                                          <tr key={student.code} className="hover:bg-gray-50">
                                              <td className="px-6 py-3 font-medium text-gray-900">#{student.index}</td>
                                              <td className="px-6 py-3 font-mono text-teal-700 font-bold tracking-wider">{student.code}</td>
                                              <td className="px-6 py-3 text-gray-400 italic">{student.name || "______________________"}</td>
                                              <td className="px-6 py-3 text-right">
                                                  <button 
                                                    onClick={() => openDmModal(student)}
                                                    className="bg-blue-50 text-blue-600 hover:bg-blue-100 px-2 py-1 rounded text-xs font-bold flex items-center gap-1 ml-auto"
                                                  >
                                                      <MessageCircle className="w-3 h-3" /> Message
                                                  </button>
                                              </td>
                                          </tr>
                                      ))}
                                  </tbody>
                              </table>
                          </div>
                      )}

                      {/* TAB 2: PERFORMANCE */}
                      {manageTab === 'performance' && (
                          <div className="p-6 h-full">

                              {/* VIEW: SUBJECT LIST */}
                              {manageView === 'subjects' && (
                                  <div className="animate-fade-in">
                                      <h3 className="text-lg font-bold text-gray-800 mb-4">Select a Subject</h3>
                                      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                                          {managedClassroom.subjects.length === 0 ? (
                                              <div className="col-span-full text-center py-10 text-gray-400 italic bg-gray-50 rounded-lg border border-dashed">
                                                  No subjects added to this class yet.
                                              </div>
                                          ) : (
                                              managedClassroom.subjects.map(subject => (
                                                  <button 
                                                      key={subject}
                                                      onClick={() => loadAssignmentsForSubject(subject)}
                                                      className="p-4 bg-white border border-gray-200 rounded-xl hover:border-teal-500 hover:shadow-md transition-all text-left group"
                                                  >
                                                      <h4 className="font-bold text-slate-700 group-hover:text-teal-700">{subject}</h4>
                                                      <div className="flex items-center text-xs text-gray-400 mt-2">
                                                          View Assignments <ChevronRight className="w-3 h-3 ml-1" />
                                                      </div>
                                                  </button>
                                              ))
                                          )}
                                      </div>
                                  </div>
                              )}

                              {/* VIEW: ASSIGNMENT LIST */}
                              {manageView === 'assignments' && (
                                  <div className="animate-fade-in h-full flex flex-col">
                                      <button onClick={() => setManageView('subjects')} className="flex items-center text-sm text-gray-500 hover:text-gray-800 mb-4 w-fit">
                                          <ArrowLeft className="w-4 h-4 mr-1" /> Back to Subjects
                                      </button>
                                      <h3 className="text-lg font-bold text-gray-800 mb-4">{selectedSubjectForStats} Assignments</h3>

                                      <div className="overflow-y-auto flex-1">
                                          {assignmentList.length === 0 ? (
                                              <div className="text-center py-10 text-gray-400 italic bg-gray-50 rounded-lg border border-dashed">
                                                  No assignments found for this subject.
                                              </div>
                                          ) : (
                                              <div className="space-y-3">
                                                  {assignmentList.map(assign => (
                                                      <div key={assign.id} onClick={() => loadResultsForAssignment(assign)} className="p-4 bg-white border border-gray-200 rounded-xl hover:border-teal-500 cursor-pointer transition-all flex justify-between items-center group">
                                                          <div>
                                                              <h4 className="font-bold text-slate-700">{assign.topic}</h4>
                                                              <p className="text-xs text-gray-500">{new Date(assign.createdAt).toLocaleDateString()} • {assign.questions.length} Questions</p>
                                                          </div>
                                                          <ChevronRight className="w-5 h-5 text-gray-300 group-hover:text-teal-500" />
                                                      </div>
                                                  ))}
                                              </div>
                                          )}
                                      </div>
                                  </div>
                              )}

                              {/* VIEW: RESULT LIST */}
                              {manageView === 'results' && selectedAssignmentForStats && (
                                  <div className="animate-fade-in h-full flex flex-col">
                                      <button onClick={() => setManageView('assignments')} className="flex items-center text-sm text-gray-500 hover:text-gray-800 mb-4 w-fit">
                                          <ArrowLeft className="w-4 h-4 mr-1" /> Back to Assignments
                                      </button>
                                      <div className="flex justify-between items-center mb-4">
                                          <div>
                                              <h3 className="text-lg font-bold text-gray-800">{selectedAssignmentForStats.topic}</h3>
                                              <p className="text-xs text-gray-500">Student Results</p>
                                          </div>
                                      </div>

                                      <div className="overflow-hidden border border-gray-200 rounded-lg">
                                          <table className="w-full text-sm text-left">
                                              <thead className="bg-gray-50 text-gray-500 font-bold uppercase text-xs">
                                                  <tr>
                                                      <th className="px-6 py-3">Student Name</th>
                                                      <th className="px-6 py-3">Score</th>
                                                      <th className="px-6 py-3 text-right">Feedback</th>
                                                  </tr>
                                              </thead>
                                              <tbody className="divide-y divide-gray-100">
                                                  {currentAssignmentResults.map((result) => (
                                                      <tr key={result.id} className="hover:bg-gray-50">
                                                          <td className="px-6 py-3 font-medium text-gray-900">
                                                              {result.studentName}
                                                              <div className="text-[10px] text-gray-400">{new Date(result.dateTaken).toLocaleDateString()}</div>
                                                          </td>
                                                          <td className="px-6 py-3">
                                                              <span className={`px-2 py-1 rounded text-xs font-bold ${result.score/result.total >= 0.5 ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                                                  {result.score}/{result.total}
                                                              </span>
                                                          </td>
                                                          <td className="px-6 py-3 text-right">
                                                              <button 
                                                                  onClick={() => openFeedbackModal(result)}
                                                                  className={`inline-flex items-center gap-1 text-xs font-bold px-3 py-1.5 rounded transition-colors ${result.feedback ? 'bg-blue-50 text-blue-600 hover:bg-blue-100' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                                                              >
                                                                  <MessageSquare className="w-3 h-3" />
                                                                  {result.feedback ? 'Edit Feedback' : 'Give Feedback'}
                                                              </button>
                                                          </td>
                                                      </tr>
                                                  ))}
                                                  {currentAssignmentResults.length === 0 && (
                                                      <tr><td colSpan={3} className="px-6 py-8 text-center text-gray-400">No students have completed this assignment yet.</td></tr>
                                                  )}
                                              </tbody>
                                          </table>
                                      </div>
                                  </div>
                              )}
                          </div>
                      )}

                      {/* TAB 3: DISCUSSION FORUM */}
                      {manageTab === 'forum' && (
                          <div className="p-6 h-full flex flex-col">
                              <h3 className="text-lg font-bold text-gray-800 mb-4">Class Discussion Forum</h3>

                              {/* New Post Form */}
                              <form onSubmit={handleCreateForumPost} className="bg-slate-50 p-4 rounded-xl border border-gray-200 mb-6">
                                  <input 
                                      type="text" 
                                      placeholder="Discussion Title" 
                                      className="w-full mb-2 p-2 rounded border border-gray-300 text-sm font-bold"
                                      value={forumPostTitle}
                                      onChange={e => setForumPostTitle(e.target.value)}
                                      required
                                  />
                                  <textarea 
                                      rows={2} 
                                      placeholder="Start a discussion or make an announcement..." 
                                      className="w-full p-2 rounded border border-gray-300 text-sm mb-2"
                                      value={forumPostContent}
                                      onChange={e => setForumPostContent(e.target.value)}
                                      required
                                  ></textarea>
                                  <div className="text-right">
                                      <button type="submit" className="bg-slate-900 text-white px-4 py-1.5 rounded text-xs font-bold hover:bg-slate-800">Post to Class</button>
                                  </div>
                              </form>

                              {/* Posts List */}
                              <div className="flex-1 overflow-y-auto space-y-4">
                                  {managedClassroom.forumPosts && managedClassroom.forumPosts.length > 0 ? (
                                      managedClassroom.forumPosts.map(post => (
                                          <div key={post.id} className="border border-gray-200 rounded-xl p-4 bg-white">
                                              <div className="flex justify-between items-start mb-2">
                                                  <div>
                                                      <h4 className="font-bold text-teal-800">{post.title}</h4>
                                                      <p className="text-xs text-gray-500">Posted by {post.authorName} • {new Date(post.timestamp).toLocaleDateString()}</p>
                                                  </div>
                                                  <span className="text-xs bg-gray-100 px-2 py-1 rounded text-gray-600">{post.replies.length} replies</span>
                                              </div>
                                              <p className="text-sm text-gray-700 mb-4">{post.content}</p>

                                              {/* Replies */}
                                              {post.replies.length > 0 && (
                                                  <div className="bg-gray-50 rounded p-3 mb-3 space-y-2">
                                                      {post.replies.map(reply => (
                                                          <div key={reply.id} className="text-xs border-l-2 border-gray-300 pl-2">
                                                              <span className={`font-bold ${reply.authorRole === 'teacher' ? 'text-teal-600' : 'text-blue-600'}`}>
                                                                  {reply.authorName}
                                                                  {reply.authorRole === 'teacher' && <span className="ml-1 text-[9px] bg-teal-100 text-teal-800 px-1 rounded uppercase">Teacher</span>}
                                                              </span>
                                                              <p className="text-gray-600">{reply.content}</p>
                                                          </div>
                                                      ))}
                                                  </div>
                                              )}

                                              {/* Reply Input */}
                                              {activePostId === post.id ? (
                                                  <div className="flex gap-2">
                                                      <input 
                                                          type="text" 
                                                          className="flex-1 text-sm border border-gray-300 rounded px-2 py-1"
                                                          placeholder="Write a reply..."
                                                          value={replyContent}
                                                          onChange={e => setReplyContent(e.target.value)}
                                                      />
                                                      <button onClick={() => handleReplyToPost(post.id)} className="bg-teal-600 text-white px-3 py-1 rounded text-xs font-bold">Reply</button>
                                                      <button onClick={() => setActivePostId(null)} className="text-gray-500 text-xs">Cancel</button>
                                                  </div>
                                              ) : (
                                                  <button onClick={() => setActivePostId(post.id)} className="text-teal-600 text-xs font-bold flex items-center gap-1 hover:underline">
                                                      <Reply className="w-3 h-3" /> Reply
                                                  </button>
                                              )}
                                          </div>
                                      ))
                                  ) : (
                                      <div className="text-center text-gray-400 py-10">No discussions yet.</div>
                                  )}
                              </div>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}

      {/* Feedback Modal */}
      {feedbackModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white">
                      <h3 className="font-bold">Feedback for {feedbackModal.name}</h3>
                      <button onClick={() => setFeedbackModal(null)}><X className="w-5 h-5" /></button>
                  </div>
                  <div className="p-6">
                      <label className="block text-sm font-medium text-gray-700 mb-2">Teacher's Comment</label>
                      <textarea 
                          rows={4}
                          className="w-full rounded-lg border border-gray-300 p-3 text-sm focus:ring-2 focus:ring-teal-500 focus:border-transparent"
                          placeholder="Write your feedback here..."
                          value={feedbackInput}
                          onChange={(e) => setFeedbackInput(e.target.value)}
                      ></textarea>
                  </div>
                  <div className="p-6 border-t border-gray-100 bg-gray-50 flex justify-end gap-2">
                      <button onClick={() => setFeedbackModal(null)} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded font-medium text-sm">Cancel</button>
                      <button onClick={saveFeedback} className="px-4 py-2 bg-teal-600 text-white rounded font-bold text-sm hover:bg-teal-700">Save Feedback</button>
                  </div>
              </div>
          </div>
      )}

      {/* DM Modal */}
      {dmModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white">
                      <h3 className="font-bold">Message {dmModal.studentName}</h3>
                      <button onClick={() => setDmModal(null)}><X className="w-5 h-5" /></button>
                  </div>
                  <div className="p-6">
                      <label className="block text-sm font-medium text-gray-700 mb-2">Message</label>
                      <textarea 
                          rows={4}
                          className="w-full rounded-lg border border-gray-300 p-3 text-sm focus:ring-2 focus:ring-teal-500 focus:border-transparent"
                          placeholder="Type your message..."
                          value={dmInput}
                          onChange={(e) => setDmInput(e.target.value)}
                      ></textarea>
                  </div>
                  <div className="p-6 border-t border-gray-100 bg-gray-50 flex justify-end gap-2">
                      <button onClick={() => setDmModal(null)} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded font-medium text-sm">Cancel</button>
                      <button onClick={sendDm} className="px-4 py-2 bg-blue-600 text-white rounded font-bold text-sm hover:bg-blue-700 flex items-center gap-2">
                          <Send className="w-3 h-3" /> Send
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Dashboard;

