            </button>

            <div className="w-full h-px bg-gray-200 my-2 md:hidden"></div>

            <button 
                onClick={handleAssignToClass} 
                disabled={isGuest} 
                className={`flex items-center gap-2 px-6 py-3 rounded-md transition-colors shadow-sm font-medium border ${isGuest ? 'bg-gray-100 text-gray-400 border-gray-200 cursor-not-allowed' : 'bg-teal-600 text-white border-teal-600 hover:bg-teal-700'}`}
