                      <button onClick={() => setShowClassSelector(false)}><X className="w-4 h-4"/></button>
                  </div>
                  <div className="p-2 max-h-80 overflow-y-auto">
                      {classrooms.map(cls => (
                          <button 
                              key={cls.id}
                              onClick={() => confirmAssignment(cls.id)}
