                    {currentPlan.learnerNotes ? (
                        <div className="prose prose-slate max-w-none bg-yellow-50/50 p-8 rounded-xl border border-yellow-200 shadow-sm">
                            <pre className="whitespace-pre-wrap font-sans text-base leading-relaxed text-slate-700">{currentPlan.learnerNotes}</pre>
                        </div>
                    ) : (
                        <div className="text-center py-10 text-gray-500 italic">
                            No notes generated for this plan.
                        </div>
                    )}
                </div>
            )}

            {/* VIEW 3: QUESTIONS */}
            {activeTab === 'questions' && (
                <div className="space-y-8">
                    <div className="flex justify-between items-center border-b border-gray-200 pb-4">
                        <h2 className="text-2xl font-bold text-slate-800">Assessment Questions</h2>
                        <span className="bg-teal-100 text-teal-800 text-xs px-3 py-1 rounded-full font-bold">
                            {currentPlan.structuredQuestions?.length || 0} Items
                        </span>
                    </div>

                    {currentPlan.structuredQuestions && currentPlan.structuredQuestions.length > 0 ? (
                        <div className="space-y-6">
                            {currentPlan.structuredQuestions.map((q, idx) => (
                                <div key={idx} className="bg-slate-50 border border-slate-200 p-5 rounded-lg">
                                    <div className="flex gap-3">
                                        <span className="font-bold text-teal-600 whitespace-nowrap">Q{idx + 1}.</span>
                                        <div className="flex-1">
                                            <p className="font-medium text-slate-800 mb-3">{q.question}</p>

                                            {q.image && (
                                                <img src={q.image} alt="Question" className="max-h-48 rounded-lg mb-3 border border-gray-200" />
                                            )}

                                            {q.type === 'mcq' && q.options ? (
                                                <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mb-4">
                                                    {q.options.map((opt, i) => (
                                                        <div key={i} className="flex items-center gap-2 p-2 bg-white rounded border border-gray-200 text-sm">
                                                            <span className="w-5 h-5 rounded-full border border-gray-300 flex items-center justify-center text-xs text-gray-500 font-bold">
                                                                {String.fromCharCode(65 + i)}
                                                            </span>
                                                            {opt}
                                                        </div>
                                                    ))}
                                                </div>
                                            ) : (
                                                <div className="h-16 border-b border-gray-300 border-dashed mb-4"></div>
                                            )}

                                            <div className="bg-green-50 p-3 rounded border border-green-100 text-sm">
                                                <p className="text-green-800 font-bold text-xs uppercase mb-1">Correct Answer</p>
                                                <p className="text-gray-700">{q.correctAnswer}</p>
                                                {q.explanation && <p className="text-gray-500 mt-1 text-xs italic">{q.explanation}</p>}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="text-center py-12 text-gray-400 border-2 border-dashed border-gray-200 rounded-xl">
                            No questions generated yet.
                        </div>
                    )}

                    {/* Actions Footer */}
                    <div className="border-t border-gray-200 pt-6 mt-8 no-print">
                        <div className="flex flex-wrap justify-center gap-4">
                            <button 
                                onClick={handleGenerateQuestions} 
                                disabled={loadingQuestions} 
                                className="flex items-center gap-2 bg-white border border-teal-600 text-teal-600 px-4 py-2 rounded-lg hover:bg-teal-50 text-sm font-bold transition-colors disabled:opacity-50"
                            >
                                {loadingQuestions ? <Loader2 className="w-4 h-4 animate-spin" /> : <RefreshCw className="w-4 h-4" />} 
                                Regenerate MCQs
                            </button>
                            <button 
                                onClick={handleAddStructuredQuestions} 
                                disabled={loadingQuestions} 
                                className="flex items-center gap-2 bg-white border border-blue-600 text-blue-600 px-4 py-2 rounded-lg hover:bg-blue-50 text-sm font-bold transition-colors disabled:opacity-50"
                            >
                                {loadingQuestions ? <Loader2 className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4" />} 
                                Add Structured Qs
                            </button>

                            <div className="w-px h-10 bg-gray-300 mx-2 hidden md:block"></div>

                            <button 
                                onClick={handleAssignToClass} 
                                disabled={isGuest} 
                                className={`flex items-center gap-2 px-6 py-2 rounded-lg font-bold text-white shadow-md transition-transform active:scale-95 ${isGuest ? 'bg-gray-400 cursor-not-allowed' : 'bg-teal-600 hover:bg-teal-700'}`}
                            >
                                {isGuest ? <Lock className="w-4 h-4" /> : <Send className="w-4 h-4" />}
                                {isGuest ? "Sign In to Assign" : "Assign to Class"}
                            </button>
                        </div>
                    </div>
                </div>
            )}

        </div>
      </div>

      {/* Class Selector Modal */}
      {showClassSelector && (
          <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-sm overflow-hidden animate-fade-in-up">
                  <div className="bg-slate-900 px-4 py-3 text-white flex justify-between items-center">
                      <h3 className="font-bold text-sm">Select Classroom</h3>
                      <button onClick={() => setShowClassSelector(false)}><X className="w-4 h-4"/></button>
                  </div>
                  <div className="p-2 max-h-80 overflow-y-auto">
                      {classrooms.map(cls => (
                          <button 
                              key={cls.id}
                              onClick={() => confirmAssignment(cls.id)}
                              className="w-full text-left p-3 hover:bg-slate-50 border-b border-gray-100 last:border-0 transition-colors"
                          >
                              <div className="font-bold text-slate-800">{cls.grade} - {cls.stream}</div>
                              <div className="text-xs text-slate-500">{cls.students.length} Students</div>
                          </button>
                      ))}
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default LessonPlanDisplay;

import React, { useState, useEffect } from 'react';
import { Student, Classroom, Assignment, StudentResult, SharedNote, QuizQuestion } from '../types';
import { authenticateStudent, updateStudentName, getAssignmentsByClassId, getStudentResults, saveStudentResult, getStudentNotes } from '../services/storageService';
import { LogIn, BookOpen, CheckCircle, Clock, ChevronRight, FileText, AlertCircle, Play, Loader2 } from 'lucide-react';

const StudentPortal: React.FC = () => {
  const [view, setView] = useState<'login' | 'dashboard' | 'quiz'>('login');
  const [accessCode, setAccessCode] = useState('');
  const [student, setStudent] = useState<Student | null>(null);
  const [classroom, setClassroom] = useState<Classroom | null>(null);
  const [studentName, setStudentName] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Data
  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [results, setResults] = useState<StudentResult[]>([]);
  const [notes, setNotes] = useState<SharedNote[]>([]);

  // Quiz State
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [quizQuestions, setQuizQuestions] = useState<QuizQuestion[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!accessCode) return;

    const result = authenticateStudent(accessCode.toUpperCase());
    if (result) {
      setStudent(result.student);
      setClassroom(result.classroom);
      if (result.student.name) {
        loadStudentData(result.student.code, result.classroom.id);
        setView('dashboard');
      }
    } else {
      setError("Invalid Access Code.");
    }
  };

  const handleNameUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (student && classroom && studentName.trim()) {
      const updated = updateStudentName(classroom.id, student.code, studentName);
      if (updated) {
        setStudent(updated);
        loadStudentData(updated.code, classroom.id);
        setView('dashboard');
      }
    }
  };

  const loadStudentData = (code: string, classId: string) => {
    const classAssignments = getAssignmentsByClassId(classId);
    const studentResults = getStudentResults(code);
    const classNotes = getStudentNotes(classId);

    setAssignments(classAssignments);
    setResults(studentResults);
    setNotes(classNotes);
  };

  const startQuiz = (assignment: Assignment) => {
    setActiveAssignment(assignment);
    setQuizQuestions(assignment.questions);
    setCurrentQuestionIndex(0);
    setSelectedAnswers({});
    setView('quiz');
  };

  const handleAnswerSelect = (answer: string) => {
      setSelectedAnswers(prev => ({
          ...prev,
          [currentQuestionIndex]: answer
      }));
  };

  const nextQuestion = () => {
      if (currentQuestionIndex < quizQuestions.length - 1) {
          setCurrentQuestionIndex(prev => prev + 1);
      }
  };

  const prevQuestion = () => {
      if (currentQuestionIndex > 0) {
          setCurrentQuestionIndex(prev => prev - 1);
      }
  };

  const submitQuiz = () => {
      if (!student || !activeAssignment) return;

      setIsSubmitting(true);

      let score = 0;
      quizQuestions.forEach((q, idx) => {
          const userAnswer = selectedAnswers[idx];
          if (userAnswer === q.correctAnswer) {
              score++;
          } else if (q.type === 'structured' && userAnswer?.toLowerCase().trim() === q.correctAnswer.toLowerCase().trim()) {
              score++;
          }
      });

      const result: StudentResult = {
          id: crypto.randomUUID(),
          assignmentId: activeAssignment.id,
          studentCode: student.code,
          studentName: student.name || 'Student',
          score: score,
          total: quizQuestions.length,
          attempts: 1,
          answers: selectedAnswers,
          dateTaken: new Date().toISOString()
      };

      saveStudentResult(result);
      if (classroom) loadStudentData(student.code, classroom.id);

      setIsSubmitting(false);
      setView('dashboard');
  };

  const allQuestionsAnswered = quizQuestions.length > 0 && Object.keys(selectedAnswers).length === quizQuestions.length;

  // --- RENDER HELPERS ---

  if (view === 'login') {
      return (
          <div className="min-h-[80vh] flex flex-col items-center justify-center p-4 bg-gray-50 font-sans">
              <div className="bg-white p-8 rounded-xl shadow-md w-full max-w-md border border-gray-200">
                  <div className="text-center mb-8">
                      <div className="bg-teal-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                          <BookOpen className="w-8 h-8 text-teal-600" />
                      </div>
                      <h2 className="text-2xl font-bold text-gray-800">Student Portal</h2>
                      <p className="text-gray-500 text-sm mt-1">Access your class materials</p>
                  </div>

                  {student && !student.name ? (
                      <form onSubmit={handleNameUpdate} className="space-y-6">
                          <div className="bg-blue-50 p-4 rounded-md text-sm text-blue-700">
                              Please update your profile with your full name to continue.
                          </div>
                          <div>
                              <label className="block text-sm font-medium text-gray-700 mb-1">Full Name</label>
                              <input 
                                  type="text" 
                                  required
                                  className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border px-3"
                                  value={studentName}
                                  onChange={e => setStudentName(e.target.value)}
                                  placeholder="e.g. John Doe"
                              />
                          </div>
                          <button type="submit" className="w-full bg-teal-600 text-white py-2.5 rounded-md font-medium hover:bg-teal-700 transition-colors">
                              Update Profile
                          </button>
                      </form>
                  ) : (
                      <form onSubmit={handleLogin} className="space-y-6">
                          {error && <div className="bg-red-50 text-red-700 p-3 rounded-md text-sm flex items-center gap-2 border border-red-200"><AlertCircle className="w-4 h-4"/> {error}</div>}
                          <div>
                              <label className="block text-sm font-medium text-gray-700 mb-1">Access Code</label>
                              <input 
                                  type="text" 
                                  required
                                  className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border px-3 text-center uppercase tracking-widest font-mono"
                                  value={accessCode}
                                  onChange={e => setAccessCode(e.target.value)}
                                  placeholder="XXXXXX"
                                  maxLength={6}
                              />
                          </div>
                          <button type="submit" className="w-full bg-teal-600 text-white py-2.5 rounded-md font-medium hover:bg-teal-700 transition-colors flex justify-center items-center gap-2">
                              <LogIn className="w-4 h-4" /> Enter Classroom
                          </button>
                      </form>
                  )}
              </div>
          </div>
      );
  }

  if (view === 'quiz' && activeAssignment) {
      const question = quizQuestions[currentQuestionIndex];
      const progress = ((currentQuestionIndex + 1) / quizQuestions.length) * 100;

      return (
          <div className="min-h-screen bg-gray-50 text-slate-800 font-sans pb-12">
              {/* Header */}
              <div className="bg-white border-b border-gray-200 px-4 py-4 sticky top-0 z-10 shadow-sm">
                  <div className="max-w-3xl mx-auto flex justify-between items-center">
                      <div>
                          <h2 className="font-bold text-gray-800">{activeAssignment.topic}</h2>
                          <p className="text-xs text-gray-500">{activeAssignment.subject}</p>
                      </div>
                      <div className="text-sm font-medium text-gray-500">
                          Question {currentQuestionIndex + 1} of {quizQuestions.length}
                      </div>
                  </div>
              </div>

              {/* Progress */}
              <div className="w-full h-1 bg-gray-200">
                  <div className="h-full bg-teal-600 transition-all duration-300" style={{ width: `${progress}%` }}></div>
              </div>

              {/* Content */}
              <div className="max-w-3xl mx-auto p-6 mt-6">
                  <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-8">
                      <p className="text-lg font-medium text-gray-900 mb-6 leading-relaxed">
                          {question.question}
                      </p>

                      {question.image && (
                          <div className="mb-6 rounded-lg overflow-hidden border border-gray-200">
                              <img src={question.image} alt="Question Visual" className="max-h-64 object-contain mx-auto" />
                          </div>
                      )}

                      {question.type === 'mcq' && question.options ? (
                          <div className="space-y-3">
                              {question.options.map((opt, idx) => (
                                  <label 
                                      key={idx} 
                                      className={`flex items-center p-4 rounded-lg border transition-all cursor-pointer hover:bg-gray-50
                                      ${selectedAnswers[currentQuestionIndex] === opt 
                                          ? 'border-teal-500 bg-teal-50 ring-1 ring-teal-500' 
                                          : 'border-gray-200'}`}
                                  >
                                      <input 
                                          type="radio" 
                                          name={`question-${question.id}`} 
                                          className="h-4 w-4 text-teal-600 focus:ring-teal-500 border-gray-300"
                                          value={opt}
                                          checked={selectedAnswers[currentQuestionIndex] === opt}
                                          onChange={() => handleAnswerSelect(opt)}
                                      />
                                      <span className="ml-3 text-gray-700">{opt}</span>
                                  </label>
                              ))}
                          </div>
                      ) : (
                          <textarea 
                              className="w-full p-4 rounded-lg border border-gray-300 focus:ring-2 focus:ring-teal-500 focus:border-transparent min-h-[120px]" 
                              placeholder="Type your answer here..."
                              value={selectedAnswers[currentQuestionIndex] || ''}
                              onChange={(e) => handleAnswerSelect(e.target.value)}
                          />
                      )}
                  </div>

                  {/* Footer Actions */}
                  <div className="mt-8 flex justify-between items-center">
                      <button 
                          onClick={() => {
                              if(confirm("Exit quiz? Progress will be lost.")) setView('dashboard');
                          }} 
                          className="text-gray-500 hover:text-gray-700 font-medium text-sm"
                      >
                          Quit Quiz
                      </button>

                      <div className="flex gap-3">
                          {currentQuestionIndex > 0 && (
                              <button onClick={prevQuestion} className="px-4 py-2 rounded-md border border-gray-300 bg-white text-gray-700 hover:bg-gray-50 font-medium">
                                  Previous
                              </button>
                          )}

                          {currentQuestionIndex < quizQuestions.length - 1 ? (
                              <button 
                                  onClick={nextQuestion} 
                                  className="px-6 py-2 rounded-md bg-teal-600 text-white hover:bg-teal-700 font-medium flex items-center gap-2"
                              >
                                  Next <ChevronRight className="w-4 h-4" />
                              </button>
                          ) : (
                              <button 
                                  onClick={submitQuiz} 
                                  disabled={!allQuestionsAnswered || isSubmitting} 
                                  className="px-6 py-2 rounded-md bg-green-600 text-white hover:bg-green-700 font-medium flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
                              >
                                  {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin"/> : <CheckCircle className="w-4 h-4" />}
                                  Submit Quiz
                              </button>
                          )}
                      </div>
                  </div>
              </div>
          </div>
      );
  }

  // Dashboard View (Formal)
  return (
      <div className="min-h-screen bg-gray-50 font-sans pb-12">
          {/* Header */}
          <div className="bg-white border-b border-gray-200">
              <div className="container mx-auto max-w-6xl px-4 py-6">
                  <div className="flex justify-between items-center">
                      <div>
                          <h1 className="text-2xl font-bold text-gray-900">Student Portal</h1>
                          <p className="text-gray-500 text-sm mt-1">
                              Welcome, <span className="font-semibold text-gray-800">{student?.name}</span> ({student?.code})
                          </p>
                      </div>
                      <div className="text-right">
                          <p className="text-sm font-medium text-gray-900">{classroom?.grade} - {classroom?.stream}</p>
                          <button 
                              onClick={() => { setStudent(null); setView('login'); }}
                              className="text-xs text-red-600 hover:text-red-800 mt-1 hover:underline"
                          >
                              Sign Out
                          </button>
                      </div>
                  </div>
              </div>
          </div>

          <div className="container mx-auto max-w-6xl px-4 mt-8">
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

                  {/* Left Column: Assignments & Results */}
                  <div className="lg:col-span-2 space-y-8">
                      {/* Active Assignments */}
                      <section>
                          <h3 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
                              <Clock className="w-5 h-5 text-teal-600" /> Pending Assignments
                          </h3>

                          <div className="space-y-3">
                              {assignments.filter(a => !results.some(r => r.assignmentId === a.id)).length === 0 ? (
                                  <div className="bg-white p-6 rounded-lg border border-gray-200 text-center text-gray-500">
                                      No pending assignments. Great job!
                                  </div>
                              ) : (
                                  assignments.filter(a => !results.some(r => r.assignmentId === a.id)).map(assign => (
                                      <div key={assign.id} className="bg-white p-5 rounded-lg border border-gray-200 shadow-sm hover:shadow-md transition-shadow flex justify-between items-center">
                                          <div>
                                              <div className="flex items-center gap-2 mb-1">
                                                  <span className="bg-blue-100 text-blue-800 text-xs px-2 py-0.5 rounded font-medium">{assign.subject}</span>
                                              </div>
                                              <h4 className="font-semibold text-gray-900">{assign.topic}</h4>
                                              <p className="text-sm text-gray-500 mt-1">{assign.questions.length} Questions</p>
                                          </div>
                                          <button 
                                              onClick={() => startQuiz(assign)}
                                              className="bg-teal-600 text-white px-4 py-2 rounded-md text-sm font-medium hover:bg-teal-700 transition-colors flex items-center gap-2"
                                          >
                                              Start <Play className="w-4 h-4" />
                                          </button>
                                      </div>
                                  ))
                              )}
                          </div>
                      </section>

                      {/* Completed Results */}
                      <section>
                          <h3 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
                              <CheckCircle className="w-5 h-5 text-green-600" /> Completed
                          </h3>
                          <div className="bg-white rounded-lg border border-gray-200 shadow-sm overflow-hidden">
                              {results.length === 0 ? (
                                  <div className="p-6 text-center text-gray-500">
                                      No completed quizzes yet.
                                  </div>
                              ) : (
                                  <table className="w-full text-sm text-left">
                                      <thead className="bg-gray-50 text-gray-600 font-medium border-b border-gray-200">
                                          <tr>
                                              <th className="px-6 py-3">Topic</th>
                                              <th className="px-6 py-3">Date</th>
                                              <th className="px-6 py-3">Score</th>
                                              <th className="px-6 py-3 text-right">Action</th>
                                          </tr>
                                      </thead>
                                      <tbody className="divide-y divide-gray-100">
                                          {results.map(result => {
                                              const assignment = assignments.find(a => a.id === result.assignmentId);
                                              const percentage = Math.round((result.score / result.total) * 100);
                                              return (
                                                  <tr key={result.id} className="hover:bg-gray-50">
                                                      <td className="px-6 py-4">
                                                          <div className="font-medium text-gray-900">{assignment?.topic || 'Unknown'}</div>
                                                          <div className="text-xs text-gray-500">{assignment?.subject}</div>
                                                          {result.feedback && (
                                                              <div className="mt-1 text-xs text-blue-600 bg-blue-50 px-2 py-1 rounded inline-block">
                                                                  Feedback: {result.feedback}
                                                              </div>
                                                          )}
                                                      </td>
                                                      <td className="px-6 py-4 text-gray-500">
                                                          {new Date(result.dateTaken).toLocaleDateString()}
                                                      </td>
                                                      <td className="px-6 py-4">
                                                          <span className={`px-2 py-1 rounded text-xs font-bold ${percentage >= 70 ? 'bg-green-100 text-green-800' : percentage >= 50 ? 'bg-yellow-100 text-yellow-800' : 'bg-red-100 text-red-800'}`}>
                                                              {percentage}% ({result.score}/{result.total})
                                                          </span>
                                                      </td>
                                                      <td className="px-6 py-4 text-right">
                                                          {/* Future: View details */}
                                                      </td>
                                                  </tr>
                                              );
                                          })}
                                      </tbody>
                                  </table>
                              )}
                          </div>
                      </section>
                  </div>

                  {/* Right Column: Resources */}
                  <div className="space-y-6">
                      <div className="bg-white p-6 rounded-lg border border-gray-200 shadow-sm">
                          <h3 className="font-bold text-gray-800 mb-4 flex items-center gap-2">
                              <FileText className="w-5 h-5 text-indigo-600" /> Class Resources
                          </h3>
                          <div className="space-y-3">
                              {notes.length === 0 ? (
                                  <p className="text-gray-500 text-sm italic">No resources shared yet.</p>
                              ) : (
                                  notes.map(note => (
                                      <div key={note.id} className="p-3 bg-gray-50 rounded border border-gray-100 hover:border-indigo-200 transition-colors cursor-pointer">
                                          <div className="text-xs font-bold text-indigo-600 mb-1 uppercase">{note.subject}</div>
                                          <h4 className="text-sm font-medium text-gray-900 mb-1">{note.title}</h4>
                                          <p className="text-xs text-gray-500 line-clamp-2">{note.content}</p>
                                      </div>
                                  ))
                              )}
                          </div>
                      </div>
                  </div>
              </div>
          </div>
      </div>
  );
};

export default StudentPortal;

import { GoogleGenAI, Chat } from "@google/genai";
import { LessonPlanData, LessonDefinition, NewsItem, QuizQuestion } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MODEL_ID = "gemini-3-flash-preview";

// Helper to sanitize JSON response
const cleanJson = (text: string): string => {
  // Remove markdown code blocks (```json ... ```)
  let cleaned = text.replace(/```json\s*/g, '').replace(/```\s*$/, '');
  // Remove markdown code blocks (``` ... ```) - generic
  cleaned = cleaned.replace(/```\s*/g, '');

  // Find first { or [
  const firstBrace = cleaned.indexOf('{');
  const firstBracket = cleaned.indexOf('[');

  let startIndex = -1;
  if (firstBrace !== -1 && firstBracket !== -1) {
    startIndex = Math.min(firstBrace, firstBracket);
  } else if (firstBrace !== -1) {
    startIndex = firstBrace;
  } else if (firstBracket !== -1) {
    startIndex = firstBracket;
  }

  if (startIndex !== -1) {
    cleaned = cleaned.substring(startIndex);
  }

  // Find last } or ]
  const lastBrace = cleaned.lastIndexOf('}');
  const lastBracket = cleaned.lastIndexOf(']');

  let endIndex = -1;
  if (lastBrace !== -1 && lastBracket !== -1) {
    endIndex = Math.max(lastBrace, lastBracket);
  } else if (lastBrace !== -1) {
    endIndex = lastBrace;
  } else if (lastBracket !== -1) {
    endIndex = lastBracket;
  }

  if (endIndex !== -1) {
    cleaned = cleaned.substring(0, endIndex + 1);
  }

  return cleaned.trim();
};

