  const [activeView, setActiveView] = useState<'overview' | 'classrooms' | 'profile' | 'saved_plans'>('overview');
  const [sidebarOpen, setSidebarOpen] = useState(true); 
  const [classrooms, setClassrooms] = useState<Classroom[]>([]);
  const [totalPlans, setTotalPlans] = useState(0);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [showNotifications, setShowNotifications] = useState(false);

  // Profile Form Data
  const [formData, setFormData] = useState<UserProfile>(profile);
  const [message, setMessage] = useState('');

  // Classroom Modals
  const [showAddClassModal, setShowAddClassModal] = useState(false);
  const [managedClassroom, setManagedClassroom] = useState<Classroom | null>(null);

  // Classroom Management State
  const [manageTab, setManageTab] = useState<'students' | 'performance' | 'forum'>('students');
  const [manageView, setManageView] = useState<'subjects' | 'assignments' | 'results'>('subjects');
  const [selectedSubjectForStats, setSelectedSubjectForStats] = useState<string>('');
  const [selectedAssignmentForStats, setSelectedAssignmentForStats] = useState<Assignment | null>(null);
  const [currentAssignmentResults, setCurrentAssignmentResults] = useState<StudentResult[]>([]);
  const [assignmentList, setAssignmentList] = useState<Assignment[]>([]);
  const [feedbackModal, setFeedbackModal] = useState<{resultId: string, name: string, currentFeedback: string} | null>(null);
  const [feedbackInput, setFeedbackInput] = useState('');

  // Direct Message Modal
  const [dmModal, setDmModal] = useState<{studentName: string, studentCode: string} | null>(null);
  const [dmInput, setDmInput] = useState('');

  // Forum State
  const [forumPostTitle, setForumPostTitle] = useState('');
  const [forumPostContent, setForumPostContent] = useState('');
  const [replyContent, setReplyContent] = useState('');
  const [activePostId, setActivePostId] = useState<string | null>(null);

  // New Class Form
  const [newClassGrade, setNewClassGrade] = useState<Grade>(Grade.GRADE_7);
  const [newClassStream, setNewClassStream] = useState('');
  const [newClassRoll, setNewClassRoll] = useState<number>(40);

  // Subject Mgmt (Quick Add)
  const [addingSubjectTo, setAddingSubjectTo] = useState<string | null>(null);
  const [selectedSubject, setSelectedSubject] = useState<Subject>(Subject.MATHEMATICS);

  useEffect(() => {
    loadData();
    // Poll for notifications
    const interval = setInterval(() => {
        setNotifications(getNotifications(profile.email));
    }, 10000);
    return () => clearInterval(interval);
  }, []);

  const loadData = () => {
    const cls = getClassrooms();
    setClassrooms(cls);
    const plans = getSavedPlans();
    setTotalPlans(plans.length);
    setNotifications(getNotifications(profile.email));
  };

  const handleCreateClassroom = (e: React.FormEvent) => {
    e.preventDefault();
    if (newClassStream && newClassRoll > 0) {
        createClassroom(newClassGrade, newClassStream, newClassRoll);
        loadData();
        setShowAddClassModal(false);
        setNewClassStream('');
        setNewClassRoll(40);
    }
  };

  const handleDeleteClassroom = (id: string) => {
    if (confirm('Are you sure? All student data will be lost.')) {
        deleteClassroom(id);
        loadData();
    }
  };

  const handleSubmitProfile = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdate(formData);
    setMessage('Profile updated successfully!');
    setTimeout(() => setMessage(''), 3000);
  };

  const handleAddSubject = (classId: string) => {
      addSubjectToClassroom(classId, selectedSubject);
      setAddingSubjectTo(null);
      loadData();
  };

  const handleRemoveSubject = (classId: string, subject: string) => {
      if (confirm(`Remove ${subject}?`)) {
          removeSubjectFromClassroom(classId, subject);
          loadData();
      }
  };

  const handlePrintCodes = () => window.print();

  // --- Classroom Management Logic ---

  const openClassroomManager = (cls: Classroom) => {
      setManagedClassroom(cls);
      setManageTab('students');
      setManageView('subjects');
  };

  const loadAssignmentsForSubject = (subject: string) => {
      if (!managedClassroom) return;
      const allAssignments = getAssignmentsByClassId(managedClassroom.id);
      const filtered = allAssignments.filter(a => a.subject === subject);
      setAssignmentList(filtered);
      setSelectedSubjectForStats(subject);
      setManageView('assignments');
  };

  const loadResultsForAssignment = (assignment: Assignment) => {
      const results = getAssignmentResults(assignment.id);
      setCurrentAssignmentResults(results);
      setSelectedAssignmentForStats(assignment);
      setManageView('results');
  };

  const openFeedbackModal = (result: StudentResult) => {
      setFeedbackInput(result.feedback || '');
      setFeedbackModal({
          resultId: result.id,
          name: result.studentName,
          currentFeedback: result.feedback || ''
      });
  };

  const saveFeedback = () => {
      if (!feedbackModal) return;
      updateStudentResultFeedback(feedbackModal.resultId, feedbackInput);
      // Update local state
      const updatedResults = currentAssignmentResults.map(r => 
          r.id === feedbackModal.resultId ? {...r, feedback: feedbackInput} : r
      );
      setCurrentAssignmentResults(updatedResults);
      setFeedbackModal(null);
  };

  // --- Messaging ---

  const openDmModal = (student: {name?: string, code: string}) => {
      setDmModal({
          studentName: student.name || `Student ${student.code}`,
          studentCode: student.code
      });
      setDmInput('');
  };

  const sendDm = () => {
      if (!dmModal || !dmInput.trim()) return;

      const msg: DirectMessage = {
          id: crypto.randomUUID(),
          senderId: profile.email,
          senderName: profile.name,
          receiverId: dmModal.studentCode,
          content: dmInput,
          timestamp: new Date().toISOString(),
          read: false,
          isFromTeacher: true
      };

      sendDirectMessage(msg);
      setDmModal(null);
      alert("Message sent successfully!");
  };

  // --- Forum ---

  const handleCreateForumPost = (e: React.FormEvent) => {
      e.preventDefault();
      if (!managedClassroom || !forumPostTitle.trim() || !forumPostContent.trim()) return;

      const newPost: ForumPost = {
          id: crypto.randomUUID(),
          authorName: profile.name,
          title: forumPostTitle,
          content: forumPostContent,
          timestamp: new Date().toISOString(),
          replies: []
      };

      createForumPost(managedClassroom.id, newPost);

      // Update local state
      const updatedClass = {
          ...managedClassroom,
          forumPosts: [newPost, ...(managedClassroom.forumPosts || [])]
      };
      setManagedClassroom(updatedClass);

      setForumPostTitle('');
      setForumPostContent('');
  };

  const handleReplyToPost = (postId: string) => {
      if (!managedClassroom || !replyContent.trim()) return;

      const reply: ForumReply = {
          id: crypto.randomUUID(),
          authorName: profile.name,
          authorRole: 'teacher',
          content: replyContent,
          timestamp: new Date().toISOString()
      };

      addForumReply(managedClassroom.id, postId, reply);

      // Update local state
      const updatedPosts = managedClassroom.forumPosts.map(p => {
          if (p.id === postId) {
              return { ...p, replies: [...p.replies, reply] };
          }
          return p;
      });

      setManagedClassroom({ ...managedClassroom, forumPosts: updatedPosts });
      setReplyContent('');
      setActivePostId(null);
  };

  const handleNotificationClick = (notif: AppNotification) => {
      markNotificationRead(notif.id);
      setNotifications(prev => prev.map(n => n.id === notif.id ? {...n, read: true} : n));
  };

  const unreadCount = notifications.filter(n => !n.read).length;

  return (
    <div className="flex min-h-screen bg-slate-50 font-sans text-slate-800">

      {/* Mobile Backdrop */}
      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden" 
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar - Fixed */}
      <aside className={`fixed inset-y-0 left-0 z-50 w-64 bg-slate-900 text-slate-300 transition-transform duration-300 ease-in-out ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} shadow-xl lg:translate-x-0`}>
        <div className="flex items-center justify-between h-16 px-6 bg-slate-950 text-white font-bold text-xl tracking-tight border-b border-slate-800">
          <div className="flex items-center">
            <BookOpen className="w-6 h-6 mr-2 text-teal-500" />
            <span>Mwalimu<span className="text-teal-500">Admin</span></span>
          </div>
          <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-slate-400 hover:text-white p-1">
            <X className="w-5 h-5" />
          </button>
        </div>

        <nav className="p-4 space-y-2 mt-4">
          <button 
            onClick={() => {setActiveView('overview'); setSidebarOpen(false);}}
            className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${activeView === 'overview' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'}`}
          >
            <Home className="w-5 h-5 mr-3" /> Dashboard
          </button>

          <button 
            onClick={() => {setActiveView('classrooms'); setSidebarOpen(false);}}
            className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${activeView === 'classrooms' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'}`}
          >
            <Users className="w-5 h-5 mr-3" /> Classrooms
          </button>

          <button 
            onClick={() => {setActiveView('profile'); setSidebarOpen(false);}}
            className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${activeView === 'profile' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'}`}
          >
            <User className="w-5 h-5 mr-3" /> Profile
          </button>

          <div className="pt-4 mt-4 border-t border-slate-800">
            <p className="px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">System</p>
            <button className="flex items-center w-full px-4 py-2 text-sm text-slate-400 hover:text-white transition-colors">
              <Settings className="w-4 h-4 mr-3" /> Settings
            </button>
          </div>
        </nav>
      </aside>

      {/* Main Content Area */}
      <div className={`flex-1 flex flex-col transition-all duration-300 lg:ml-64`}>

        {/* Top Header */}
        <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 lg:px-8 sticky top-0 z-40 shadow-sm">
          <button 
            onClick={() => setSidebarOpen(!sidebarOpen)} 
            className="p-2 text-gray-500 hover:bg-gray-100 rounded-md focus:outline-none focus:ring-2 focus:ring-teal-500 lg:hidden"
            title="Toggle Sidebar"
          >
            <Menu className="w-6 h-6" />
          </button>

          <div className="flex items-center gap-4 ml-auto relative">
            {/* Notifications */}
            <div className="relative">
                <button 
                    onClick={() => setShowNotifications(!showNotifications)}
                    className="p-2 text-gray-400 hover:text-gray-600 relative focus:outline-none"
                >
                    <Bell className="w-5 h-5" />
                    {unreadCount > 0 && <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>}
                </button>

                {showNotifications && (
                    <div className="absolute right-0 mt-2 w-80 bg-white rounded-xl shadow-xl border border-gray-200 overflow-hidden z-50 animate-fade-in-up">
                        <div className="bg-slate-50 px-4 py-3 border-b border-gray-100 font-bold text-sm text-gray-700 flex justify-between">
                            <span>Notifications</span>
                            <span className="text-xs bg-slate-200 px-2 py-0.5 rounded-full">{unreadCount} New</span>
                        </div>
                        <div className="max-h-80 overflow-y-auto">
                            {notifications.length === 0 ? (
                                <div className="p-6 text-center text-gray-400 text-sm">No notifications</div>
                            ) : (
                                notifications.map(notif => (
                                    <div 
                                        key={notif.id} 
                                        onClick={() => handleNotificationClick(notif)}
                                        className={`p-4 border-b border-gray-50 hover:bg-slate-50 cursor-pointer transition-colors ${!notif.read ? 'bg-blue-50/50' : ''}`}
                                    >
                                        <div className="flex justify-between items-start mb-1">
                                            <span className="font-bold text-xs uppercase text-teal-600">{notif.type}</span>
                                            <span className="text-[10px] text-gray-400">{new Date(notif.timestamp).toLocaleDateString()}</span>
                                        </div>
                                        <h4 className={`text-sm ${!notif.read ? 'font-bold text-slate-800' : 'font-medium text-slate-600'}`}>{notif.title}</h4>
                                        <p className="text-xs text-gray-500 mt-1 line-clamp-2">{notif.message}</p>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                )}
            </div>

            <div className="flex items-center gap-2 pl-4 border-l border-gray-200">
              <div className="w-8 h-8 bg-slate-800 rounded-full flex items-center justify-center text-white text-xs font-bold">
                {profile.name.charAt(0)}
              </div>
              <span className="text-sm font-medium text-gray-700 hidden md:block">{profile.name}</span>
              <ChevronDown className="w-4 h-4 text-gray-400" />
            </div>
          </div>
        </header>

        {/* Content Body */}
        <main className="p-4 lg:p-8">

          {/* Subscription/Info Alert */}
          <div className="bg-amber-100 border-l-4 border-amber-500 text-amber-800 p-4 mb-8 rounded-r shadow-sm flex justify-between items-start">
            <div className="flex gap-3">
                <span className="bg-amber-200 p-1 rounded text-amber-700 font-bold px-2">i</span>
                <p className="text-sm">Welcome to MwalimuPlanner. Create classrooms to generate student codes. Ensure your profile is up to date.</p>
            </div>
            <button className="text-amber-600 hover:text-amber-900"><X className="w-4 h-4" /></button>
          </div>

          {/* VIEW: OVERVIEW */}
          {activeView === 'overview' && (
            <div className="space-y-8 animate-fade-in">
                <div className="flex justify-between items-center">
                    <h2 className="text-xl text-gray-600 font-light uppercase tracking-wide">Dashboard Overview</h2>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <StatCard icon={FileText} label="Total Plans" value={totalPlans} color="bg-teal-500" />
                    <StatCard icon={Users} label="Active Classrooms" value={classrooms.length} color="bg-blue-500" />
                    <StatCard icon={Users} label="Total Students" value={classrooms.reduce((acc, c) => acc + c.students.length, 0)} color="bg-indigo-500" />
                </div>

                {/* Recent Activity Table style */}
                <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                    <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center">
                        <h3 className="font-semibold text-gray-700">Recent Classrooms</h3>
                    </div>
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-gray-50 text-gray-500 font-bold uppercase text-xs">
                                <tr>
                                    <th className="px-6 py-3">Grade & Stream</th>
                                    <th className="px-6 py-3">Students</th>
                                    <th className="px-6 py-3">Subjects</th>
                                    <th className="px-6 py-3 text-right">Action</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {classrooms.slice(0, 5).map(c => (
                                    <tr key={c.id} className="hover:bg-gray-50">
                                        <td className="px-6 py-4 font-medium text-gray-900">{c.grade} - {c.stream}</td>
                                        <td className="px-6 py-4 text-gray-500">{c.students.length}</td>
                                        <td className="px-6 py-4 text-gray-500">
                                            {c.subjects.length > 0 ? (
                                                <div className="flex gap-1 flex-wrap">
                                                    {c.subjects.slice(0, 2).map(s => <span key={s} className="bg-blue-50 text-blue-700 px-2 py-0.5 rounded text-xs">{s}</span>)}
                                                    {c.subjects.length > 2 && <span className="text-xs text-gray-400">+{c.subjects.length - 2}</span>}
                                                </div>
                                            ) : <span className="text-gray-400 italic">None</span>}
                                        </td>
                                        <td className="px-6 py-4 text-right">
                                            <button onClick={() => { setActiveView('classrooms'); openClassroomManager(c); }} className="text-teal-600 hover:underline">View</button>
                                        </td>
                                    </tr>
                                ))}
                                {classrooms.length === 0 && (
                                    <tr><td colSpan={4} className="px-6 py-8 text-center text-gray-400">No classrooms found.</td></tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
          )}

          {/* VIEW: CLASSROOMS */}
          {activeView === 'classrooms' && (
            <div className="space-y-6 animate-fade-in">
                <div className="flex justify-between items-center mb-4">
                    <h2 className="text-xl text-gray-600 font-light uppercase tracking-wide">My Classrooms</h2>
                    <button onClick={() => setShowAddClassModal(true)} className="bg-teal-600 text-white px-4 py-2 rounded shadow hover:bg-teal-700 flex items-center gap-2 text-sm font-bold">
                        <Plus className="w-4 h-4" /> Add Classroom
                    </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {classrooms.map((room) => (
                        <div key={room.id} className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                            <div className="p-5 border-b border-gray-100 flex justify-between items-start">
                                <div>
                                    <h4 className="text-lg font-bold text-slate-800">{room.grade} <span className="text-gray-400">|</span> {room.stream}</h4>
                                    <div className="flex items-center gap-4 mt-2 text-xs text-gray-500 font-medium uppercase tracking-wide">
                                        <span className="flex items-center gap-1"><Users className="w-3 h-3" /> {room.students.length} Students</span>
                                    </div>
                                </div>
                                <div className="flex gap-2">
                                    <button onClick={() => openClassroomManager(room)} className="p-2 bg-gray-100 hover:bg-gray-200 rounded text-gray-600" title="View Students"><Eye className="w-4 h-4" /></button>
                                    <button onClick={() => handleDeleteClassroom(room.id)} className="p-2 bg-red-50 hover:bg-red-100 rounded text-red-600" title="Delete"><Trash2 className="w-4 h-4" /></button>
                                </div>
                            </div>
                            <div className="p-5 bg-slate-50 min-h-[100px]">
                                <div className="flex justify-between items-center mb-3">
                                    <h5 className="text-xs font-bold text-gray-400 uppercase">Subjects</h5>
                                    {addingSubjectTo === room.id ? (
                                        <div className="flex items-center gap-1">
                                            <select 
                                                value={selectedSubject} 
                                                onChange={(e) => setSelectedSubject(e.target.value as Subject)}
                                                className="text-xs border-gray-300 rounded shadow-sm py-1 w-32"
                                            >
                                                {Object.values(Subject).map(s => <option key={s} value={s}>{s}</option>)}
                                            </select>
                                            <button onClick={() => handleAddSubject(room.id)} className="bg-green-600 text-white p-1 rounded"><Check className="w-3 h-3" /></button>
                                            <button onClick={() => setAddingSubjectTo(null)} className="bg-gray-300 text-gray-700 p-1 rounded"><X className="w-3 h-3" /></button>
                                        </div>
                                    ) : (
                                        <button onClick={() => setAddingSubjectTo(room.id)} className="text-teal-600 text-xs font-bold hover:underline flex items-center gap-1"><Plus className="w-3 h-3" /> Add</button>
                                    )}
                                </div>
                                <div className="flex flex-wrap gap-2">
                                    {room.subjects.length > 0 ? room.subjects.map(sub => (
                                        <span key={sub} className="inline-flex items-center gap-1 bg-white border border-gray-200 text-gray-600 px-2 py-1 rounded text-xs font-medium">
                                            {sub}
                                            <button onClick={() => handleRemoveSubject(room.id, sub)} className="text-gray-400 hover:text-red-500"><X className="w-3 h-3" /></button>
                                        </span>
                                    )) : <span className="text-gray-400 text-xs italic">No subjects added.</span>}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
          )}

          {/* VIEW: PROFILE */}
          {activeView === 'profile' && (
            <div className="max-w-2xl animate-fade-in">
                <h2 className="text-xl text-gray-600 font-light uppercase tracking-wide mb-6">Profile Settings</h2>
                <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                    <form onSubmit={handleSubmitProfile} className="p-8 space-y-6">
                        {message && <div className="bg-green-50 text-green-700 p-3 rounded text-sm">{message}</div>}
                        <div className="grid grid-cols-1 gap-6">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Name</label>
                                <input type="text" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full rounded border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 p-2 border" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">School</label>
                                <input type="text" required value={formData.school} onChange={e => setFormData({...formData, school: e.target.value})} className="w-full rounded border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 p-2 border" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                                <input type="email" readOnly value={formData.email} className="w-full rounded border-gray-300 bg-gray-50 text-gray-500 p-2 border cursor-not-allowed" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Phone</label>
                                <input type="tel" required value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full rounded border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 p-2 border" />
                            </div>
                        </div>
                        <div className="pt-4 text-right">
                            <button type="submit" className="bg-slate-900 text-white px-6 py-2 rounded hover:bg-slate-800 transition-colors">Save Changes</button>
                        </div>
                    </form>
                </div>
            </div>
          )}

        </main>
      </div>

      {/* Add Class Modal */}
      {showAddClassModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white">
                    <h3 className="font-bold">New Classroom</h3>
                    <button onClick={() => setShowAddClassModal(false)}><X className="w-5 h-5" /></button>
                </div>
                <form onSubmit={handleCreateClassroom} className="p-6 space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Grade</label>
                        <select value={newClassGrade} onChange={(e) => setNewClassGrade(e.target.value as Grade)} className="w-full rounded border-gray-300 p-2 border">
                            {Object.values(Grade).map(g => <option key={g} value={g}>{g}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Stream</label>
                        <input type="text" required placeholder="e.g. Blue" value={newClassStream} onChange={(e) => setNewClassStream(e.target.value)} className="w-full rounded border-gray-300 p-2 border" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Roll</label>
                        <input type="number" min="1" max="100" required value={newClassRoll} onChange={(e) => setNewClassRoll(parseInt(e.target.value) || 0)} className="w-full rounded border-gray-300 p-2 border" />
                    </div>
                    <button type="submit" className="w-full bg-teal-600 text-white font-bold py-2 rounded hover:bg-teal-700">Generate</button>
                </form>
            </div>
        </div>
      )}

      {/* Classroom Manager Modal */}
      {managedClassroom && (
