  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_ID,
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json"
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from Gemini");

    // Clean and parse
    const cleanedText = cleanJson(text);
    return JSON.parse(cleanedText) as NewsItem[];
  } catch (error) {
    console.error("Gemini API Error (News):", error);
    // Return dummy news if API fails to avoid breaking UI
    return [
        {
            title: "TSC Updates Teacher Promotion Guidelines",
            summary: "The Teachers Service Commission has released new criteria for the promotion of teachers in C1 and C2 job groups.",
            source: "Education News",
            date: "Today",
            url: "#"
        },
        {
            title: "Ministry of Education Releases JS Capitation",
            summary: "Schools have started receiving capitation funds for Junior Schools to facilitate learning resources.",
            source: "Ministry of Education",
            date: "Yesterday",
            url: "#"
        }
    ];
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Student, Classroom, Assignment, StudentResult, SharedNote, QuizQuestion, DirectMessage, ForumPost, ForumReply, AppNotification } from '../types';
import { 
    authenticateStudent, updateStudentName, getAssignmentsByClassId, getStudentResults, 
    saveStudentResult, getStudentNotes, getDirectMessages, sendDirectMessage, markMessagesRead, 
    createForumPost, addForumReply, getClassrooms 
} from '../services/storageService';
import { generateStudentPerformanceReport } from '../services/geminiService';
import { 
    LogIn, BookOpen, CheckCircle, Clock, ChevronRight, FileText, AlertCircle, Play, 
    Loader2, Menu, Home, Layers, Book, List, CheckSquare, BarChart2, Mail, MessageSquare, 
    User, LogOut, X, Send, Reply, Bell, ChevronLeft, ChevronLast
} from 'lucide-react';

const StudentPortal: React.FC = () => {
  // Auth State
  const [view, setView] = useState<'login' | 'portal'>('login');
  const [accessCode, setAccessCode] = useState('');
  const [student, setStudent] = useState<Student | null>(null);
  const [classroom, setClassroom] = useState<Classroom | null>(null);
  const [studentName, setStudentName] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Portal UI State
  const [activeSection, setActiveSection] = useState<'dashboard' | 'notes' | 'textbooks' | 'all_assignments' | 'pending' | 'completed' | 'results' | 'inbox' | 'forum' | 'profile'>('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(true); // Mobile toggle
  const [isCollapsed, setIsCollapsed] = useState(false); // Desktop collapse

  // Data State
  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [results, setResults] = useState<StudentResult[]>([]);
  const [notes, setNotes] = useState<SharedNote[]>([]);
  const [messages, setMessages] = useState<DirectMessage[]>([]);
  const [forumPosts, setForumPosts] = useState<ForumPost[]>([]);

  // Quiz Execution State
  const [quizMode, setQuizMode] = useState(false);
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Timing State
  const [quizStartTime, setQuizStartTime] = useState<number>(0);
  const [questionStartTime, setQuestionStartTime] = useState<number>(0);
  const [timePerQuestion, setTimePerQuestion] = useState<Record<number, number>>({});

  // Messaging State
  const [newMessage, setNewMessage] = useState('');

  // Forum State
  const [newForumReply, setNewForumReply] = useState('');
  const [activeForumPostId, setActiveForumPostId] = useState<string | null>(null);

  // Notification Counts
  const pendingCount = assignments.filter(a => !results.some(r => r.assignmentId === a.id)).length;
  const unreadMsgCount = messages.filter(m => !m.read && m.receiverId === student?.code).length;

  // Polling for new messages
  useEffect(() => {
      if (student && view === 'portal') {
          const interval = setInterval(() => {
              loadStudentData(student.code, classroom!.id);
          }, 10000);
          return () => clearInterval(interval);
      }
  }, [student, view, classroom]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!accessCode) return;

    const result = authenticateStudent(accessCode.toUpperCase());
    if (result) {
      setStudent(result.student);
      setClassroom(result.classroom);
      if (result.student.name) {
        loadStudentData(result.student.code, result.classroom.id);
        setView('portal');
      }
    } else {
      setError("Invalid Access Code.");
    }
  };

  const handleNameUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (student && classroom && studentName.trim()) {
      const updated = updateStudentName(classroom.id, student.code, studentName);
      if (updated) {
        setStudent(updated);
        loadStudentData(updated.code, classroom.id);
        setView('portal');
      }
    }
  };

  const loadStudentData = (code: string, classId: string) => {
    const classAssignments = getAssignmentsByClassId(classId);
    const studentResults = getStudentResults(code);
    const classNotes = getStudentNotes(classId);
    const msgs = getDirectMessages(code);

    const refreshedResult = authenticateStudent(code);
    if (refreshedResult) {
        setClassroom(refreshedResult.classroom);
        setForumPosts(refreshedResult.classroom.forumPosts || []);
    }

    setAssignments(classAssignments);
    setResults(studentResults);
    setNotes(classNotes);
    setMessages(msgs);
  };

  // --- Quiz Functions ---
  const startQuiz = (assignment: Assignment) => {
    setActiveAssignment(assignment);
    setCurrentQuestionIndex(0);
    setSelectedAnswers({});
    setTimePerQuestion({});

    const now = Date.now();
    setQuizStartTime(now);
    setQuestionStartTime(now);

    setQuizMode(true);
    setSidebarOpen(false); // Mobile close
    if(window.innerWidth < 1024) setSidebarOpen(false);
  };

  const recordTimeForCurrentQuestion = () => {
      const now = Date.now();
      const timeSpent = (now - questionStartTime) / 1000; // in seconds

      setTimePerQuestion(prev => {
          // If returning to a question, add to existing time
          const existing = prev[currentQuestionIndex] || 0;
          return { ...prev, [currentQuestionIndex]: existing + timeSpent };
      });
      setQuestionStartTime(now); // Reset for next/prev question
  };

  const handleNextQuestion = () => {
      recordTimeForCurrentQuestion();
      setCurrentQuestionIndex(prev => prev + 1);
  };

  const handlePrevQuestion = () => {
      recordTimeForCurrentQuestion();
      setCurrentQuestionIndex(prev => prev - 1);
  };

  const handleAnswerSelect = (answer: string) => {
      setSelectedAnswers(prev => ({ ...prev, [currentQuestionIndex]: answer }));
  };

  const submitQuiz = async () => {
      if (!student || !activeAssignment) return;

      // Capture time for the last question
      recordTimeForCurrentQuestion();
      const totalTimeTaken = (Date.now() - quizStartTime) / 1000; // Total seconds

      setIsSubmitting(true);

      // Calculate Score
      let score = 0;
      activeAssignment.questions.forEach((q, idx) => {
          const userAnswer = selectedAnswers[idx];
          if (userAnswer === q.correctAnswer) score++;
          else if (q.type === 'structured' && userAnswer?.toLowerCase().trim() === q.correctAnswer.toLowerCase().trim()) score++;
      });

      // Generate AI Analysis
      let aiReport = "";
      try {
          // We pass the collected timePerQuestion state which has the accumulated seconds for each index
          aiReport = await generateStudentPerformanceReport(
              activeAssignment,
              selectedAnswers,
              score,
              totalTimeTaken,
              timePerQuestion
          );
      } catch (err) {
          console.error("AI Report Generation Failed", err);
          aiReport = "Analysis could not be generated at this time.";
      }

      const result: StudentResult = {
          id: crypto.randomUUID(),
          assignmentId: activeAssignment.id,
          studentCode: student.code,
          studentName: student.name || 'Student',
          score: score,
          total: activeAssignment.questions.length,
          attempts: 1,
          answers: selectedAnswers,
          dateTaken: new Date().toISOString(),
          timeTaken: totalTimeTaken,
          timePerQuestion: timePerQuestion,
          aiAnalysis: aiReport
      };

      saveStudentResult(result);

      // Send message to teacher about new submission
      const submissionMsg: DirectMessage = {
          id: crypto.randomUUID(),
          senderId: student.code,
          senderName: student.name || 'Student',
          receiverId: classroom?.userId || '',
          content: `I have submitted the assignment: ${activeAssignment.topic}. Score: ${score}/${activeAssignment.questions.length}.`,
          timestamp: new Date().toISOString(),
          read: false,
          isFromTeacher: false
      };
      if (classroom?.userId) sendDirectMessage(submissionMsg);

      if (classroom) loadStudentData(student.code, classroom.id);

      setIsSubmitting(false);
      setQuizMode(false);
      setActiveSection('results');
      setActiveAssignment(null);
  };

  // --- Messaging Functions ---
  const handleSendMessage = (e: React.FormEvent) => {
      e.preventDefault();
      if (!newMessage.trim() || !student || !classroom) return;

      const msg: DirectMessage = {
          id: crypto.randomUUID(),
          senderId: student.code,
          senderName: student.name || 'Student',
          receiverId: classroom.userId, // Teacher Email
          content: newMessage,
          timestamp: new Date().toISOString(),
          read: false,
          isFromTeacher: false
      };

      sendDirectMessage(msg);
      setNewMessage('');
      loadStudentData(student.code, classroom.id);
  };

  // --- Forum Functions ---
  const handleForumReply = (postId: string) => {
      if (!newForumReply.trim() || !student || !classroom) return;

      const reply: ForumReply = {
          id: crypto.randomUUID(),
          authorName: student.name || 'Student',
          authorRole: 'student',
          content: newForumReply,
          timestamp: new Date().toISOString()
      };

      addForumReply(classroom.id, postId, reply);
      setNewForumReply('');
      loadStudentData(student.code, classroom.id);
  };

  // --- Views ---

  if (view === 'login') {
      return (
          <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-gray-50 font-sans">
              <div className="bg-white p-8 rounded-xl shadow-xl w-full max-w-md border border-gray-200">
                  <div className="text-center mb-8">
                      <div className="bg-teal-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                          <BookOpen className="w-8 h-8 text-teal-600" />
                      </div>
                      <h2 className="text-2xl font-bold text-gray-800">Student Portal</h2>
                      <p className="text-gray-500 text-sm mt-1">Access your class materials</p>
                  </div>

                  {student && !student.name ? (
                      <form onSubmit={handleNameUpdate} className="space-y-6">
                          <div className="bg-blue-50 p-4 rounded-md text-sm text-blue-700">
                              Please update your profile with your full name to continue.
                          </div>
                          <div>
                              <label className="block text-sm font-medium text-gray-700 mb-1">Full Name</label>
                              <input 
                                  type="text" 
                                  required
                                  className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border px-3"
                                  value={studentName}
                                  onChange={e => setStudentName(e.target.value)}
                                  placeholder="e.g. John Doe"
                              />
                          </div>
                          <button type="submit" className="w-full bg-teal-600 text-white py-2.5 rounded-md font-medium hover:bg-teal-700 transition-colors">
                              Update Profile
                          </button>
                      </form>
                  ) : (
                      <form onSubmit={handleLogin} className="space-y-6">
                          {error && <div className="bg-red-50 text-red-700 p-3 rounded-md text-sm flex items-center gap-2 border border-red-200"><AlertCircle className="w-4 h-4"/> {error}</div>}
                          <div>
                              <label className="block text-sm font-medium text-gray-700 mb-1">Access Code</label>
                              <input 
                                  type="text" 
                                  required
                                  className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border px-3 text-center uppercase tracking-widest font-mono"
                                  value={accessCode}
                                  onChange={e => setAccessCode(e.target.value)}
                                  placeholder="XXXXXX"
                                  maxLength={6}
                              />
                          </div>
                          <button type="submit" className="w-full bg-teal-600 text-white py-2.5 rounded-md font-medium hover:bg-teal-700 transition-colors flex justify-center items-center gap-2">
                              <LogIn className="w-4 h-4" /> Enter Classroom
                          </button>
                      </form>
                  )}
              </div>
          </div>
      );
  }

  // Quiz Mode rendering
  if (quizMode && activeAssignment) {
      const question = activeAssignment.questions[currentQuestionIndex];
      const progress = ((currentQuestionIndex + 1) / activeAssignment.questions.length) * 100;
      const allAnswered = activeAssignment.questions.length > 0 && Object.keys(selectedAnswers).length === activeAssignment.questions.length;

      return (
          <div className="min-h-screen bg-gray-50 text-slate-800 font-sans pb-12">
              <div className="bg-white border-b border-gray-200 px-4 py-4 sticky top-0 z-10 shadow-sm">
                  <div className="max-w-3xl mx-auto flex justify-between items-center">
                      <div>
                          <h2 className="font-bold text-gray-800">{activeAssignment.topic}</h2>
                          <p className="text-xs text-gray-500">{activeAssignment.subject}</p>
                      </div>
                      <div className="text-sm font-medium text-gray-500">
                          Question {currentQuestionIndex + 1} of {activeAssignment.questions.length}
                      </div>
                  </div>
              </div>
              <div className="w-full h-1 bg-gray-200"><div className="h-full bg-teal-600 transition-all duration-300" style={{ width: `${progress}%` }}></div></div>
              <div className="max-w-3xl mx-auto p-6 mt-6">
                  {isSubmitting ? (
                      <div className="flex flex-col items-center justify-center py-20">
                          <Loader2 className="w-12 h-12 text-teal-600 animate-spin mb-4" />
                          <h3 className="text-xl font-bold text-gray-800">Submitting Answers...</h3>
                          <p className="text-gray-500 mt-2">Analyzing performance and generating report for your teacher.</p>
                      </div>
                  ) : (
                      <>
                          <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-8">
                              <p className="text-lg font-medium text-gray-900 mb-6 leading-relaxed">{question.question}</p>
                              {question.image && (
                                  <div className="mb-6 rounded-lg overflow-hidden border border-gray-200">
                                      <img src={question.image} alt="Question Visual" className="max-h-64 object-contain mx-auto" />
                                  </div>
                              )}
                              {question.type === 'mcq' && question.options ? (
                                  <div className="space-y-3">
                                      {question.options.map((opt, idx) => (
                                          <label key={idx} className={`flex items-center p-4 rounded-lg border transition-all cursor-pointer hover:bg-gray-50 ${selectedAnswers[currentQuestionIndex] === opt ? 'border-teal-500 bg-teal-50 ring-1 ring-teal-500' : 'border-gray-200'}`}>
                                              <input type="radio" name={`question-${question.id}`} className="h-4 w-4 text-teal-600 focus:ring-teal-500 border-gray-300" value={opt} checked={selectedAnswers[currentQuestionIndex] === opt} onChange={() => handleAnswerSelect(opt)} />
                                              <span className="ml-3 text-gray-700">{opt}</span>
                                          </label>
                                      ))}
                                  </div>
                              ) : (
                                  <textarea className="w-full p-4 rounded-lg border border-gray-300 focus:ring-2 focus:ring-teal-500 focus:border-transparent min-h-[120px]" placeholder="Type your answer here..." value={selectedAnswers[currentQuestionIndex] || ''} onChange={(e) => handleAnswerSelect(e.target.value)} />
                              )}
                          </div>
                          <div className="mt-8 flex justify-between items-center">
                              <button onClick={() => { if(confirm("Exit quiz? Progress will be lost.")) setQuizMode(false); }} className="text-gray-500 hover:text-gray-700 font-medium text-sm">Quit Quiz</button>
                              <div className="flex gap-3">
                                  {currentQuestionIndex > 0 && <button onClick={handlePrevQuestion} className="px-4 py-2 rounded-md border border-gray-300 bg-white text-gray-700 hover:bg-gray-50 font-medium">Previous</button>}
                                  {currentQuestionIndex < activeAssignment.questions.length - 1 ? (
                                      <button onClick={handleNextQuestion} className="px-6 py-2 rounded-md bg-teal-600 text-white hover:bg-teal-700 font-medium flex items-center gap-2">Next <ChevronRight className="w-4 h-4" /></button>
                                  ) : (
                                      <button onClick={submitQuiz} disabled={!allAnswered} className="px-6 py-2 rounded-md bg-green-600 text-white hover:bg-green-700 font-medium flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed">
                                          <CheckCircle className="w-4 h-4" /> Submit Quiz
                                      </button>
                                  )}
                              </div>
                          </div>
                      </>
                  )}
              </div>
          </div>
      );
  }

  // --- Helpers for Sidebar Items ---
  const SidebarItem = ({ 
      id, icon: Icon, label, badgeCount 
  }: { 
      id: string, icon: any, label: string, badgeCount?: number 
  }) => (
      <button 
          onClick={() => {setActiveSection(id as any); if(window.innerWidth < 1024) setSidebarOpen(false);}} 
          className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors group relative ${
              activeSection === id ? 'bg-teal-600 text-white shadow-md' : 'text-slate-300 hover:bg-slate-800 hover:text-white'
          }`}
          title={isCollapsed ? label : ''}
      >
          <Icon className={`w-5 h-5 flex-shrink-0 ${!isCollapsed && 'mr-3'}`} />
          {!isCollapsed && <span>{label}</span>}

          {/* Notification Badge */}
          {badgeCount && badgeCount > 0 ? (
              isCollapsed ? (
                  <span className="absolute top-2 right-2 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-slate-900"></span>
              ) : (
                  <span className="ml-auto bg-red-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full shadow-sm animate-pulse">
                      {badgeCount}
                  </span>
              )
          ) : null}
      </button>
  );

  // --- Main Dashboard Layout ---
  return (
      <div className="flex min-h-screen bg-slate-50 font-sans text-slate-800">
          {/* Mobile Backdrop */}
          {sidebarOpen && (
            <div 
              className="fixed inset-0 bg-black/50 z-40 lg:hidden" 
              onClick={() => setSidebarOpen(false)}
            />
          )}

          {/* Sidebar */}
          <aside className={`fixed inset-y-0 left-0 z-50 bg-slate-900 text-slate-300 transition-all duration-300 ease-in-out shadow-xl flex flex-col 
              ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} 
              lg:translate-x-0 
              ${isCollapsed ? 'w-20' : 'w-64'}
          `}>
              <div className={`flex items-center h-16 px-4 bg-slate-950 text-white font-bold text-xl tracking-tight border-b border-slate-800 ${isCollapsed ? 'justify-center' : 'justify-between'}`}>
                  {!isCollapsed ? (
                      <div className="flex items-center">
                          <BookOpen className="w-6 h-6 mr-2 text-teal-500" />
                          <span>Student<span className="text-teal-500">Portal</span></span>
                      </div>
                  ) : (
                      <BookOpen className="w-8 h-8 text-teal-500" />
                  )}
                  <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-slate-400 hover:text-white p-1"><X className="w-5 h-5" /></button>
              </div>

              <nav className="flex-1 overflow-y-auto p-3 space-y-1">
                  <SidebarItem id="dashboard" icon={Home} label="Dashboard" />

                  <div className={`mt-6 mb-2 px-4 text-xs font-bold text-slate-500 uppercase tracking-wider ${isCollapsed ? 'text-center' : ''}`}>
                      {isCollapsed ? '---' : 'Academics'}
                  </div>
                  <SidebarItem id="notes" icon={FileText} label="Lesson Notes" />
                  <SidebarItem id="textbooks" icon={Book} label="Class Textbooks" />

                  <div className={`mt-6 mb-2 px-4 text-xs font-bold text-slate-500 uppercase tracking-wider ${isCollapsed ? 'text-center' : ''}`}>
                      {isCollapsed ? '---' : 'Assignments'}
                  </div>
                  <SidebarItem id="all_assignments" icon={List} label="All Assignments" />
                  <SidebarItem id="pending" icon={Clock} label="Pending" badgeCount={pendingCount} />
                  <SidebarItem id="completed" icon={CheckSquare} label="Completed" />
                  <SidebarItem id="results" icon={BarChart2} label="Results" />

                  <div className={`mt-6 mb-2 px-4 text-xs font-bold text-slate-500 uppercase tracking-wider ${isCollapsed ? 'text-center' : ''}`}>
                      {isCollapsed ? '---' : 'Communication'}
                  </div>
                  <SidebarItem id="inbox" icon={Mail} label="My Inbox" badgeCount={unreadMsgCount} />
                  <SidebarItem id="forum" icon={MessageSquare} label="Discussion Forum" badgeCount={forumPosts.length > 0 ? 1 : 0} />

                  <div className={`mt-6 mb-2 px-4 text-xs font-bold text-slate-500 uppercase tracking-wider ${isCollapsed ? 'text-center' : ''}`}>
                      {isCollapsed ? '---' : 'Account'}
                  </div>
                  <SidebarItem id="profile" icon={User} label="My Profile" />
              </nav>

              <div className="p-4 border-t border-slate-800">
                  <button onClick={() => { setStudent(null); setView('login'); }} className={`flex items-center w-full px-4 py-2.5 text-sm font-medium rounded-lg text-red-400 hover:bg-slate-800 hover:text-red-300 transition-colors ${isCollapsed ? 'justify-center' : ''}`}>
                      <LogOut className={`w-5 h-5 ${!isCollapsed && 'mr-3'}`} />
                      {!isCollapsed && <span>Sign Out</span>}
                  </button>
                  <button 
                      onClick={() => setIsCollapsed(!isCollapsed)}
                      className="hidden lg:flex mt-2 w-full items-center justify-center p-2 text-slate-500 hover:text-white hover:bg-slate-800 rounded-lg transition-colors"
                  >
                      {isCollapsed ? <ChevronRight className="w-5 h-5"/> : <ChevronLeft className="w-5 h-5"/>}
                  </button>
              </div>
          </aside>

          {/* Main Content Area */}
          <div className={`flex-1 flex flex-col transition-all duration-300 ${isCollapsed ? 'lg:ml-20' : 'lg:ml-64'}`}>
              {/* Header */}
              <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 sticky top-0 z-40 shadow-sm">
                  <div className="flex items-center gap-3">
                      <button onClick={() => setSidebarOpen(!sidebarOpen)} className="lg:hidden p-2 text-gray-500 hover:bg-gray-100 rounded-md">
                          <Menu className="w-6 h-6" />
                      </button>
                      <h1 className="text-xl font-bold text-gray-800 hidden sm:block capitalize">
                          {activeSection.replace('_', ' ')}
                      </h1>
                  </div>
                  <div className="ml-auto flex items-center gap-4">
                      <div className="text-right hidden md:block">
                          <p className="text-sm font-bold text-gray-800">{student?.name || 'Student'}</p>
                          <p className="text-xs text-gray-500">{classroom?.grade} - {classroom?.stream}</p>
                      </div>
                      <div className="w-8 h-8 bg-teal-100 text-teal-700 rounded-full flex items-center justify-center font-bold border border-teal-200">
                          {student?.name?.charAt(0) || 'S'}
                      </div>
                  </div>
              </header>

              {/* Content Render */}
              <main className="p-4 lg:p-8 max-w-7xl mx-auto w-full">

                  {activeSection === 'dashboard' && (
                      <div className="space-y-6 animate-fade-in">
                          <h2 className="text-2xl font-bold text-gray-800">Overview</h2>
                          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                              <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition-shadow">
                                  <div className="flex items-center gap-3 mb-2">
                                      <div className="p-2 bg-blue-100 text-blue-600 rounded-lg"><Clock className="w-5 h-5"/></div>
                                      <h3 className="font-bold text-gray-700">Pending Assignments</h3>
                                  </div>
                                  <p className="text-3xl font-black text-gray-800">{pendingCount}</p>
                              </div>
                              <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition-shadow">
                                  <div className="flex items-center gap-3 mb-2">
                                      <div className="p-2 bg-green-100 text-green-600 rounded-lg"><CheckCircle className="w-5 h-5"/></div>
                                      <h3 className="font-bold text-gray-700">Completed</h3>
                                  </div>
                                  <p className="text-3xl font-black text-gray-800">{results.length}</p>
                              </div>
                              <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition-shadow">
                                  <div className="flex items-center gap-3 mb-2">
                                      <div className="p-2 bg-purple-100 text-purple-600 rounded-lg"><Mail className="w-5 h-5"/></div>
                                      <h3 className="font-bold text-gray-700">New Messages</h3>
                                  </div>
                                  <p className="text-3xl font-black text-gray-800">{unreadMsgCount}</p>
                              </div>
                          </div>
                      </div>
                  )}

                  {/* Other sections rendered as before... */}
                  {(activeSection === 'all_assignments' || activeSection === 'pending' || activeSection === 'completed') && (
                      <div className="space-y-6 animate-fade-in">
                          <div className="space-y-3">
                              {assignments
                                  .filter(a => {
                                      const isCompleted = results.some(r => r.assignmentId === a.id);
                                      if (activeSection === 'pending') return !isCompleted;
                                      if (activeSection === 'completed') return isCompleted;
                                      return true;
                                  })
                                  .map(assign => {
                                      const isCompleted = results.some(r => r.assignmentId === assign.id);
                                      return (
                                          <div key={assign.id} className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                                              <div>
                                                  <div className="flex items-center gap-2 mb-1">
                                                      <span className="bg-slate-100 text-slate-700 text-xs px-2 py-0.5 rounded font-bold uppercase">{assign.subject}</span>
                                                      {isCompleted && <span className="bg-green-100 text-green-700 text-xs px-2 py-0.5 rounded font-bold flex items-center gap-1"><CheckCircle className="w-3 h-3"/> Done</span>}
                                                  </div>
                                                  <h4 className="font-bold text-lg text-gray-900">{assign.topic}</h4>
                                                  <p className="text-sm text-gray-500">{assign.questions.length} Questions • Posted {new Date(assign.createdAt).toLocaleDateString()}</p>
                                              </div>
                                              {!isCompleted ? (
                                                  <button onClick={() => startQuiz(assign)} className="bg-teal-600 text-white px-5 py-2 rounded-lg font-bold text-sm hover:bg-teal-700 transition-colors flex items-center gap-2">
                                                      Start Quiz <Play className="w-4 h-4" />
                                                  </button>
                                              ) : (
                                                  <button disabled className="bg-gray-100 text-gray-400 px-5 py-2 rounded-lg font-bold text-sm cursor-not-allowed border border-gray-200">
                                                      Completed
                                                  </button>
                                              )}
                                          </div>
                                      );
                                  })
                              }
                              {assignments.length === 0 && <p className="text-gray-500 italic">No assignments found.</p>}
                          </div>
                      </div>
                  )}

                  {(activeSection === 'notes' || activeSection === 'textbooks') && (
                      <div className="space-y-6 animate-fade-in">
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                              {notes.length === 0 ? (
                                  <p className="text-gray-500 italic col-span-full">No resources shared yet.</p>
                              ) : (
                                  notes.map(note => (
                                      <div key={note.id} className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition-shadow">
                                          <div className="flex justify-between items-start mb-2">
                                              <span className="bg-indigo-50 text-indigo-700 text-xs px-2 py-0.5 rounded font-bold uppercase">{note.subject}</span>
                                              <span className="text-xs text-gray-400">{new Date(note.dateShared).toLocaleDateString()}</span>
                                          </div>
                                          <h4 className="font-bold text-lg text-gray-900 mb-2">{note.title}</h4>
                                          <p className="text-sm text-gray-600 line-clamp-3 mb-4">{note.content}</p>
                                          <button className="text-teal-600 text-sm font-bold hover:underline flex items-center gap-1">
                                              Read Full Note <ChevronRight className="w-4 h-4"/>
                                          </button>
                                      </div>
                                  ))
                              )}
                          </div>
                      </div>
                  )}

                  {activeSection === 'results' && (
                      <div className="space-y-6 animate-fade-in">
                          <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                              <table className="w-full text-sm text-left">
                                  <thead className="bg-gray-50 text-gray-600 font-bold border-b border-gray-200">
                                      <tr>
                                          <th className="px-6 py-4">Assignment</th>
                                          <th className="px-6 py-4">Date</th>
                                          <th className="px-6 py-4">Score</th>
                                          <th className="px-6 py-4">Feedback</th>
                                      </tr>
                                  </thead>
                                  <tbody className="divide-y divide-gray-100">
                                      {results.map(result => {
                                          const assign = assignments.find(a => a.id === result.assignmentId);
                                          const pct = Math.round((result.score/result.total)*100);
                                          return (
                                              <tr key={result.id} className="hover:bg-gray-50">
                                                  <td className="px-6 py-4">
                                                      <div className="font-bold text-gray-900">{assign?.topic || 'Unknown'}</div>
                                                      <div className="text-xs text-gray-500">{assign?.subject}</div>
                                                  </td>
                                                  <td className="px-6 py-4 text-gray-500">{new Date(result.dateTaken).toLocaleDateString()}</td>
                                                  <td className="px-6 py-4">
                                                      <span className={`px-2 py-1 rounded text-xs font-bold ${pct >= 70 ? 'bg-green-100 text-green-700' : pct >= 50 ? 'bg-yellow-100 text-yellow-700' : 'bg-red-100 text-red-700'}`}>
                                                          {pct}% ({result.score}/{result.total})
                                                      </span>
                                                  </td>
                                                  <td className="px-6 py-4 text-gray-600 italic">
                                                      {result.feedback || <span className="text-gray-400">No feedback yet</span>}
                                                  </td>
                                              </tr>
                                          );
                                      })}
                                      {results.length === 0 && <tr><td colSpan={4} className="px-6 py-8 text-center text-gray-400">No results found.</td></tr>}
                                  </tbody>
                              </table>
                          </div>
                      </div>
                  )}

                  {activeSection === 'inbox' && (
                      <div className="flex flex-col h-[calc(100vh-8rem)] bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden animate-fade-in">
                          <div className="p-4 border-b border-gray-200 bg-gray-50 flex justify-between items-center">
                              <h3 className="font-bold text-gray-800 flex items-center gap-2"><Mail className="w-5 h-5"/> My Inbox</h3>
                              <span className="text-xs text-gray-500">Direct Messages with Teacher</span>
                          </div>
                          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50">
                              {messages.length === 0 ? (
                                  <div className="text-center py-10 text-gray-400">No messages yet. Start a conversation!</div>
                              ) : (
                                  messages.map(msg => (
                                      <div key={msg.id} className={`flex ${msg.senderId === student?.code ? 'justify-end' : 'justify-start'}`}>
                                          <div className={`max-w-[80%] rounded-xl p-3 shadow-sm ${msg.senderId === student?.code ? 'bg-teal-600 text-white rounded-br-none' : 'bg-white text-gray-800 border border-gray-200 rounded-bl-none'}`}>
                                              <p className="text-sm">{msg.content}</p>
                                              <p className={`text-[10px] mt-1 text-right ${msg.senderId === student?.code ? 'text-teal-200' : 'text-gray-400'}`}>{new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                                          </div>
                                      </div>
                                  ))
                              )}
                          </div>
                          <div className="p-4 border-t border-gray-200 bg-white">
                              <form onSubmit={handleSendMessage} className="flex gap-2">
                                  <input 
                                      type="text" 
                                      className="flex-1 border border-gray-300 rounded-lg px-4 py-2 text-sm focus:outline-none focus:border-teal-500"
                                      placeholder="Type a message to your teacher..."
                                      value={newMessage}
                                      onChange={e => setNewMessage(e.target.value)}
                                  />
                                  <button type="submit" disabled={!newMessage.trim()} className="bg-teal-600 text-white p-2 rounded-lg hover:bg-teal-700 disabled:opacity-50 transition-colors">
                                      <Send className="w-5 h-5" />
                                  </button>
                              </form>
                          </div>
                      </div>
                  )}

                  {activeSection === 'forum' && (
                      <div className="space-y-6 animate-fade-in">
                          {/* Forum Code remains same as original */}
                          {forumPosts.length === 0 ? (
                                  <div className="text-center py-10 text-gray-400 bg-white rounded-xl border border-gray-200 border-dashed">No discussions started yet.</div>
                              ) : (
                                  forumPosts.map(post => (
                                      <div key={post.id} className="bg-white border border-gray-200 rounded-xl p-5 shadow-sm">
                                          <div className="flex justify-between items-start mb-2">
                                              <div>
                                                  <h3 className="font-bold text-lg text-teal-800">{post.title}</h3>
                                                  <p className="text-xs text-gray-500">Posted by {post.authorName} • {new Date(post.timestamp).toLocaleDateString()}</p>
                                              </div>
                                              <span className="bg-gray-100 text-gray-600 text-xs px-2 py-1 rounded font-medium">{post.replies.length} replies</span>
                                          </div>
                                          <p className="text-gray-700 mb-4 text-sm">{post.content}</p>

                                          {/* Replies */}
                                          {post.replies.length > 0 && (
                                              <div className="bg-gray-50 rounded-lg p-3 space-y-3 mb-3 border border-gray-100">
                                                  {post.replies.map(reply => (
                                                      <div key={reply.id} className="text-sm border-l-2 border-teal-200 pl-3">
                                                          <div className="flex justify-between">
                                                              <span className={`font-bold text-xs ${reply.authorRole === 'teacher' ? 'text-teal-600' : 'text-blue-600'}`}>{reply.authorName} {reply.authorRole === 'teacher' && '(Teacher)'}</span>
                                                              <span className="text-[10px] text-gray-400">{new Date(reply.timestamp).toLocaleDateString()}</span>
                                                          </div>
                                                          <p className="text-gray-600 mt-1">{reply.content}</p>
                                                      </div>
                                                  ))}
                                              </div>
                                          )}

                                          {/* Reply Input */}
                                          {activeForumPostId === post.id ? (
                                              <div className="flex gap-2 mt-2">
                                                  <input 
                                                      type="text" 
                                                      className="flex-1 border border-gray-300 rounded px-3 py-1.5 text-sm focus:border-teal-500 outline-none"
                                                      placeholder="Write a reply..."
                                                      value={newForumReply}
                                                      onChange={e => setNewForumReply(e.target.value)}
                                                  />
                                                  <button onClick={() => handleForumReply(post.id)} className="bg-teal-600 text-white px-3 py-1.5 rounded text-xs font-bold">Reply</button>
                                                  <button onClick={() => setActiveForumPostId(null)} className="text-gray-500 text-xs hover:text-gray-700">Cancel</button>
                                              </div>
                                          ) : (
                                              <button onClick={() => setActiveForumPostId(post.id)} className="text-teal-600 text-xs font-bold flex items-center gap-1 hover:underline">
                                                  <Reply className="w-3 h-3"/> Reply to discussion
                                              </button>
                                          )}
                                      </div>
                                  ))
                              )}
                      </div>
                  )}

                  {activeSection === 'profile' && (
                      <div className="max-w-xl mx-auto bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden animate-fade-in">
                          {/* Profile code remains same */}
                          <div className="bg-slate-900 px-6 py-8 text-center text-white">
                              <div className="w-20 h-20 bg-teal-500 rounded-full flex items-center justify-center text-2xl font-bold mx-auto mb-3 border-4 border-slate-800">
                                  {student?.name?.charAt(0)}
                              </div>
                              <h2 className="text-xl font-bold">{student?.name}</h2>
                              <p className="text-teal-200 font-mono text-sm tracking-wider">{student?.code}</p>
                          </div>
                          <div className="p-6 space-y-4">
                              <div>
                                  <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Classroom</label>
                                  <div className="p-3 bg-gray-50 rounded border border-gray-200 font-medium text-gray-700">{classroom?.grade} - {classroom?.stream}</div>
                              </div>
                              <form onSubmit={handleNameUpdate} className="pt-4 border-t border-gray-100">
                                  <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Update Full Name</label>
                                  <div className="flex gap-2">
                                      <input 
                                          type="text" 
                                          className="flex-1 border border-gray-300 rounded px-3 py-2 text-sm focus:border-teal-500 outline-none"
                                          value={studentName}
                                          onChange={e => setStudentName(e.target.value)}
                                          placeholder={student?.name}
                                      />
                                      <button type="submit" className="bg-slate-900 text-white px-4 py-2 rounded text-sm font-bold hover:bg-slate-800">Save</button>
                                  </div>
                              </form>
                          </div>
                      </div>
                  )}

              </main>
          </div>
      </div>
  );
};

export default StudentPortal;

import React, { useState, useEffect } from 'react';
import { UserProfile, Classroom, Grade, Subject, Assignment, StudentResult, ForumPost, ForumReply, DirectMessage, AppNotification } from '../types';
import { 
  User, School, Phone, Mail, Save, Plus, Trash2, 
  BookOpen, Users, Eye, X, Home, FileText, Settings, 
  Menu, Bell, ChevronDown, Check, ArrowLeft, MessageSquare, ChevronRight, MessageCircle, Send, Reply, ChevronLeft, Layers, Bookmark, Sparkles
} from 'lucide-react';
import { 
    createClassroom, getClassrooms, deleteClassroom, addSubjectToClassroom, 
    removeSubjectFromClassroom, getSavedPlans, getAssignmentsByClassId, 
    getAssignmentResults, updateStudentResultFeedback, createForumPost, 
    addForumReply, sendDirectMessage, getDirectMessages, markMessagesRead, 
    getNotifications, markNotificationRead
} from '../services/storageService';

interface Props {
  profile: UserProfile;
  onUpdate: (profile: UserProfile) => void;
}

// Stats Card Component for Dashboard
const StatCard = ({ icon: Icon, label, value, color }: { icon: any, label: string, value: string | number, color: string }) => (
  <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex items-center justify-between transition-transform hover:-translate-y-1 duration-300">
    <div>
      <div className={`p-3 rounded-full w-12 h-12 flex items-center justify-center mb-3 ${color} bg-opacity-10`}>
        <Icon className={`w-6 h-6 ${color.replace('bg-', 'text-')}`} />
      </div>
      <h3 className="text-gray-500 text-sm font-medium uppercase tracking-wider">{label}</h3>
    </div>
    <div className="text-right">
      <span className={`text-4xl font-light ${color.replace('bg-', 'text-')}`}>{value}</span>
    </div>
  </div>
);

const Dashboard: React.FC<Props> = ({ profile, onUpdate }) => {
  const [activeView, setActiveView] = useState<'overview' | 'classrooms' | 'profile' | 'saved_plans'>('overview');
  const [sidebarOpen, setSidebarOpen] = useState(true); // Mobile Toggle
  const [isCollapsed, setIsCollapsed] = useState(false); // Desktop Collapse
  const [expandedClassId, setExpandedClassId] = useState<string | null>(null); // For sidebar accordion

  const [classrooms, setClassrooms] = useState<Classroom[]>([]);
  const [totalPlans, setTotalPlans] = useState(0);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [showNotifications, setShowNotifications] = useState(false);

  // Profile Form Data
  const [formData, setFormData] = useState<UserProfile>(profile);
  const [message, setMessage] = useState('');

  // Classroom Modals
  const [showAddClassModal, setShowAddClassModal] = useState(false);
  const [managedClassroom, setManagedClassroom] = useState<Classroom | null>(null);

  // Classroom Management State
  const [manageTab, setManageTab] = useState<'students' | 'performance' | 'forum'>('students');
  const [manageView, setManageView] = useState<'subjects' | 'assignments' | 'results'>('subjects');
  const [selectedSubjectForStats, setSelectedSubjectForStats] = useState<string>('');
  const [selectedAssignmentForStats, setSelectedAssignmentForStats] = useState<Assignment | null>(null);
  const [currentAssignmentResults, setCurrentAssignmentResults] = useState<StudentResult[]>([]);
  const [assignmentList, setAssignmentList] = useState<Assignment[]>([]);
  const [feedbackModal, setFeedbackModal] = useState<{resultId: string, name: string, currentFeedback: string} | null>(null);
  const [feedbackInput, setFeedbackInput] = useState('');

  // AI Analysis Modal
  const [analysisModal, setAnalysisModal] = useState<{studentName: string, report: string} | null>(null);

  // Direct Message Modal
  const [dmModal, setDmModal] = useState<{studentName: string, studentCode: string} | null>(null);
  const [dmInput, setDmInput] = useState('');

  // Forum State
  const [forumPostTitle, setForumPostTitle] = useState('');
  const [forumPostContent, setForumPostContent] = useState('');
  const [replyContent, setReplyContent] = useState('');
  const [activePostId, setActivePostId] = useState<string | null>(null);

  // New Class Form
  const [newClassGrade, setNewClassGrade] = useState<Grade>(Grade.GRADE_7);
  const [newClassStream, setNewClassStream] = useState('');
  const [newClassRoll, setNewClassRoll] = useState<number>(40);

  // Subject Mgmt (Quick Add)
  const [addingSubjectTo, setAddingSubjectTo] = useState<string | null>(null);
  const [selectedSubject, setSelectedSubject] = useState<Subject>(Subject.MATHEMATICS);

  useEffect(() => {
    loadData();
    // Poll for notifications
    const interval = setInterval(() => {
        setNotifications(getNotifications(profile.email));
    }, 10000);
    return () => clearInterval(interval);
  }, []);

  const loadData = () => {
    const cls = getClassrooms();
    setClassrooms(cls);
    const plans = getSavedPlans();
    setTotalPlans(plans.length);
    setNotifications(getNotifications(profile.email));
  };

  const handleCreateClassroom = (e: React.FormEvent) => {
    e.preventDefault();
    if (newClassStream && newClassRoll > 0) {
        createClassroom(newClassGrade, newClassStream, newClassRoll);
        loadData();
        setShowAddClassModal(false);
        setNewClassStream('');
        setNewClassRoll(40);
    }
  };

  const handleDeleteClassroom = (id: string) => {
    if (confirm('Are you sure? All student data will be lost.')) {
        deleteClassroom(id);
        loadData();
        if (managedClassroom?.id === id) setManagedClassroom(null);
    }
  };

  const handleSubmitProfile = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdate(formData);
    setMessage('Profile updated successfully!');
    setTimeout(() => setMessage(''), 3000);
  };

  const handleAddSubject = (classId: string) => {
      addSubjectToClassroom(classId, selectedSubject);
      setAddingSubjectTo(null);
      loadData();
  };

  const handleRemoveSubject = (classId: string, subject: string) => {
      if (confirm(`Remove ${subject}?`)) {
          removeSubjectFromClassroom(classId, subject);
          loadData();
      }
  };

  const handlePrintCodes = () => window.print();

  // --- Classroom Management Logic ---

  const openClassroomManager = (cls: Classroom) => {
      setManagedClassroom(cls);
      setManageTab('students');
      setManageView('subjects');
      setActiveView('classrooms');
  };

  const handleSidebarSubjectClick = (cls: Classroom, subject: string) => {
      setManagedClassroom(cls);
      setManageTab('performance');
      loadAssignmentsForSubjectInternal(cls.id, subject);
      setActiveView('classrooms');
      if (window.innerWidth < 1024) setSidebarOpen(false);
  };

  const loadAssignmentsForSubject = (subject: string) => {
      if (!managedClassroom) return;
      loadAssignmentsForSubjectInternal(managedClassroom.id, subject);
  };

  const loadAssignmentsForSubjectInternal = (classId: string, subject: string) => {
      const allAssignments = getAssignmentsByClassId(classId);
      const filtered = allAssignments.filter(a => a.subject === subject);
      setAssignmentList(filtered);
      setSelectedSubjectForStats(subject);
      setManageView('assignments');
  };

  const loadResultsForAssignment = (assignment: Assignment) => {
      const results = getAssignmentResults(assignment.id);
      setCurrentAssignmentResults(results);
      setSelectedAssignmentForStats(assignment);
      setManageView('results');
  };

  const openFeedbackModal = (result: StudentResult) => {
      setFeedbackInput(result.feedback || '');
      setFeedbackModal({
          resultId: result.id,
          name: result.studentName,
          currentFeedback: result.feedback || ''
      });
  };

  const saveFeedback = () => {
      if (!feedbackModal) return;
      updateStudentResultFeedback(feedbackModal.resultId, feedbackInput);
      const updatedResults = currentAssignmentResults.map(r => 
          r.id === feedbackModal.resultId ? {...r, feedback: feedbackInput} : r
      );
      setCurrentAssignmentResults(updatedResults);
      setFeedbackModal(null);
  };

  // --- Messaging ---

  const openDmModal = (student: {name?: string, code: string}) => {
      setDmModal({
          studentName: student.name || `Student ${student.code}`,
          studentCode: student.code
      });
      setDmInput('');
  };

  const sendDm = () => {
      if (!dmModal || !dmInput.trim()) return;
      const msg: DirectMessage = {
          id: crypto.randomUUID(),
          senderId: profile.email,
          senderName: profile.name,
          receiverId: dmModal.studentCode,
          content: dmInput,
          timestamp: new Date().toISOString(),
          read: false,
          isFromTeacher: true
      };
      sendDirectMessage(msg);
      setDmModal(null);
      alert("Message sent successfully!");
  };

  // --- Forum ---

  const handleCreateForumPost = (e: React.FormEvent) => {
      e.preventDefault();
      if (!managedClassroom || !forumPostTitle.trim() || !forumPostContent.trim()) return;
      const newPost: ForumPost = {
          id: crypto.randomUUID(),
          authorName: profile.name,
          title: forumPostTitle,
          content: forumPostContent,
          timestamp: new Date().toISOString(),
          replies: []
      };
      createForumPost(managedClassroom.id, newPost);
      const updatedClass = {
          ...managedClassroom,
          forumPosts: [newPost, ...(managedClassroom.forumPosts || [])]
      };
      setManagedClassroom(updatedClass);
      setForumPostTitle('');
      setForumPostContent('');
  };

  const handleReplyToPost = (postId: string) => {
      if (!managedClassroom || !replyContent.trim()) return;
      const reply: ForumReply = {
          id: crypto.randomUUID(),
          authorName: profile.name,
          authorRole: 'teacher',
          content: replyContent,
          timestamp: new Date().toISOString()
      };
      addForumReply(managedClassroom.id, postId, reply);
      const updatedPosts = managedClassroom.forumPosts.map(p => {
          if (p.id === postId) {
              return { ...p, replies: [...p.replies, reply] };
          }
          return p;
      });
      setManagedClassroom({ ...managedClassroom, forumPosts: updatedPosts });
      setReplyContent('');
      setActivePostId(null);
  };

  const handleNotificationClick = (notif: AppNotification) => {
      markNotificationRead(notif.id);
      setNotifications(prev => prev.map(n => n.id === notif.id ? {...n, read: true} : n));
  };

  const unreadCount = notifications.filter(n => !n.read).length;

  return (
    <div className="flex min-h-screen bg-slate-50 font-sans text-slate-800">

      {/* Mobile Backdrop */}
      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden" 
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar - Fixed */}
      <aside className={`fixed inset-y-0 left-0 z-50 bg-slate-900 text-slate-300 transition-all duration-300 ease-in-out shadow-xl flex flex-col 
          ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} 
          lg:translate-x-0 
          ${isCollapsed ? 'w-20' : 'w-64'}
      `}>
        <div className={`flex items-center h-16 px-4 bg-slate-950 text-white font-bold text-xl tracking-tight border-b border-slate-800 ${isCollapsed ? 'justify-center' : 'justify-between'}`}>
          {!isCollapsed ? (
              <div className="flex items-center">
                <BookOpen className="w-6 h-6 mr-2 text-teal-500" />
                <span>Mwalimu<span className="text-teal-500">Admin</span></span>
              </div>
          ) : (
