  `;

  if (plan.customContext) {
      prompt += `\nAdditional Context: ${plan.customContext}`;
  }

  prompt += `\n\nRequirements:
    1. Generate exactly 10 questions.
    2. ALL questions MUST be **Multiple Choice Questions (MCQ)**. Do NOT generate structured or short answer questions.
    3. Each question must have 4 options.
    4. Questions should be age-appropriate for ${plan.grade}.
    5. Return a STRICT JSON array. Ensure all keys are double-quoted.
    6. **Language:** ${isKiswahili ? 'Use KISWAHILI language throughout.' : 'Use English.'}
    7. Do NOT use markdown bold characters (**).

    Expected JSON Schema:
    [
      {
        "id": 1,
        "type": "mcq", 
        "question": "The question text",
        "options": ["Option A", "Option B", "Option C", "Option D"],
        "correctAnswer": "The exact string of the correct option",
        "explanation": "Brief explanation"
      }
    ]
  `;

  const parts: any[] = [{ text: prompt }];
  if (plan.images && plan.images.length > 0) {
      plan.images.forEach((base64Image: string) => {
          const rawBase64 = base64Image.split(',')[1] || base64Image;
          parts.push({
              inlineData: { mimeType: 'image/jpeg', data: rawBase64 }
          });
      });
      parts.push({ text: "Use the provided images to generate visual-based questions if appropriate." });
  }

  try {
    const response = await ai.models.generateContent({
      model: MODEL_ID,
      contents: { parts: parts },
      config: {
        responseMimeType: "application/json"
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response");

    const cleanedText = cleanJson(text);
    // Remove bold from JSON string before parsing to be safe
    const safeText = removeBold(cleanedText);
    return JSON.parse(safeText) as QuizQuestion[];
  } catch (error) {
    console.error("Gemini API Error (Questions):", error);
    throw new Error("Failed to generate questions.");
  }
};

