                                                  </div>
                                              </div>
                                          ))}
                                      </div>
                                  ) : (
                                      <div className="text-center py-10 text-gray-400 italic bg-slate-50 rounded-lg border border-dashed">
                                          No textbooks uploaded yet.
                                      </div>
                                  )}
                              </div>
                          </div>
                      )}

                      {/* TAB 4: DISCUSSION FORUM */}
                      {manageTab === 'forum' && (
                          <div className="p-6 h-full flex flex-col">
                              <h3 className="text-lg font-bold text-gray-800 mb-4">Class Discussion Forum</h3>

                              {/* New Post Form */}
