export const getClassrooms = (): Classroom[] => {
  const currentUser = getCurrentUser();
  if (!currentUser) return [];

  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

  // Filter logic based on role
  if (currentUser.role === 'school_admin' && currentUser.schoolId) {
    // School Admin sees all classes in their school
    return allClassrooms.filter(c => c.schoolId === currentUser.schoolId).map(c => ({
        ...c,
        forumPosts: c.forumPosts || [],
        textbooks: c.textbooks || []
    }));
  } else {
    // Teacher sees classes they created OR classes assigned to them
    return allClassrooms.filter(c => c.userId === currentUser.email || c.teacherId === currentUser.email).map(c => ({
        ...c,
        forumPosts: c.forumPosts || [],
        textbooks: c.textbooks || []
    }));
  }
};

