                                                              <button 
                                                                  onClick={() => openFeedbackModal(result)}
                                                                  className={`inline-flex items-center gap-1 text-xs font-bold px-3 py-1.5 rounded transition-colors ${result.feedback ? 'bg-blue-50 text-blue-600 hover:bg-blue-100' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
