                                                  <div className="bg-gray-50 rounded p-3 mb-3 space-y-2">
                                                      {post.replies.map(reply => (
                                                          <div key={reply.id} className="text-xs border-l-2 border-gray-300 pl-2">
                                                              <span className={`font-bold ${reply.authorRole === 'teacher' ? 'text-teal-600' : 'text-blue-600'}`}>
