export const saveAssignment = (assignment: Assignment): void => {
  const data = localStorage.getItem(ASSIGNMENTS_STORAGE_KEY);
  const assignments: Assignment[] = data ? JSON.parse(data) : [];
  assignments.push(assignment);
  localStorage.setItem(ASSIGNMENTS_STORAGE_KEY, JSON.stringify(assignments));

  const clsData = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  if (clsData) {
      const classrooms: Classroom[] = JSON.parse(clsData);
      const cls = classrooms.find(c => c.id === assignment.classroomId);
      if (cls) {
          cls.students.forEach(s => {
              createNotification(s.code, 'assignment', 'New Assignment', `New ${assignment.subject} assignment: ${assignment.topic}`);
          });
      }
  }
};

