export const registerSchool = (schoolName: string, adminEmail: string, adminPass: string, adminPhone: string, address: string): UserProfile => {
    const schools = getSchools();
    const users = getUsers();

    // Check if school admin email exists
    if (users.some(u => u.email.toLowerCase() === adminEmail.toLowerCase())) {
        throw new Error('An account with this email already exists.');
    }

    const adminId = crypto.randomUUID();
    const schoolId = crypto.randomUUID();

    const newSchool: School = {
        id: schoolId,
        name: schoolName,
        email: adminEmail,
        phone: adminPhone,
        address: address,
        adminId: adminId,
        createdAt: new Date().toISOString()
    };

    const adminUser: UserProfile = {
        id: adminId,
        name: `${schoolName} Admin`,
        email: adminEmail,
        password: adminPass,
        phone: adminPhone,
        school: schoolName,
        schoolId: schoolId,
        role: 'school_admin',
        isAdmin: false
    };

    schools.push(newSchool);
    users.push(adminUser);

    localStorage.setItem(SCHOOLS_DB_KEY, JSON.stringify(schools));
    localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));
    localStorage.setItem(SESSION_KEY, JSON.stringify(adminUser));

    return adminUser;
};

// Replaced by linkTeacherToSchool for core flow, but kept as util
export const createTeacherAccount = (schoolId: string, teacherName: string, teacherEmail: string, teacherPhone: string, password: string): UserProfile => {
    const users = getUsers();
    const schools = getSchools();
    const school = schools.find(s => s.id === schoolId);

    if (!school) throw new Error("School not found.");

    if (users.some(u => u.email.toLowerCase() === teacherEmail.toLowerCase())) {
        throw new Error('A teacher with this email already exists.');
    }

    const newTeacher: UserProfile = {
        id: crypto.randomUUID(),
        name: teacherName,
        email: teacherEmail,
        phone: teacherPhone,
        password: password,
        school: school.name,
        schoolId: schoolId,
        role: 'teacher',
        isAdmin: false,
        teacherCode: generateTeacherCode()
    };

    users.push(newTeacher);
    localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));

    return newTeacher;
};

export const linkTeacherToSchool = (schoolId: string, teacherCode: string): UserProfile => {
  const users = getUsers();
  const schools = getSchools();
  const school = schools.find(s => s.id === schoolId);
  const teacherIdx = users.findIndex(u => u.teacherCode === teacherCode && u.role === 'teacher');

  if (!school) throw new Error("School not found");
  if (teacherIdx === -1) throw new Error("Invalid Teacher Code or user not found.");

  const teacher = users[teacherIdx];
  if (teacher.schoolId) throw new Error(`Teacher is already linked to ${teacher.school}.`);

  // Update Teacher
  users[teacherIdx].schoolId = schoolId;
  users[teacherIdx].school = school.name;
  localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));

  // Update Classrooms (Reflect data to school)
  const classrooms = getAllClassroomsGlobal();
  let classroomsChanged = false;
  classrooms.forEach(c => {
    if (c.userId === teacher.email) {
      c.schoolId = schoolId;
      classroomsChanged = true;
    }
  });
  if (classroomsChanged) localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(classrooms));

  // Update Plans (Reflect data to school - Visual update)
  const plans = getAllGlobalPlans();
  let plansChanged = false;
  plans.forEach(p => {
    if (p.userId === teacher.email) {
      p.schoolName = school.name;
      plansChanged = true;
    }
  });
  if (plansChanged) localStorage.setItem(PLANS_STORAGE_KEY, JSON.stringify(plans));

  return users[teacherIdx];
};

export const getSchoolTeachers = (schoolId: string): UserProfile[] => {
    const users = getUsers();
    return users.filter(u => u.schoolId === schoolId && u.role === 'teacher');
};

export const getTeacherPlans = (teacherEmail: string): LessonPlanData[] => {
    const plans = getAllGlobalPlans();
    return plans.filter(p => p.userId === teacherEmail).sort((a,b) => new Date(b.createdAt || b.date).getTime() - new Date(a.createdAt || a.date).getTime());
};

export const registerUser = (user: UserProfile): UserProfile => {
  const users = getUsers();

  if (users.some(u => u.email.toLowerCase() === user.email.toLowerCase())) {
    throw new Error('An account with this email already exists.');
  }

  user.id = user.id || crypto.randomUUID();
  user.isAdmin = false;
  user.role = 'teacher'; // Default independent teacher
  user.teacherCode = generateTeacherCode();

  users.push(user);
  localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));

  localStorage.setItem(SESSION_KEY, JSON.stringify(user));
  return user;
};

export const loginUser = (email: string, password: string): UserProfile => {
  if (email === 'admin@mwalimuplanner.com' && password === 'admin123') {
    const adminUser: UserProfile = {
      name: 'System Administrator',
      email: 'admin@mwalimuplanner.com',
      school: 'HQ',
      phone: '0000000000',
      isAdmin: true,
      role: 'system_admin'
    };
    localStorage.setItem(SESSION_KEY, JSON.stringify(adminUser));
    return adminUser;
  }

  const users = getUsers();
  const user = users.find(u => 
    u.email.toLowerCase() === email.toLowerCase() && 
    u.password === password
  );

  if (!user) {
    throw new Error('Invalid email or password.');
  }

  localStorage.setItem(SESSION_KEY, JSON.stringify(user));
  return user;
};

export const logoutUser = (): void => {
  localStorage.removeItem(SESSION_KEY);
};

export const getCurrentUser = (): UserProfile | null => {
  const data = localStorage.getItem(SESSION_KEY);
  return data ? JSON.parse(data) : null;
};

export const updateUserProfile = (updatedProfile: UserProfile): void => {
  const users = getUsers();
  const index = users.findIndex(u => u.email === updatedProfile.email);

  if (index !== -1) {
    const existingUser = users[index];
    // Preserve schoolID and role if not passed (though they shouldn't change via profile update usually)
    users[index] = { ...existingUser, ...updatedProfile };

    localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));
    localStorage.setItem(SESSION_KEY, JSON.stringify(users[index]));
  }
};

export const resetUserPassword = (email: string, newPass: string): boolean => {
    const users = getUsers();
    const index = users.findIndex(u => u.email.toLowerCase() === email.toLowerCase());

    if (index !== -1) {
        users[index].password = newPass;
        localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));
        return true;
    }
    return false;
};

