                                              className="hidden" 
                                              onChange={handleTextbookUpload}
                                          />
                                      </label>
                                      <span className="text-xs text-blue-500">Max size 2MB</span>
                                  </div>
                              </div>

                              <div className="flex-1 overflow-y-auto">
                                  {managedClassroom.textbooks && managedClassroom.textbooks.length > 0 ? (
                                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                          {managedClassroom.textbooks.map(book => (
                                              <div key={book.id} className="border border-gray-200 rounded-lg p-4 bg-white hover:shadow-md transition-shadow flex items-start gap-3">
                                                  <div className="p-3 bg-red-50 text-red-600 rounded-lg">
                                                      <File className="w-6 h-6" />
                                                  </div>
                                                  <div className="flex-1 min-w-0">
                                                      <h4 className="font-bold text-slate-700 truncate">{book.title}</h4>
                                                      <p className="text-xs text-gray-500">{new Date(book.uploadDate).toLocaleDateString()} • {book.size}</p>
                                                      <a href={book.fileData} download={book.title} className="text-xs text-teal-600 font-bold hover:underline mt-1 inline-block">Download</a>
                                                  </div>
                                              </div>
                                          ))}
                                      </div>
                                  ) : (
                                      <div className="text-center py-10 text-gray-400 italic bg-slate-50 rounded-lg border border-dashed">
                                          No textbooks uploaded yet.
                                      </div>
                                  )}
                              </div>
                          </div>
                      )}

                      {/* TAB 4: DISCUSSION FORUM */}
                      {manageTab === 'forum' && (
                          <div className="p-6 h-full flex flex-col">
                              <h3 className="text-lg font-bold text-gray-800 mb-4">Class Discussion Forum</h3>

                              {/* New Post Form */}
                              <form onSubmit={handleCreateForumPost} className="bg-slate-50 p-4 rounded-xl border border-gray-200 mb-6">
                                  <input 
                                      type="text" 
                                      placeholder="Discussion Title" 
                                      className="w-full mb-2 p-2 rounded border border-gray-300 text-sm font-bold"
                                      value={forumPostTitle}
                                      onChange={e => setForumPostTitle(e.target.value)}
                                      required
                                  />
                                  <textarea 
                                      rows={2} 
                                      placeholder="Start a discussion or make an announcement..." 
                                      className="w-full p-2 rounded border border-gray-300 text-sm mb-2"
                                      value={forumPostContent}
                                      onChange={e => setForumPostContent(e.target.value)}
                                      required
                                  ></textarea>
                                  <div className="text-right">
                                      <button type="submit" className="bg-slate-900 text-white px-4 py-1.5 rounded text-xs font-bold hover:bg-slate-800">Post to Class</button>
                                  </div>
                              </form>

                              {/* Posts List */}
                              <div className="flex-1 overflow-y-auto space-y-4">
                                  {managedClassroom.forumPosts && managedClassroom.forumPosts.length > 0 ? (
                                      managedClassroom.forumPosts.map(post => (
                                          <div key={post.id} className="border border-gray-200 rounded-xl p-4 bg-white">
                                              <div className="flex justify-between items-start mb-2">
                                                  <div>
                                                      <h4 className="font-bold text-teal-800">{post.title}</h4>
                                                      <p className="text-xs text-gray-500">Posted by {post.authorName} • {new Date(post.timestamp).toLocaleDateString()}</p>
                                                  </div>
                                                  <span className="text-xs bg-gray-100 px-2 py-1 rounded text-gray-600">{post.replies.length} replies</span>
                                              </div>
                                              <p className="text-sm text-gray-700 mb-4">{post.content}</p>

                                              {/* Replies */}
                                              {post.replies.length > 0 && (
                                                  <div className="bg-gray-50 rounded p-3 mb-3 space-y-2">
                                                      {post.replies.map(reply => (
                                                          <div key={reply.id} className="text-xs border-l-2 border-gray-300 pl-2">
                                                              <span className={`font-bold ${reply.authorRole === 'teacher' ? 'text-teal-600' : 'text-blue-600'}`}>
                                                                  {reply.authorName}
                                                                  {reply.authorRole === 'teacher' && <span className="ml-1 text-[9px] bg-teal-100 text-teal-800 px-1 rounded uppercase">Teacher</span>}
                                                              </span>
                                                              <p className="text-gray-600">{reply.content}</p>
                                                          </div>
                                                      ))}
                                                  </div>
                                              )}

                                              {/* Reply Input */}
                                              {activePostId === post.id ? (
                                                  <div className="flex gap-2">
                                                      <input 
                                                          type="text" 
                                                          className="flex-1 text-sm border border-gray-300 rounded px-2 py-1"
                                                          placeholder="Write a reply..."
                                                          value={replyContent}
                                                          onChange={e => setReplyContent(e.target.value)}
                                                      />
                                                      <button onClick={() => handleReplyToPost(post.id)} className="bg-teal-600 text-white px-3 py-1 rounded text-xs font-bold">Reply</button>
                                                      <button onClick={() => setActivePostId(null)} className="text-gray-500 text-xs">Cancel</button>
                                                  </div>
                                              ) : (
                                                  <button onClick={() => setActivePostId(post.id)} className="text-teal-600 text-xs font-bold flex items-center gap-1 hover:underline">
                                                      <Reply className="w-3 h-3" /> Reply
                                                  </button>
                                              )}
                                          </div>
                                      ))
                                  ) : (
                                      <div className="text-center text-gray-400 py-10">No discussions yet.</div>
                                  )}
                              </div>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}

      {/* Feedback Modal */}
      {feedbackModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white">
                      <h3 className="font-bold">Feedback for {feedbackModal.name}</h3>
                      <button onClick={() => setFeedbackModal(null)}><X className="w-5 h-5" /></button>
                  </div>
                  <div className="p-6">
                      <label className="block text-sm font-medium text-gray-700 mb-2">Teacher's Comment</label>
                      <textarea 
                          rows={4}
                          className="w-full rounded-lg border border-gray-300 p-3 text-sm focus:ring-2 focus:ring-teal-500 focus:border-transparent"
                          placeholder="Write your feedback here..."
                          value={feedbackInput}
                          onChange={(e) => setFeedbackInput(e.target.value)}
                      ></textarea>
                  </div>
                  <div className="p-6 border-t border-gray-100 bg-gray-50 flex justify-end gap-2">
                      <button onClick={() => setFeedbackModal(null)} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded font-medium text-sm">Cancel</button>
                      <button onClick={saveFeedback} className="px-4 py-2 bg-teal-600 text-white rounded font-bold text-sm hover:bg-teal-700">Save Feedback</button>
                  </div>
              </div>
          </div>
      )}

      {/* DM Modal */}
      {dmModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white">
                      <h3 className="font-bold">Message {dmModal.studentName}</h3>
                      <button onClick={() => setDmModal(null)}><X className="w-5 h-5" /></button>
                  </div>
                  <div className="p-6">
                      <label className="block text-sm font-medium text-gray-700 mb-2">Message</label>
                      <textarea 
                          rows={4}
                          className="w-full rounded-lg border border-gray-300 p-3 text-sm focus:ring-2 focus:ring-teal-500 focus:border-transparent"
                          placeholder="Type your message..."
                          value={dmInput}
                          onChange={(e) => setDmInput(e.target.value)}
                      ></textarea>
                  </div>
                  <div className="p-6 border-t border-gray-100 bg-gray-50 flex justify-end gap-2">
                      <button onClick={() => setDmModal(null)} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded font-medium text-sm">Cancel</button>
                      <button onClick={sendDm} className="px-4 py-2 bg-blue-600 text-white rounded font-bold text-sm hover:bg-blue-700 flex items-center gap-2">
                          <Send className="w-3 h-3" /> Send
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { Student, Classroom, Assignment, StudentResult, SharedNote, QuizQuestion, DirectMessage, ForumPost, ForumReply, AppNotification } from '../types';
import { 
    authenticateStudent, updateStudentName, getAssignmentsByClassId, getStudentResults, 
    saveStudentResult, getStudentNotes, getDirectMessages, sendDirectMessage, markMessagesRead, 
    addForumReply 
} from '../services/storageService';
import { generateStudentPerformanceReport } from '../services/geminiService';
import { 
    LogIn, BookOpen, CheckCircle, Clock, ChevronRight, FileText, AlertCircle, Play, 
    Loader2, Menu, Home, Book, List, CheckSquare, BarChart2, Mail, MessageSquare, 
    User, LogOut, X, Send, Reply, ChevronLeft, File, Download, RotateCcw
} from 'lucide-react';

const StudentPortal: React.FC = () => {
  // Auth State
  const [view, setView] = useState<'login' | 'portal'>('login');
  const [accessCode, setAccessCode] = useState('');
  const [student, setStudent] = useState<Student | null>(null);
  const [classroom, setClassroom] = useState<Classroom | null>(null);
  const [studentName, setStudentName] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Portal UI State
  const [activeSection, setActiveSection] = useState<'dashboard' | 'notes' | 'textbooks' | 'all_assignments' | 'pending' | 'completed' | 'results' | 'inbox' | 'forum' | 'profile'>('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [isCollapsed, setIsCollapsed] = useState(false);

  // Data State
  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [results, setResults] = useState<StudentResult[]>([]);
  const [notes, setNotes] = useState<SharedNote[]>([]);
  const [messages, setMessages] = useState<DirectMessage[]>([]);
  const [forumPosts, setForumPosts] = useState<ForumPost[]>([]);

  // Quiz Execution State
  const [quizMode, setQuizMode] = useState(false);
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Timing State
  const [quizStartTime, setQuizStartTime] = useState<number>(0);
  const [questionStartTime, setQuestionStartTime] = useState<number>(0);
  const [timePerQuestion, setTimePerQuestion] = useState<Record<number, number>>({});

  // View Modals
  const [selectedFullNote, setSelectedFullNote] = useState<SharedNote | null>(null);

  // Messaging State
  const [newMessage, setNewMessage] = useState('');

  // Forum State
  const [newForumReply, setNewForumReply] = useState('');
  const [activeForumPostId, setActiveForumPostId] = useState<string | null>(null);

  // Notification Counts
  const pendingCount = assignments.filter(a => !results.some(r => r.assignmentId === a.id)).length;
  const unreadMsgCount = messages.filter(m => !m.read && m.receiverId === student?.code).length;

  useEffect(() => {
      if (student && view === 'portal') {
          const interval = setInterval(() => {
              loadStudentData(student.code, classroom!.id);
          }, 10000);
          return () => clearInterval(interval);
      }
  }, [student, view, classroom]);

  const loadStudentData = (code: string, classId: string) => {
    const classAssignments = getAssignmentsByClassId(classId);
    const studentResults = getStudentResults(code);
    const classNotes = getStudentNotes(classId);
    const msgs = getDirectMessages(code);

    const refreshedResult = authenticateStudent(code);
    if (refreshedResult) {
        setClassroom(refreshedResult.classroom);
        setForumPosts(refreshedResult.classroom.forumPosts || []);
    }

    setAssignments(classAssignments);
    setResults(studentResults);
    setNotes(classNotes);
    setMessages(msgs);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!accessCode) return;

    const result = authenticateStudent(accessCode.toUpperCase());
    if (result) {
      setStudent(result.student);
      setClassroom(result.classroom);
      if (result.student.name) {
        loadStudentData(result.student.code, result.classroom.id);
        setView('portal');
      }
    } else {
      setError("Invalid Access Code.");
    }
  };

  const handleNameUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (student && classroom && studentName.trim()) {
      const updated = updateStudentName(classroom.id, student.code, studentName);
      if (updated) {
        setStudent(updated);
        loadStudentData(updated.code, classroom.id);
        setView('portal');
      }
    }
  };

  const startQuiz = (assignment: Assignment) => {
    setActiveAssignment(assignment);
    setCurrentQuestionIndex(0);
    setSelectedAnswers({});
    setTimePerQuestion({});

    const now = Date.now();
    setQuizStartTime(now);
    setQuestionStartTime(now);

    setQuizMode(true);
    if(window.innerWidth < 1024) setSidebarOpen(false);
  };

  const recordTimeForCurrentQuestion = () => {
      const now = Date.now();
      const timeSpent = (now - questionStartTime) / 1000;
      setTimePerQuestion(prev => {
          const existing = prev[currentQuestionIndex] || 0;
          return { ...prev, [currentQuestionIndex]: existing + timeSpent };
      });
      setQuestionStartTime(now);
  };

  const handleNextQuestion = () => {
      recordTimeForCurrentQuestion();
      setCurrentQuestionIndex(prev => prev + 1);
  };

  const handlePrevQuestion = () => {
      recordTimeForCurrentQuestion();
      setCurrentQuestionIndex(prev => prev - 1);
  };

  const handleAnswerSelect = (answer: string) => {
      setSelectedAnswers(prev => ({ ...prev, [currentQuestionIndex]: answer }));
  };

  const submitQuiz = async () => {
      if (!student || !activeAssignment) return;

      recordTimeForCurrentQuestion();
      const totalTimeTaken = (Date.now() - quizStartTime) / 1000;

      setIsSubmitting(true);

      let score = 0;
      activeAssignment.questions.forEach((q, idx) => {
          const userAnswer = selectedAnswers[idx];
          if (userAnswer === q.correctAnswer) score++;
          else if (q.type === 'structured' && userAnswer?.toLowerCase().trim() === q.correctAnswer.toLowerCase().trim()) score++;
      });

      let aiReport = "";
      try {
          aiReport = await generateStudentPerformanceReport(
              activeAssignment,
              selectedAnswers,
              score,
              totalTimeTaken,
              timePerQuestion
          );
      } catch (err) {
          aiReport = "Analysis could not be generated at this time.";
      }

      const result: StudentResult = {
          id: crypto.randomUUID(),
          assignmentId: activeAssignment.id,
          studentCode: student.code,
          studentName: student.name || 'Student',
          score: score,
          total: activeAssignment.questions.length,
          attempts: 1, // Logic handled in storageService
          answers: selectedAnswers,
          dateTaken: new Date().toISOString(),
          timeTaken: totalTimeTaken,
          timePerQuestion: timePerQuestion,
          aiAnalysis: aiReport
      };

      saveStudentResult(result);

      const submissionMsg: DirectMessage = {
          id: crypto.randomUUID(),
          senderId: student.code,
          senderName: student.name || 'Student',
          receiverId: classroom?.userId || '',
          content: `I have submitted the assignment: ${activeAssignment.topic}. Score: ${score}/${activeAssignment.questions.length}.`,
          timestamp: new Date().toISOString(),
          read: false,
          isFromTeacher: false
      };
      if (classroom?.userId) sendDirectMessage(submissionMsg);

      if (classroom) loadStudentData(student.code, classroom.id);

      setIsSubmitting(false);
      setQuizMode(false);
      setActiveSection('results');
      setActiveAssignment(null);
  };

  const handleSendMessage = (e: React.FormEvent) => {
      e.preventDefault();
      if (!newMessage.trim() || !student || !classroom) return;
      const msg: DirectMessage = {
          id: crypto.randomUUID(),
          senderId: student.code,
          senderName: student.name || 'Student',
          receiverId: classroom.userId,
          content: newMessage,
          timestamp: new Date().toISOString(),
          read: false,
          isFromTeacher: false
      };
      sendDirectMessage(msg);
      setNewMessage('');
      loadStudentData(student.code, classroom.id);
  };

  const handleForumReplySubmit = (postId: string) => {
      if (!newForumReply.trim() || !student || !classroom) return;
      const reply: ForumReply = {
          id: crypto.randomUUID(),
          authorName: student.name || 'Student',
          authorRole: 'student',
          content: newForumReply,
          timestamp: new Date().toISOString()
      };
      addForumReply(classroom.id, postId, reply);
      setNewForumReply('');
      loadStudentData(student.code, classroom.id);
  };

  const groupedAssignments = useMemo(() => {
      const groups: Record<string, Assignment[]> = {};
      assignments.forEach(a => {
          if (!groups[a.subject]) groups[a.subject] = [];
          groups[a.subject].push(a);
      });
      return groups;
  }, [assignments]);

  const groupedNotes = useMemo(() => {
      const groups: Record<string, SharedNote[]> = {};
      notes.forEach(n => {
          if (!groups[n.subject]) groups[n.subject] = [];
          groups[n.subject].push(n);
      });
      return groups;
  }, [notes]);

  const getAttemptsForAssignment = (id: string) => {
      return results.filter(r => r.assignmentId === id).length;
  };

  if (view === 'login') {
      return (
          <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-gray-50 font-sans">
              <div className="bg-white p-8 rounded-xl shadow-xl w-full max-w-md border border-gray-200">
                  <div className="text-center mb-8">
                      <div className="bg-teal-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                          <BookOpen className="w-8 h-8 text-teal-600" />
                      </div>
                      <h2 className="text-2xl font-bold text-gray-800">Student Portal</h2>
                      <p className="text-gray-500 text-sm mt-1">Access your class materials</p>
                  </div>

                  {student && !student.name ? (
                      <form onSubmit={handleNameUpdate} className="space-y-6">
                          <div className="bg-blue-50 p-4 rounded-md text-sm text-blue-700">
                              Please update your profile with your full name to continue.
                          </div>
                          <div>
                              <label className="block text-sm font-medium text-gray-700 mb-1">Full Name</label>
                              <input 
                                  type="text" 
                                  required
                                  className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border px-3"
                                  value={studentName}
                                  onChange={e => setStudentName(e.target.value)}
                                  placeholder="e.g. John Doe"
                              />
                          </div>
                          <button type="submit" className="w-full bg-teal-600 text-white py-2.5 rounded-md font-medium hover:bg-teal-700 transition-colors">
                              Update Profile
                          </button>
                      </form>
                  ) : (
                      <form onSubmit={handleLogin} className="space-y-6">
                          {error && <div className="bg-red-50 text-red-700 p-3 rounded-md text-sm flex items-center gap-2 border border-red-200"><AlertCircle className="w-4 h-4"/> {error}</div>}
                          <div>
                              <label className="block text-sm font-medium text-gray-700 mb-1">Access Code</label>
                              <input 
                                  type="text" 
                                  required
                                  className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border px-3 text-center uppercase tracking-widest font-mono"
                                  value={accessCode}
                                  onChange={e => setAccessCode(e.target.value)}
                                  placeholder="XXXXXX"
                                  maxLength={6}
                              />
                          </div>
                          <button type="submit" className="w-full bg-teal-600 text-white py-2.5 rounded-md font-medium hover:bg-teal-700 transition-colors flex justify-center items-center gap-2">
                              <LogIn className="w-4 h-4" /> Enter Classroom
                          </button>
                      </form>
                  )}
              </div>
          </div>
      );
  }

  return (
      <div className="flex min-h-screen bg-slate-50 font-sans text-slate-800">
          {sidebarOpen && (
            <div className="fixed inset-0 bg-black/50 z-40 lg:hidden" onClick={() => setSidebarOpen(false)} />
          )}

          <aside className={`fixed inset-y-0 left-0 z-50 bg-slate-900 text-slate-300 transition-all duration-300 ease-in-out shadow-xl flex flex-col 
              ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 ${isCollapsed ? 'w-20' : 'w-64'}`}>
              <div className={`flex items-center h-16 px-4 bg-slate-950 text-white font-bold text-xl tracking-tight border-b border-slate-800 ${isCollapsed ? 'justify-center' : 'justify-between'}`}>
                  {!isCollapsed ? (
                      <div className="flex items-center">
                          <BookOpen className="w-6 h-6 mr-2 text-teal-500" />
                          <span>Student<span className="text-teal-500">Portal</span></span>
                      </div>
                  ) : (
                      <BookOpen className="w-8 h-8 text-teal-500" />
                  )}
                  <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-slate-400 hover:text-white p-1"><X className="w-5 h-5" /></button>
              </div>

              <nav className="flex-1 overflow-y-auto p-3 space-y-1">
                  <SidebarItem id="dashboard" icon={Home} label="Dashboard" activeSection={activeSection} setActiveSection={setActiveSection} setSidebarOpen={setSidebarOpen} isCollapsed={isCollapsed} />
                  <SidebarItem id="notes" icon={FileText} label="Lesson Notes" activeSection={activeSection} setActiveSection={setActiveSection} setSidebarOpen={setSidebarOpen} isCollapsed={isCollapsed} />
                  <SidebarItem id="textbooks" icon={Book} label="Class Textbooks" activeSection={activeSection} setActiveSection={setActiveSection} setSidebarOpen={setSidebarOpen} isCollapsed={isCollapsed} />
                  <SidebarItem id="all_assignments" icon={List} label="All Assignments" activeSection={activeSection} setActiveSection={setActiveSection} setSidebarOpen={setSidebarOpen} isCollapsed={isCollapsed} />
                  <SidebarItem id="pending" icon={Clock} label="Pending" activeSection={activeSection} setActiveSection={setActiveSection} setSidebarOpen={setSidebarOpen} isCollapsed={isCollapsed} badgeCount={pendingCount} />
                  <SidebarItem id="completed" icon={CheckSquare} label="Completed" activeSection={activeSection} setActiveSection={setActiveSection} setSidebarOpen={setSidebarOpen} isCollapsed={isCollapsed} />
                  <SidebarItem id="results" icon={BarChart2} label="Results" activeSection={activeSection} setActiveSection={setActiveSection} setSidebarOpen={setSidebarOpen} isCollapsed={isCollapsed} />
                  <SidebarItem id="inbox" icon={Mail} label="My Inbox" activeSection={activeSection} setActiveSection={setActiveSection} setSidebarOpen={setSidebarOpen} isCollapsed={isCollapsed} badgeCount={unreadMsgCount} />
                  <SidebarItem id="forum" icon={MessageSquare} label="Discussion Forum" activeSection={activeSection} setActiveSection={setActiveSection} setSidebarOpen={setSidebarOpen} isCollapsed={isCollapsed} badgeCount={forumPosts.length > 0 ? 1 : 0} />
                  <SidebarItem id="profile" icon={User} label="My Profile" activeSection={activeSection} setActiveSection={setActiveSection} setSidebarOpen={setSidebarOpen} isCollapsed={isCollapsed} />
              </nav>

              <div className="p-4 border-t border-slate-800">
                  <button onClick={() => { setStudent(null); setView('login'); }} className={`flex items-center w-full px-4 py-2.5 text-sm font-medium rounded-lg text-red-400 hover:bg-slate-800 hover:text-red-300 transition-colors ${isCollapsed ? 'justify-center' : ''}`}>
                      <LogOut className={`w-5 h-5 ${!isCollapsed && 'mr-3'}`} />
                      {!isCollapsed && <span>Sign Out</span>}
                  </button>
                  <button onClick={() => setIsCollapsed(!isCollapsed)} className="hidden lg:flex mt-2 w-full items-center justify-center p-2 text-slate-500 hover:text-white hover:bg-slate-800 rounded-lg transition-colors">
                      {isCollapsed ? <ChevronRight className="w-5 h-5"/> : <ChevronLeft className="w-5 h-5"/>}
                  </button>
              </div>
          </aside>

