export const generateStudentPerformanceReport = async (
  assignment: Assignment,
  studentAnswers: Record<number, string>,
  score: number,
  timeTaken: number,
  timePerQuestion: Record<number, number>
): Promise<string> => {
  const isKiswahili = assignment.subject === "Kiswahili";

  // Construct a concise summary of performance data
  let answersContext = "";
  assignment.questions.forEach((q, idx) => {
    const userAnswer = studentAnswers[idx] || "No Answer";
    const isCorrect = userAnswer === q.correctAnswer;
    const timeForQ = timePerQuestion[idx] ? `${timePerQuestion[idx].toFixed(1)}s` : "N/A";
    answersContext += `Q${idx + 1}: ${q.question} \n- Correct Answer: ${q.correctAnswer} \n- Student Answer: ${userAnswer} (${isCorrect ? 'Correct' : 'Incorrect'}) \n- Time Taken: ${timeForQ}\n\n`;
  });

  const prompt = `
    You are an expert pedagogical analyst. Review the following student quiz performance and generate a concise report FOR THE TEACHER.

    **Context:**
    Subject: ${assignment.subject}
    Topic: ${assignment.topic}
    Grade: ${assignment.grade || 'N/A'}
    Score: ${score} / ${assignment.questions.length}
    Total Time Taken: ${(timeTaken / 60).toFixed(1)} minutes

    **Detailed Question Analysis:**
    ${answersContext}

    **Task:**
    Provide a professional analysis covering:
    1. **Learning Gaps:** Identify specific concepts the student is struggling with based on incorrect answers.
    2. **Strengths:** Identify concepts the student has mastered.
    3. **Time Management:** Comment on if they rushed or took too long on specific questions.
    4. **Recommendation:** One actionable step for the teacher to help this student.

    **Format:**
    - Use bullet points.
    - Keep it brief (approx 150 words).
    - Tone: Professional and constructive.
    - Do NOT use bold characters (**) or markdown formatting. Just plain text.
    ${isKiswahili ? 'IMPORTANT: Write the report in KISWAHILI.' : ''}
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_ID,
      contents: prompt,
    });
    return removeBold(response.text || "Analysis unavailable.");
  } catch (error) {
    console.error("Gemini API Error (Student Report):", error);
    return "Analysis unavailable due to an error.";
  }
};

export const generateGoogleFormScript = async (title: string, questions: string): Promise<string> => {
  const prompt = `
    You are a Google Apps Script developer.
    Convert the following list of practice questions into a Google Apps Script that creates a Google Form Quiz.

    Lesson Title: "${title}"

    Questions Content:
    ${questions}

    Requirements for the Script:
    1. Function name must be 'createQuiz'.
    2. Use 'FormApp.create' to create a new form with the title "${title} - Practice Quiz".
    3. Set the form to be a quiz using 'setIsQuiz(true)'.
    4. Parse the questions provided above and add them to the form.
       - If the question text implies multiple choice (e.g. has options A, B, C), use 'addMultipleChoiceItem'.
       - If it is a direct question, use 'addTextItem' (Short Answer) or 'addParagraphItem' (Long Answer).
       - Mark all questions as required.
    5. At the end of the script, log the 'Published URL' and 'Edit URL' using Logger.log().
    6. RETURN ONLY THE RAW JAVASCRIPT CODE. Do not use markdown blocks (\`\`\`). Do not include explanation text.
  `;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_ID,
      contents: prompt,
    });
    let text = response.text || "";
    // Clean up if markdown is present despite instructions
    text = text.replace(/```javascript/g, '').replace(/```/g, '');
    return text;
  } catch (error) {
    console.error("Gemini API Error (Form Script):", error);
    throw new Error("Failed to generate form script.");
  }
};

