                                      <div>
                                          <h3 className="font-bold text-gray-800">{messages.find(m => m.senderId === selectedThread || m.receiverId === selectedThread)?.senderName || 'Student'}</h3>
                                          <p className="text-xs text-gray-500 text-teal-600 font-mono">{selectedThread}</p>
                                      </div>
                                  </div>
