                                          onChange={e => setReplyText(e.target.value)}
                                          onKeyDown={e => e.key === 'Enter' && handleReplyToStudent(selectedThread!, messages.find(m=>m.senderId===selectedThread)?.senderName || 'Student')}
                                      />
                                      <button 
                                          onClick={() => handleReplyToStudent(selectedThread!, messages.find(m=>m.senderId===selectedThread)?.senderName || 'Student')}
                                          disabled={!replyText.trim()}
                                          className="bg-blue-600 text-white p-2 rounded-lg hover:bg-blue-700 disabled:opacity-50 transition-colors"
                                      >
                                          <Send className="w-5 h-5" />
                                      </button>
                                  </div>
                              </div>
                          </>
                      ) : (
                          <div className="flex-1 flex items-center justify-center text-gray-400 flex-col">
                              <MessageCircle className="w-12 h-12 mb-2 opacity-20" />
                              <p>Select a conversation to read</p>
