                      </div>
                      <div className="flex-1 overflow-y-auto">
                          {/* Group messages by student sender */}
                          {Array.from(new Set(messages.filter(m => !m.isFromTeacher).map(m => m.senderId))).map(studentId => {
                              const lastMsg = messages.filter(m => m.senderId === studentId || m.receiverId === studentId).pop();
                              const unread = messages.filter(m => m.senderId === studentId && !m.read).length;
                              const studentName = lastMsg?.senderId === studentId ? lastMsg?.senderName : (messages.find(m => m.senderId === studentId)?.senderName || studentId);

                              return (
                                  <div 
                                      key={studentId} 
                                      onClick={() => {
                                          setSelectedThread(studentId);
                                          markMessagesRead(studentId, profile.email);
                                          setNotifications(prev => prev.filter(n => n.type !== 'message')); // Clear notifs locally
                                      }}
                                      className={`p-4 border-b border-gray-100 hover:bg-slate-50 cursor-pointer transition-colors ${selectedThread === studentId ? 'bg-blue-50' : ''}`}
                                  >
                                      <div className="flex justify-between items-start mb-1">
                                          <h4 className={`text-sm ${unread > 0 ? 'font-bold text-slate-900' : 'font-medium text-slate-700'}`}>{studentName}</h4>
                                          <span className="text-[10px] text-gray-400">{lastMsg ? new Date(lastMsg.timestamp).toLocaleDateString() : ''}</span>
                                      </div>
                                      <p className={`text-xs truncate ${unread > 0 ? 'font-bold text-slate-800' : 'text-gray-500'}`}>
                                          {lastMsg?.isFromTeacher ? 'You: ' : ''}{lastMsg?.content}
                                      </p>
                                      {unread > 0 && <span className="inline-block bg-red-500 text-white text-[10px] px-2 rounded-full mt-1">{unread}</span>}
                                  </div>
                              );
                          })}
                          {messages.length === 0 && <div className="p-6 text-center text-gray-400 text-sm">No messages found.</div>}
                      </div>
                  </div>

