                    <form onSubmit={handleSubmitProfile} className="p-8 space-y-6">
                        {message && <div className="bg-green-50 text-green-700 p-3 rounded text-sm">{message}</div>}
                        <div className="grid grid-cols-1 gap-6">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Name</label>
                                <input type="text" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full rounded border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 p-2 border" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">School</label>
                                <input type="text" required value={formData.school} onChange={e => setFormData({...formData, school: e.target.value})} readOnly={!!profile.schoolId} className={`w-full rounded border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 p-2 border ${profile.schoolId ? 'bg-gray-100 cursor-not-allowed' : ''}`} />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                                <input type="email" readOnly value={formData.email} className="w-full rounded border-gray-300 bg-gray-50 text-gray-500 p-2 border cursor-not-allowed" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Phone</label>
                                <input type="tel" required value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full rounded border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 p-2 border" />
                            </div>
                            {profile.teacherCode && !profile.schoolId && (
                                <div className="bg-yellow-50 p-4 rounded border border-yellow-200">
                                    <label className="block text-xs font-bold text-yellow-800 mb-1 uppercase tracking-wide">Linking Code</label>
                                    <div className="text-2xl font-mono font-bold text-yellow-900 tracking-wider">{profile.teacherCode}</div>
                                    <p className="text-xs text-yellow-700 mt-1">Provide this code to your School Administrator to link your account.</p>
                                </div>
                            )}
                        </div>
                        <div className="pt-4 text-right">
                            <button type="submit" className="bg-slate-900 text-white px-6 py-2 rounded hover:bg-slate-800 transition-colors">Save Changes</button>
                        </div>
                    </form>
                </div>
            </div>
          )}

