                          Subject Performance
                      </button>
                      <button 
                          onClick={() => setManageTab('resources')}
                          className={`flex-1 py-3 px-4 text-sm font-bold border-b-2 transition-colors whitespace-nowrap ${manageTab === 'resources' ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                      >
                          Textbooks & Resources
                      </button>
                      <button 
                          onClick={() => setManageTab('forum')}
                          className={`flex-1 py-3 px-4 text-sm font-bold border-b-2 transition-colors whitespace-nowrap ${manageTab === 'forum' ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                      >
