                      <label className="block text-sm font-medium text-gray-700 mb-2">Message</label>
                      <textarea 
                          rows={4}
                          className="w-full rounded-lg border border-gray-300 p-3 text-sm focus:ring-2 focus:ring-teal-500 focus:border-transparent"
                          placeholder="Type your message..."
                          value={dmInput}
                          onChange={(e) => setDmInput(e.target.value)}
                      ></textarea>
                  </div>
                  <div className="p-6 border-t border-gray-100 bg-gray-50 flex justify-end gap-2">
                      <button onClick={() => setDmModal(null)} className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded font-medium text-sm">Cancel</button>
                      <button onClick={sendDm} className="px-4 py-2 bg-blue-600 text-white rounded font-bold text-sm hover:bg-blue-700 flex items-center gap-2">
                          <Send className="w-3 h-3" /> Send
                      </button>
                  </div>
              </div>
          </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useRef } from 'react';
import { Student, Classroom, Assignment, StudentResult, SharedNote, QuizQuestion, DirectMessage, ForumPost, ForumReply, AppNotification } from '../types';
import { 
    authenticateStudent, updateStudentName, getAssignmentsByClassId, getStudentResults, 
    saveStudentResult, getStudentNotes, getDirectMessages, sendDirectMessage, markMessagesRead, 
    createForumPost, addForumReply, getClassrooms 
} from '../services/storageService';
import { generateStudentPerformanceReport } from '../services/geminiService';
import { 
    LogIn, BookOpen, CheckCircle, Clock, ChevronRight, FileText, AlertCircle, Play, 
    Loader2, Menu, Home, Layers, Book, List, CheckSquare, BarChart2, Mail, MessageSquare, 
    User, LogOut, X, Send, Reply, Bell, ChevronLeft, ChevronLast, File, Download, Calendar, RefreshCw
} from 'lucide-react';

const StudentPortal: React.FC = () => {
  // Auth State
  const [view, setView] = useState<'login' | 'portal'>('login');
  const [accessCode, setAccessCode] = useState('');
  const [student, setStudent] = useState<Student | null>(null);
  const [classroom, setClassroom] = useState<Classroom | null>(null);
  const [studentName, setStudentName] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Portal UI State
  const [activeSection, setActiveSection] = useState<'dashboard' | 'notes' | 'textbooks' | 'all_assignments' | 'pending' | 'completed' | 'results' | 'inbox' | 'forum' | 'profile'>('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(true); // Mobile toggle
  const [isCollapsed, setIsCollapsed] = useState(false); // Desktop collapse

  // Data State
  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [results, setResults] = useState<StudentResult[]>([]);
  const [notes, setNotes] = useState<SharedNote[]>([]);
  const [messages, setMessages] = useState<DirectMessage[]>([]);
  const [forumPosts, setForumPosts] = useState<ForumPost[]>([]);

  // Notes View State
  const [selectedNote, setSelectedNote] = useState<SharedNote | null>(null);

  // Quiz Execution State
  const [quizMode, setQuizMode] = useState(false);
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Timing State
  const [quizStartTime, setQuizStartTime] = useState<number>(0);
  const [questionStartTime, setQuestionStartTime] = useState<number>(0);
  const [timePerQuestion, setTimePerQuestion] = useState<Record<number, number>>({});

  // Messaging State
  const [newMessage, setNewMessage] = useState('');

  // Forum State
  const [newForumReply, setNewForumReply] = useState('');
  const [activeForumPostId, setActiveForumPostId] = useState<string | null>(null);

  // Notification Counts
  const pendingCount = assignments.filter(a => !results.some(r => r.assignmentId === a.id)).length;
  const unreadMsgCount = messages.filter(m => !m.read && m.receiverId === student?.code).length;

  // Polling for new messages
  useEffect(() => {
      if (student && view === 'portal') {
          const interval = setInterval(() => {
              loadStudentData(student.code, classroom!.id);
          }, 10000);
          return () => clearInterval(interval);
      }
  }, [student, view, classroom]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!accessCode) return;

    const result = authenticateStudent(accessCode.toUpperCase());
    if (result) {
      setStudent(result.student);
      setClassroom(result.classroom);
      if (result.student.name) {
        loadStudentData(result.student.code, result.classroom.id);
        setView('portal');
      }
    } else {
      setError("Invalid Access Code.");
    }
  };

  const handleNameUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (student && classroom && studentName.trim()) {
      const updated = updateStudentName(classroom.id, student.code, studentName);
      if (updated) {
        setStudent(updated);
        loadStudentData(updated.code, classroom.id);
        setView('portal');
      }
    }
  };

  const loadStudentData = (code: string, classId: string) => {
    const classAssignments = getAssignmentsByClassId(classId);
    const studentResults = getStudentResults(code);
    const classNotes = getStudentNotes(classId);
    const msgs = getDirectMessages(code);

    const refreshedResult = authenticateStudent(code);
    if (refreshedResult) {
        setClassroom(refreshedResult.classroom);
        setForumPosts(refreshedResult.classroom.forumPosts || []);
    }

    setAssignments(classAssignments);
    setResults(studentResults);
    setNotes(classNotes);
    setMessages(msgs);
  };

  // --- Quiz Functions ---
  const startQuiz = (assignment: Assignment) => {
    // Attempt Limit Check
    const pastAttempts = results.filter(r => r.assignmentId === assignment.id).length;
    if (pastAttempts >= 3) {
        alert("You have reached the maximum number of attempts (3) for this assignment.");
        return;
    }

    setActiveAssignment(assignment);
    setCurrentQuestionIndex(0);
    setSelectedAnswers({});
    setTimePerQuestion({});

    const now = Date.now();
    setQuizStartTime(now);
    setQuestionStartTime(now);

    setQuizMode(true);
    setSidebarOpen(false); // Mobile close
    if(window.innerWidth < 1024) setSidebarOpen(false);
  };

  const recordTimeForCurrentQuestion = () => {
      const now = Date.now();
      const timeSpent = (now - questionStartTime) / 1000; // in seconds

      setTimePerQuestion(prev => {
          // If returning to a question, add to existing time
          const existing = prev[currentQuestionIndex] || 0;
          return { ...prev, [currentQuestionIndex]: existing + timeSpent };
      });
      setQuestionStartTime(now); // Reset for next/prev question
  };

  const handleNextQuestion = () => {
      recordTimeForCurrentQuestion();
      setCurrentQuestionIndex(prev => prev + 1);
  };

  const handlePrevQuestion = () => {
      recordTimeForCurrentQuestion();
      setCurrentQuestionIndex(prev => prev - 1);
  };

  const handleAnswerSelect = (answer: string) => {
      setSelectedAnswers(prev => ({ ...prev, [currentQuestionIndex]: answer }));
  };

  const submitQuiz = async () => {
      if (!student || !activeAssignment) return;

      // Capture time for the last question
      recordTimeForCurrentQuestion();
      const totalTimeTaken = (Date.now() - quizStartTime) / 1000; // Total seconds

      setIsSubmitting(true);

      // Calculate Score
      let score = 0;
      activeAssignment.questions.forEach((q, idx) => {
          const userAnswer = selectedAnswers[idx];
          if (userAnswer === q.correctAnswer) score++;
          else if (q.type === 'structured' && userAnswer?.toLowerCase().trim() === q.correctAnswer.toLowerCase().trim()) score++;
      });

      // Generate AI Analysis
      let aiReport = "";
      try {
          // We pass the collected timePerQuestion state which has the accumulated seconds for each index
          aiReport = await generateStudentPerformanceReport(
              activeAssignment,
              selectedAnswers,
              score,
              totalTimeTaken,
              timePerQuestion
          );
      } catch (err) {
          console.error("AI Report Generation Failed", err);
          aiReport = "Analysis could not be generated at this time.";
      }

      const result: StudentResult = {
          id: crypto.randomUUID(),
          assignmentId: activeAssignment.id,
          studentCode: student.code,
          studentName: student.name || 'Student',
          score: score,
          total: activeAssignment.questions.length,
          attempts: 1, // Will be updated by storage service based on history
          answers: selectedAnswers,
          dateTaken: new Date().toISOString(),
          timeTaken: totalTimeTaken,
          timePerQuestion: timePerQuestion,
          aiAnalysis: aiReport
      };

      saveStudentResult(result);

      // Send message to teacher about new submission
      const submissionMsg: DirectMessage = {
          id: crypto.randomUUID(),
          senderId: student.code,
          senderName: student.name || 'Student',
          receiverId: classroom?.userId || '',
          content: `I have submitted the assignment: ${activeAssignment.topic}. Score: ${score}/${activeAssignment.questions.length}.`,
          timestamp: new Date().toISOString(),
          read: false,
          isFromTeacher: false
      };
      if (classroom?.userId) sendDirectMessage(submissionMsg);

      if (classroom) loadStudentData(student.code, classroom.id);

      setIsSubmitting(false);
      setQuizMode(false);
      setActiveSection('results');
      setActiveAssignment(null);
  };

  // --- Messaging Functions ---
  const handleSendMessage = (e: React.FormEvent) => {
      e.preventDefault();
      if (!newMessage.trim() || !student || !classroom) return;

      const msg: DirectMessage = {
          id: crypto.randomUUID(),
          senderId: student.code,
          senderName: student.name || 'Student',
          receiverId: classroom.userId, // Teacher Email
          content: newMessage,
          timestamp: new Date().toISOString(),
          read: false,
          isFromTeacher: false
      };

      sendDirectMessage(msg);
      setNewMessage('');
      loadStudentData(student.code, classroom.id);
  };

  // --- Forum Functions ---
  const handleForumReply = (postId: string) => {
      if (!newForumReply.trim() || !student || !classroom) return;

      const reply: ForumReply = {
          id: crypto.randomUUID(),
          authorName: student.name || 'Student',
          authorRole: 'student',
          content: newForumReply,
          timestamp: new Date().toISOString()
      };

      addForumReply(classroom.id, postId, reply);
      setNewForumReply('');
      loadStudentData(student.code, classroom.id);
  };

  // --- Views ---

  if (view === 'login') {
      return (
          <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-gray-50 font-sans">
              <div className="bg-white p-8 rounded-xl shadow-xl w-full max-w-md border border-gray-200">
                  <div className="text-center mb-8">
                      <div className="bg-teal-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                          <BookOpen className="w-8 h-8 text-teal-600" />
                      </div>
                      <h2 className="text-2xl font-bold text-gray-800">Student Portal</h2>
                      <p className="text-gray-500 text-sm mt-1">Access your class materials</p>
                  </div>

                  {student && !student.name ? (
                      <form onSubmit={handleNameUpdate} className="space-y-6">
                          <div className="bg-blue-50 p-4 rounded-md text-sm text-blue-700">
                              Please update your profile with your full name to continue.
                          </div>
                          <div>
                              <label className="block text-sm font-medium text-gray-700 mb-1">Full Name</label>
                              <input 
                                  type="text" 
                                  required
                                  className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border px-3"
                                  value={studentName}
                                  onChange={e => setStudentName(e.target.value)}
                                  placeholder="e.g. John Doe"
                              />
                          </div>
                          <button type="submit" className="w-full bg-teal-600 text-white py-2.5 rounded-md font-medium hover:bg-teal-700 transition-colors">
                              Update Profile
                          </button>
                      </form>
                  ) : (
                      <form onSubmit={handleLogin} className="space-y-6">
                          {error && <div className="bg-red-50 text-red-700 p-3 rounded-md text-sm flex items-center gap-2 border border-red-200"><AlertCircle className="w-4 h-4"/> {error}</div>}
                          <div>
                              <label className="block text-sm font-medium text-gray-700 mb-1">Access Code</label>
                              <input 
                                  type="text" 
                                  required
                                  className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border px-3 text-center uppercase tracking-widest font-mono"
                                  value={accessCode}
                                  onChange={e => setAccessCode(e.target.value)}
                                  placeholder="XXXXXX"
                                  maxLength={6}
                              />
                          </div>
                          <button type="submit" className="w-full bg-teal-600 text-white py-2.5 rounded-md font-medium hover:bg-teal-700 transition-colors flex justify-center items-center gap-2">
                              <LogIn className="w-4 h-4" /> Enter Classroom
                          </button>
                      </form>
                  )}
              </div>
          </div>
      );
  }

  // Quiz Mode rendering
  if (quizMode && activeAssignment) {
      const question = activeAssignment.questions[currentQuestionIndex];
      const progress = ((currentQuestionIndex + 1) / activeAssignment.questions.length) * 100;
      const allAnswered = activeAssignment.questions.length > 0 && Object.keys(selectedAnswers).length === activeAssignment.questions.length;

      return (
          <div className="min-h-screen bg-gray-50 text-slate-800 font-sans pb-12">
              <div className="bg-white border-b border-gray-200 px-4 py-4 sticky top-0 z-10 shadow-sm">
                  <div className="max-w-3xl mx-auto flex justify-between items-center">
                      <div>
                          <h2 className="font-bold text-gray-800">{activeAssignment.topic}</h2>
                          <p className="text-xs text-gray-500">{activeAssignment.subject}</p>
                      </div>
                      <div className="text-sm font-medium text-gray-500">
                          Question {currentQuestionIndex + 1} of {activeAssignment.questions.length}
                      </div>
                  </div>
              </div>
              <div className="w-full h-1 bg-gray-200"><div className="h-full bg-teal-600 transition-all duration-300" style={{ width: `${progress}%` }}></div></div>
              <div className="max-w-3xl mx-auto p-6 mt-6">
                  {isSubmitting ? (
                      <div className="flex flex-col items-center justify-center py-20">
                          <Loader2 className="w-12 h-12 text-teal-600 animate-spin mb-4" />
                          <h3 className="text-xl font-bold text-gray-800">Submitting Answers...</h3>
                          <p className="text-gray-500 mt-2">Analyzing performance and generating report for your teacher.</p>
                      </div>
                  ) : (
                      <>
                          <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-8">
                              <p className="text-lg font-medium text-gray-900 mb-6 leading-relaxed">{question.question}</p>
                              {question.image && (
                                  <div className="mb-6 rounded-lg overflow-hidden border border-gray-200">
                                      <img src={question.image} alt="Question Visual" className="max-h-64 object-contain mx-auto" />
                                  </div>
                              )}
                              {question.type === 'mcq' && question.options ? (
                                  <div className="space-y-3">
                                      {question.options.map((opt, idx) => (
                                          <label key={idx} className={`flex items-center p-4 rounded-lg border transition-all cursor-pointer hover:bg-gray-50 ${selectedAnswers[currentQuestionIndex] === opt ? 'border-teal-500 bg-teal-50 ring-1 ring-teal-500' : 'border-gray-200'}`}>
                                              <input type="radio" name={`question-${question.id}`} className="h-4 w-4 text-teal-600 focus:ring-teal-500 border-gray-300" value={opt} checked={selectedAnswers[currentQuestionIndex] === opt} onChange={() => handleAnswerSelect(opt)} />
                                              <span className="ml-3 text-gray-700">{opt}</span>
                                          </label>
                                      ))}
                                  </div>
                              ) : (
                                  <div className="space-y-2">
                                     <label className="text-xs font-bold text-gray-500 uppercase">Your Answer</label>
                                     <textarea 
                                        className="w-full p-4 rounded-lg border border-gray-300 focus:ring-2 focus:ring-teal-500 focus:border-transparent min-h-[150px] shadow-sm resize-y" 
                                        placeholder="Type your structured response here..." 
                                        value={selectedAnswers[currentQuestionIndex] || ''} 
                                        onChange={(e) => handleAnswerSelect(e.target.value)} 
                                     />
                                  </div>
                              )}
                          </div>
                          <div className="mt-8 flex justify-between items-center">
                              <button onClick={() => { if(confirm("Exit quiz? Progress will be lost.")) setQuizMode(false); }} className="text-gray-500 hover:text-gray-700 font-medium text-sm">Quit Quiz</button>
                              <div className="flex gap-3">
                                  {currentQuestionIndex > 0 && <button onClick={handlePrevQuestion} className="px-4 py-2 rounded-md border border-gray-300 bg-white text-gray-700 hover:bg-gray-50 font-medium">Previous</button>}
                                  {currentQuestionIndex < activeAssignment.questions.length - 1 ? (
                                      <button onClick={handleNextQuestion} className="px-6 py-2 rounded-md bg-teal-600 text-white hover:bg-teal-700 font-medium flex items-center gap-2">Next <ChevronRight className="w-4 h-4" /></button>
                                  ) : (
                                      <button onClick={submitQuiz} disabled={!allAnswered} className="px-6 py-2 rounded-md bg-green-600 text-white hover:bg-green-700 font-medium flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed">
                                          <CheckCircle className="w-4 h-4" /> Submit Quiz
                                      </button>
                                  )}
                              </div>
                          </div>
                      </>
                  )}
              </div>
          </div>
      );
  }

  // --- Helpers for Sidebar Items ---
  const SidebarItem = ({ 
      id, icon: Icon, label, badgeCount 
  }: { 
      id: string, icon: any, label: string, badgeCount?: number 
  }) => (
      <button 
          onClick={() => {setActiveSection(id as any); if(window.innerWidth < 1024) setSidebarOpen(false);}} 
          className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors group relative ${
              activeSection === id ? 'bg-teal-600 text-white shadow-md' : 'text-slate-300 hover:bg-slate-800 hover:text-white'
          }`}
          title={isCollapsed ? label : ''}
      >
          <Icon className={`w-5 h-5 flex-shrink-0 ${!isCollapsed && 'mr-3'}`} />
          {!isCollapsed && <span>{label}</span>}

          {/* Notification Badge */}
          {badgeCount && badgeCount > 0 ? (
              isCollapsed ? (
                  <span className="absolute top-2 right-2 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-slate-900"></span>
              ) : (
                  <span className="ml-auto bg-red-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full shadow-sm animate-pulse">
                      {badgeCount}
                  </span>
              )
          ) : null}
      </button>
  );

  // --- Main Dashboard Layout ---
  return (
      <div className="flex min-h-screen bg-slate-50 font-sans text-slate-800">
          {/* Mobile Backdrop */}
          {sidebarOpen && (
            <div 
              className="fixed inset-0 bg-black/50 z-40 lg:hidden" 
              onClick={() => setSidebarOpen(false)}
            />
          )}

          {/* Sidebar */}
          <aside className={`fixed inset-y-0 left-0 z-50 bg-slate-900 text-slate-300 transition-all duration-300 ease-in-out shadow-xl flex flex-col 
              ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} 
              lg:translate-x-0 
              ${isCollapsed ? 'w-20' : 'w-64'}
          `}>
              <div className={`flex items-center h-16 px-4 bg-slate-950 text-white font-bold text-xl tracking-tight border-b border-slate-800 ${isCollapsed ? 'justify-center' : 'justify-between'}`}>
                  {!isCollapsed ? (
                      <div className="flex items-center">
                          <BookOpen className="w-6 h-6 mr-2 text-teal-500" />
                          <span>Student<span className="text-teal-500">Portal</span></span>
                      </div>
                  ) : (
                      <BookOpen className="w-8 h-8 text-teal-500" />
                  )}
                  <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-slate-400 hover:text-white p-1"><X className="w-5 h-5" /></button>
              </div>

              <nav className="flex-1 overflow-y-auto p-3 space-y-1">
                  <SidebarItem id="dashboard" icon={Home} label="Dashboard" />

                  <div className={`mt-6 mb-2 px-4 text-xs font-bold text-slate-500 uppercase tracking-wider ${isCollapsed ? 'text-center' : ''}`}>
                      {isCollapsed ? '---' : 'Academics'}
                  </div>
                  <SidebarItem id="notes" icon={FileText} label="Lesson Notes" />
                  <SidebarItem id="textbooks" icon={Book} label="Class Textbooks" />

                  <div className={`mt-6 mb-2 px-4 text-xs font-bold text-slate-500 uppercase tracking-wider ${isCollapsed ? 'text-center' : ''}`}>
                      {isCollapsed ? '---' : 'Assignments'}
                  </div>
                  <SidebarItem id="all_assignments" icon={List} label="All Assignments" />
                  <SidebarItem id="pending" icon={Clock} label="Pending" badgeCount={pendingCount} />
                  <SidebarItem id="completed" icon={CheckSquare} label="Completed" />
                  <SidebarItem id="results" icon={BarChart2} label="Results" />

                  <div className={`mt-6 mb-2 px-4 text-xs font-bold text-slate-500 uppercase tracking-wider ${isCollapsed ? 'text-center' : ''}`}>
                      {isCollapsed ? '---' : 'Communication'}
                  </div>
                  <SidebarItem id="inbox" icon={Mail} label="My Inbox" badgeCount={unreadMsgCount} />
                  <SidebarItem id="forum" icon={MessageSquare} label="Discussion Forum" badgeCount={forumPosts.length > 0 ? 1 : 0} />

                  <div className={`mt-6 mb-2 px-4 text-xs font-bold text-slate-500 uppercase tracking-wider ${isCollapsed ? 'text-center' : ''}`}>
                      {isCollapsed ? '---' : 'Account'}
                  </div>
                  <SidebarItem id="profile" icon={User} label="My Profile" />
              </nav>

              <div className="p-4 border-t border-slate-800">
                  <button onClick={() => { setStudent(null); setView('login'); }} className={`flex items-center w-full px-4 py-2.5 text-sm font-medium rounded-lg text-red-400 hover:bg-slate-800 hover:text-red-300 transition-colors ${isCollapsed ? 'justify-center' : ''}`}>
                      <LogOut className={`w-5 h-5 ${!isCollapsed && 'mr-3'}`} />
                      {!isCollapsed && <span>Sign Out</span>}
                  </button>
                  <button 
                      onClick={() => setIsCollapsed(!isCollapsed)}
                      className="hidden lg:flex mt-2 w-full items-center justify-center p-2 text-slate-500 hover:text-white hover:bg-slate-800 rounded-lg transition-colors"
                  >
                      {isCollapsed ? <ChevronRight className="w-5 h-5"/> : <ChevronLeft className="w-5 h-5"/>}
                  </button>
              </div>
          </aside>

          {/* Main Content Area */}
          <div className={`flex-1 flex flex-col transition-all duration-300 ${isCollapsed ? 'lg:ml-20' : 'lg:ml-64'}`}>
              {/* Header */}
              <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 sticky top-0 z-40 shadow-sm">
                  <div className="flex items-center gap-3">
                      <button onClick={() => setSidebarOpen(!sidebarOpen)} className="lg:hidden p-2 text-gray-500 hover:bg-gray-100 rounded-md">
                          <Menu className="w-6 h-6" />
                      </button>
                      <h1 className="text-xl font-bold text-gray-800 hidden sm:block capitalize">
                          {activeSection.replace('_', ' ')}
                      </h1>
                  </div>
                  <div className="ml-auto flex items-center gap-4">
                      <div className="text-right hidden md:block">
                          <p className="text-sm font-bold text-gray-800">{student?.name || 'Student'}</p>
                          <p className="text-xs text-gray-500">{classroom?.grade} - {classroom?.stream}</p>
                      </div>
                      <div className="w-8 h-8 bg-teal-100 text-teal-700 rounded-full flex items-center justify-center font-bold border border-teal-200">
                          {student?.name?.charAt(0) || 'S'}
                      </div>
                  </div>
              </header>

              {/* Content Render */}
              <main className="p-4 lg:p-8 max-w-7xl mx-auto w-full">

                  {activeSection === 'dashboard' && (
                      <div className="space-y-6 animate-fade-in">
                          <h2 className="text-2xl font-bold text-gray-800">Overview</h2>
                          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                              <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition-shadow">
                                  <div className="flex items-center gap-3 mb-2">
                                      <div className="p-2 bg-blue-100 text-blue-600 rounded-lg"><Clock className="w-5 h-5"/></div>
