                                  {student?.name?.charAt(0)}
                              </div>
                              <h2 className="text-xl font-bold">{student?.name}</h2>
                              <p className="text-teal-200 font-mono text-sm tracking-wider">{student?.code}</p>
                          </div>
                          <div className="p-6 space-y-4">
                              <div>
                                  <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Classroom</label>
                                  <div className="p-3 bg-gray-50 rounded border border-gray-200 font-medium text-gray-700">{classroom?.grade} - {classroom?.stream}</div>
                              </div>
                              <form onSubmit={handleNameUpdate} className="pt-4 border-t border-gray-100">
                                  <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Update Full Name</label>
                                  <div className="flex gap-2">
                                      <input 
                                          type="text" 
                                          className="flex-1 border border-gray-300 rounded px-3 py-2 text-sm focus:border-teal-500 outline-none"
                                          value={studentName}
                                          onChange={e => setStudentName(e.target.value)}
                                          placeholder={student?.name}
                                      />
                                      <button type="submit" className="bg-slate-900 text-white px-4 py-2 rounded text-sm font-bold hover:bg-slate-800">Save</button>
                                  </div>
                              </form>
                          </div>
                      </div>
                  )}
              </main>

              {/* Note Modal */}
              {selectedNote && (
                    <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
                        <div className="bg-white rounded-xl shadow-xl w-full max-w-2xl max-h-[80vh] flex flex-col overflow-hidden animate-fade-in-up">
                            <div className="bg-slate-50 px-6 py-4 border-b border-gray-200 flex justify-between items-start">
                                <div>
                                    <h3 className="text-xl font-bold text-gray-900">{selectedNote.title}</h3>
                                    <div className="flex gap-3 text-xs text-gray-500 mt-1">
                                         <span className="bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded font-bold uppercase">{selectedNote.subject}</span>
                                         <span>{new Date(selectedNote.dateShared).toLocaleDateString()}</span>
                                    </div>
                                </div>
                                <button onClick={() => setSelectedNote(null)} className="p-1 hover:bg-gray-200 rounded transition-colors"><X className="w-6 h-6 text-gray-500"/></button>
                            </div>
                            <div className="p-6 overflow-y-auto">
                                <div className="prose prose-sm max-w-none text-gray-700 whitespace-pre-wrap leading-relaxed">
                                    {selectedNote.content}
                                </div>
                                {selectedNote.images && selectedNote.images.length > 0 && (
                                    <div className="mt-6 grid grid-cols-2 gap-4">
                                        {selectedNote.images.map((img, i) => (
                                             <img key={i} src={img} alt="Note attachment" className="rounded-lg border border-gray-200 w-full object-cover" />
                                        ))}
                                    </div>
                                )}
                            </div>
                            <div className="bg-gray-50 px-6 py-4 border-t border-gray-200 flex justify-end">
                                <button onClick={() => setSelectedNote(null)} className="bg-slate-800 text-white px-4 py-2 rounded-lg text-sm font-bold hover:bg-slate-900">Close</button>
                            </div>
                        </div>
                    </div>
              )}
          </div>
      </div>
  );
};

export default StudentPortal;

