                    </div>
                    <button type="submit" disabled={loading} className="w-full flex justify-center items-center gap-2 bg-teal-600 hover:bg-teal-700 text-white font-bold py-3 px-4 rounded-lg transition-colors shadow-md mt-6 disabled:opacity-50">
                        {loading ? "Signing in..." : <>Sign In <ArrowRight className="w-4 h-4" /></>}
                    </button>
                </form>
            )}

            {/* FORGOT PASSWORD FORM */}
            {view === 'forgot' && (
                <form onSubmit={handleRetrievePassword} className="space-y-5">
                    <div className="bg-blue-50 text-blue-800 text-xs p-3 rounded mb-4">
                        Enter your details to retrieve your password.
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Email Address</label>
                        <input type="email" required value={recoverEmail} onChange={e => setRecoverEmail(e.target.value)} className="w-full rounded-md border-gray-300 p-2.5 border" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Phone Number</label>
