import React, { useState, useEffect } from 'react';
import { UserProfile, Classroom, Grade, Subject, Assignment, StudentResult, ForumPost, ForumReply, DirectMessage, AppNotification, Textbook } from '../types';
import { 
  User, School, Phone, Mail, Save, Plus, Trash2, 
  BookOpen, Users, Eye, X, Home, FileText, Settings, 
  Menu, Bell, ChevronDown, Check, ArrowLeft, MessageSquare, ChevronRight, MessageCircle, Send, Reply, ChevronLeft, Layers, Bookmark, Sparkles, Upload, File as FileIcon, Building2, Key
} from 'lucide-react';
import { 
    createClassroom, getClassrooms, deleteClassroom, addSubjectToClassroom, 
    removeSubjectFromClassroom, getSavedPlans, getAssignmentsByClassId, 
    getAssignmentResults, updateStudentResultFeedback, createForumPost, 
    addForumReply, sendDirectMessage, getDirectMessages, markMessagesRead, 
    getNotifications, markNotificationRead, uploadTextbookToClassroom
} from '../services/storageService';

interface Props {
  profile: UserProfile;
  onUpdate: (profile: UserProfile) => void;
}

// Stats Card Component for Dashboard
const StatCard = ({ icon: Icon, label, value, color }: { icon: any, label: string, value: string | number, color: string }) => (
  <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex items-center justify-between transition-transform hover:-translate-y-1 duration-300">
    <div>
      <div className={`p-3 rounded-full w-12 h-12 flex items-center justify-center mb-3 ${color} bg-opacity-10`}>
        <Icon className={`w-6 h-6 ${color.replace('bg-', 'text-')}`} />
      </div>
      <h3 className="text-gray-500 text-sm font-medium uppercase tracking-wider">{label}</h3>
    </div>
    <div className="text-right">
      <span className={`text-4xl font-light ${color.replace('bg-', 'text-')}`}>{value}</span>
    </div>
  </div>
);

const Dashboard: React.FC<Props> = ({ profile, onUpdate }) => {
  const [activeView, setActiveView] = useState<'overview' | 'classrooms' | 'profile' | 'inbox' | 'saved_plans'>('overview');
  const [sidebarOpen, setSidebarOpen] = useState(true); // Mobile Toggle
  const [isCollapsed, setIsCollapsed] = useState(false); // Desktop Collapse
  const [expandedClassId, setExpandedClassId] = useState<string | null>(null); // For sidebar accordion

  const [classrooms, setClassrooms] = useState<Classroom[]>([]);
  const [totalPlans, setTotalPlans] = useState(0);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [showNotifications, setShowNotifications] = useState(false);
  const [messages, setMessages] = useState<DirectMessage[]>([]);

  // Profile Form Data
  const [formData, setFormData] = useState<UserProfile>(profile);
  const [message, setMessage] = useState('');

  // Classroom Modals
  const [showAddClassModal, setShowAddClassModal] = useState(false);
  const [managedClassroom, setManagedClassroom] = useState<Classroom | null>(null);

  // Classroom Management State
  const [manageTab, setManageTab] = useState<'students' | 'performance' | 'forum' | 'resources'>('students');
  const [manageView, setManageView] = useState<'subjects' | 'assignments' | 'results'>('subjects');
  const [selectedSubjectForStats, setSelectedSubjectForStats] = useState<string>('');
  const [selectedAssignmentForStats, setSelectedAssignmentForStats] = useState<Assignment | null>(null);
  const [currentAssignmentResults, setCurrentAssignmentResults] = useState<StudentResult[]>([]);
  const [assignmentList, setAssignmentList] = useState<Assignment[]>([]);
  const [feedbackModal, setFeedbackModal] = useState<{resultId: string, name: string, currentFeedback: string} | null>(null);
  const [feedbackInput, setFeedbackInput] = useState('');

  // AI Analysis Modal
  const [analysisModal, setAnalysisModal] = useState<{studentName: string, report: string} | null>(null);

  // Direct Message Modal
  const [dmModal, setDmModal] = useState<{studentName: string, studentCode: string} | null>(null);
  const [dmInput, setDmInput] = useState('');

  // Inbox Reply State
  const [replyText, setReplyText] = useState('');
  const [selectedThread, setSelectedThread] = useState<string | null>(null);

  // Forum State
  const [forumPostTitle, setForumPostTitle] = useState('');
  const [forumPostContent, setForumPostContent] = useState('');
  const [replyContent, setReplyContent] = useState('');
  const [activePostId, setActivePostId] = useState<string | null>(null);

  // New Class Form
  const [newClassGrade, setNewClassGrade] = useState<Grade>(Grade.GRADE_7);
  const [newClassStream, setNewClassStream] = useState('');
  const [newClassRoll, setNewClassRoll] = useState<number>(40);

  // Subject Mgmt (Quick Add)
  const [addingSubjectTo, setAddingSubjectTo] = useState<string | null>(null);
  const [selectedSubject, setSelectedSubject] = useState<Subject>(Subject.MATHEMATICS);

  useEffect(() => {
    loadData();
    // Poll for notifications and messages
    const interval = setInterval(() => {
        setNotifications(getNotifications(profile.email));
        setMessages(getDirectMessages(profile.email));
    }, 10000);
    return () => clearInterval(interval);
  }, []);

  const loadData = () => {
    const cls = getClassrooms();
    setClassrooms(cls);
    const plans = getSavedPlans();
    setTotalPlans(plans.length);
    setNotifications(getNotifications(profile.email));
    setMessages(getDirectMessages(profile.email));
  };

  const handleCreateClassroom = (e: React.FormEvent) => {
    e.preventDefault();
    if (newClassStream && newClassRoll > 0) {
        createClassroom(newClassGrade, newClassStream, newClassRoll);
        loadData();
        setShowAddClassModal(false);
        setNewClassStream('');
        setNewClassRoll(40);
    }
  };

  const handleDeleteClassroom = (id: string) => {
    if (confirm('Are you sure? All student data will be lost.')) {
        deleteClassroom(id);
        loadData();
        if (managedClassroom?.id === id) setManagedClassroom(null);
    }
  };

  const handleSubmitProfile = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdate(formData);
    setMessage('Profile updated successfully!');
    setTimeout(() => setMessage(''), 3000);
  };

  const handleAddSubject = (classId: string) => {
      addSubjectToClassroom(classId, selectedSubject);
      setAddingSubjectTo(null);
      loadData();
  };

  const handleRemoveSubject = (classId: string, subject: string) => {
      if (confirm(`Remove ${subject}?`)) {
          removeSubjectFromClassroom(classId, subject);
          loadData();
      }
  };

  const handlePrintCodes = () => window.print();

  // --- Classroom Management Logic ---

  const openClassroomManager = (cls: Classroom) => {
      setManagedClassroom(cls);
      setManageTab('students');
      setManageView('subjects');
      setActiveView('classrooms');
  };

  const handleSidebarSubjectClick = (cls: Classroom, subject: string) => {
      setManagedClassroom(cls);
      setManageTab('performance');
      loadAssignmentsForSubjectInternal(cls.id, subject);
      setActiveView('classrooms');
      if (window.innerWidth < 1024) setSidebarOpen(false);
  };

  const loadAssignmentsForSubject = (subject: string) => {
      if (!managedClassroom) return;
      loadAssignmentsForSubjectInternal(managedClassroom.id, subject);
  };

  const loadAssignmentsForSubjectInternal = (classId: string, subject: string) => {
      const allAssignments = getAssignmentsByClassId(classId);
      const filtered = allAssignments.filter(a => a.subject === subject);
      setAssignmentList(filtered);
      setSelectedSubjectForStats(subject);
      setManageView('assignments');
  };

  const loadResultsForAssignment = (assignment: Assignment) => {
      const results = getAssignmentResults(assignment.id);
      setCurrentAssignmentResults(results);
      setSelectedAssignmentForStats(assignment);
      setManageView('results');
  };

  const openFeedbackModal = (result: StudentResult) => {
      setFeedbackInput(result.feedback || '');
      setFeedbackModal({
          resultId: result.id,
          name: result.studentName,
          currentFeedback: result.feedback || ''
      });
  };

  const saveFeedback = () => {
      if (!feedbackModal) return;
      updateStudentResultFeedback(feedbackModal.resultId, feedbackInput);
      const updatedResults = currentAssignmentResults.map(r => 
          r.id === feedbackModal.resultId ? {...r, feedback: feedbackInput} : r
      );
      setCurrentAssignmentResults(updatedResults);
      setFeedbackModal(null);
  };

  // --- Messaging ---

  const openDmModal = (student: {name?: string, code: string}) => {
      setDmModal({
          studentName: student.name || `Student ${student.code}`,
          studentCode: student.code
      });
      setDmInput('');
  };

  const sendDm = () => {
      if (!dmModal || !dmInput.trim()) return;
      const msg: DirectMessage = {
          id: crypto.randomUUID(),
          senderId: profile.email,
          senderName: profile.name,
          receiverId: dmModal.studentCode,
          content: dmInput,
          timestamp: new Date().toISOString(),
          read: false,
          isFromTeacher: true
      };
      sendDirectMessage(msg);
      setDmModal(null);
      alert("Message sent successfully!");
      setMessages(getDirectMessages(profile.email)); // Refresh local state
  };

  const handleReplyToStudent = (studentId: string, studentName: string) => {
      if (!replyText.trim()) return;
      const msg: DirectMessage = {
          id: crypto.randomUUID(),
          senderId: profile.email,
          senderName: profile.name,
          receiverId: studentId,
          content: replyText,
          timestamp: new Date().toISOString(),
          read: false,
          isFromTeacher: true
      };
      sendDirectMessage(msg);
      setReplyText('');
      setMessages(getDirectMessages(profile.email)); // Refresh
  };

  // --- Textbook Upload ---
  const handleTextbookUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file && managedClassroom) {
          if (file.size > 2 * 1024 * 1024) { // 2MB limit
              alert("File too large. Please upload files smaller than 2MB.");
              return;
          }

          const reader = new FileReader();
          reader.onloadend = () => {
              const base64 = typeof reader.result === 'string' ? reader.result : '';
              if (!base64) return;

              const newBook: Textbook = {
                  id: crypto.randomUUID(),
                  title: file.name,
                  fileData: base64,
                  fileType: file.type.includes('pdf') ? 'pdf' : 'word',
                  uploadDate: new Date().toISOString(),
                  size: `${(file.size/1024).toFixed(1)} KB`
              };

              if (managedClassroom) {
                  uploadTextbookToClassroom(managedClassroom.id, newBook);
                  // Update local state
                  setManagedClassroom(prev => prev ? {...prev, textbooks: [...(prev.textbooks || []), newBook]} : null);
              }
          };
          reader.readAsDataURL(file);
      }
  };

  // --- Forum ---

  const handleCreateForumPost = (e: React.FormEvent) => {
      e.preventDefault();
      if (!managedClassroom || !forumPostTitle.trim() || !forumPostContent.trim()) return;
      const newPost: ForumPost = {
          id: crypto.randomUUID(),
          authorName: profile.name,
          title: forumPostTitle,
          content: forumPostContent,
          timestamp: new Date().toISOString(),
          replies: []
      };
      createForumPost(managedClassroom.id, newPost);
      const updatedClass = {
          ...managedClassroom,
          forumPosts: [newPost, ...(managedClassroom.forumPosts || [])]
      };
      setManagedClassroom(updatedClass);
      setForumPostTitle('');
      setForumPostContent('');
  };

  const handleReplyToPost = (postId: string) => {
      if (!managedClassroom || !replyContent.trim()) return;
      const reply: ForumReply = {
          id: crypto.randomUUID(),
          authorName: profile.name,
          authorRole: 'teacher',
          content: replyContent,
          timestamp: new Date().toISOString()
      };
      addForumReply(managedClassroom.id, postId, reply);
      const updatedPosts = managedClassroom.forumPosts.map(p => {
          if (p.id === postId) {
              return { ...p, replies: [...p.replies, reply] };
          }
          return p;
      });
      setManagedClassroom({ ...managedClassroom, forumPosts: updatedPosts });
      setReplyContent('');
      setActivePostId(null);
  };

  const handleNotificationClick = (notif: AppNotification) => {
      markNotificationRead(notif.id);
      setNotifications(prev => prev.map(n => n.id === notif.id ? {...n, read: true} : n));
      if (notif.type === 'message') {
          setActiveView('inbox');
      }
  };

  const unreadCount = notifications.filter(n => !n.read).length;
  const unreadMessagesCount = messages.filter(m => !m.read && m.receiverId === profile.email).length;

  return (
    <div className="flex min-h-screen bg-slate-50 font-sans text-slate-800">

      {/* Mobile Backdrop */}
      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-40 lg:hidden" 
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar - Fixed */}
      <aside className={`fixed inset-y-0 left-0 z-50 bg-slate-900 text-slate-300 transition-all duration-300 ease-in-out shadow-xl flex flex-col 
          ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} 
          lg:translate-x-0 
          ${isCollapsed ? 'w-20' : 'w-64'}
      `}>
        <div className={`flex items-center h-16 px-4 bg-slate-950 text-white font-bold text-xl tracking-tight border-b border-slate-800 ${isCollapsed ? 'justify-center' : 'justify-between'}`}>
          {!isCollapsed ? (
              <div className="flex items-center">
                <BookOpen className="w-6 h-6 mr-2 text-teal-500" />
                <span>Mwalimu<span className="text-teal-500">Admin</span></span>
              </div>
          ) : (
              <BookOpen className="w-8 h-8 text-teal-500" />
          )}
          <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-slate-400 hover:text-white p-1">
            <X className="w-5 h-5" />
          </button>
        </div>

        <nav className="flex-1 overflow-y-auto p-3 space-y-1">
          <button 
            onClick={() => {setActiveView('overview'); if(window.innerWidth < 1024) setSidebarOpen(false);}}
            className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${activeView === 'overview' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'} ${isCollapsed ? 'justify-center' : ''}`}
            title="Dashboard"
          >
            <Home className={`w-5 h-5 ${!isCollapsed && 'mr-3'}`} />
            {!isCollapsed && "Dashboard"}
          </button>

          <button 
            onClick={() => {setActiveView('classrooms'); if(window.innerWidth < 1024) setSidebarOpen(false);}}
            className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${activeView === 'classrooms' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'} ${isCollapsed ? 'justify-center' : ''}`}
            title="All Classrooms"
          >
            <Layers className={`w-5 h-5 ${!isCollapsed && 'mr-3'}`} />
            {!isCollapsed && "All Classrooms"}
          </button>

          {/* Dynamic Classrooms List */}
          <div className="mt-4">
              {!isCollapsed && <p className="px-4 text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">My Classes</p>}
              <div className="space-y-1">
                  {classrooms.length > 0 ? classrooms.map(cls => (
                      <div key={cls.id} className="w-full">
                          <button 
                              onClick={() => {
                                  if (isCollapsed) {
                                      setIsCollapsed(false);
                                      setExpandedClassId(cls.id);
                                  } else {
                                      setExpandedClassId(expandedClassId === cls.id ? null : cls.id);
                                  }
                              }}
                              className={`flex items-center w-full px-4 py-2.5 text-sm font-medium rounded-lg transition-colors hover:bg-slate-800 hover:text-white ${expandedClassId === cls.id ? 'bg-slate-800 text-white' : 'text-slate-400'} ${isCollapsed ? 'justify-center' : 'justify-between'}`}
                              title={`${cls.grade} - ${cls.stream}`}
                          >
                              <div className="flex items-center">
                                  <Users className={`w-4 h-4 ${!isCollapsed && 'mr-3'}`} />
                                  {!isCollapsed && <span>{cls.grade} <span className="text-[10px] text-teal-500 ml-1">{cls.stream}</span></span>}
                              </div>
                              {!isCollapsed && (
                                  <ChevronDown className={`w-3 h-3 transition-transform ${expandedClassId === cls.id ? 'rotate-180' : ''}`} />
                              )}
                          </button>

                          {/* Expanded Class Menu */}
                          {!isCollapsed && expandedClassId === cls.id && (
                              <div className="bg-slate-950/50 rounded-lg my-1 mx-2 overflow-hidden">
                                  <button 
                                      onClick={() => {openClassroomManager(cls); if(window.innerWidth < 1024) setSidebarOpen(false);}}
                                      className="flex items-center w-full px-8 py-2 text-xs text-slate-400 hover:text-white hover:bg-slate-800"
                                  >
                                      <span className="w-1.5 h-1.5 rounded-full bg-slate-600 mr-2"></span> Students ({cls.students.length})
                                  </button>
                                  {cls.subjects.length > 0 ? (
                                      cls.subjects.map(sub => (
                                          <button 
                                              key={sub}
                                              onClick={() => handleSidebarSubjectClick(cls, sub)}
                                              className="flex items-center w-full px-8 py-2 text-xs text-slate-400 hover:text-white hover:bg-slate-800"
                                          >
                                              <span className="w-1.5 h-1.5 rounded-full bg-teal-600 mr-2"></span> {sub}
                                          </button>
                                      ))
                                  ) : (
                                      <div className="px-8 py-2 text-[10px] text-slate-600 italic">No subjects added</div>
                                  )}
                              </div>
                          )}
                      </div>
                  )) : (
                      !isCollapsed && <div className="px-4 text-xs text-slate-500 italic">No classes assigned yet.</div>
                  )}
              </div>
          </div>

          <div className="pt-4 mt-4 border-t border-slate-800">
            {!isCollapsed && <p className="px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">Communication</p>}
            <button 
                onClick={() => {setActiveView('inbox'); if(window.innerWidth < 1024) setSidebarOpen(false);}}
                className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors group relative ${activeView === 'inbox' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'} ${isCollapsed ? 'justify-center' : ''}`}
                title="My Inbox"
            >
              <Mail className={`w-5 h-5 ${!isCollapsed && 'mr-3'}`} />
              {!isCollapsed && <span>My Inbox</span>}
              {unreadMessagesCount > 0 && (
                  isCollapsed ? 
                  <span className="absolute top-2 right-2 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-slate-900"></span> :
                  <span className="ml-auto bg-red-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full">{unreadMessagesCount}</span>
              )}
            </button>
          </div>

          <div className="pt-4 mt-4 border-t border-slate-800">
            {!isCollapsed && <p className="px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">Account</p>}
