                                                          <td className="px-6 py-3 text-right flex gap-2 justify-end">
                                                              {result.aiAnalysis && (
                                                                  <button 
                                                                    onClick={() => setAnalysisModal({ studentName: result.studentName, report: result.aiAnalysis || '' })}
                                                                    className="inline-flex items-center gap-1 text-xs font-bold px-3 py-1.5 rounded bg-purple-50 text-purple-600 hover:bg-purple-100 transition-colors"
                                                                    title="View AI Analysis"
