                              <div className="flex-1 overflow-y-auto">
                                  {managedClassroom.textbooks && managedClassroom.textbooks.length > 0 ? (
                                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                          {managedClassroom.textbooks.map(book => (
                                              <div key={book.id} className="border border-gray-200 rounded-lg p-4 bg-white hover:shadow-md transition-shadow flex items-start gap-3">
                                                  <div className="p-3 bg-red-50 text-red-600 rounded-lg">
                                                      <FileIcon className="w-6 h-6" />
                                                  </div>
                                                  <div className="flex-1 min-w-0">
                                                      <h4 className="font-bold text-slate-700 truncate">{book.title}</h4>
                                                      <p className="text-xs text-gray-500">{new Date(book.uploadDate).toLocaleDateString()} • {book.size}</p>
                                                      <a href={book.fileData} download={book.title} className="text-xs text-teal-600 font-bold hover:underline mt-1 inline-block">Download</a>
                                                  </div>
