                                                              {result.aiAnalysis && (
                                                                  <button 
                                                                    onClick={() => setAnalysisModal({ studentName: result.studentName, report: result.aiAnalysis || '' })}
                                                                    className="inline-flex items-center gap-1 text-xs font-bold px-3 py-1.5 rounded bg-purple-50 text-purple-600 hover:bg-purple-100 transition-colors"
                                                                    title="View AI Analysis"
                                                                  >
                                                                      <Sparkles className="w-3 h-3" /> Report
                                                                  </button>
                                                              )}
                                                              <button 
                                                                  onClick={() => openFeedbackModal(result)}
                                                                  className={`inline-flex items-center gap-1 text-xs font-bold px-3 py-1.5 rounded transition-colors ${result.feedback ? 'bg-blue-50 text-blue-600 hover:bg-blue-100' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                                                              >
                                                                  <MessageSquare className="w-3 h-3" />
                                                                  {result.feedback ? 'Edit Feedback' : 'Give Feedback'}
                                                              </button>
                                                          </td>
                                                      </tr>
                                                  ))}
                                                  {currentAssignmentResults.length === 0 && (
                                                      <tr><td colSpan={4} className="px-6 py-8 text-center text-gray-400">No students have completed this assignment yet.</td></tr>
                                                  )}
                                              </tbody>
                                          </table>
                                      </div>
                                  </div>
                              )}
                          </div>
                      )}

                      {/* TAB 3: TEXTBOOKS & RESOURCES */}
                      {manageTab === 'resources' && (
                          <div className="p-6 h-full flex flex-col">
                              <h3 className="text-lg font-bold text-gray-800 mb-4">Class Textbooks & Resources</h3>

                              <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 mb-6">
                                  <label className="block text-sm font-medium text-blue-800 mb-2">Upload New Textbook (PDF/Doc)</label>
                                  <div className="flex items-center gap-3">
                                      <label className="cursor-pointer bg-white border border-blue-300 text-blue-600 hover:bg-blue-50 px-4 py-2 rounded-md shadow-sm text-sm font-bold flex items-center gap-2 transition-colors">
                                          <Upload className="w-4 h-4" />
