                              <form onSubmit={handleCreateForumPost} className="bg-slate-50 p-4 rounded-xl border border-gray-200 mb-6">
                                  <input 
                                      type="text" 
                                      placeholder="Discussion Title" 
                                      className="w-full mb-2 p-2 rounded border border-gray-300 text-sm font-bold"
                                      value={forumPostTitle}
                                      onChange={e => setForumPostTitle(e.target.value)}
                                      required
                                  />
                                  <textarea 
                                      rows={2} 
                                      placeholder="Start a discussion or make an announcement..." 
                                      className="w-full p-2 rounded border border-gray-300 text-sm mb-2"
                                      value={forumPostContent}
                                      onChange={e => setForumPostContent(e.target.value)}
                                      required
                                  ></textarea>
                                  <div className="text-right">
                                      <button type="submit" className="bg-slate-900 text-white px-4 py-1.5 rounded text-xs font-bold hover:bg-slate-800">Post to Class</button>
                                  </div>
                              </form>

                              {/* Posts List */}
                              <div className="flex-1 overflow-y-auto space-y-4">
                                  {managedClassroom.forumPosts && managedClassroom.forumPosts.length > 0 ? (
                                      managedClassroom.forumPosts.map(post => (
                                          <div key={post.id} className="border border-gray-200 rounded-xl p-4 bg-white">
                                              <div className="flex justify-between items-start mb-2">
                                                  <div>
                                                      <h4 className="font-bold text-teal-800">{post.title}</h4>
                                                      <p className="text-xs text-gray-500">Posted by {post.authorName} • {new Date(post.timestamp).toLocaleDateString()}</p>
                                                  </div>
                                                  <span className="text-xs bg-gray-100 px-2 py-1 rounded text-gray-600">{post.replies.length} replies</span>
                                              </div>
                                              <p className="text-sm text-gray-700 mb-4">{post.content}</p>

                                              {/* Replies */}
                                              {post.replies.length > 0 && (
                                                  <div className="bg-gray-50 rounded p-3 mb-3 space-y-2">
                                                      {post.replies.map(reply => (
                                                          <div key={reply.id} className="text-xs border-l-2 border-gray-300 pl-2">
                                                              <span className={`font-bold ${reply.authorRole === 'teacher' ? 'text-teal-600' : 'text-blue-600'}`}>
                                                                  {reply.authorName}
                                                                  {reply.authorRole === 'teacher' && <span className="ml-1 text-[9px] bg-teal-100 text-teal-800 px-1 rounded uppercase">Teacher</span>}
                                                              </span>
                                                              <p className="text-gray-600">{reply.content}</p>
                                                          </div>
                                                      ))}
                                                  </div>
                                              )}

                                              {/* Reply Input */}
                                              {activePostId === post.id ? (
                                                  <div className="flex gap-2">
                                                      <input 
                                                          type="text" 
                                                          className="flex-1 text-sm border border-gray-300 rounded px-2 py-1"
