                                              : 'N/A'
                                          }
                                      </span>
                                  </div>
                              </div>
                              <div className="mt-8">
                                  <button onClick={() => { setStudent(null); setView('login'); }} className="w-full bg-red-50 text-red-600 py-3 rounded-lg font-bold hover:bg-red-100 transition-colors flex justify-center items-center gap-2">
                                      <LogOut className="w-4 h-4" /> Sign Out
