                              <h3 className="font-bold text-lg">{selectedNote.title}</h3>
                              <p className="text-xs text-slate-400">{selectedNote.subject} • {new Date(selectedNote.dateShared).toLocaleDateString()}</p>
                          </div>
                          <button onClick={() => setSelectedNote(null)}><X className="w-5 h-5" /></button>
