                                          <div key={msg.id} className={`flex ${msg.isFromTeacher ? 'justify-end' : 'justify-start'}`}>
                                              <div className={`max-w-[70%] rounded-xl p-3 text-sm shadow-sm ${msg.isFromTeacher ? 'bg-blue-600 text-white rounded-br-none' : 'bg-white text-gray-800 border border-gray-200 rounded-bl-none'}`}>
                                                  <p>{msg.content}</p>
                                                  <p className={`text-[10px] mt-1 text-right ${msg.isFromTeacher ? 'text-blue-200' : 'text-gray-400'}`}>
                                                      {new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                                  </p>
                                              </div>
                                          </div>
                                      ))}
                              </div>
                              <div className="p-4 border-t border-gray-200 bg-white">
                                  <div className="flex gap-2">
                                      <input 
                                          type="text" 
                                          className="flex-1 border border-gray-300 rounded-lg px-4 py-2 text-sm focus:outline-none focus:border-teal-500"
                                          placeholder="Type your reply..."
