                            </div>
                            <div className="p-5 bg-slate-50 min-h-[100px]">
                                <div className="flex justify-between items-center mb-3">
                                    <h5 className="text-xs font-bold text-gray-400 uppercase">Subjects</h5>
                                    {addingSubjectTo === room.id ? (
                                        <div className="flex items-center gap-1">
                                            <select 
                                                value={selectedSubject} 
                                                onChange={(e) => setSelectedSubject(e.target.value as Subject)}
                                                className="text-xs border-gray-300 rounded shadow-sm py-1 w-32"
                                            >
                                                {Object.values(Subject).map(s => <option key={s} value={s}>{s}</option>)}
                                            </select>
                                            <button onClick={() => handleAddSubject(room.id)} className="bg-green-600 text-white p-1 rounded"><Check className="w-3 h-3" /></button>
                                            <button onClick={() => setAddingSubjectTo(null)} className="bg-gray-300 text-gray-700 p-1 rounded"><X className="w-3 h-3" /></button>
                                        </div>
                                    ) : (
                                        <button onClick={() => setAddingSubjectTo(room.id)} className="text-teal-600 text-xs font-bold hover:underline flex items-center gap-1"><Plus className="w-3 h-3" /> Add</button>
                                    )}
                                </div>
                                <div className="flex flex-wrap gap-2">
                                    {room.subjects.length > 0 ? room.subjects.map(sub => (
                                        <span key={sub} className="inline-flex items-center gap-1 bg-white border border-gray-200 text-gray-600 px-2 py-1 rounded text-xs font-medium">
                                            {sub}
                                            <button onClick={() => handleRemoveSubject(room.id, sub)} className="text-gray-400 hover:text-red-500"><X className="w-3 h-3" /></button>
                                        </span>
                                    )) : <span className="text-gray-400 text-xs italic">No subjects added.</span>}
                                </div>
                            </div>
                        </div>
                    ))}
                    {classrooms.length === 0 && <div className="col-span-full text-center py-10 text-gray-400 italic">No classrooms found.</div>}
                </div>
            </div>
