      {/* Add Class Modal - Only for independent teachers */}
      {showAddClassModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white">
                    <h3 className="font-bold">New Classroom</h3>
                    <button onClick={() => setShowAddClassModal(false)}><X className="w-5 h-5" /></button>
                </div>
                <form onSubmit={handleCreateClassroom} className="p-6 space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Grade</label>
                        <select value={newClassGrade} onChange={(e) => setNewClassGrade(e.target.value as Grade)} className="w-full rounded border-gray-300 p-2 border">
                            {Object.values(Grade).map(g => <option key={g} value={g}>{g}</option>)}
                        </select>
