                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Roll</label>
                        <input type="number" min="1" max="100" required value={newClassRoll} onChange={(e) => setNewClassRoll(parseInt(e.target.value) || 0)} className="w-full rounded border-gray-300 p-2 border" />
                    </div>
                    <button type="submit" className="w-full bg-teal-600 text-white font-bold py-2 rounded hover:bg-teal-700">Generate</button>
                </form>
            </div>
        </div>
      )}

      {/* Classroom Manager Modal */}
      {managedClassroom && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-4xl overflow-hidden animate-fade-in-up h-[90vh] flex flex-col">
                  {/* Header */}
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white shrink-0">
                      <div>
                          <h3 className="font-bold text-lg">{managedClassroom.grade} - {managedClassroom.stream}</h3>
                          <p className="text-slate-400 text-xs">Classroom Management</p>
                      </div>
                      <button onClick={() => setManagedClassroom(null)} className="hover:bg-slate-700 p-2 rounded transition-colors"><X className="w-5 h-5" /></button>
                  </div>

                  {/* Tabs */}
                  <div className="flex border-b border-gray-200 bg-gray-50 overflow-x-auto">
                      <button 
                          onClick={() => setManageTab('students')}
                          className={`flex-1 py-3 px-4 text-sm font-bold border-b-2 transition-colors whitespace-nowrap ${manageTab === 'students' ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                      >
                          Student Codes
                      </button>
                      <button 
                          onClick={() => { setManageTab('performance'); setManageView('subjects'); }}
                          className={`flex-1 py-3 px-4 text-sm font-bold border-b-2 transition-colors whitespace-nowrap ${manageTab === 'performance' ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                      >
                          Subject Performance
                      </button>
                      <button 
                          onClick={() => setManageTab('resources')}
                          className={`flex-1 py-3 px-4 text-sm font-bold border-b-2 transition-colors whitespace-nowrap ${manageTab === 'resources' ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                      >
                          Textbooks & Resources
                      </button>
                      <button 
                          onClick={() => setManageTab('forum')}
                          className={`flex-1 py-3 px-4 text-sm font-bold border-b-2 transition-colors whitespace-nowrap ${manageTab === 'forum' ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
                      >
                          Discussion Forum
                      </button>
                  </div>

