};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { UserProfile, Classroom, Grade, Subject, Student, LessonPlanData, LessonPlanComment } from '../types';
import { 
    getClassrooms, createClassroom, getSchoolTeachers, linkTeacherToSchool, createTeacherAccount,
    addStudentsToClassroom, updateStudentName, getTeacherPlans, deleteStudentFromClassroom, addCommentToPlan
} from '../services/storageService';
import LessonPlanDisplay from './LessonPlanDisplay';
import { 
    Users, BookOpen, UserPlus, Plus, GraduationCap, School, 
    ChevronRight, Copy, Check, Search, Mail, Phone, Lock, Eye, Trash2, Link, ArrowLeft, MessageSquare, Send
} from 'lucide-react';

interface Props {
  profile: UserProfile;
}

const SchoolDashboard: React.FC<Props> = ({ profile }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'teachers' | 'classes' | 'students'>('overview');
  const [teachers, setTeachers] = useState<UserProfile[]>([]);
  const [classrooms, setClassrooms] = useState<Classroom[]>([]);

  // Teacher Linking & Creation
  const [showLinkTeacher, setShowLinkTeacher] = useState(false);
  const [showCreateTeacher, setShowCreateTeacher] = useState(false);
  const [teacherCode, setTeacherCode] = useState('');
  const [newTeacherForm, setNewTeacherForm] = useState({ name: '', email: '', phone: '', password: '' });

  // Class Creation
  const [showAddClass, setShowAddClass] = useState(false);
  const [newClassData, setNewClassData] = useState({ grade: Grade.GRADE_7, stream: '', teacherId: '', roll: 40 });

  // Student Management
  const [selectedClassId, setSelectedClassId] = useState<string | null>(null);
  const [bulkStudentCount, setBulkStudentCount] = useState(5);

  // Teacher Profile View
  const [selectedTeacher, setSelectedTeacher] = useState<UserProfile | null>(null);

  // Lesson Plan View
  const [selectedPlan, setSelectedPlan] = useState<LessonPlanData | null>(null);
  const [newComment, setNewComment] = useState('');

  useEffect(() => {
      loadData();
  }, []);

  const loadData = () => {
      if (profile.schoolId) {
          setTeachers(getSchoolTeachers(profile.schoolId));
          setClassrooms(getClassrooms()); // getClassrooms filters by schoolId for school_admins
      }
  };

  const handleLinkTeacher = (e: React.FormEvent) => {
      e.preventDefault();
      try {
          if (profile.schoolId) {
            linkTeacherToSchool(profile.schoolId, teacherCode.toUpperCase());
            setShowLinkTeacher(false);
            setTeacherCode('');
            loadData();
            alert("Teacher linked successfully! All their data has been transferred.");
          }
      } catch (e: any) {
          alert(e.message);
      }
  };

  const handleCreateTeacher = (e: React.FormEvent) => {
      e.preventDefault();
      try {
          if (profile.schoolId) {
              createTeacherAccount(profile.schoolId, newTeacherForm.name, newTeacherForm.email, newTeacherForm.phone, newTeacherForm.password);
              setShowCreateTeacher(false);
              setNewTeacherForm({ name: '', email: '', phone: '', password: '' });
              loadData();
              alert("Teacher account created successfully! They can now log in.");
          }
      } catch (e: any) {
          alert(e.message);
      }
  };

  const handleCreateClass = (e: React.FormEvent) => {
      e.preventDefault();
      try {
          createClassroom(newClassData.grade, newClassData.stream, newClassData.roll, newClassData.teacherId);
          setShowAddClass(false);
          setNewClassData({ grade: Grade.GRADE_7, stream: '', teacherId: '', roll: 40 });
          loadData();
      } catch (e: any) {
          alert(e.message);
      }
  };

  const handleAddBulkStudents = (classId: string) => {
      if (bulkStudentCount > 0) {
          addStudentsToClassroom(classId, bulkStudentCount);
          loadData();
          setBulkStudentCount(5);
      }
  };

  const handleDeleteStudent = (classId: string, studentCode: string) => {
      if (confirm("Are you sure you want to delete this student?")) {
          deleteStudentFromClassroom(classId, studentCode);
          loadData();
      }
  };

  const handleAddComment = () => {
      if (!selectedPlan || !selectedPlan.id || !newComment.trim()) return;
      const comment: LessonPlanComment = {
          id: crypto.randomUUID(),
          authorName: profile.name,
          date: new Date().toISOString(),
          content: newComment
      };
      addCommentToPlan(selectedPlan.id, comment);
      setNewComment('');
      // Refresh local state for immediate feedback
      setSelectedPlan({
          ...selectedPlan,
          adminComments: [...(selectedPlan.adminComments || []), comment]
      });
  };

  const copyToClipboard = (text: string) => {
      navigator.clipboard.writeText(text);
      alert("Copied to clipboard!");
  };

  const totalStudents = classrooms.reduce((acc, c) => acc + c.students.length, 0);

  // If viewing a plan details
  if (selectedPlan) {
      return (
          <div className="min-h-screen bg-gray-100">
              <div className="bg-white border-b border-gray-200 px-4 py-3 sticky top-0 z-40 flex items-center justify-between">
                  <button onClick={() => setSelectedPlan(null)} className="flex items-center text-slate-600 hover:text-slate-800 font-bold">
                      <ArrowLeft className="w-5 h-5 mr-2" /> Back to Teacher Profile
                  </button>
                  <div className="text-sm font-bold text-slate-500">Admin Review Mode</div>
              </div>

              <div className="flex flex-col lg:flex-row max-w-7xl mx-auto gap-6 p-6">
                  <div className="flex-1">
                      <LessonPlanDisplay plan={selectedPlan} onBack={() => setSelectedPlan(null)} />
                  </div>

                  {/* Admin Comment Section */}
                  <div className="w-full lg:w-80 shrink-0 space-y-4">
                      <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200">
                          <h3 className="font-bold text-slate-800 mb-3 flex items-center gap-2">
                              <MessageSquare className="w-4 h-4" /> Admin Comments
                          </h3>
                          <div className="space-y-3 max-h-[400px] overflow-y-auto mb-4">
                              {selectedPlan.adminComments?.map(comment => (
                                  <div key={comment.id} className="bg-slate-50 p-3 rounded-lg text-sm">
                                      <div className="flex justify-between items-center mb-1">
                                          <span className="font-bold text-slate-700">{comment.authorName}</span>
                                          <span className="text-[10px] text-gray-400">{new Date(comment.date).toLocaleDateString()}</span>
                                      </div>
                                      <p className="text-slate-600">{comment.content}</p>
                                  </div>
                              ))}
                              {(!selectedPlan.adminComments || selectedPlan.adminComments.length === 0) && (
                                  <p className="text-slate-400 text-xs italic text-center py-4">No comments yet.</p>
                              )}
                          </div>

                          <div className="pt-3 border-t border-gray-100">
