                            <label className="text-xs font-bold text-slate-500 uppercase">Email Address</label>
                            <input required type="email" className="w-full border rounded p-2 text-sm" value={newTeacherForm.email} onChange={e => setNewTeacherForm({...newTeacherForm, email: e.target.value})} placeholder="teacher@school.com"/>
