                        <div>
                            <label className="text-xs font-bold text-slate-500 uppercase">Phone Number</label>
                            <input required type="tel" className="w-full border rounded p-2 text-sm" value={newTeacherForm.phone} onChange={e => setNewTeacherForm({...newTeacherForm, phone: e.target.value})} placeholder="07..."/>
                        </div>
                        <div>
                            <label className="text-xs font-bold text-slate-500 uppercase">Set Password</label>
                            <input required type="password" className="w-full border rounded p-2 text-sm" value={newTeacherForm.password} onChange={e => setNewTeacherForm({...newTeacherForm, password: e.target.value})} placeholder="••••••••" minLength={6}/>
                        </div>
                        <div className="flex gap-2 justify-end mt-6">
                            <button type="button" onClick={() => setShowCreateTeacher(false)} className="px-4 py-2 text-slate-600 font-bold text-sm">Cancel</button>
                            <button type="submit" className="px-4 py-2 bg-teal-600 text-white rounded font-bold text-sm">Create Account</button>
                        </div>
                    </form>
                </div>
            </div>
        )}

        {/* MODAL: ADD CLASS */}
        {showAddClass && (
            <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
                <div className="bg-white rounded-xl shadow-xl w-full max-w-md p-6 animate-fade-in-up">
                    <h3 className="text-lg font-bold text-slate-800 mb-4">Create New Class</h3>
                    <form onSubmit={handleCreateClass} className="space-y-4">
                        <div>
                            <label className="text-xs font-bold text-slate-500 uppercase">Grade</label>
                            <select value={newClassData.grade} onChange={e => setNewClassData({...newClassData, grade: e.target.value as Grade})} className="w-full border rounded p-2 text-sm">
                                {Object.values(Grade).map(g => <option key={g} value={g}>{g}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="text-xs font-bold text-slate-500 uppercase">Stream Name</label>
                            <input required type="text" placeholder="e.g. Blue, East, A" className="w-full border rounded p-2 text-sm" value={newClassData.stream} onChange={e => setNewClassData({...newClassData, stream: e.target.value})} />
                        </div>
                        <div>
                            <label className="text-xs font-bold text-slate-500 uppercase">Class Teacher (Assign)</label>
                            <select value={newClassData.teacherId} onChange={e => setNewClassData({...newClassData, teacherId: e.target.value})} className="w-full border rounded p-2 text-sm">
                                <option value="">-- Select Teacher --</option>
                                {teachers.map(t => <option key={t.id} value={t.email}>{t.name}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="text-xs font-bold text-slate-500 uppercase">Number of Students</label>
                            <input required type="number" min="0" max="100" className="w-full border rounded p-2 text-sm" value={newClassData.roll} onChange={e => setNewClassData({...newClassData, roll: parseInt(e.target.value)})} />
                        </div>
                        <div className="flex gap-2 justify-end mt-6">
                            <button type="button" onClick={() => setShowAddClass(false)} className="px-4 py-2 text-slate-600 font-bold text-sm">Cancel</button>
                            <button type="submit" className="px-4 py-2 bg-indigo-600 text-white rounded font-bold text-sm">Create Class</button>
                        </div>
                    </form>
                </div>
            </div>
        )}

    </div>
  );
};

