                                                      <button onClick={() => startQuiz(assign)} className="bg-blue-600 text-white px-5 py-2 rounded-lg font-bold text-sm hover:bg-blue-700 transition-colors flex items-center gap-2">
                                                          <RefreshCw className="w-4 h-4" /> Retake Quiz
                                                      </button>
                                                  )
                                              )}
                                          </div>
                                      );
                                  })
