                              Object.entries(groupedNotes).map(([subject, subjectNotes]) => (
                                  <div key={subject}>
                                      <h3 className="text-lg font-bold text-teal-800 mb-4 flex items-center gap-2">
                                          <span className="w-2 h-8 bg-teal-500 rounded-full"></span>
                                          {subject}
                                      </h3>
                                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                          {subjectNotes.map(note => (
                                              <div key={note.id} className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition-shadow">
                                                  <div className="flex justify-between items-start mb-2">
                                                      <span className="text-xs text-gray-400 flex items-center gap-1">
                                                          <Clock className="w-3 h-3" /> {new Date(note.dateShared).toLocaleDateString()}
                                                      </span>
                                                  </div>
                                                  <h4 className="font-bold text-lg text-gray-900 mb-2">{note.title}</h4>
                                                  <p className="text-sm text-gray-600 line-clamp-3 mb-4">{note.content.replace(/\*\*/g, '')}</p>
                                                  <button onClick={() => setSelectedNote(note)} className="text-teal-600 text-sm font-bold hover:underline flex items-center gap-1">
                                                      Read Full Note <ChevronRight className="w-4 h-4"/>
                                                  </button>
                                              </div>
                                          ))}
                                      </div>
                                  </div>
                              ))
                          )}
                      </div>
                  )}

                  {activeSection === 'textbooks' && (
                      <div className="space-y-6 animate-fade-in">
                          <h2 className="text-2xl font-bold text-gray-800">Class Textbooks & Resources</h2>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                              {classroom?.textbooks && classroom.textbooks.length > 0 ? (
                                  classroom.textbooks.map(book => (
                                      <div key={book.id} className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition-shadow flex items-start gap-4">
                                          <div className="p-3 bg-red-50 text-red-600 rounded-lg">
                                              <File className="w-8 h-8" />
                                          </div>
                                          <div className="flex-1 min-w-0">
                                              <h4 className="font-bold text-slate-800 truncate mb-1">{book.title}</h4>
                                              <p className="text-xs text-gray-500 mb-3">{new Date(book.uploadDate).toLocaleDateString()} • {book.size}</p>
                                              <a 
                                                  href={book.fileData} 
                                                  download={book.title}
                                                  className="inline-flex items-center gap-2 bg-teal-600 text-white px-4 py-2 rounded-lg text-xs font-bold hover:bg-teal-700 transition-colors"
                                              >
                                                  <Download className="w-3 h-3" /> Download
                                              </a>
                                          </div>
                                      </div>
                                  ))
                              ) : (
                                  <div className="col-span-full text-center py-10 bg-white rounded-xl border border-dashed border-gray-200 text-gray-400">
                                      No textbooks uploaded by your teacher yet.
                                  </div>
                              )}
                          </div>
                      </div>
                  )}

                  {activeSection === 'results' && (
                      <div className="space-y-6 animate-fade-in">
                          <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                              <table className="w-full text-sm text-left">
                                  <thead className="bg-gray-50 text-gray-600 font-bold border-b border-gray-200">
                                      <tr>
                                          <th className="px-6 py-4">Assignment</th>
                                          <th className="px-6 py-4">Date</th>
                                          <th className="px-6 py-4">Score</th>
                                          <th className="px-6 py-4">Feedback</th>
                                      </tr>
                                  </thead>
                                  <tbody className="divide-y divide-gray-100">
                                      {processedResults.map(result => {
                                          const assign = assignments.find(a => a.id === result.assignmentId);
                                          const pct = Math.round((result.score/result.total)*100);
                                          return (
                                              <tr key={result.id} className="hover:bg-gray-50">
                                                  <td className="px-6 py-4">
                                                      <div className="font-bold text-gray-900">{assign?.topic || 'Unknown'}</div>
                                                      <div className="text-xs text-gray-500">{assign?.subject}</div>
                                                  </td>
                                                  <td className="px-6 py-4 text-gray-500">{new Date(result.dateTaken).toLocaleDateString()}</td>
                                                  <td className="px-6 py-4">
                                                      <span className={`px-2 py-1 rounded text-xs font-bold ${pct >= 70 ? 'bg-green-100 text-green-700' : pct >= 50 ? 'bg-yellow-100 text-yellow-700' : 'bg-red-100 text-red-700'}`}>
                                                          {pct}% ({result.score}/{result.total})
                                                      </span>
                                                  </td>
                                                  <td className="px-6 py-4 text-gray-600 italic">
                                                      {result.feedback || <span className="text-gray-400">No feedback yet</span>}
                                                  </td>
                                              </tr>
                                          );
                                      })}
                                      {processedResults.length === 0 && <tr><td colSpan={4} className="px-6 py-8 text-center text-gray-400">No results found.</td></tr>}
                                  </tbody>
                              </table>
                          </div>
                      </div>
                  )}

                  {activeSection === 'inbox' && (
                      <div className="flex flex-col h-[calc(100vh-8rem)] bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden animate-fade-in">
                          <div className="p-4 border-b border-gray-200 bg-gray-50 flex justify-between items-center">
                              <h3 className="font-bold text-gray-800 flex items-center gap-2"><Mail className="w-5 h-5"/> My Inbox</h3>
                              <span className="text-xs text-gray-500">Direct Messages with Teacher</span>
                          </div>
                          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50">
                              {messages.length === 0 ? (
                                  <div className="text-center py-10 text-gray-400">No messages yet. Start a conversation!</div>
                              ) : (
                                  messages.map(msg => (
                                      <div key={msg.id} className={`flex ${msg.senderId === student?.code ? 'justify-end' : 'justify-start'}`}>
                                          <div className={`max-w-[80%] rounded-xl p-3 shadow-sm ${msg.senderId === student?.code ? 'bg-teal-600 text-white rounded-br-none' : 'bg-white text-gray-800 border border-gray-200 rounded-bl-none'}`}>
                                              <p className="text-sm">{msg.content}</p>
                                              <p className={`text-[10px] mt-1 text-right ${msg.senderId === student?.code ? 'text-teal-200' : 'text-gray-400'}`}>{new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                                          </div>
                                      </div>
                                  ))
