            <div className="flex gap-3">
                <span className="bg-amber-200 p-1 rounded text-amber-700 font-bold px-2">i</span>
                <div>
                    <p className="text-sm font-bold">Welcome to MwalimuPlanner</p>
                    <p className="text-xs mt-1">
                        {profile.schoolId 
                            ? "Your account is managed by your school." 
                            : `Your Unique Teacher Code is: ${profile.teacherCode}. Share this code with your School Admin to link your account.`}
                    </p>
                </div>
            </div>
            <button className="text-amber-600 hover:text-amber-900"><X className="w-4 h-4" /></button>
          </div>

