                      <div className="p-4 border-b border-gray-200 bg-gray-50">
                          <h3 className="font-bold text-gray-800">My Inbox</h3>
                          <p className="text-xs text-gray-500">Student Messages</p>
                      </div>
                      <div className="flex-1 overflow-y-auto">
                          {/* Group messages by student sender */}
                          {Array.from(new Set(messages.filter(m => !m.isFromTeacher).map(m => m.senderId))).map(studentId => {
                              const lastMsg = messages.filter(m => m.senderId === studentId || m.receiverId === studentId).pop();
                              const unread = messages.filter(m => m.senderId === studentId && !m.read).length;
                              const studentName = lastMsg?.senderId === studentId ? lastMsg?.senderName : (messages.find(m => m.senderId === studentId)?.senderName || studentId);

                              return (
                                  <div 
                                      key={studentId} 
                                      onClick={() => handleSelectThread(studentId)}
                                      className={`p-4 border-b border-gray-100 hover:bg-slate-50 cursor-pointer transition-colors ${selectedThread === studentId ? 'bg-blue-50' : ''}`}
                                  >
                                      <div className="flex justify-between items-start mb-1">
                                          <h4 className={`text-sm ${unread > 0 ? 'font-bold text-slate-900' : 'font-medium text-slate-700'}`}>{studentName}</h4>
                                          <span className="text-[10px] text-gray-400">{lastMsg ? new Date(lastMsg.timestamp).toLocaleDateString() : ''}</span>
                                      </div>
                                      <p className={`text-xs truncate ${unread > 0 ? 'font-bold text-slate-800' : 'text-gray-500'}`}>
                                          {lastMsg?.isFromTeacher ? 'You: ' : ''}{lastMsg?.content}
                                      </p>
                                      {unread > 0 && <span className="inline-block bg-red-500 text-white text-[10px] px-2 rounded-full mt-1">{unread}</span>}
                                  </div>
                              );
                          })}
                          {messages.length === 0 && <div className="p-6 text-center text-gray-400 text-sm">No messages found.</div>}
                      </div>
                  </div>

                  {/* Chat View */}
                  <div className={`flex-1 flex flex-col ${!selectedThread ? 'hidden md:flex' : 'flex'}`}>
                      {selectedThread ? (
                          <>
                              <div className="p-4 border-b border-gray-200 bg-white flex justify-between items-center">
                                  <div className="flex items-center gap-2">
                                      <button onClick={() => setSelectedThread(null)} className="md:hidden text-gray-500"><ArrowLeft className="w-5 h-5"/></button>
                                      <div>
                                          <h3 className="font-bold text-gray-800">{messages.find(m => m.senderId === selectedThread || m.receiverId === selectedThread)?.senderName || 'Student'}</h3>
                                          <p className="text-xs text-gray-500 text-teal-600 font-mono">{selectedThread}</p>
                                      </div>
                                  </div>
                              </div>
                              <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50">
                                  {messages
                                      .filter(m => m.senderId === selectedThread || m.receiverId === selectedThread)
                                      .map(msg => (
                                          <div key={msg.id} className={`flex ${msg.isFromTeacher ? 'justify-end' : 'justify-start'}`}>
                                              <div className={`max-w-[70%] rounded-xl p-3 text-sm shadow-sm ${msg.isFromTeacher ? 'bg-blue-600 text-white rounded-br-none' : 'bg-white text-gray-800 border border-gray-200 rounded-bl-none'}`}>
                                                  <p>{msg.content}</p>
                                                  <p className={`text-[10px] mt-1 text-right ${msg.isFromTeacher ? 'text-blue-200' : 'text-gray-400'}`}>
                                                      {new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                                  </p>
                                              </div>
                                          </div>
                                      ))}
                              </div>
                              <div className="p-4 border-t border-gray-200 bg-white">
                                  <div className="flex gap-2">
                                      <input 
                                          type="text" 
                                          className="flex-1 border border-gray-300 rounded-lg px-4 py-2 text-sm focus:outline-none focus:border-teal-500"
                                          placeholder="Type your reply..."
                                          value={replyText}
                                          onChange={e => setReplyText(e.target.value)}
                                          onKeyDown={e => e.key === 'Enter' && handleReplyToStudent(selectedThread!, messages.find(m=>m.senderId===selectedThread)?.senderName || 'Student')}
                                      />
                                      <button 
                                          onClick={() => handleReplyToStudent(selectedThread!, messages.find(m=>m.senderId===selectedThread)?.senderName || 'Student')}
                                          disabled={!replyText.trim()}
                                          className="bg-blue-600 text-white p-2 rounded-lg hover:bg-blue-700 disabled:opacity-50 transition-colors"
                                      >
                                          <Send className="w-5 h-5" />
                                      </button>
                                  </div>
                              </div>
                          </>
                      ) : (
                          <div className="flex-1 flex items-center justify-center text-gray-400 flex-col">
                              <MessageCircle className="w-12 h-12 mb-2 opacity-20" />
                              <p>Select a conversation to read</p>
                          </div>
                      )}
                  </div>
              </div>
          )}

          {/* VIEW: PROFILE */}
          {activeView === 'profile' && (
            <div className="max-w-2xl animate-fade-in">
                <h2 className="text-xl text-gray-600 font-light uppercase tracking-wide mb-6">Profile Settings</h2>
                <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                    <form onSubmit={handleSubmitProfile} className="p-8 space-y-6">
                        {message && <div className="bg-green-50 text-green-700 p-3 rounded text-sm">{message}</div>}
                        <div className="grid grid-cols-1 gap-6">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Name</label>
                                <input type="text" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full rounded border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 p-2 border" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">School</label>
                                <input type="text" required value={formData.school} onChange={e => setFormData({...formData, school: e.target.value})} readOnly={!!profile.schoolId} className={`w-full rounded border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 p-2 border ${profile.schoolId ? 'bg-gray-100 cursor-not-allowed' : ''}`} />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                                <input type="email" readOnly value={formData.email} className="w-full rounded border-gray-300 bg-gray-50 text-gray-500 p-2 border cursor-not-allowed" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Phone</label>
                                <input type="tel" required value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full rounded border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 p-2 border" />
                            </div>
                            {profile.teacherCode && !profile.schoolId && (
                                <div className="bg-yellow-50 p-4 rounded border border-yellow-200">
                                    <label className="block text-xs font-bold text-yellow-800 mb-1 uppercase tracking-wide">Linking Code</label>
                                    <div className="text-2xl font-mono font-bold text-yellow-900 tracking-wider">{profile.teacherCode}</div>
                                    <p className="text-xs text-yellow-700 mt-1">Provide this code to your School Administrator to link your account.</p>
                                </div>
                            )}
                        </div>
                        <div className="pt-4 text-right">
                            <button type="submit" className="bg-slate-900 text-white px-6 py-2 rounded hover:bg-slate-800 transition-colors">Save Changes</button>
                        </div>
                    </form>
                </div>
            </div>
          )}

        </main>
      </div>

      {/* Add Class Modal - Only for independent teachers */}
      {showAddClassModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white">
                    <h3 className="font-bold">New Classroom</h3>
                    <button onClick={() => setShowAddClassModal(false)}><X className="w-5 h-5" /></button>
                </div>
                <form onSubmit={handleCreateClassroom} className="p-6 space-y-4">
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Grade</label>
                        <select value={newClassGrade} onChange={(e) => setNewClassGrade(e.target.value as Grade)} className="w-full rounded border-gray-300 p-2 border">
                            {Object.values(Grade).map(g => <option key={g} value={g}>{g}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Stream</label>
                        <input type="text" required placeholder="e.g. Blue" value={newClassStream} onChange={(e) => setNewClassStream(e.target.value)} className="w-full rounded border-gray-300 p-2 border" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Roll</label>
                        <input type="number" min="1" max="100" required value={newClassRoll} onChange={(e) => setNewClassRoll(parseInt(e.target.value) || 0)} className="w-full rounded border-gray-300 p-2 border" />
                    </div>
                    <button type="submit" className="w-full bg-teal-600 text-white font-bold py-2 rounded hover:bg-teal-700">Generate</button>
                </form>
            </div>
        </div>
      )}

      {/* Classroom Manager Modal */}
      {managedClassroom && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4">
