                <div className="p-6 max-h-[70vh] overflow-y-auto">
                    <h4 className="font-bold text-gray-800 mb-2">{analysisModal.studentName}</h4>
                    <div className="prose prose-sm text-gray-600 whitespace-pre-wrap">
                        {analysisModal.report}
                    </div>
                </div>
                <div className="p-4 border-t border-gray-100 bg-gray-50 text-right">
                    <button onClick={() => setAnalysisModal(null)} className="px-4 py-2 bg-slate-800 text-white rounded text-sm font-bold hover:bg-slate-900 transition-colors">Close</button>
                </div>
            </div>
