                    <form onSubmit={handleSubmitProfile} className="p-8 space-y-6">
                        {message && <div className="bg-green-50 text-green-700 p-3 rounded text-sm">{message}</div>}
                        <div className="grid grid-cols-1 gap-6">
                            <div><label className="block text-sm font-medium text-gray-700 mb-1">Name</label><input type="text" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full rounded border-gray-300 p-2 border" /></div>
                            <div><label className="block text-sm font-medium text-gray-700 mb-1">School</label><input type="text" required value={formData.school} onChange={e => setFormData({...formData, school: e.target.value})} readOnly={!!profile.schoolId} className={`w-full rounded border-gray-300 p-2 border ${profile.schoolId ? 'bg-gray-100 cursor-not-allowed' : ''}`} /></div>
                            <div><label className="block text-sm font-medium text-gray-700 mb-1">Phone</label><input type="tel" required value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full rounded border-gray-300 p-2 border" /></div>
                        </div>
                        <div className="pt-4 text-right"><button type="submit" className="bg-slate-900 text-white px-6 py-2 rounded hover:bg-slate-800">Save</button></div>
                    </form>
                </div>
            </div>
          )}
        </main>
      </div>

      {managedClassroom && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-4xl overflow-hidden h-[90vh] flex flex-col">
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white shrink-0">
                      <div><h3 className="font-bold text-lg">{managedClassroom.grade} - {managedClassroom.stream}</h3><p className="text-slate-400 text-xs">Manager</p></div>
                      <button onClick={() => setManagedClassroom(null)}><X className="w-5 h-5" /></button>
                  </div>
                  <div className="flex border-b border-gray-200 bg-gray-50 overflow-x-auto">
                      {['students', 'performance', 'resources', 'forum'].map((tab) => (
                          <button key={tab} onClick={() => { setManageTab(tab as any); if(tab === 'performance') setManageView('subjects'); }} className={`flex-1 py-3 px-4 text-sm font-bold border-b-2 capitalize transition-colors ${manageTab === tab ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>
                              {tab}
                          </button>
                      ))}
                  </div>
                  <div className="flex-1 overflow-y-auto p-0 bg-white relative">
                      {manageTab === 'students' && (
                          <div className="p-0">
                              <table className="w-full text-sm text-left">
                                  <thead className="bg-gray-50 text-gray-500 font-bold uppercase text-xs sticky top-0">
                                      <tr><th className="px-6 py-3">Index</th><th className="px-6 py-3">Code</th><th className="px-6 py-3">Name</th><th className="px-6 py-3 text-right">Actions</th></tr>
                                  </thead>
                                  <tbody className="divide-y divide-gray-100">
                                      {managedClassroom.students.map((student) => (
                                          <tr key={student.code} className="hover:bg-gray-50"><td className="px-6 py-3">#{student.index}</td><td className="px-6 py-3 font-mono text-teal-700 font-bold">{student.code}</td><td className="px-6 py-3 italic">{student.name || "______________________"}</td><td className="px-6 py-3 text-right"><button onClick={() => openDmModal(student)} className="bg-blue-50 text-blue-600 px-2 py-1 rounded text-xs font-bold flex items-center gap-1 ml-auto"><MessageCircle className="w-3 h-3" /> Message</button></td></tr>
                                      ))}
                                  </tbody>
                              </table>
                          </div>
                      )}
                      {manageTab === 'performance' && (
                          <div className="p-6 h-full">
                              {manageView === 'subjects' && (
                                  <div className="animate-fade-in"><h3 className="text-lg font-bold text-gray-800 mb-4">Select Subject</h3><div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">{managedClassroom.subjects.length === 0 ? (<div className="col-span-full py-10 text-center text-gray-400 italic bg-gray-50 rounded border border-dashed">No subjects.</div>) : (managedClassroom.subjects.map((sub) => (<button key={sub} onClick={() => loadAssignmentsForSubject(sub)} className="p-4 bg-white border rounded-xl hover:border-teal-500 text-left group"><h4 className="font-bold text-slate-700">{sub}</h4><div className="flex items-center text-xs text-gray-400 mt-2">View <ChevronRight className="w-3 h-3 ml-1" /></div></button>)))}</div></div>
                              )}
                              {manageView === 'assignments' && (
                                  <div className="animate-fade-in h-full flex flex-col"><button onClick={() => setManageView('subjects')} className="flex items-center text-sm text-gray-500 mb-4"><ArrowLeft className="w-4 h-4 mr-1" /> Back</button><h3 className="text-lg font-bold text-gray-800 mb-4">{selectedSubjectForStats}</h3><div className="overflow-y-auto flex-1">{assignmentList.length === 0 ? (<div className="text-center py-10 text-gray-400 italic">No assignments.</div>) : (<div className="space-y-3">{assignmentList.map(assign => (<div key={assign.id} onClick={() => loadResultsForAssignment(assign)} className="p-4 bg-white border border-gray-200 rounded-xl hover:border-teal-500 cursor-pointer flex justify-between items-center group"><div><h4 className="font-bold text-slate-700">{assign.topic}</h4><p className="text-xs text-gray-500">{new Date(assign.createdAt).toLocaleDateString()}</p></div><ChevronRight className="w-5 h-5 text-gray-300" /></div>))}</div>)}</div></div>
                              )}
                              {manageView === 'results' && selectedAssignmentForStats && (
                                  <div className="animate-fade-in h-full flex flex-col"><button onClick={() => setManageView('assignments')} className="flex items-center text-sm text-gray-500 mb-4"><ArrowLeft className="w-4 h-4 mr-1" /> Back</button><div className="mb-4"><h3 className="text-lg font-bold text-gray-800">{selectedAssignmentForStats.topic}</h3><p className="text-xs text-gray-500">Student Results</p></div><div className="overflow-hidden border border-gray-200 rounded-lg"><table className="w-full text-sm text-left"><thead className="bg-gray-50 text-gray-500 font-bold uppercase text-xs"><tr><th className="px-6 py-3">Student</th><th className="px-6 py-3">Score</th><th className="px-6 py-3">Time</th><th className="px-6 py-3 text-right">Actions</th></tr></thead><tbody className="divide-y divide-gray-100">{currentAssignmentResults.map((res) => (<tr key={res.id} className="hover:bg-gray-50"><td className="px-6 py-3">{res.studentName}</td><td className="px-6 py-3"><span className={`px-2 py-1 rounded text-xs font-bold ${res.score/res.total >= 0.5 ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{res.score}/{res.total}</span></td><td className="px-6 py-3 text-gray-500 text-xs">{res.timeTaken ? `${Math.round(res.timeTaken)}s` : '-'}</td><td className="px-6 py-3 text-right flex gap-2 justify-end">{res.aiAnalysis && <button onClick={() => setAnalysisModal({ studentName: res.studentName, report: res.aiAnalysis || '' })} className="inline-flex items-center gap-1 text-xs font-bold px-3 py-1.5 rounded bg-purple-50 text-purple-600 hover:bg-purple-100 transition-colors"><Sparkles className="w-3 h-3" /> Report</button>}<button onClick={() => openFeedbackModal(res)} className={`inline-flex items-center gap-1 text-xs font-bold px-3 py-1.5 rounded transition-colors ${res.feedback ? 'bg-blue-50 text-blue-600 hover:bg-blue-100' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}><MessageSquare className="w-3 h-3" />{res.feedback ? 'Edit' : 'Feedback'}</button></td></tr>))}</tbody></table></div></div>
                              )}
                          </div>
                      )}
                      {manageTab === 'resources' && (
                          <div className="p-6 h-full flex flex-col overflow-y-auto">
                              <h3 className="text-lg font-bold text-gray-800 mb-4">Class Textbooks & Resources</h3>
                              <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 mb-8">
                                  <label className="block text-sm font-medium text-blue-800 mb-2">Upload New Textbook</label>
                                  <div className="flex items-center gap-3">
                                      <label className="cursor-pointer bg-white border border-blue-300 text-blue-600 px-4 py-2 rounded-md text-sm font-bold flex items-center gap-2"><Upload className="w-4 h-4" />Select File<input type="file" accept=".pdf,.doc,.docx" className="hidden" onChange={handleTextbookUpload}/></label>
                                      <span className="text-xs text-blue-500">Max size 2MB</span>
                                  </div>
                              </div>
                              <div className="space-y-8">
                                  <div>
                                      <h4 className="text-sm font-bold text-gray-500 uppercase tracking-wider mb-3">Textbooks</h4>
                                      {managedClassroom.textbooks && managedClassroom.textbooks.length > 0 ? (
                                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                              {managedClassroom.textbooks.map(book => (<div key={book.id} className="border border-gray-200 rounded-lg p-4 bg-white flex items-start gap-3"><div className="p-3 bg-red-50 text-red-600 rounded-lg"><FileIcon className="w-6 h-6" /></div><div className="flex-1 min-w-0"><h4 className="font-bold text-slate-700 truncate">{book.title}</h4><p className="text-xs text-gray-500">{new Date(book.uploadDate).toLocaleDateString()} • {book.size}</p><a href={book.fileData} download={book.title} className="text-xs text-teal-600 font-bold hover:underline mt-1 inline-block">Download</a></div></div>))}
                                          </div>
                                      ) : (<div className="text-center py-6 text-gray-400 italic bg-slate-50 rounded border border-dashed">No textbooks.</div>)}
                                  </div>
                                  <div>
                                      <h4 className="text-sm font-bold text-gray-500 uppercase tracking-wider mb-3">Shared Lesson Notes</h4>
                                      {(() => {
                                          if (!managedClassroom.sharedNotes || managedClassroom.sharedNotes.length === 0) return <div className="text-center py-6 text-gray-400 italic bg-slate-50 rounded border border-dashed">No notes shared.</div>;
                                          const groupedClassroomNotes: Record<string, SharedNote[]> = {};
                                          managedClassroom.sharedNotes.forEach(note => {
                                              if (!groupedClassroomNotes[note.subject]) groupedClassroomNotes[note.subject] = [];
                                              groupedClassroomNotes[note.subject].push(note);
                                          });
                                          return Object.entries(groupedClassroomNotes).map(([subject, notes]: [string, SharedNote[]]) => (
                                              <div key={subject} className="mb-6">
                                                  <h5 className="font-bold text-teal-700 mb-2 pl-2 border-l-4 border-teal-500">{subject}</h5>
                                                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                                      {notes.map(note => (<div key={note.id} className="border border-gray-200 rounded-lg p-4 bg-white shadow-sm"><h4 className="font-bold text-slate-800">{note.title}</h4><p className="text-xs text-gray-500 mb-2">{new Date(note.dateShared).toLocaleDateString()}</p><p className="text-xs text-gray-600 line-clamp-2">{note.content.substring(0, 100)}...</p></div>))}
                                                  </div>
                                              </div>
                                          ));
                                      })()}
                                  </div>
                              </div>
                          </div>
                      )}
                      {manageTab === 'forum' && (
                          <div className="p-6 h-full flex flex-col">
                              <h3 className="text-lg font-bold text-gray-800 mb-4">Class Forum</h3>
                              <form onSubmit={handleCreateForumPost} className="bg-slate-50 p-4 rounded-xl border border-gray-200 mb-6">
                                  <input type="text" placeholder="Title" className="w-full mb-2 p-2 rounded border border-gray-300 text-sm font-bold" value={forumPostTitle} onChange={(e) => setForumPostTitle(e.target.value)} required />
                                  <textarea rows={2} placeholder="Post..." className="w-full p-2 rounded border border-gray-300 text-sm mb-2" value={forumPostContent} onChange={(e) => setForumPostContent(e.target.value)} required />
                                  <div className="text-right"><button type="submit" className="bg-slate-900 text-white px-4 py-1.5 rounded text-xs font-bold hover:bg-slate-800">Post</button></div>
                              </form>
                              <div className="flex-1 overflow-y-auto space-y-4">
                                  {managedClassroom.forumPosts && managedClassroom.forumPosts.length > 0 ? (
                                      managedClassroom.forumPosts.map(post => (
                                          <div key={post.id} className="border border-gray-200 rounded-xl p-4 bg-white">
                                              <div className="flex justify-between items-start mb-2"><div><h4 className="font-bold text-teal-800">{post.title}</h4><p className="text-xs text-gray-500">{post.authorName} • {new Date(post.timestamp).toLocaleDateString()}</p></div><span className="text-xs bg-gray-100 px-2 py-1 rounded text-gray-600">{post.replies.length} replies</span></div>
                                              <p className="text-sm text-gray-700 mb-4">{post.content}</p>
                                              {post.replies.length > 0 && (<div className="bg-gray-50 rounded p-3 mb-3 space-y-2">{post.replies.map(reply => (<div key={reply.id} className="text-xs border-l-2 border-gray-300 pl-2"><span className={`font-bold ${reply.authorRole === 'teacher' ? 'text-teal-600' : 'text-blue-600'}`}>{reply.authorName}</span><p className="text-gray-600">{reply.content}</p></div>))}</div>)}
                                              {activePostId === post.id ? (<div className="flex gap-2"><input type="text" className="flex-1 text-sm border border-gray-300 rounded px-2 py-1" placeholder="Reply..." value={replyContent} onChange={(e) => setReplyContent(e.target.value)} /><button onClick={() => handleReplyToPost(post.id)} className="bg-teal-600 text-white px-3 py-1 rounded text-xs font-bold">Reply</button><button onClick={() => setActivePostId(null)} className="text-gray-500 text-xs">Cancel</button></div>) : (<button onClick={() => setActivePostId(post.id)} className="text-teal-600 text-xs font-bold flex items-center gap-1 hover:underline"><Reply className="w-3 h-3" /> Reply</button>)}
                                          </div>
                                      ))
                                  ) : (<div className="text-center text-gray-400 py-10">No discussions yet.</div>)}
                              </div>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}

      {/* Restoring shared logic modals at the root level for z-index safety */}
      {feedbackModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white"><h3 className="font-bold">Feedback for {feedbackModal.name}</h3><button onClick={() => setFeedbackModal(null)}><X className="w-5 h-5" /></button></div>
                  <div className="p-6"><label className="block text-sm font-medium text-gray-700 mb-2">Teacher's Comment</label><textarea rows={4} className="w-full rounded-lg border border-gray-300 p-3 text-sm" placeholder="Write feedback..." value={feedbackInput} onChange={(e) => setFeedbackInput(e.target.value)} /></div>
                  <div className="p-6 border-t border-gray-100 bg-gray-50 flex justify-end gap-2"><button onClick={() => setFeedbackModal(null)} className="px-4 py-2 text-gray-600 rounded font-medium text-sm">Cancel</button><button onClick={saveFeedback} className="px-4 py-2 bg-teal-600 text-white rounded font-bold text-sm">Save</button></div>
              </div>
          </div>
      )}

      {dmModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white"><h3 className="font-bold">Message {dmModal.studentName}</h3><button onClick={() => setDmModal(null)}><X className="w-5 h-5" /></button></div>
                  <div className="p-6"><label className="block text-sm font-medium text-gray-700 mb-2">Message</label><textarea rows={4} className="w-full rounded-lg border border-gray-300 p-3 text-sm" placeholder="Type message..." value={dmInput} onChange={(e) => setDmInput(e.target.value)} /></div>
                  <div className="p-6 border-t border-gray-100 bg-gray-50 flex justify-end gap-2"><button onClick={() => setDmModal(null)} className="px-4 py-2 text-gray-600 rounded font-medium text-sm">Cancel</button><button onClick={sendDm} className="px-4 py-2 bg-blue-600 text-white rounded font-bold text-sm flex items-center gap-2"><Send className="w-3 h-3" /> Send</button></div>
              </div>
          </div>
      )}

      {analysisModal && (
        <div className="fixed inset-0 z-[80] flex items-center justify-center bg-black/50 p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-lg overflow-hidden animate-fade-in-up">
                <div className="bg-purple-600 px-6 py-4 flex justify-between items-center text-white"><h3 className="font-bold flex items-center gap-2"><Sparkles className="w-4 h-4"/> AI Analysis</h3><button onClick={() => setAnalysisModal(null)}><X className="w-5 h-5" /></button></div>
                <div className="p-6 max-h-[70vh] overflow-y-auto"><h4 className="font-bold text-gray-800 mb-2">{analysisModal.studentName}</h4><div className="prose prose-sm text-gray-600 whitespace-pre-wrap">{analysisModal.report}</div></div>
                <div className="p-4 border-t border-gray-100 bg-gray-50 text-right"><button onClick={() => setAnalysisModal(null)} className="px-4 py-2 bg-slate-800 text-white rounded text-sm font-bold">Close</button></div>
            </div>
        </div>
      )}

      {showAddClassModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white"><h3 className="font-bold">New Classroom</h3><button onClick={() => setShowAddClassModal(false)}><X className="w-5 h-5" /></button></div>
                <form onSubmit={handleCreateClassroom} className="p-6 space-y-4">
                    <div><label className="block text-sm font-medium text-gray-700 mb-1">Grade</label><select value={newClassGrade} onChange={(e) => setNewClassGrade(e.target.value as Grade)} className="w-full rounded border-gray-300 p-2 border">{Object.values(Grade).map(g => <option key={g} value={g}>{g}</option>)}</select></div>
                    <div><label className="block text-sm font-medium text-gray-700 mb-1">Stream</label><input type="text" required placeholder="e.g. Blue" value={newClassStream} onChange={(e) => setNewClassStream(e.target.value)} className="w-full rounded border-gray-300 p-2 border" /></div>
                    <div><label className="block text-sm font-medium text-gray-700 mb-1">Roll</label><input type="number" min="1" max="100" required value={newClassRoll} onChange={(e) => setNewClassRoll(parseInt(e.target.value) || 0)} className="w-full rounded border-gray-300 p-2 border" /></div>
                    <button type="submit" className="w-full bg-teal-600 text-white font-bold py-2 rounded">Generate</button>
                </form>
            </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { LessonPlanData } from '../types';
import { getSavedPlans, deletePlan } from '../services/storageService';
import { FileText, Calendar, Trash2, ChevronRight, Search, Book, Layers } from 'lucide-react';

interface Props {
  onSelectPlan: (plan: LessonPlanData) => void;
}

const SavedPlans: React.FC<Props> = ({ onSelectPlan }) => {
  const [plans, setPlans] = useState<LessonPlanData[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [groupBy, setGroupBy] = useState<'subject' | 'grade'>('subject');

  useEffect(() => {
    setPlans(getSavedPlans());
  }, []);

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm('Are you sure you want to delete this lesson plan?')) {
      deletePlan(id);
      setPlans(getSavedPlans());
    }
  };

  const groupedPlans = useMemo(() => {
      const filtered = plans.filter(p => 
        p.topic.toLowerCase().includes(searchTerm.toLowerCase()) || 
        p.subject.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.grade.toLowerCase().includes(searchTerm.toLowerCase())
      );

      const groups: Record<string, LessonPlanData[]> = {};
      filtered.forEach(plan => {
          const key = groupBy === 'subject' ? plan.subject : plan.grade;
          if (!groups[key]) groups[key] = [];
          groups[key].push(plan);
      });

      return Object.keys(groups).sort().reduce((acc, key) => {
          acc[key] = groups[key];
          return acc;
      }, {} as Record<string, LessonPlanData[]>);
  }, [plans, searchTerm, groupBy]);

  const cleanTopic = (topic: string) => topic.replace(/^Lesson \d+:\s*/i, '');

  return (
    <div className="max-w-4xl mx-auto">
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-6 gap-4">
        <div>
            <h2 className="text-2xl font-bold text-gray-800">Generated Lesson Plans</h2>
            <p className="text-gray-500 text-sm">{plans.length} plans saved</p>
        </div>

        <div className="flex items-center gap-3">
             <div className="flex bg-gray-100 p-1 rounded-lg">
                <button 
                    onClick={() => setGroupBy('subject')}
                    className={`px-3 py-1.5 text-xs font-bold rounded-md flex items-center gap-1 transition-colors ${groupBy === 'subject' ? 'bg-white text-teal-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <Book className="w-3 h-3" /> Subject
                </button>
                <button 
                    onClick={() => setGroupBy('grade')}
                    className={`px-3 py-1.5 text-xs font-bold rounded-md flex items-center gap-1 transition-colors ${groupBy === 'grade' ? 'bg-white text-teal-700 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                >
                    <Layers className="w-3 h-3" /> Grade
                </button>
            </div>

            <div className="relative">
                <Search className="w-4 h-4 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
                <input 
                    type="text" 
                    placeholder="Search plans..." 
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="pl-9 pr-4 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-teal-500 w-full md:w-48"
                />
            </div>
        </div>
      </div>

      {Object.keys(groupedPlans).length === 0 ? (
        <div className="text-center py-16 bg-white rounded-xl shadow-sm border border-gray-200">
          <div className="bg-gray-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
            <FileText className="w-8 h-8 text-gray-400" />
          </div>
          <h3 className="text-lg font-medium text-gray-900">No generated plans found</h3>
          <p className="text-gray-500 mt-1">Generate a lesson plan to see it here.</p>
        </div>
      ) : (
          <div className="space-y-8">
              {Object.entries(groupedPlans).map(([groupTitle, groupPlans]: [string, LessonPlanData[]]) => (
                  <div key={groupTitle} className="animate-fade-in">
                      <div className="flex items-center gap-2 mb-3">
                          <span className="bg-teal-100 text-teal-800 p-1.5 rounded-lg">
                              {groupBy === 'subject' ? <Book className="w-4 h-4" /> : <Layers className="w-4 h-4" />}
                          </span>
                          <h3 className="text-lg font-bold text-gray-800">{groupTitle}</h3>
                          <span className="text-xs font-medium text-gray-500 bg-gray-100 px-2 py-0.5 rounded-full">{groupPlans.length}</span>
                      </div>
                      <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                          <ul className="divide-y divide-gray-200">
                            {groupPlans.map((plan) => (
                              <li key={plan.id} onClick={() => onSelectPlan(plan)} className="group hover:bg-gray-50 transition-colors cursor-pointer">
                                <div className="p-5 flex items-center justify-between">
                                  <div className="flex-1 min-w-0">
                                    <h3 className="text-base font-semibold text-teal-800 truncate mb-1 group-hover:text-teal-600">{cleanTopic(plan.lessonNumber || plan.topic)}</h3>
                                    <div className="flex flex-wrap gap-x-4 gap-y-1 text-sm text-gray-500">
                                      {groupBy !== 'subject' && <span className="font-medium text-gray-700">{plan.subject}</span>}
                                      {groupBy !== 'grade' && <span className="bg-gray-200 text-xs px-2 py-0.5 rounded-full">{plan.grade}</span>}
                                      <span className="flex items-center gap-1"><Calendar className="w-3 h-3" />{new Date(plan.date).toLocaleDateString()}</span>
                                    </div>
                                  </div>
                                  <div className="flex items-center gap-4 ml-4"><button onClick={(e) => handleDelete(e, plan.id || '')} className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-full"><Trash2 className="w-4 h-4" /></button><ChevronRight className="w-5 h-5 text-gray-300 group-hover:text-teal-500" /></div>
                                </div>
                              </li>
                            ))}
                          </ul>
                      </div>
                  </div>
              ))}
          </div>
      )}
    </div>
  );
};

export default SavedPlans;

import React, { useState, useEffect, useMemo } from 'react';
import { Student, Classroom, Assignment, StudentResult, SharedNote, DirectMessage, ForumPost, ForumReply } from '../types';
import { 
    authenticateStudent, updateStudentName, getAssignmentsByClassId, getStudentResults, 
    saveStudentResult, getStudentNotes, getDirectMessages, sendDirectMessage, markMessagesRead, 
    addForumReply
} from '../services/storageService';
import { generateStudentPerformanceReport } from '../services/geminiService';
import { 
    LogIn, BookOpen, CheckCircle, Clock, ChevronRight, FileText, AlertCircle, Play, 
    Loader2, Menu, Home, Layers, Book, List, CheckSquare, BarChart2, Mail, MessageSquare, 
    User, LogOut, X, Send, Reply, ChevronLeft, Download, Calendar, RefreshCw
} from 'lucide-react';

export default function StudentPortal() {
  const [view, setView] = useState<'login' | 'portal'>('login');
  const [accessCode, setAccessCode] = useState('');
  const [student, setStudent] = useState<Student | null>(null);
  const [classroom, setClassroom] = useState<Classroom | null>(null);
  const [studentName, setStudentName] = useState('');
  const [error, setError] = useState<string | null>(null);

  const [activeSection, setActiveSection] = useState<'dashboard' | 'notes' | 'textbooks' | 'all_assignments' | 'pending' | 'completed' | 'results' | 'inbox' | 'forum' | 'profile'>('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [isCollapsed, setIsCollapsed] = useState(false);

  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [results, setResults] = useState<StudentResult[]>([]);
  const [notes, setNotes] = useState<SharedNote[]>([]);
  const [messages, setMessages] = useState<DirectMessage[]>([]);
  const [forumPosts, setForumPosts] = useState<ForumPost[]>([]);

  const [selectedNote, setSelectedNote] = useState<SharedNote | null>(null);
  const [quizMode, setQuizMode] = useState(false);
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [quizStartTime, setQuizStartTime] = useState<number>(0);
  const [questionStartTime, setQuestionStartTime] = useState<number>(0);
  const [timePerQuestion, setTimePerQuestion] = useState<Record<number, number>>({});
  const [newMessage, setNewMessage] = useState('');
  const [newForumReply, setNewForumReply] = useState('');
  const [activeForumPostId, setActiveForumPostId] = useState<string | null>(null);
  const [hasViewedForum, setHasViewedForum] = useState(false);

  const pendingCount = assignments.filter(a => !results.some(r => r.assignmentId === a.id)).length;
  const unreadMsgCount = messages.filter(m => !m.read && m.receiverId === student?.code).length;

  useEffect(() => {
      if (student && view === 'portal') {
          const interval = setInterval(() => {
              if (classroom) loadStudentData(student.code, classroom.id);
          }, 10000);
          return () => clearInterval(interval);
      }
  }, [student, view, classroom]);

  useEffect(() => {
      if (activeSection === 'inbox' && messages.length > 0 && student && classroom) {
           const unread = messages.some(m => !m.read && m.receiverId === student.code);
           if (unread) {
               markMessagesRead(classroom.userId, student.code);
               setMessages(prev => prev.map(m => m.receiverId === student.code ? {...m, read: true} : m));
           }
      }
  }, [activeSection, messages, student, classroom]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!accessCode) return;
    const result = authenticateStudent(accessCode.toUpperCase());
    if (result) {
      setStudent(result.student);
      setClassroom(result.classroom);
      if (result.student.name) {
        loadStudentData(result.student.code, result.classroom.id);
        setView('portal');
      }
    } else setError("Invalid Access Code.");
  };

  const handleNameUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (student && classroom && studentName.trim()) {
      const updated = updateStudentName(classroom.id, student.code, studentName);
      if (updated) {
        setStudent(updated);
        loadStudentData(updated.code, classroom.id);
        setView('portal');
      }
    }
  };

  const loadStudentData = (code: string, classId: string) => {
    const classAssignments = getAssignmentsByClassId(classId);
    const studentResults = getStudentResults(code);
    const classNotes = getStudentNotes(classId);
    const msgs = getDirectMessages(code);
    const refreshed = authenticateStudent(code);
    if (refreshed) {
        setClassroom(refreshed.classroom);
        setForumPosts(refreshed.classroom.forumPosts || []);
    }
    setAssignments(classAssignments);
    setResults(studentResults);
    setNotes(classNotes);
    setMessages(msgs);
  };

  const groupedNotes = useMemo(() => {
      const groups: Record<string, SharedNote[]> = {};
      notes.forEach(note => {
          if (!groups[note.subject]) groups[note.subject] = [];
          groups[note.subject].push(note);
      });
      return groups;
  }, [notes]);

  const startQuiz = (assignment: Assignment) => {
    const pastAttempts = results.filter(r => r.assignmentId === assignment.id).length;
    if (pastAttempts >= 3) {
        alert("Maximum number of attempts (3) reached.");
        return;
    }
    setActiveAssignment(assignment);
    setCurrentQuestionIndex(0);
    setSelectedAnswers({});
    setTimePerQuestion({});
    const now = Date.now();
    setQuizStartTime(now);
    setQuestionStartTime(now);
    setQuizMode(true);
    if(window.innerWidth < 1024) setSidebarOpen(false);
  };

  const handleNextQuestion = () => {
      const now = Date.now();
      const timeSpent = (now - questionStartTime) / 1000;
      setTimePerQuestion(prev => ({ ...prev, [currentQuestionIndex]: (prev[currentQuestionIndex] || 0) + timeSpent }));
      setQuestionStartTime(now);
      setCurrentQuestionIndex(prev => prev + 1);
  };

  const submitQuiz = async () => {
      if (!student || !activeAssignment) return;
      const now = Date.now();
      const lastSpent = (now - questionStartTime) / 1000;
      const finalTPQ = { ...timePerQuestion, [currentQuestionIndex]: (timePerQuestion[currentQuestionIndex] || 0) + lastSpent };
      const totalTimeTaken = (now - quizStartTime) / 1000;
      setIsSubmitting(true);
      let score = 0;
      activeAssignment.questions.forEach((q, idx) => {
          const userAnswer = selectedAnswers[idx];
          if (userAnswer === q.correctAnswer) score++;
          else if (q.type === 'structured' && userAnswer?.toLowerCase().trim() === q.correctAnswer.toLowerCase().trim()) score++;
      });
      let aiReport = "";
      try {
          aiReport = await generateStudentPerformanceReport(activeAssignment, selectedAnswers, score, totalTimeTaken, finalTPQ);
      } catch (err) { aiReport = "Analysis could not be generated."; }
      const result: StudentResult = {
          id: crypto.randomUUID(), assignmentId: activeAssignment.id, studentCode: student.code, studentName: student.name || 'Student', score: score, total: activeAssignment.questions.length, attempts: 1, answers: selectedAnswers, dateTaken: new Date().toISOString(), timeTaken: totalTimeTaken, timePerQuestion: finalTPQ, aiAnalysis: aiReport
      };
      saveStudentResult(result);
      const submissionMsg: DirectMessage = {
          id: crypto.randomUUID(), senderId: student.code, senderName: student.name || 'Student', receiverId: classroom?.userId || '', content: `I submitted: ${activeAssignment.topic}. Score: ${score}/${activeAssignment.questions.length}.`, timestamp: new Date().toISOString(), read: false, isFromTeacher: false
      };
      if (classroom?.userId) sendDirectMessage(submissionMsg);
      if (classroom) loadStudentData(student.code, classroom.id);
      setIsSubmitting(false); setQuizMode(false); setActiveSection('results'); setActiveAssignment(null);
  };

  const handleSendMessage = (e: React.FormEvent) => {
      e.preventDefault();
      if (!newMessage.trim() || !student || !classroom) return;
      const msg: DirectMessage = { id: crypto.randomUUID(), senderId: student.code, senderName: student.name || 'Student', receiverId: classroom.userId, content: newMessage, timestamp: new Date().toISOString(), read: false, isFromTeacher: false };
      sendDirectMessage(msg);
      setNewMessage('');
      loadStudentData(student.code, classroom.id);
  };

  const handleForumReply = (postId: string) => {
      if (!newForumReply.trim() || !student || !classroom) return;
      const reply: ForumReply = { id: crypto.randomUUID(), authorName: student.name || 'Student', authorRole: 'student', content: newForumReply, timestamp: new Date().toISOString() };
      addForumReply(classroom.id, postId, reply);
      setNewForumReply('');
      loadStudentData(student.code, classroom.id);
  };

  if (view === 'login') return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-gray-50 font-sans">
      <div className="bg-white p-8 rounded-xl shadow-xl w-full max-w-md border border-gray-200">
        <div className="text-center mb-8">
          <div className="bg-teal-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4"><BookOpen className="w-8 h-8 text-teal-600" /></div>
          <h2 className="text-2xl font-bold text-gray-800">Student Portal</h2>
        </div>
        {student && !student.name ? (
          <form onSubmit={handleNameUpdate} className="space-y-6">
            <div className="bg-blue-50 p-4 rounded text-sm text-blue-700">Update your full name.</div>
            <input type="text" required className="w-full rounded border-gray-300 py-2.5 border px-3" value={studentName} onChange={e => setStudentName(e.target.value)} placeholder="Full Name" />
            <button type="submit" className="w-full bg-teal-600 text-white py-2.5 rounded hover:bg-teal-700">Update Profile</button>
          </form>
        ) : (
          <form onSubmit={handleLogin} className="space-y-6">
            {error && <div className="bg-red-50 text-red-700 p-3 rounded text-sm border border-red-200">{error}</div>}
            <input type="text" required className="w-full rounded border-gray-300 py-2.5 border px-3 text-center uppercase font-mono" value={accessCode} onChange={e => setAccessCode(e.target.value)} placeholder="XXXXXX" maxLength={6} />
            <button type="submit" className="w-full bg-teal-600 text-white py-2.5 rounded hover:bg-teal-700 flex justify-center items-center gap-2"><LogIn className="w-4 h-4" /> Enter</button>
          </form>
        )}
      </div>
    </div>
  );

  if (quizMode && activeAssignment) {
      const q = activeAssignment.questions[currentQuestionIndex];
      const progress = ((currentQuestionIndex + 1) / activeAssignment.questions.length) * 100;
      return (
        <div className="min-h-screen bg-gray-50 text-slate-800 font-sans pb-12">
          <div className="bg-white border-b border-gray-200 px-4 py-4 sticky top-0 z-10 shadow-sm"><div className="max-w-3xl mx-auto flex justify-between items-center"><div><h2 className="font-bold text-gray-800">{activeAssignment.topic}</h2></div><div className="text-sm font-medium text-gray-500">Question {currentQuestionIndex + 1} of {activeAssignment.questions.length}</div></div></div>
          <div className="w-full h-1 bg-gray-200"><div className="h-full bg-teal-600" style={{ width: `${progress}%` }}></div></div>
          <div className="max-w-3xl mx-auto p-6 mt-6">
            {isSubmitting ? (<div className="flex flex-col items-center justify-center py-20"><Loader2 className="w-12 h-12 text-teal-600 animate-spin mb-4" /><h3 className="text-xl font-bold text-gray-800">Submitting...</h3></div>) : (
              <>
                <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-8"><p className="text-lg font-medium text-gray-900 mb-6">{q.question}</p>{q.type === 'mcq' ? (<div className="space-y-3">{q.options?.map(opt => (<label key={opt} className={`flex items-center p-4 rounded-lg border cursor-pointer ${selectedAnswers[currentQuestionIndex] === opt ? 'border-teal-500 bg-teal-50' : 'border-gray-200'}`}><input type="radio" name="q" className="hidden" value={opt} checked={selectedAnswers[currentQuestionIndex] === opt} onChange={() => setSelectedAnswers({ ...selectedAnswers, [currentQuestionIndex]: opt })} /><span>{opt}</span></label>))}</div>) : (<textarea className="w-full p-4 rounded-lg border border-gray-300 min-h-[150px]" value={selectedAnswers[currentQuestionIndex] || ''} onChange={e => setSelectedAnswers({ ...selectedAnswers, [currentQuestionIndex]: e.target.value })} />)}</div>
                <div className="mt-8 flex justify-between items-center"><button onClick={() => setQuizMode(false)} className="text-gray-500">Quit</button><div className="flex gap-3">{currentQuestionIndex > 0 && <button onClick={() => setCurrentQuestionIndex(prev => prev - 1)} className="px-4 py-2 bg-white border rounded">Prev</button>}{currentQuestionIndex < activeAssignment.questions.length - 1 ? (<button onClick={handleNextQuestion} className="px-6 py-2 bg-teal-600 text-white rounded">Next</button>) : (<button onClick={submitQuiz} className="px-6 py-2 bg-green-600 text-white rounded">Submit</button>)}</div></div>
              </>
            )}
          </div>
        </div>
      );
  }

  const processedResults = useMemo(() => {
    const map = new Map<string, StudentResult>();
    results.forEach(r => { const existing = map.get(r.assignmentId); if (!existing || r.score > existing.score) map.set(r.assignmentId, r); });
    return Array.from(map.values()).sort((a,b) => new Date(b.dateTaken).getTime() - new Date(a.dateTaken).getTime());
  }, [results]);

  const SidebarItem = ({ id, icon: Icon, label, badgeCount }: any) => (
    <button onClick={() => { setActiveSection(id); if (id === 'forum') setHasViewedForum(true); if(window.innerWidth < 1024) setSidebarOpen(false); }} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors group relative ${activeSection === id ? 'bg-teal-600 text-white shadow-md' : 'text-slate-300 hover:bg-slate-800 hover:text-white'}`}>
        <Icon className={`w-5 h-5 flex-shrink-0 ${!isCollapsed && 'mr-3'}`} />
        {!isCollapsed && <span>{label}</span>}
        {badgeCount > 0 && <span className="ml-auto bg-red-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full">{badgeCount}</span>}
    </button>
  );

  return (
      <div className="flex min-h-screen bg-slate-50 font-sans text-slate-800">
          {sidebarOpen && (<div className="fixed inset-0 bg-black/50 z-40 lg:hidden" onClick={() => setSidebarOpen(false)}/>)}
          <aside className={`fixed inset-y-0 left-0 z-50 bg-slate-900 text-slate-300 transition-all duration-300 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 ${isCollapsed ? 'w-20' : 'w-64'} flex flex-col`}>
              <div className="flex items-center h-16 px-4 bg-slate-950 text-white font-bold text-xl tracking-tight border-b border-slate-800 justify-between">
                  {!isCollapsed ? (<div className="flex items-center"><BookOpen className="w-6 h-6 mr-2 text-teal-500" /><span>Portal</span></div>) : (<BookOpen className="w-8 h-8 text-teal-500" />)}
              </div>
              <nav className="flex-1 overflow-y-auto p-3 space-y-1">
                  <SidebarItem id="dashboard" icon={Home} label="Dashboard" />
                  <SidebarItem id="notes" icon={FileText} label="Notes" />
                  <SidebarItem id="textbooks" icon={Book} label="Books" />
                  <SidebarItem id="all_assignments" icon={List} label="Assignments" />
                  <SidebarItem id="pending" icon={Clock} label="Pending" badgeCount={pendingCount} />
                  <SidebarItem id="results" icon={BarChart2} label="Results" />
                  <SidebarItem id="inbox" icon={Mail} label="Inbox" badgeCount={unreadMsgCount} />
                  <SidebarItem id="forum" icon={MessageSquare} label="Forum" badgeCount={!hasViewedForum && forumPosts.length > 0 ? 1 : 0} />
                  <SidebarItem id="profile" icon={User} label="Profile" />
              </nav>
              <div className="p-4 border-t border-slate-800"><button onClick={() => setView('login')} className="flex items-center w-full px-4 py-2.5 text-sm font-medium rounded-lg text-red-400 hover:bg-slate-800"><LogOut className="w-5 h-5 mr-3" />{!isCollapsed && "Sign Out"}</button></div>
          </aside>
          <div className={`flex-1 flex flex-col transition-all duration-300 ${isCollapsed ? 'lg:ml-20' : 'lg:ml-64'}`}>
              <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 sticky top-0 z-40 shadow-sm">
                  <button onClick={() => setSidebarOpen(!sidebarOpen)} className="lg:hidden p-2 text-gray-500"><Menu className="w-6 h-6" /></button>
                  <h1 className="text-xl font-bold text-gray-800 hidden sm:block capitalize">{activeSection.replace('_', ' ')}</h1>
                  <div className="ml-auto flex items-center gap-4"><div className="text-right hidden md:block"><p className="text-sm font-bold text-gray-800">{student?.name}</p></div><div className="w-8 h-8 bg-teal-100 text-teal-700 rounded-full flex items-center justify-center font-bold">{student?.name?.charAt(0)}</div></div>
              </header>
              <main className="p-4 lg:p-8 max-w-7xl mx-auto w-full">
                  {activeSection === 'dashboard' && (<div className="space-y-6"><h2 className="text-2xl font-bold">Overview</h2><div className="grid grid-cols-1 md:grid-cols-3 gap-6"><div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm"><h3 className="font-bold">Pending</h3><p className="text-3xl font-black">{pendingCount}</p></div><div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm"><h3 className="font-bold">Completed</h3><p className="text-3xl font-black">{processedResults.length}</p></div></div></div>)}
                  {activeSection === 'notes' && (
                      <div className="space-y-8 animate-fade-in">
                          <h2 className="text-2xl font-bold text-gray-800">Lesson Notes</h2>
                          {Object.keys(groupedNotes).length === 0 ? (<p className="text-gray-500 italic">No notes.</p>) : (
                              Object.entries(groupedNotes).map(([subject, subjectNotes]: [string, SharedNote[]]) => (
                                  <div key={subject}><h3 className="text-lg font-bold text-teal-800 mb-4 flex items-center gap-2"><span className="w-2 h-8 bg-teal-500 rounded-full"></span>{subject}</h3><div className="grid grid-cols-1 md:grid-cols-2 gap-4">{subjectNotes.map(note => (<div key={note.id} className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition-shadow"><h4 className="font-bold text-lg text-gray-900 mb-2">{note.title}</h4><p className="text-sm text-gray-600 line-clamp-3 mb-4">{note.content.replace(/\*\*/g, '')}</p><button onClick={() => setSelectedNote(note)} className="text-teal-600 text-sm font-bold hover:underline flex items-center gap-1">Read Full <ChevronRight className="w-4 h-4"/></button></div>))}</div></div>
                              ))
                          )}
                      </div>
                  )}
                  {/* ... other sections rendering logic restored ... */}
                  {activeSection === 'results' && (<div className="bg-white rounded-xl border border-gray-200 overflow-hidden"><table className="w-full text-sm text-left"><thead className="bg-gray-50 border-b"><tr><th className="px-6 py-4">Assignment</th><th className="px-6 py-4">Score</th><th className="px-6 py-4">Feedback</th></tr></thead><tbody className="divide-y">{processedResults.map(r => (<tr key={r.id} className="hover:bg-gray-50"><td className="px-6 py-4">{assignments.find(a=>a.id===r.assignmentId)?.topic}</td><td className="px-6 py-4"><span className="font-bold">{r.score}/{r.total}</span></td><td className="px-6 py-4 italic text-gray-500">{r.feedback || 'None'}</td></tr>))}</tbody></table></div>)}
              </main>
          </div>
          {selectedNote && (
              <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"><div className="bg-white rounded-xl shadow-xl w-full max-w-2xl max-h-[80vh] overflow-hidden flex flex-col animate-fade-in-up"><div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white shrink-0"><h3 className="font-bold text-lg">{selectedNote.title}</h3><button onClick={() => setSelectedNote(null)}><X className="w-5 h-5" /></button></div><div className="p-6 overflow-y-auto whitespace-pre-wrap">{selectedNote.content}</div></div></div>
          )}
      </div>
  );
}

