  const [classrooms, setClassrooms] = useState<Classroom[]>([]);
  const [totalPlans, setTotalPlans] = useState(0);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [showNotifications, setShowNotifications] = useState(false);
  const [messages, setMessages] = useState<DirectMessage[]>([]);

  const [formData, setFormData] = useState<UserProfile>(profile);
  const [message, setMessage] = useState('');

  const [showAddClassModal, setShowAddClassModal] = useState(false);
  const [managedClassroom, setManagedClassroom] = useState<Classroom | null>(null);

  const [manageTab, setManageTab] = useState<'students' | 'performance' | 'forum' | 'resources'>('students');
  const [manageView, setManageView] = useState<'subjects' | 'assignments' | 'results'>('subjects');
  const [selectedSubjectForStats, setSelectedSubjectForStats] = useState<string>('');
  const [selectedAssignmentForStats, setSelectedAssignmentForStats] = useState<Assignment | null>(null);
  const [currentAssignmentResults, setCurrentAssignmentResults] = useState<StudentResult[]>([]);
  const [assignmentList, setAssignmentList] = useState<Assignment[]>([]);
  const [feedbackModal, setFeedbackModal] = useState<{resultId: string, name: string, currentFeedback: string} | null>(null);
  const [feedbackInput, setFeedbackInput] = useState('');

  const [analysisModal, setAnalysisModal] = useState<{studentName: string, report: string} | null>(null);
  const [dmModal, setDmModal] = useState<{studentName: string, studentCode: string} | null>(null);
  const [dmInput, setDmInput] = useState('');
  const [replyText, setReplyText] = useState('');
  const [selectedThread, setSelectedThread] = useState<string | null>(null);

  const [forumPostTitle, setForumPostTitle] = useState('');
  const [forumPostContent, setForumPostContent] = useState('');
  const [replyContent, setReplyContent] = useState('');
  const [activePostId, setActivePostId] = useState<string | null>(null);

  const [newClassGrade, setNewClassGrade] = useState<Grade>(Grade.GRADE_7);
  const [newClassStream, setNewClassStream] = useState('');
  const [newClassRoll, setNewClassRoll] = useState<number>(40);
  const [addingSubjectTo, setAddingSubjectTo] = useState<string | null>(null);
  const [selectedSubject, setSelectedSubject] = useState<Subject>(Subject.MATHEMATICS);

  useEffect(() => {
    loadData();
    const interval = setInterval(() => {
        setNotifications(getNotifications(profile.email));
        setMessages(getDirectMessages(profile.email));
    }, 10000);
    return () => clearInterval(interval);
  }, []);

  const loadData = () => {
    const cls = getClassrooms();
    setClassrooms(cls);
    const plans = getSavedPlans();
    setTotalPlans(plans.length);
    setNotifications(getNotifications(profile.email));
    setMessages(getDirectMessages(profile.email));
  };

  const handleCreateClassroom = (e: React.FormEvent) => {
    e.preventDefault();
    if (newClassStream && newClassRoll > 0) {
        createClassroom(newClassGrade, newClassStream, newClassRoll);
        loadData();
        setShowAddClassModal(false);
        setNewClassStream('');
        setNewClassRoll(40);
    }
  };

  const handleDeleteClassroom = (id: string) => {
    if (confirm('Are you sure? All student data will be lost.')) {
        deleteClassroom(id);
        loadData();
        if (managedClassroom?.id === id) setManagedClassroom(null);
    }
  };

  const handleSubmitProfile = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdate(formData);
    setMessage('Profile updated successfully!');
    setTimeout(() => setMessage(''), 3000);
  };

  const handleAddSubject = (classId: string) => {
      addSubjectToClassroom(classId, selectedSubject);
      setAddingSubjectTo(null);
      loadData();
  };

  const handleRemoveSubject = (classId: string, subject: string) => {
      if (confirm(`Remove ${subject}?`)) {
          removeSubjectFromClassroom(classId, subject);
          loadData();
      }
  };

  const openClassroomManager = (cls: Classroom) => {
      setManagedClassroom(cls);
      setManageTab('students');
      setManageView('subjects');
      setActiveView('classrooms');
  };

  const handleSidebarSubjectClick = (cls: Classroom, subject: string) => {
      setManagedClassroom(cls);
      setManageTab('performance');
      loadAssignmentsForSubjectInternal(cls.id, subject);
      setActiveView('classrooms');
      if (window.innerWidth < 1024) setSidebarOpen(false);
  };

  const loadAssignmentsForSubject = (subject: string) => {
      if (!managedClassroom) return;
      loadAssignmentsForSubjectInternal(managedClassroom.id, subject);
  };

  const loadAssignmentsForSubjectInternal = (classId: string, subject: string) => {
      const allAssignments = getAssignmentsByClassId(classId);
      const filtered = allAssignments.filter(a => a.subject === subject);
      setAssignmentList(filtered);
      setSelectedSubjectForStats(subject);
      setManageView('assignments');
  };

  const loadResultsForAssignment = (assignment: Assignment) => {
      const results = getAssignmentResults(assignment.id);
      const highestScoreMap = new Map<string, StudentResult>();
      results.forEach(result => {
        const existing = highestScoreMap.get(result.studentCode);
        if (!existing || result.score > existing.score) {
          highestScoreMap.set(result.studentCode, result);
        }
      });
      const filteredResults = Array.from(highestScoreMap.values());
      setCurrentAssignmentResults(filteredResults);
      setSelectedAssignmentForStats(assignment);
      setManageView('results');
  };

  const openFeedbackModal = (result: StudentResult) => {
      setFeedbackInput(result.feedback || '');
      setFeedbackModal({
          resultId: result.id,
          name: result.studentName,
          currentFeedback: result.feedback || ''
      });
  };

  const saveFeedback = () => {
      if (!feedbackModal) return;
      updateStudentResultFeedback(feedbackModal.resultId, feedbackInput);
      const updatedResults = currentAssignmentResults.map(r => 
          r.id === feedbackModal.resultId ? {...r, feedback: feedbackInput} : r
      );
      setCurrentAssignmentResults(updatedResults);
      setFeedbackModal(null);
  };

  const openDmModal = (student: {name?: string, code: string}) => {
      setDmModal({
          studentName: student.name || `Student ${student.code}`,
          studentCode: student.code
      });
      setDmInput('');
  };

  const sendDm = () => {
      if (!dmModal || !dmInput.trim()) return;
      const msg: DirectMessage = {
          id: crypto.randomUUID(),
          senderId: profile.email,
          senderName: profile.name,
          receiverId: dmModal.studentCode,
          content: dmInput,
          timestamp: new Date().toISOString(),
          read: false,
          isFromTeacher: true
      };
      sendDirectMessage(msg);
      setDmModal(null);
      alert("Message sent successfully!");
      setMessages(getDirectMessages(profile.email));
  };

  const handleReplyToStudent = (studentId: string, studentName: string) => {
      if (!replyText.trim()) return;
      const msg: DirectMessage = {
          id: crypto.randomUUID(),
          senderId: profile.email,
          senderName: profile.name,
          receiverId: studentId,
          content: replyText,
          timestamp: new Date().toISOString(),
          read: false,
          isFromTeacher: true
      };
      sendDirectMessage(msg);
      setReplyText('');
      setMessages(prev => [...prev, msg]); 
  };

  const handleTextbookUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file && managedClassroom) {
          if (file.size > 2 * 1024 * 1024) {
              alert("File too large. Please upload files smaller than 2MB.");
              return;
          }
          const reader = new FileReader();
          reader.onloadend = () => {
              const result = reader.result;
              const base64 = typeof result === 'string' ? result : '';
              if (!base64) return;
              const newBook: Textbook = {
                  id: crypto.randomUUID(),
                  title: file.name,
                  fileData: base64,
                  fileType: file.type.includes('pdf') ? 'pdf' : 'word',
                  uploadDate: new Date().toISOString(),
                  size: `${(file.size/1024).toFixed(1)} KB`
              };
              if (managedClassroom) {
                  uploadTextbookToClassroom(managedClassroom.id, newBook);
                  setManagedClassroom(prev => prev ? {...prev, textbooks: [...(prev.textbooks || []), newBook]} : null);
              }
          };
          reader.readAsDataURL(file);
      }
  };

  const handleCreateForumPost = (e: React.FormEvent) => {
      e.preventDefault();
      if (!managedClassroom || !forumPostTitle.trim() || !forumPostContent.trim()) return;
      const newPost: ForumPost = {
          id: crypto.randomUUID(),
          authorName: profile.name,
          title: forumPostTitle,
          content: forumPostContent,
          timestamp: new Date().toISOString(),
          replies: []
      };
      createForumPost(managedClassroom.id, newPost);
      const updatedClass = {
          ...managedClassroom,
          forumPosts: [newPost, ...(managedClassroom.forumPosts || [])]
      };
      setManagedClassroom(updatedClass);
      setForumPostTitle('');
      setForumPostContent('');
  };

  const handleReplyToPost = (postId: string) => {
      if (!managedClassroom || !replyContent.trim()) return;
      const reply: ForumReply = {
          id: crypto.randomUUID(),
          authorName: profile.name,
          authorRole: 'teacher',
          content: replyContent,
          timestamp: new Date().toISOString()
      };
      addForumReply(managedClassroom.id, postId, reply);
      const updatedPosts = managedClassroom.forumPosts.map(p => {
          if (p.id === postId) {
              return { ...p, replies: [...p.replies, reply] };
          }
          return p;
      });
      setManagedClassroom({ ...managedClassroom, forumPosts: updatedPosts });
      setReplyContent('');
      setActivePostId(null);
  };

  const handleNotificationClick = (notif: AppNotification) => {
      markNotificationRead(notif.id);
      setNotifications(prev => prev.map(n => n.id === notif.id ? {...n, read: true} : n));
      if (notif.type === 'message') {
          setActiveView('inbox');
      }
  };

  const handleSelectThread = (studentId: string) => {
      setSelectedThread(studentId);
      markMessagesRead(studentId, profile.email);
      setNotifications(prev => prev.filter(n => !(n.type === 'message' && n.title.includes(studentId))));
      setMessages(prev => prev.map(m => (m.senderId === studentId && m.receiverId === profile.email) ? {...m, read: true} : m));
  };

  const unreadCount = notifications.filter(n => !n.read).length;
  const unreadMessagesCount = messages.filter(m => !m.read && m.receiverId === profile.email).length;

  return (
    <div className="flex min-h-screen bg-slate-50 font-sans text-slate-800">
      {sidebarOpen && (
        <div className="fixed inset-0 bg-black/50 z-40 lg:hidden" onClick={() => setSidebarOpen(false)}/>
      )}
      <aside className={`fixed inset-y-0 left-0 z-50 bg-slate-900 text-slate-300 transition-all duration-300 ease-in-out shadow-xl flex flex-col 
          ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} 
          lg:translate-x-0 
          ${isCollapsed ? 'w-20' : 'w-64'}
      `}>
        <div className={`flex items-center h-16 px-4 bg-slate-950 text-white font-bold text-xl tracking-tight border-b border-slate-800 ${isCollapsed ? 'justify-center' : 'justify-between'}`}>
          {!isCollapsed ? (
              <div className="flex items-center">
                <BookOpen className="w-6 h-6 mr-2 text-teal-500" />
                <span>Mwalimu<span className="text-teal-500">Admin</span></span>
              </div>
          ) : (
              <BookOpen className="w-8 h-8 text-teal-500" />
          )}
          <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-slate-400 hover:text-white p-1">
            <X className="w-5 h-5" />
          </button>
        </div>
        <nav className="flex-1 overflow-y-auto p-3 space-y-1">
          <button onClick={() => {setActiveView('overview'); if(window.innerWidth < 1024) setSidebarOpen(false);}} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${activeView === 'overview' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'} ${isCollapsed ? 'justify-center' : ''}`}>
            <Home className={`w-5 h-5 ${!isCollapsed && 'mr-3'}`} />
            {!isCollapsed && "Dashboard"}
          </button>
          <button onClick={() => {setActiveView('classrooms'); if(window.innerWidth < 1024) setSidebarOpen(false);}} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${activeView === 'classrooms' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'} ${isCollapsed ? 'justify-center' : ''}`}>
            <Layers className={`w-5 h-5 ${!isCollapsed && 'mr-3'}`} />
            {!isCollapsed && "All Classrooms"}
          </button>
          <div className="mt-4">
              {!isCollapsed && <p className="px-4 text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">My Classes</p>}
              <div className="space-y-1">
                  {classrooms.length > 0 ? classrooms.map(cls => (
                      <div key={cls.id} className="w-full">
                          <button onClick={() => isCollapsed ? (setIsCollapsed(false), setExpandedClassId(cls.id)) : setExpandedClassId(expandedClassId === cls.id ? null : cls.id)} className={`flex items-center w-full px-4 py-2.5 text-sm font-medium rounded-lg transition-colors hover:bg-slate-800 hover:text-white ${expandedClassId === cls.id ? 'bg-slate-800 text-white' : 'text-slate-400'} ${isCollapsed ? 'justify-center' : 'justify-between'}`}>
                              <div className="flex items-center">
                                  <Users className={`w-4 h-4 ${!isCollapsed && 'mr-3'}`} />
                                  {!isCollapsed && <span>{cls.grade} <span className="text-[10px] text-teal-500 ml-1">{cls.stream}</span></span>}
                              </div>
                              {!isCollapsed && <ChevronDown className={`w-3 h-3 transition-transform ${expandedClassId === cls.id ? 'rotate-180' : ''}`} />}
                          </button>
                          {!isCollapsed && expandedClassId === cls.id && (
                              <div className="bg-slate-950/50 rounded-lg my-1 mx-2 overflow-hidden">
                                  <button onClick={() => {openClassroomManager(cls); if(window.innerWidth < 1024) setSidebarOpen(false);}} className="flex items-center w-full px-8 py-2 text-xs text-slate-400 hover:text-white hover:bg-slate-800">
                                      <span className="w-1.5 h-1.5 rounded-full bg-slate-600 mr-2"></span> Students ({cls.students.length})
                                  </button>
                                  {cls.subjects.length > 0 ? cls.subjects.map(sub => (
                                      <button key={sub} onClick={() => handleSidebarSubjectClick(cls, sub)} className="flex items-center w-full px-8 py-2 text-xs text-slate-400 hover:text-white hover:bg-slate-800">
                                          <span className="w-1.5 h-1.5 rounded-full bg-teal-600 mr-2"></span> {sub}
                                      </button>
                                  )) : <div className="px-8 py-2 text-[10px] text-slate-600 italic">No subjects</div>}
                              </div>
                          )}
                      </div>
                  )) : !isCollapsed && <div className="px-4 text-xs text-slate-500 italic">No classes.</div>}
              </div>
          </div>
          <div className="pt-4 mt-4 border-t border-slate-800">
            {!isCollapsed && <p className="px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">Communication</p>}
            <button onClick={() => {setActiveView('inbox'); if(window.innerWidth < 1024) setSidebarOpen(false);}} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors group relative ${activeView === 'inbox' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'} ${isCollapsed ? 'justify-center' : ''}`}>
              <Mail className={`w-5 h-5 ${!isCollapsed && 'mr-3'}`} />
              {!isCollapsed && <span>My Inbox</span>}
              {unreadMessagesCount > 0 && (isCollapsed ? <span className="absolute top-2 right-2 w-2.5 h-2.5 bg-red-500 rounded-full border-2 border-slate-900"></span> : <span className="ml-auto bg-red-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full">{unreadMessagesCount}</span>)}
            </button>
          </div>
          <div className="pt-4 mt-4 border-t border-slate-800">
            {!isCollapsed && <p className="px-4 text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">Account</p>}
            <button onClick={() => {setActiveView('profile'); if(window.innerWidth < 1024) setSidebarOpen(false);}} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors ${activeView === 'profile' ? 'bg-teal-600 text-white shadow-md' : 'hover:bg-slate-800 hover:text-white'} ${isCollapsed ? 'justify-center' : ''}`}>
              <User className={`w-5 h-5 ${!isCollapsed && 'mr-3'}`} />
              {!isCollapsed && "Profile"}
            </button>
          </div>
        </nav>
        <div className="p-4 border-t border-slate-800">
            <button onClick={() => setIsCollapsed(!isCollapsed)} className="hidden lg:flex w-full items-center justify-center p-2 text-slate-500 hover:text-white hover:bg-slate-800 rounded-lg transition-colors">
                {isCollapsed ? <ChevronRight className="w-5 h-5"/> : <ChevronLeft className="w-5 h-5"/>}
            </button>
        </div>
      </aside>
      <div className={`flex-1 flex flex-col transition-all duration-300 ${isCollapsed ? 'lg:ml-20' : 'lg:ml-64'}`}>
        <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 lg:px-8 sticky top-0 z-40 shadow-sm">
          <div className="flex items-center gap-3">
              <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-gray-500 hover:bg-gray-100 rounded-md focus:outline-none lg:hidden"><Menu className="w-6 h-6" /></button>
              <h2 className="text-xl font-bold text-gray-800 hidden sm:block capitalize">{activeView === 'overview' ? 'Dashboard' : activeView}</h2>
          </div>
          <div className="flex items-center gap-4 ml-auto relative">
             {profile.schoolId ? (
                 <div className="hidden md:flex items-center gap-2 bg-indigo-50 text-indigo-700 px-3 py-1 rounded-full text-xs font-bold border border-indigo-200"><Building2 className="w-3 h-3" />{profile.school}</div>
             ) : profile.teacherCode && (
                 <div className="hidden md:flex items-center gap-2 bg-yellow-50 text-yellow-700 px-3 py-1 rounded-full text-xs font-bold border border-yellow-200"><Key className="w-3 h-3" />Code: {profile.teacherCode}</div>
             )}
            <div className="relative">
                <button onClick={() => setShowNotifications(!showNotifications)} className="p-2 text-gray-400 hover:text-gray-600 relative focus:outline-none"><Bell className="w-5 h-5" />{unreadCount > 0 && <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>}</button>
                {showNotifications && (
                    <div className="absolute right-0 mt-2 w-80 bg-white rounded-xl shadow-xl border border-gray-200 overflow-hidden z-50 animate-fade-in-up">
                        <div className="bg-slate-50 px-4 py-3 border-b border-gray-100 font-bold text-sm text-gray-700 flex justify-between"><span>Notifications</span><span className="text-xs bg-slate-200 px-2 py-0.5 rounded-full">{unreadCount} New</span></div>
                        <div className="max-h-80 overflow-y-auto">
                            {notifications.length === 0 ? (<div className="p-6 text-center text-gray-400 text-sm">No notifications</div>) : (
                                notifications.map(notif => (<div key={notif.id} onClick={() => handleNotificationClick(notif)} className={`p-4 border-b border-gray-50 hover:bg-slate-50 cursor-pointer transition-colors ${!notif.read ? 'bg-blue-50/50' : ''}`}><div className="flex justify-between items-start mb-1"><span className="font-bold text-xs uppercase text-teal-600">{notif.type}</span><span className="text-[10px] text-gray-400">{new Date(notif.timestamp).toLocaleDateString()}</span></div><h4 className={`text-sm ${!notif.read ? 'font-bold text-slate-800' : 'font-medium text-slate-600'}`}>{notif.title}</h4><p className="text-xs text-gray-500 mt-1 line-clamp-2">{notif.message}</p></div>))
                            )}
                        </div>
                    </div>
                )}
            </div>
            <div className="flex items-center gap-2 pl-4 border-l border-gray-200">
              <div className="w-8 h-8 bg-slate-800 rounded-full flex items-center justify-center text-white text-xs font-bold">{profile.name.charAt(0)}</div>
              <span className="text-sm font-medium text-gray-700 hidden md:block">{profile.name}</span>
              <ChevronDown className="w-4 h-4 text-gray-400" />
            </div>
          </div>
        </header>
        <main className="p-4 lg:p-8 max-w-7xl mx-auto w-full">
          {activeView === 'overview' && (
            <div className="space-y-8 animate-fade-in">
                <h2 className="text-xl text-gray-600 font-light uppercase tracking-wide">Overview</h2>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <StatCard icon={FileText} label="Total Plans" value={totalPlans} color="bg-teal-500" />
                    <StatCard icon={Users} label="Classrooms" value={classrooms.length} color="bg-blue-500" />
                    <StatCard icon={Users} label="Total Students" value={classrooms.reduce((acc, c) => acc + c.students.length, 0)} color="bg-indigo-500" />
                </div>
            </div>
          )}
          {activeView === 'classrooms' && (
            <div className="space-y-6 animate-fade-in">
                <div className="flex justify-between items-center mb-4">
                    <h2 className="text-xl text-gray-600 font-light uppercase tracking-wide">My Classrooms</h2>
                    {!profile.schoolId && <button onClick={() => setShowAddClassModal(true)} className="bg-teal-600 text-white px-4 py-2 rounded shadow hover:bg-teal-700 flex items-center gap-2 text-sm font-bold"><Plus className="w-4 h-4" /> Add Classroom</button>}
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {classrooms.map((room) => (
                        <div key={room.id} className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                            <div className="p-5 border-b border-gray-100 flex justify-between items-start">
                                <div><h4 className="text-lg font-bold text-slate-800">{room.grade} <span className="text-gray-400">|</span> {room.stream}</h4><div className="flex items-center gap-4 mt-2 text-xs text-gray-500 font-medium uppercase tracking-wide"><span className="flex items-center gap-1"><Users className="w-3 h-3" /> {room.students.length} Students</span></div></div>
                                <div className="flex gap-2"><button onClick={() => openClassroomManager(room)} className="p-2 bg-gray-100 hover:bg-gray-200 rounded text-gray-600"><Eye className="w-4 h-4" /></button>{!profile.schoolId && <button onClick={() => handleDeleteClassroom(room.id)} className="p-2 bg-red-50 hover:bg-red-100 rounded text-red-600"><Trash2 className="w-4 h-4" /></button>}</div>
                            </div>
                            <div className="p-5 bg-slate-50 min-h-[100px]">
                                <div className="flex justify-between items-center mb-3"><h5 className="text-xs font-bold text-gray-400 uppercase">Subjects</h5>{addingSubjectTo === room.id ? (<div className="flex items-center gap-1"><select value={selectedSubject} onChange={(e) => setSelectedSubject(e.target.value as Subject)} className="text-xs border-gray-300 rounded py-1 w-32">{Object.values(Subject).map(s => <option key={s} value={s}>{s}</option>)}</select><button onClick={() => handleAddSubject(room.id)} className="bg-green-600 text-white p-1 rounded"><Check className="w-3 h-3" /></button><button onClick={() => setAddingSubjectTo(null)} className="bg-gray-300 text-gray-700 p-1 rounded"><X className="w-3 h-3" /></button></div>) : (<button onClick={() => setAddingSubjectTo(room.id)} className="text-teal-600 text-xs font-bold hover:underline flex items-center gap-1"><Plus className="w-3 h-3" /> Add</button>)}</div>
                                <div className="flex flex-wrap gap-2">{room.subjects.length > 0 ? room.subjects.map(sub => (<span key={sub} className="inline-flex items-center gap-1 bg-white border border-gray-200 text-gray-600 px-2 py-1 rounded text-xs font-medium">{sub}<button onClick={() => handleRemoveSubject(room.id, sub)} className="text-gray-400 hover:text-red-500"><X className="w-3 h-3" /></button></span>)) : <span className="text-gray-400 text-xs italic">No subjects.</span>}</div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
          )}
          {activeView === 'inbox' && (
              <div className="h-[calc(100vh-8rem)] bg-white rounded-xl border border-gray-200 shadow-sm flex overflow-hidden animate-fade-in">
                  <div className={`w-full md:w-1/3 border-r border-gray-200 flex flex-col ${selectedThread ? 'hidden md:flex' : 'flex'}`}>
                      <div className="p-4 border-b border-gray-200 bg-gray-50"><h3 className="font-bold text-gray-800">My Inbox</h3><p className="text-xs text-gray-500">Student Messages</p></div>
                      <div className="flex-1 overflow-y-auto">
                          {Array.from(new Set(messages.filter(m => !m.isFromTeacher).map(m => m.senderId))).map(studentId => {
                              const lastMsg = messages.filter(m => m.senderId === studentId || m.receiverId === studentId).pop();
                              const unread = messages.filter(m => m.senderId === studentId && !m.read).length;
                              const studentName = lastMsg?.senderId === studentId ? lastMsg?.senderName : (messages.find(m => m.senderId === studentId)?.senderName || studentId);
                              return (<div key={studentId} onClick={() => handleSelectThread(studentId)} className={`p-4 border-b border-gray-100 hover:bg-slate-50 cursor-pointer transition-colors ${selectedThread === studentId ? 'bg-blue-50' : ''}`}><div className="flex justify-between items-start mb-1"><h4 className={`text-sm ${unread > 0 ? 'font-bold text-slate-900' : 'font-medium text-slate-700'}`}>{studentName}</h4><span className="text-[10px] text-gray-400">{lastMsg ? new Date(lastMsg.timestamp).toLocaleDateString() : ''}</span></div><p className={`text-xs truncate ${unread > 0 ? 'font-bold text-slate-800' : 'text-gray-500'}`}>{lastMsg?.isFromTeacher ? 'You: ' : ''}{lastMsg?.content}</p>{unread > 0 && <span className="inline-block bg-red-500 text-white text-[10px] px-2 rounded-full mt-1">{unread}</span>}</div>);
                          })}
                      </div>
                  </div>
                  <div className={`flex-1 flex flex-col ${!selectedThread ? 'hidden md:flex' : 'flex'}`}>
                      {selectedThread ? (<><div className="p-4 border-b border-gray-200 bg-white flex justify-between items-center"><div className="flex items-center gap-2"><button onClick={() => setSelectedThread(null)} className="md:hidden text-gray-500"><ArrowLeft className="w-5 h-5"/></button><div><h3 className="font-bold text-gray-800">{messages.find(m => m.senderId === selectedThread || m.receiverId === selectedThread)?.senderName || 'Student'}</h3><p className="text-xs text-gray-500 text-teal-600 font-mono">{selectedThread}</p></div></div></div><div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50">{messages.filter(m => m.senderId === selectedThread || m.receiverId === selectedThread).map(msg => (<div key={msg.id} className={`flex ${msg.isFromTeacher ? 'justify-end' : 'justify-start'}`}><div className={`max-w-[70%] rounded-xl p-3 text-sm shadow-sm ${msg.isFromTeacher ? 'bg-blue-600 text-white rounded-br-none' : 'bg-white text-gray-800 border border-gray-200 rounded-bl-none'}`}><p>{msg.content}</p><p className={`text-[10px] mt-1 text-right ${msg.isFromTeacher ? 'text-blue-200' : 'text-gray-400'}`}>{new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p></div></div>))}</div><div className="p-4 border-t border-gray-200 bg-white"><div className="flex gap-2"><input type="text" className="flex-1 border border-gray-300 rounded-lg px-4 py-2 text-sm focus:outline-none focus:border-teal-500" placeholder="Type reply..." value={replyText} onChange={e => setReplyText(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleReplyToStudent(selectedThread!, messages.find(m=>m.senderId===selectedThread)?.senderName || 'Student')} /><button onClick={() => handleReplyToStudent(selectedThread!, messages.find(m=>m.senderId===selectedThread)?.senderName || 'Student')} disabled={!replyText.trim()} className="bg-blue-600 text-white p-2 rounded-lg hover:bg-blue-700 disabled:opacity-50"><Send className="w-5 h-5" /></button></div></div></>) : (<div className="flex-1 flex items-center justify-center text-gray-400 flex-col"><MessageCircle className="w-12 h-12 mb-2 opacity-20" /><p>Select thread</p></div>)}
                  </div>
              </div>
          )}
          {activeView === 'profile' && (
            <div className="max-w-2xl animate-fade-in">
                <h2 className="text-xl text-gray-600 font-light uppercase tracking-wide mb-6">Profile</h2>
                <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                    <form onSubmit={handleSubmitProfile} className="p-8 space-y-6">
                        {message && <div className="bg-green-50 text-green-700 p-3 rounded text-sm">{message}</div>}
                        <div className="grid grid-cols-1 gap-6">
                            <div><label className="block text-sm font-medium text-gray-700 mb-1">Name</label><input type="text" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full rounded border-gray-300 p-2 border" /></div>
                            <div><label className="block text-sm font-medium text-gray-700 mb-1">School</label><input type="text" required value={formData.school} onChange={e => setFormData({...formData, school: e.target.value})} readOnly={!!profile.schoolId} className={`w-full rounded border-gray-300 p-2 border ${profile.schoolId ? 'bg-gray-100 cursor-not-allowed' : ''}`} /></div>
                            <div><label className="block text-sm font-medium text-gray-700 mb-1">Phone</label><input type="tel" required value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full rounded border-gray-300 p-2 border" /></div>
                        </div>
                        <div className="pt-4 text-right"><button type="submit" className="bg-slate-900 text-white px-6 py-2 rounded hover:bg-slate-800">Save</button></div>
                    </form>
                </div>
            </div>
          )}
        </main>
      </div>

      {managedClassroom && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-4xl overflow-hidden h-[90vh] flex flex-col">
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white shrink-0">
                      <div><h3 className="font-bold text-lg">{managedClassroom.grade} - {managedClassroom.stream}</h3><p className="text-slate-400 text-xs">Manager</p></div>
                      <button onClick={() => setManagedClassroom(null)}><X className="w-5 h-5" /></button>
                  </div>
                  <div className="flex border-b border-gray-200 bg-gray-50 overflow-x-auto">
                      {['students', 'performance', 'resources', 'forum'].map((tab) => (
                          <button key={tab} onClick={() => { setManageTab(tab as any); if(tab === 'performance') setManageView('subjects'); }} className={`flex-1 py-3 px-4 text-sm font-bold border-b-2 capitalize transition-colors ${manageTab === tab ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>
                              {tab}
                          </button>
                      ))}
                  </div>
                  <div className="flex-1 overflow-y-auto p-0 bg-white relative">
                      {manageTab === 'students' && (
                          <div className="p-0">
                              <table className="w-full text-sm text-left">
                                  <thead className="bg-gray-50 text-gray-500 font-bold uppercase text-xs sticky top-0">
                                      <tr><th className="px-6 py-3">Index</th><th className="px-6 py-3">Code</th><th className="px-6 py-3">Name</th><th className="px-6 py-3 text-right">Actions</th></tr>
                                  </thead>
                                  <tbody className="divide-y divide-gray-100">
                                      {managedClassroom.students.map((student) => (
                                          <tr key={student.code} className="hover:bg-gray-50"><td className="px-6 py-3">#{student.index}</td><td className="px-6 py-3 font-mono text-teal-700 font-bold">{student.code}</td><td className="px-6 py-3 italic">{student.name || "______________________"}</td><td className="px-6 py-3 text-right"><button onClick={() => openDmModal(student)} className="bg-blue-50 text-blue-600 px-2 py-1 rounded text-xs font-bold flex items-center gap-1 ml-auto"><MessageCircle className="w-3 h-3" /> Message</button></td></tr>
                                      ))}
                                  </tbody>
                              </table>
                          </div>
                      )}
                      {manageTab === 'performance' && (
                          <div className="p-6 h-full">
                              {manageView === 'subjects' && (
                                  <div className="animate-fade-in"><h3 className="text-lg font-bold text-gray-800 mb-4">Select Subject</h3><div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">{managedClassroom.subjects.length === 0 ? (<div className="col-span-full py-10 text-center text-gray-400 italic bg-gray-50 rounded border border-dashed">No subjects.</div>) : (managedClassroom.subjects.map((sub) => (<button key={sub} onClick={() => loadAssignmentsForSubject(sub)} className="p-4 bg-white border rounded-xl hover:border-teal-500 text-left group"><h4 className="font-bold text-slate-700">{sub}</h4><div className="flex items-center text-xs text-gray-400 mt-2">View <ChevronRight className="w-3 h-3 ml-1" /></div></button>)))}</div></div>
                              )}
                              {manageView === 'assignments' && (
                                  <div className="animate-fade-in h-full flex flex-col"><button onClick={() => setManageView('subjects')} className="flex items-center text-sm text-gray-500 mb-4"><ArrowLeft className="w-4 h-4 mr-1" /> Back</button><h3 className="text-lg font-bold text-gray-800 mb-4">{selectedSubjectForStats}</h3><div className="overflow-y-auto flex-1">{assignmentList.length === 0 ? (<div className="text-center py-10 text-gray-400 italic">No assignments.</div>) : (<div className="space-y-3">{assignmentList.map(assign => (<div key={assign.id} onClick={() => loadResultsForAssignment(assign)} className="p-4 bg-white border border-gray-200 rounded-xl hover:border-teal-500 cursor-pointer flex justify-between items-center group"><div><h4 className="font-bold text-slate-700">{assign.topic}</h4><p className="text-xs text-gray-500">{new Date(assign.createdAt).toLocaleDateString()}</p></div><ChevronRight className="w-5 h-5 text-gray-300" /></div>))}</div>)}</div></div>
                              )}
                              {manageView === 'results' && selectedAssignmentForStats && (
                                  <div className="animate-fade-in h-full flex flex-col"><button onClick={() => setManageView('assignments')} className="flex items-center text-sm text-gray-500 mb-4"><ArrowLeft className="w-4 h-4 mr-1" /> Back</button><div className="mb-4"><h3 className="text-lg font-bold text-gray-800">{selectedAssignmentForStats.topic}</h3><p className="text-xs text-gray-500">Student Results</p></div><div className="overflow-hidden border border-gray-200 rounded-lg"><table className="w-full text-sm text-left"><thead className="bg-gray-50 text-gray-500 font-bold uppercase text-xs"><tr><th className="px-6 py-3">Student</th><th className="px-6 py-3">Score</th><th className="px-6 py-3">Time</th><th className="px-6 py-3 text-right">Actions</th></tr></thead><tbody className="divide-y divide-gray-100">{currentAssignmentResults.map((res) => (<tr key={res.id} className="hover:bg-gray-50"><td className="px-6 py-3">{res.studentName}</td><td className="px-6 py-3"><span className={`px-2 py-1 rounded text-xs font-bold ${res.score/res.total >= 0.5 ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{res.score}/{res.total}</span></td><td className="px-6 py-3 text-gray-500 text-xs">{res.timeTaken ? `${Math.round(res.timeTaken)}s` : '-'}</td><td className="px-6 py-3 text-right flex gap-2 justify-end">{res.aiAnalysis && <button onClick={() => setAnalysisModal({ studentName: res.studentName, report: res.aiAnalysis || '' })} className="inline-flex items-center gap-1 text-xs font-bold px-3 py-1.5 rounded bg-purple-50 text-purple-600 hover:bg-purple-100 transition-colors"><Sparkles className="w-3 h-3" /> Report</button>}<button onClick={() => openFeedbackModal(res)} className={`inline-flex items-center gap-1 text-xs font-bold px-3 py-1.5 rounded transition-colors ${res.feedback ? 'bg-blue-50 text-blue-600 hover:bg-blue-100' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}><MessageSquare className="w-3 h-3" />{res.feedback ? 'Edit' : 'Feedback'}</button></td></tr>))}</tbody></table></div></div>
                              )}
                          </div>
                      )}
                      {manageTab === 'resources' && (
                          <div className="p-6 h-full flex flex-col overflow-y-auto">
                              <h3 className="text-lg font-bold text-gray-800 mb-4">Class Textbooks & Resources</h3>
                              <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 mb-8">
                                  <label className="block text-sm font-medium text-blue-800 mb-2">Upload New Textbook</label>
                                  <div className="flex items-center gap-3">
                                      <label className="cursor-pointer bg-white border border-blue-300 text-blue-600 px-4 py-2 rounded-md text-sm font-bold flex items-center gap-2"><Upload className="w-4 h-4" />Select File<input type="file" accept=".pdf,.doc,.docx" className="hidden" onChange={handleTextbookUpload}/></label>
                                      <span className="text-xs text-blue-500">Max size 2MB</span>
                                  </div>
                              </div>
                              <div className="space-y-8">
                                  <div>
                                      <h4 className="text-sm font-bold text-gray-500 uppercase tracking-wider mb-3">Textbooks</h4>
                                      {managedClassroom.textbooks && managedClassroom.textbooks.length > 0 ? (
                                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                              {managedClassroom.textbooks.map(book => (<div key={book.id} className="border border-gray-200 rounded-lg p-4 bg-white flex items-start gap-3"><div className="p-3 bg-red-50 text-red-600 rounded-lg"><FileIcon className="w-6 h-6" /></div><div className="flex-1 min-w-0"><h4 className="font-bold text-slate-700 truncate">{book.title}</h4><p className="text-xs text-gray-500">{new Date(book.uploadDate).toLocaleDateString()} • {book.size}</p><a href={book.fileData} download={book.title} className="text-xs text-teal-600 font-bold hover:underline mt-1 inline-block">Download</a></div></div>))}
                                          </div>
                                      ) : (<div className="text-center py-6 text-gray-400 italic bg-slate-50 rounded border border-dashed">No textbooks.</div>)}
                                  </div>
                                  <div>
                                      <h4 className="text-sm font-bold text-gray-500 uppercase tracking-wider mb-3">Shared Lesson Notes</h4>
                                      {(() => {
                                          if (!managedClassroom.sharedNotes || managedClassroom.sharedNotes.length === 0) return <div className="text-center py-6 text-gray-400 italic bg-slate-50 rounded border border-dashed">No notes shared.</div>;
                                          const groupedClassroomNotes: Record<string, SharedNote[]> = {};
                                          managedClassroom.sharedNotes.forEach(note => {
                                              if (!groupedClassroomNotes[note.subject]) groupedClassroomNotes[note.subject] = [];
                                              groupedClassroomNotes[note.subject].push(note);
                                          });
                                          // Fix Object.entries destructuring with explicit typing
                                          return (Object.entries(groupedClassroomNotes) as [string, SharedNote[]][]).map(([subject, notes]) => (
                                              <div key={subject} className="mb-6">
                                                  <h5 className="font-bold text-teal-700 mb-2 pl-2 border-l-4 border-teal-500">{subject}</h5>
                                                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                                      {notes.map((note: SharedNote) => (<div key={note.id} className="border border-gray-200 rounded-lg p-4 bg-white shadow-sm"><h4 className="font-bold text-slate-800">{note.title}</h4><p className="text-xs text-gray-500 mb-2">{new Date(note.dateShared).toLocaleDateString()}</p><p className="text-xs text-gray-600 line-clamp-2">{note.content.substring(0, 100)}...</p></div>))}
                                                  </div>
                                              </div>
                                          ));
                                      })()}
                                  </div>
                              </div>
                          </div>
                      )}
                      {manageTab === 'forum' && (
                          <div className="p-6 h-full flex flex-col">
                              <h3 className="text-lg font-bold text-gray-800 mb-4">Class Forum</h3>
                              <form onSubmit={handleCreateForumPost} className="bg-slate-50 p-4 rounded-xl border border-gray-200 mb-6">
                                  <input type="text" placeholder="Title" className="w-full mb-2 p-2 rounded border border-gray-300 text-sm font-bold" value={forumPostTitle} onChange={(e) => setForumPostTitle(e.target.value)} required />
                                  <textarea rows={2} placeholder="Post..." className="w-full p-2 rounded border border-gray-300 text-sm mb-2" value={forumPostContent} onChange={(e) => setForumPostContent(e.target.value)} required />
                                  <div className="text-right"><button type="submit" className="bg-slate-900 text-white px-4 py-1.5 rounded text-xs font-bold hover:bg-slate-800">Post</button></div>
                              </form>
                              <div className="flex-1 overflow-y-auto space-y-4">
                                  {managedClassroom.forumPosts && managedClassroom.forumPosts.length > 0 ? (
                                      (managedClassroom.forumPosts as ForumPost[]).map((post: ForumPost) => (
                                          <div key={post.id} className="border border-gray-200 rounded-xl p-4 bg-white">
                                              <div className="flex justify-between items-start mb-2"><div><h4 className="font-bold text-teal-800">{post.title}</h4><p className="text-xs text-gray-500">{post.authorName} • {new Date(post.timestamp).toLocaleDateString()}</p></div><span className="text-xs bg-gray-100 px-2 py-1 rounded text-gray-600">{post.replies.length} replies</span></div>
                                              <p className="text-sm text-gray-700 mb-4">{post.content}</p>
                                              {post.replies.length > 0 && (<div className="bg-gray-50 rounded p-3 mb-3 space-y-2">{post.replies.map((reply: ForumReply) => (<div key={reply.id} className="text-xs border-l-2 border-gray-300 pl-2"><span className={`font-bold ${reply.authorRole === 'teacher' ? 'text-teal-600' : 'text-blue-600'}`}>{reply.authorName}</span><p className="text-gray-600">{reply.content}</p></div>))}</div>)}
                                              {activePostId === post.id ? (<div className="flex gap-2"><input type="text" className="flex-1 text-sm border border-gray-300 rounded px-2 py-1" placeholder="Reply..." value={replyContent} onChange={(e) => setReplyContent(e.target.value)} /><button onClick={() => handleReplyToPost(post.id)} className="bg-teal-600 text-white px-3 py-1 rounded text-xs font-bold">Reply</button><button onClick={() => setActivePostId(null)} className="text-gray-500 text-xs">Cancel</button></div>) : (<button onClick={() => setActivePostId(post.id)} className="text-teal-600 text-xs font-bold flex items-center gap-1 hover:underline"><Reply className="w-3 h-3" /> Reply</button>)}
                                          </div>
                                      ))
                                  ) : (<div className="text-center text-gray-400 py-10">No discussions yet.</div>)}
                              </div>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}

      {/* Restoring shared logic modals at the root level for z-index safety */}
      {feedbackModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white"><h3 className="font-bold">Feedback for {feedbackModal.name}</h3><button onClick={() => setFeedbackModal(null)}><X className="w-5 h-5" /></button></div>
                  <div className="p-6"><label className="block text-sm font-medium text-gray-700 mb-2">Teacher's Comment</label><textarea rows={4} className="w-full rounded-lg border border-gray-300 p-3 text-sm" placeholder="Write feedback..." value={feedbackInput} onChange={(e) => setFeedbackInput(e.target.value)} /></div>
                  <div className="p-6 border-t border-gray-100 bg-gray-50 flex justify-end gap-2"><button onClick={() => setFeedbackModal(null)} className="px-4 py-2 text-gray-600 rounded font-medium text-sm">Cancel</button><button onClick={saveFeedback} className="px-4 py-2 bg-teal-600 text-white rounded font-bold text-sm">Save</button></div>
              </div>
          </div>
      )}

      {dmModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white"><h3 className="font-bold">Message {dmModal.studentName}</h3><button onClick={() => setDmModal(null)}><X className="w-5 h-5" /></button></div>
                  <div className="p-6"><label className="block text-sm font-medium text-gray-700 mb-2">Message</label><textarea rows={4} className="w-full rounded-lg border border-gray-300 p-3 text-sm" placeholder="Type message..." value={dmInput} onChange={(e) => setDmInput(e.target.value)} /></div>
                  <div className="p-6 border-t border-gray-100 bg-gray-50 flex justify-end gap-2"><button onClick={() => setDmModal(null)} className="px-4 py-2 text-gray-600 rounded font-medium text-sm">Cancel</button><button onClick={sendDm} className="px-4 py-2 bg-blue-600 text-white rounded font-bold text-sm flex items-center gap-2"><Send className="w-3 h-3" /> Send</button></div>
              </div>
          </div>
      )}

      {analysisModal && (
        <div className="fixed inset-0 z-[80] flex items-center justify-center bg-black/50 p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-lg overflow-hidden animate-fade-in-up">
                <div className="bg-purple-600 px-6 py-4 flex justify-between items-center text-white"><h3 className="font-bold flex items-center gap-2"><Sparkles className="w-4 h-4"/> AI Analysis</h3><button onClick={() => setAnalysisModal(null)}><X className="w-5 h-5" /></button></div>
                <div className="p-6 max-h-[70vh] overflow-y-auto"><h4 className="font-bold text-gray-800 mb-2">{analysisModal.studentName}</h4><div className="prose prose-sm text-gray-600 whitespace-pre-wrap">{analysisModal.report}</div></div>
                <div className="p-4 border-t border-gray-100 bg-gray-50 text-right"><button onClick={() => setAnalysisModal(null)} className="px-4 py-2 bg-slate-800 text-white rounded text-sm font-bold">Close</button></div>
            </div>
        </div>
      )}

      {showAddClassModal && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white"><h3 className="font-bold">New Classroom</h3><button onClick={() => setShowAddClassModal(false)}><X className="w-5 h-5" /></button></div>
                <form onSubmit={handleCreateClassroom} className="p-6 space-y-4">
                    <div><label className="block text-sm font-medium text-gray-700 mb-1">Grade</label><select value={newClassGrade} onChange={(e) => setNewClassGrade(e.target.value as Grade)} className="w-full rounded border-gray-300 p-2 border">{Object.values(Grade).map(g => <option key={g} value={g}>{g}</option>)}</select></div>
                    <div><label className="block text-sm font-medium text-gray-700 mb-1">Stream</label><input type="text" required placeholder="e.g. Blue" value={newClassStream} onChange={(e) => setNewClassStream(e.target.value)} className="w-full rounded border-gray-300 p-2 border" /></div>
                    <div><label className="block text-sm font-medium text-gray-700 mb-1">Roll</label><input type="number" min="1" max="100" required value={newClassRoll} onChange={(e) => setNewClassRoll(parseInt(e.target.value) || 0)} className="w-full rounded border-gray-300 p-2 border" /></div>
                    <button type="submit" className="w-full bg-teal-600 text-white font-bold py-2 rounded">Generate</button>
                </form>
            </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

