// --- Student Login & Results ---

export const authenticateStudent = (code: string): { student: Student, classroom: Classroom } | null => {
  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

  for (const cls of allClassrooms) {
    const student = cls.students.find(s => s.code === code);
    if (student) {
      const classroomData = { ...cls, forumPosts: cls.forumPosts || [], textbooks: cls.textbooks || [] };
      return { student, classroom: classroomData };
    }
  }
  return null;
};

export const updateStudentName = (classId: string, studentCode: string, name: string): Student | null => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];

    const clsIndex = allClassrooms.findIndex(c => c.id === classId);
    if (clsIndex === -1) return null;

    const studentIndex = allClassrooms[clsIndex].students.findIndex(s => s.code === studentCode);
    if (studentIndex === -1) return null;

    allClassrooms[clsIndex].students[studentIndex].name = name;
    localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));

    return allClassrooms[clsIndex].students[studentIndex];
};

export const saveStudentResult = (result: StudentResult): void => {
  const data = localStorage.getItem(RESULTS_STORAGE_KEY);
  const results: StudentResult[] = data ? JSON.parse(data) : [];
  const priorAttempts = results.filter(r => r.assignmentId === result.assignmentId && r.studentCode === result.studentCode);
  result.attempts = priorAttempts.length + 1;
  results.push(result);
  localStorage.setItem(RESULTS_STORAGE_KEY, JSON.stringify(results));
};

export const getStudentResults = (studentCode: string): StudentResult[] => {
    const data = localStorage.getItem(RESULTS_STORAGE_KEY);
    const results: StudentResult[] = data ? JSON.parse(data) : [];
    return results.filter(r => r.studentCode === studentCode).sort((a,b) => new Date(b.dateTaken).getTime() - new Date(a.dateTaken).getTime());
};

export const getAssignmentResults = (assignmentId: string): StudentResult[] => {
    const data = localStorage.getItem(RESULTS_STORAGE_KEY);
    const results: StudentResult[] = data ? JSON.parse(data) : [];
    return results.filter(r => r.assignmentId === assignmentId).sort((a,b) => new Date(b.dateTaken).getTime() - new Date(a.dateTaken).getTime());
};

export const updateStudentResultFeedback = (resultId: string, feedback: string): void => {
    const data = localStorage.getItem(RESULTS_STORAGE_KEY);
    const results: StudentResult[] = data ? JSON.parse(data) : [];
    const index = results.findIndex(r => r.id === resultId);

    if (index !== -1) {
        results[index].feedback = feedback;
        localStorage.setItem(RESULTS_STORAGE_KEY, JSON.stringify(results));
        createNotification(results[index].studentCode, 'assignment', 'Teacher Feedback', 'You have received feedback on your assignment.');
    }
};

// --- User Authentication & Management ---

const generateTeacherCode = () => {
  return Math.random().toString(36).substring(2, 8).toUpperCase();
};

const getUsers = (): UserProfile[] => {
  const data = localStorage.getItem(USERS_DB_KEY);
  return data ? JSON.parse(data) : [];
};

const getSchools = (): School[] => {
    const data = localStorage.getItem(SCHOOLS_DB_KEY);
    return data ? JSON.parse(data) : [];
};

export const getAllUsers = (): UserProfile[] => {
  return getUsers();
};

export const registerSchool = (schoolName: string, adminEmail: string, adminPass: string, adminPhone: string, address: string): UserProfile => {
    const schools = getSchools();
    const users = getUsers();

    if (users.some(u => u.email.toLowerCase() === adminEmail.toLowerCase())) {
        throw new Error('An account with this email already exists.');
    }

    const adminId = crypto.randomUUID();
    const schoolId = crypto.randomUUID();

    const newSchool: School = {
        id: schoolId,
        name: schoolName,
        email: adminEmail,
        phone: adminPhone,
        address: address,
        adminId: adminId,
        createdAt: new Date().toISOString()
    };

    const adminUser: UserProfile = {
        id: adminId,
        name: `${schoolName} Admin`,
        email: adminEmail,
        password: adminPass,
        phone: adminPhone,
        school: schoolName,
        schoolId: schoolId,
        role: 'school_admin',
        isAdmin: false
    };

    schools.push(newSchool);
    users.push(adminUser);

    localStorage.setItem(SCHOOLS_DB_KEY, JSON.stringify(schools));
    localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));
    localStorage.setItem(SESSION_KEY, JSON.stringify(adminUser));

    return adminUser;
};

export const createTeacherAccount = (schoolId: string, teacherName: string, teacherEmail: string, teacherPhone: string, password: string): UserProfile => {
    const users = getUsers();
    const schools = getSchools();
    const school = schools.find(s => s.id === schoolId);

    if (!school) throw new Error("School not found.");
    if (users.some(u => u.email.toLowerCase() === teacherEmail.toLowerCase())) {
        throw new Error('A teacher with this email already exists.');
    }

    const newTeacher: UserProfile = {
        id: crypto.randomUUID(),
        name: teacherName,
        email: teacherEmail,
        phone: teacherPhone,
        password: password,
        school: school.name,
        schoolId: schoolId,
        role: 'teacher',
        isAdmin: false,
        teacherCode: generateTeacherCode()
    };

    users.push(newTeacher);
    localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));
    return newTeacher;
};

export const linkTeacherToSchool = (schoolId: string, teacherCode: string): UserProfile => {
  const users = getUsers();
  const schools = getSchools();
  const school = schools.find(s => s.id === schoolId);
  const teacherIdx = users.findIndex(u => u.teacherCode === teacherCode && u.role === 'teacher');

  if (!school) throw new Error("School not found");
  if (teacherIdx === -1) throw new Error("Invalid Teacher Code or user not found.");

  const teacher = users[teacherIdx];
  if (teacher.schoolId) throw new Error(`Teacher is already linked to ${teacher.school}.`);

  users[teacherIdx].schoolId = schoolId;
  users[teacherIdx].school = school.name;
  localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));

  const classrooms = getAllClassroomsGlobal();
  classrooms.forEach(c => {
    if (c.userId === teacher.email) c.schoolId = schoolId;
  });
  localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(classrooms));

  const plans = getAllGlobalPlans();
  plans.forEach(p => {
    if (p.userId === teacher.email) p.schoolName = school.name;
  });
  localStorage.setItem(PLANS_STORAGE_KEY, JSON.stringify(plans));

  return users[teacherIdx];
};

export const getSchoolTeachers = (schoolId: string): UserProfile[] => {
    const users = getUsers();
    return users.filter(u => u.schoolId === schoolId && u.role === 'teacher');
};

export const getTeacherPlans = (teacherEmail: string): LessonPlanData[] => {
    const plans = getAllGlobalPlans();
    return plans.filter(p => p.userId === teacherEmail).sort((a,b) => new Date(b.createdAt || b.date).getTime() - new Date(a.createdAt || a.date).getTime());
};

export const registerUser = (user: UserProfile): UserProfile => {
  const users = getUsers();
  if (users.some(u => u.email.toLowerCase() === user.email.toLowerCase())) {
    throw new Error('An account with this email already exists.');
  }
  user.id = user.id || crypto.randomUUID();
  user.isAdmin = false;
  user.role = 'teacher';
  user.teacherCode = generateTeacherCode();
  users.push(user);
  localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));
  localStorage.setItem(SESSION_KEY, JSON.stringify(user));
  return user;
};

