  initialMode?: 'signin' | 'signup';
}

type AuthView = 'signin' | 'signup' | 'forgot' | 'school_signup' | 'verify_pending';

const Login: React.FC<Props> = ({ onLogin, onStudentLoginClick, initialMode = 'signin' }) => {
  const [view, setView] = useState<AuthView>(initialMode);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [pendingEmail, setPendingEmail] = useState('');

  // Login Data
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPass, setLoginPass] = useState('');

  // Teacher Signup Data
  const [formData, setFormData] = useState({
    email: '',
    name: '',
    school: '',
    phone: '',
    password: ''
  });

  // School Signup Data
  const [schoolData, setSchoolData] = useState({
      name: '',
      email: '',
      phone: '',
      address: '',
      password: '',
      confirmPassword: ''
  });

  const handleError = (err: any) => {
      console.error(err);
      if (err.code === 'auth/email-already-in-use') {
          setError("User already exists. Please sign in");
      } else if (err.code === 'auth/invalid-credential' || err.code === 'auth/wrong-password' || err.code === 'auth/user-not-found') {
          setError("Email or password is incorrect");
      } else {
          setError(err.message || "An unexpected error occurred.");
      }
  };

  const handleSignUp = async (e: React.FormEvent) => {
      e.preventDefault();
      setError(null);
      setLoading(true);
      try {
          const userCredential = await createUserWithEmailAndPassword(auth, formData.email, formData.password);
          const user = userCredential.user;

          await sendEmailVerification(user);

          // Save metadata locally
          saveUserMetadata({
              email: formData.email,
              name: formData.name,
              school: formData.school,
              phone: formData.phone,
              role: 'teacher'
          });

          setPendingEmail(formData.email);
          await signOut(auth); // Sign out so they must verify and log in
          setView('verify_pending');
      } catch (err: any) {
          handleError(err);
      } finally {
          setLoading(false);
      }
  };

  const handleSchoolSignUp = async (e: React.FormEvent) => {
      e.preventDefault();
      if (schoolData.password !== schoolData.confirmPassword) {
          setError("Passwords do not match.");
          return;
      }
      setError(null);
      setLoading(true);
      try {
          const userCredential = await createUserWithEmailAndPassword(auth, schoolData.email, schoolData.password);
          const user = userCredential.user;

          await sendEmailVerification(user);

          registerSchool(schoolData.name, schoolData.email, schoolData.password, schoolData.phone, schoolData.address);

          setPendingEmail(schoolData.email);
          await signOut(auth);
          setView('verify_pending');
      } catch (err: any) {
          handleError(err);
      } finally {
          setLoading(false);
      }
  };

  const handleLoginSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);
    try {
        const userCredential = await signInWithEmailAndPassword(auth, loginEmail, loginPass);
        const user = userCredential.user;

        if (!user.emailVerified) {
            setPendingEmail(user.email || loginEmail);
            await signOut(auth);
            setView('verify_pending');
            setLoading(false);
            return;
        }

        // Get stored profile data or create basic one
        const metadata = getLocalUserMetadata(user.email!);
        const profile: UserProfile = metadata || {
            email: user.email!,
            name: user.displayName || 'Teacher',
            school: 'Independent',
            phone: '',
            role: 'teacher'
        };

        loginUser(profile);
        onLogin(profile);
    } catch (err: any) {
        handleError(err);
    } finally {
        setLoading(false);
    }
  };

  return (
    <div className="min-h-[80vh] flex flex-col justify-center items-center p-4 bg-gray-50">
      <div className="max-w-md w-full bg-white rounded-xl shadow-xl border border-gray-200 overflow-hidden">

        {view === 'verify_pending' ? (
          <div className="p-8 text-center animate-fade-in">
              <div className="mx-auto bg-blue-100 w-20 h-20 rounded-full flex items-center justify-center mb-6">
                <MailCheck className="w-10 h-10 text-blue-600" />
              </div>
              <h2 className="text-2xl font-bold text-slate-800 mb-4">Verify Your Email</h2>
              <p className="text-slate-600 mb-8 leading-relaxed">
                We have sent you a verification email to <span className="font-bold text-indigo-600">{pendingEmail}</span>. Please verify it and log in.
              </p>
              <button 
                onClick={() => setView('signin')}
                className="w-full flex justify-center items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 px-4 rounded-lg transition-colors shadow-md"
              >
                Login
              </button>
          </div>
        ) : (
          <>
            <div className="bg-slate-900 px-6 py-8 text-center text-white">
              <div className="mx-auto bg-slate-800 w-16 h-16 rounded-full flex items-center justify-center mb-4 shadow-inner border border-slate-700">
                {view === 'signup' ? <User className="w-8 h-8 text-teal-400" /> : 
                 view === 'school_signup' ? <Building2 className="w-8 h-8 text-indigo-400" /> :
                 view === 'forgot' ? <Key className="w-8 h-8 text-teal-400" /> :
                 <LogIn className="w-8 h-8 text-teal-400" />}
              </div>
              <h2 className="text-2xl font-bold">
                  {view === 'signup' ? "Teacher Registration" : 
                   view === 'school_signup' ? "Register School" :
                   view === 'forgot' ? "Retrieve Password" : 
                   "Welcome Back"}
              </h2>
              <p className="text-slate-400 mt-2 text-sm">
                {view === 'signup' ? "Join as an independent teacher" : 
                 view === 'school_signup' ? "Create a school account to manage teachers" :
                 view === 'forgot' ? "Enter your email for instructions" :
                 "Sign in to continue planning"}
              </p>
            </div>

            <div className="p-8">
                {error && (
                    <div className="mb-6 bg-red-50 text-red-600 p-3 rounded-md text-sm border border-red-200 flex items-start gap-2">
                        <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
                        <span>{error}</span>
                    </div>
                )}

                {view === 'signin' && (
                    <form onSubmit={handleLoginSubmit} className="space-y-5">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Email Address</label>
                            <div className="relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                    <Mail className="h-5 w-5 text-gray-400" />
                                </div>
                                <input
                                    type="email"
                                    required
                                    value={loginEmail}
                                    onChange={e => setLoginEmail(e.target.value)}
                                    className="pl-10 w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border"
                                    placeholder="name@school.edu"
                                />
                            </div>
                        </div>
                        <div>
                            <div className="flex justify-between items-center mb-1">
                                <label className="block text-sm font-medium text-gray-700">Password</label>
                                <button type="button" onClick={() => setView('forgot')} className="text-xs text-teal-600 hover:text-teal-800">Forgot Password?</button>
                            </div>
                            <div className="relative">
                                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                                    <Lock className="h-5 w-5 text-gray-400" />
                                </div>
                                <input
                                    type="password"
                                    required
                                    value={loginPass}
                                    onChange={e => setLoginPass(e.target.value)}
                                    className="pl-10 w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 border"
                                    placeholder="••••••••"
                                />
                            </div>
                        </div>
                        <button 
                            type="submit" 
                            disabled={loading}
                            className="w-full flex justify-center items-center gap-2 bg-teal-600 hover:bg-teal-700 text-white font-bold py-3 px-4 rounded-lg transition-colors shadow-md mt-6 disabled:opacity-50"
                        >
                            {loading ? <Loader2 className="w-5 h-5 animate-spin" /> : "Sign In"} <ArrowRight className="w-4 h-4" />
                        </button>
                    </form>
                )}

                {view === 'forgot' && (
                    <div className="space-y-4">
                        <p className="text-sm text-slate-600">Please contact support at macdonaldmuhiga@gmail.com to reset your password or follow the Firebase password reset flow if configured.</p>
                        <button onClick={() => setView('signin')} className="w-full text-sm text-teal-600 font-bold">Back to Login</button>
                    </div>
                )}

                {view === 'signup' && (
                    <form onSubmit={handleSignUp} className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Official Name</label>
                            <input type="text" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="Full Name" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">School Name</label>
                            <input type="text" required value={formData.school} onChange={e => setFormData({...formData, school: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="School Name" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Email Address</label>
                            <input type="email" required value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="Email" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Phone</label>
                            <input type="tel" required value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="Phone" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Password</label>
                            <input type="password" required value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="••••••••" minLength={6} />
                        </div>
                        <button 
                            type="submit" 
                            disabled={loading}
                            className="w-full bg-teal-600 hover:bg-teal-700 text-white font-bold py-3 px-4 rounded-lg transition-colors shadow-md mt-4 disabled:opacity-50"
                        >
                            {loading ? <Loader2 className="w-5 h-5 animate-spin mx-auto" /> : "Create Teacher Account"}
                        </button>
                    </form>
                )}

                {view === 'school_signup' && (
                    <form onSubmit={handleSchoolSignUp} className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">School Name</label>
                            <input type="text" required value={schoolData.name} onChange={e => setSchoolData({...schoolData, name: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="School Name" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Admin Email (Login)</label>
                            <input type="email" required value={schoolData.email} onChange={e => setSchoolData({...schoolData, email: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="admin@school.com" />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Password</label>
                                <input type="password" required value={schoolData.password} onChange={e => setSchoolData({...schoolData, password: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="••••••••" minLength={6} />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Confirm</label>
                                <input type="password" required value={schoolData.confirmPassword} onChange={e => setSchoolData({...schoolData, confirmPassword: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="••••••••" />
                            </div>
                        </div>
                        <button 
                            type="submit" 
                            disabled={loading}
                            className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 px-4 rounded-lg transition-colors shadow-md mt-4 disabled:opacity-50"
                        >
                            {loading ? <Loader2 className="w-5 h-5 animate-spin mx-auto" /> : "Register School"}
                        </button>
                    </form>
                )}

                <div className="mt-6 text-center space-y-4">
                    {view === 'signin' && (
                        <>
                            <p className="text-sm text-gray-600">
                                Don't have an account?
                                <button onClick={() => setView('signup')} className="ml-2 text-teal-600 hover:text-teal-800 font-semibold focus:outline-none">
                                    Register as Teacher
                                </button>
                            </p>
                            <button onClick={() => setView('school_signup')} className="text-sm text-indigo-600 hover:text-indigo-800 font-semibold flex items-center justify-center gap-1 mx-auto">
                                <Building2 className="w-4 h-4"/> Register a School
                            </button>
                        </>
                    )}

                    {(view === 'signup' || view === 'school_signup') && (
                        <p className="text-sm text-gray-600">
                            Already have an account?
                            <button onClick={() => setView('signin')} className="ml-2 text-teal-600 hover:text-teal-800 font-semibold focus:outline-none">
                                Sign In
                            </button>
                        </p>
                    )}

                    <div className="pt-4 border-t border-gray-100">
                        <button 
                            onClick={onStudentLoginClick}
                            className="inline-flex items-center gap-2 text-sm text-slate-500 hover:text-slate-800 font-medium px-4 py-2 rounded-full bg-slate-50 hover:bg-slate-100 transition-colors"
                        >
                            <GraduationCap className="w-4 h-4" />
                            I am a Student
                        </button>
                    </div>
                </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import LessonGenerator from './components/LessonGenerator';
import LessonPlanDisplay from './components/LessonPlanDisplay';
import Login from './components/Login';
import Dashboard from './components/Dashboard';
import SchoolDashboard from './components/SchoolDashboard';
import LandingPage from './components/LandingPage';
import SavedPlans from './components/SavedPlans';
import NewsSection from './components/NewsSection';
import AdminDashboard from './components/AdminDashboard';
import StudentPortal from './components/StudentPortal';
import MwalimuBot from './components/MwalimuBot';
import { LessonPlanData, UserProfile } from './types';
import { LayoutDashboard, FileText, LogOut, Save, Newspaper, Shield, Building2 } from 'lucide-react';
import { getCurrentUser, logoutUser, updateUserProfile, loginUser, getLocalUserMetadata } from './services/storageService';
import { auth } from './services/firebase';
import { onAuthStateChanged, signOut } from 'firebase/auth';

function App() {
  const [user, setUser] = useState<UserProfile | null>(() => getCurrentUser());
  const [generatedPlan, setGeneratedPlan] = useState<LessonPlanData | null>(null);
  const [currentView, setCurrentView] = useState<'landing' | 'auth' | 'generator' | 'dashboard' | 'school_dashboard' | 'saved' | 'news' | 'admin' | 'student'>('landing');
  const [authMode, setAuthMode] = useState<'signin' | 'signup'>('signup');

  // Initial routing based on user state
  useEffect(() => {
    if (user) {
        if (user.role === 'school_admin') setCurrentView('school_dashboard');
        else if (user.role === 'system_admin' || user.isAdmin) setCurrentView('admin');
        else setCurrentView('generator');
    } else {
        setCurrentView('landing');
    }
  }, []);

  // Firebase Auth State Listener
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (firebaseUser) => {
        if (firebaseUser && firebaseUser.emailVerified) {
            const metadata = getLocalUserMetadata(firebaseUser.email!);
            const profile = metadata || {
                email: firebaseUser.email!,
                name: firebaseUser.displayName || 'Teacher',
                school: 'Independent',
                phone: '',
                role: 'teacher'
            };
            setUser(profile);
            loginUser(profile);
        } else {
            // Unverified or not logged in - don't force landing if they are midway through auth
        }
    });
    return () => unsubscribe();
  }, []);

  const handleLogin = (profile: UserProfile) => {
    setUser(profile);
    if (profile.role === 'school_admin') setCurrentView('school_dashboard');
    else if (profile.role === 'system_admin' || profile.isAdmin) setCurrentView('admin');
    else setCurrentView('generator');
  };

  const handleUpdateProfile = (profile: UserProfile) => {
    updateUserProfile(profile);
    setUser(profile);
  };

  const handleLogout = async () => {
    await signOut(auth);
    logoutUser();
    setUser(null);
    setGeneratedPlan(null);
    setCurrentView('landing');
  };

  const navigateToAuth = (mode: 'signin' | 'signup') => {
      setAuthMode(mode);
      setCurrentView('auth');
  };

  const handleHomeClick = () => {
    if (currentView === 'student') return;
    if (user) {
        if (user.role === 'school_admin') setCurrentView('school_dashboard');
        else if (user.role === 'system_admin' || user.isAdmin) setCurrentView('admin');
        else {
            setCurrentView('generator');
            setGeneratedPlan(null);
        }
    } else {
        setCurrentView('landing');
        setGeneratedPlan(null);
    }
  };

  if (currentView === 'student') {
      return (
          <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
              <Header onHomeClick={() => setCurrentView('landing')} />
              <StudentPortal />
          </div>
      );
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col font-sans">
      <Header onHomeClick={handleHomeClick} />
      <main className="flex-1 relative">
        {currentView === 'landing' && !user && (
            <LandingPage 
                onStart={() => navigateToAuth('signup')} 
                user={user}
                onLogout={handleLogout}
                onPlanGenerated={(plan) => setGeneratedPlan(plan)} 
            />
        )}
        {currentView === 'auth' && !user && (
            <Login 
                onLogin={handleLogin} 
                initialMode={authMode} 
                onStudentLoginClick={() => setCurrentView('student')}
            />
        )}
        {user && (
            <div className={`container mx-auto px-4 py-8 md:py-12 ${currentView === 'admin' || currentView === 'school_dashboard' ? 'max-w-full px-0 py-0' : 'max-w-5xl'}`}>
                <div className={`flex flex-wrap gap-4 justify-between items-center mb-8 border-b border-gray-200 pb-4 no-print ${['admin', 'school_dashboard'].includes(currentView) ? 'px-4 pt-4' : ''}`}>
                    <div className="flex gap-2 md:gap-4 overflow-x-auto pb-2 md:pb-0">
                        {(user.role === 'system_admin' || user.isAdmin) ? (
                            <button onClick={() => setCurrentView('admin')} className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'admin' ? 'bg-slate-800 text-white' : 'text-gray-600 hover:bg-gray-100'}`}>
                                <Shield className="w-4 h-4" /> Admin Panel
                            </button>
                        ) : user.role === 'school_admin' ? (
                            <button onClick={() => setCurrentView('school_dashboard')} className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'school_dashboard' ? 'bg-indigo-600 text-white' : 'text-gray-600 hover:bg-gray-100'}`}>
                                <Building2 className="w-4 h-4" /> School Portal
                            </button>
                        ) : (
                            <>
                                <button onClick={() => { setCurrentView('generator'); setGeneratedPlan(null); }} className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'generator' && !generatedPlan ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}>
                                    <FileText className="w-4 h-4" /> Planner
                                </button>
                                <button onClick={() => { setCurrentView('saved'); setGeneratedPlan(null); }} className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'saved' ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}>
                                    <Save className="w-4 h-4" /> Generated Plans
                                </button>
                                <button onClick={() => { setCurrentView('news'); setGeneratedPlan(null); }} className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'news' ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}>
                                    <Newspaper className="w-4 h-4" /> News
                                </button>
                                <button onClick={() => { setCurrentView('dashboard'); setGeneratedPlan(null); }} className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-md font-medium transition-colors text-sm md:text-base ${currentView === 'dashboard' ? 'bg-teal-100 text-teal-800' : 'text-gray-600 hover:bg-gray-100'}`}>
                                    <LayoutDashboard className="w-4 h-4" /> Dashboard
                                </button>
                            </>
                        )}
                    </div>
                    <div className="flex items-center gap-4">
                        <span className="text-sm text-gray-500 hidden md:inline">{user.school ? <span className="font-bold text-indigo-600 mr-2">{user.school}</span> : ''}{user.name}</span>
                        <button onClick={handleLogout} className="flex items-center gap-2 px-3 py-1.5 text-sm text-red-600 hover:bg-red-50 rounded-md transition-colors">
                            <LogOut className="w-4 h-4" /> Logout
                        </button>
                    </div>
                </div>
                {currentView === 'admin' ? (<AdminDashboard />) : 
                 currentView === 'school_dashboard' ? (<SchoolDashboard profile={user} />) : 
                 currentView === 'dashboard' ? (<Dashboard profile={user} onUpdate={handleUpdateProfile} />) : 
                 currentView === 'saved' ? (<SavedPlans onSelectPlan={(plan) => { setGeneratedPlan(plan); setCurrentView('generator'); }} />) : 
                 currentView === 'news' ? (<NewsSection />) : 
                 generatedPlan ? (<LessonPlanDisplay plan={generatedPlan} onBack={() => setGeneratedPlan(null)} />) : (
                    <div className="animate-fade-in-up">
                        <div className="text-center mb-8 no-print">
                            <h2 className="text-2xl font-semibold text-gray-800">Create Your Lesson Plan</h2>
                            <p className="text-gray-600 mt-2">Fill in the details below to generate a comprehensive, curriculum-aligned lesson plan in seconds.</p>
                        </div>
                        <LessonGenerator userProfile={user} onPlanGenerated={setGeneratedPlan} />
                    </div>
                )}
            </div>
        )}
        {!user && generatedPlan && (
             <div className="container mx-auto px-4 py-8 md:py-12 max-w-5xl animate-fade-in">
                <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4 mb-6 flex justify-between items-center">
                    <p className="text-sm text-yellow-700">You are viewing this plan as a guest. <strong>Sign in</strong> to save it to your account.</p>
                    <button onClick={() => navigateToAuth('signin')} className="text-sm font-medium text-yellow-800 underline hover:text-yellow-900">Sign In Now</button>
                </div>
                <LessonPlanDisplay plan={generatedPlan} onBack={() => { setGeneratedPlan(null); setCurrentView('landing'); }} />
            </div>
        )}
        {user && !user.isAdmin && user.role !== 'school_admin' && <MwalimuBot />}
      </main>
      <footer className="bg-slate-900 text-slate-400 py-8 text-center text-sm no-print mt-auto">
        <p>© {new Date().getFullYear()} MwalimuPlanner. All Rights Reserved.</p>
        <p className="mt-1">Empowering Kenyan Educators.</p>
      </footer>
    </div>
  );
}

export default App;

import { LessonPlanData, UserProfile, Classroom, Assignment, StudentResult, Student, SharedNote, ForumPost, ForumReply, DirectMessage, AppNotification, Textbook, School, LessonPlanComment } from '../types';
import { db } from './firebase';
import { doc, setDoc } from "firebase/firestore";

const PLANS_STORAGE_KEY = 'mwalimu_saved_plans';
const USERS_DB_KEY = 'mwalimu_users_db';
const SCHOOLS_DB_KEY = 'mwalimu_schools_db';
const SESSION_KEY = 'mwalimu_current_session';
const CLASSROOMS_STORAGE_KEY = 'mwalimu_classrooms';
const ASSIGNMENTS_STORAGE_KEY = 'mwalimu_assignments';
const RESULTS_STORAGE_KEY = 'mwalimu_results';
const MESSAGES_STORAGE_KEY = 'mwalimu_direct_messages';
const NOTIFICATIONS_STORAGE_KEY = 'mwalimu_notifications';

// --- Firebase Sync Logic ---

export const syncPlansToFirebase = async (): Promise<void> => {
    const user = getCurrentUser();
    if (!user) return;

    const localPlans = getSavedPlans();

    try {
        for (const plan of localPlans) {
            if (plan.id) {
                const planRef = doc(db, "lesson_plans", plan.id);
                await setDoc(planRef, {
                    ...plan,
                    syncedAt: new Date().toISOString()
                }, { merge: true });
            }
        }
    } catch (error) {
        console.error("Error syncing to Firebase:", error);
    }
};

// --- Notifications System ---

export const getNotifications = (userId: string): AppNotification[] => {
    const data = localStorage.getItem(NOTIFICATIONS_STORAGE_KEY);
    const all: AppNotification[] = data ? JSON.parse(data) : [];
    return all.filter(n => n.userId === userId).sort((a,b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
};

export const markNotificationRead = (notificationId: string): void => {
    const data = localStorage.getItem(NOTIFICATIONS_STORAGE_KEY);
    let all: AppNotification[] = data ? JSON.parse(data) : [];
    all = all.map(n => n.id === notificationId ? { ...n, read: true } : n);
    localStorage.setItem(NOTIFICATIONS_STORAGE_KEY, JSON.stringify(all));
};

const createNotification = (userId: string, type: 'message' | 'assignment' | 'forum' | 'system', title: string, message: string, linkTo?: string) => {
    const data = localStorage.getItem(NOTIFICATIONS_STORAGE_KEY);
    const all: AppNotification[] = data ? JSON.parse(data) : [];

    const newNotif: AppNotification = {
        id: crypto.randomUUID(),
        userId,
        type,
        title,
        message,
        read: false,
        timestamp: new Date().toISOString(),
        linkTo
    };

    all.push(newNotif);
    localStorage.setItem(NOTIFICATIONS_STORAGE_KEY, JSON.stringify(all));
};

// --- Direct Messages ---

export const sendDirectMessage = (msg: DirectMessage): void => {
    const data = localStorage.getItem(MESSAGES_STORAGE_KEY);
    const allMessages: DirectMessage[] = data ? JSON.parse(data) : [];
    allMessages.push(msg);
    localStorage.setItem(MESSAGES_STORAGE_KEY, JSON.stringify(allMessages));

    createNotification(
        msg.receiverId,
        'message',
        `New message from ${msg.senderName}`,
        msg.content.substring(0, 50) + (msg.content.length > 50 ? '...' : '')
    );
};

export const getDirectMessages = (userId: string): DirectMessage[] => {
    const data = localStorage.getItem(MESSAGES_STORAGE_KEY);
    const allMessages: DirectMessage[] = data ? JSON.parse(data) : [];
    return allMessages.filter(m => m.senderId === userId || m.receiverId === userId)
        .sort((a,b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());
};

export const markMessagesRead = (senderId: string, receiverId: string): void => {
    const data = localStorage.getItem(MESSAGES_STORAGE_KEY);
    let allMessages: DirectMessage[] = data ? JSON.parse(data) : [];
    allMessages = allMessages.map(m => 
        (m.senderId === senderId && m.receiverId === receiverId) ? { ...m, read: true } : m
    );
    localStorage.setItem(MESSAGES_STORAGE_KEY, JSON.stringify(allMessages));
};

// --- Forum System ---

export const createForumPost = (classId: string, post: ForumPost): void => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];
    const idx = allClassrooms.findIndex(c => c.id === classId);

    if (idx !== -1) {
        if (!allClassrooms[idx].forumPosts) allClassrooms[idx].forumPosts = [];
        allClassrooms[idx].forumPosts.unshift(post);
        localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));

        const currentUser = getCurrentUser();
        if (currentUser && (currentUser.email === allClassrooms[idx].userId || currentUser.email === allClassrooms[idx].teacherId)) {
             allClassrooms[idx].students.forEach(s => {
                 createNotification(s.code, 'forum', 'New Class Discussion', post.title);
             });
        }
    }
};

export const addForumReply = (classId: string, postId: string, reply: ForumReply): void => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];
    const classIdx = allClassrooms.findIndex(c => c.id === classId);

    if (classIdx !== -1) {
        const posts = allClassrooms[classIdx].forumPosts || [];
        const postIdx = posts.findIndex(p => p.id === postId);

        if (postIdx !== -1) {
            posts[postIdx].replies.push(reply);
            localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));
        }
    }
};

// --- Plan Management ---

export const savePlan = (plan: LessonPlanData): void => {
  const currentUser = getCurrentUser();
  if (!currentUser) return;

  const allPlans = getAllGlobalPlans();
  if (!plan.id) plan.id = crypto.randomUUID();
  if (!plan.createdAt) plan.createdAt = new Date().toISOString();
  plan.userId = currentUser.email;

  const existingIndex = allPlans.findIndex(p => p.id === plan.id);
  if (existingIndex >= 0) allPlans[existingIndex] = plan;
  else allPlans.unshift(plan);

  localStorage.setItem(PLANS_STORAGE_KEY, JSON.stringify(allPlans));
  syncPlansToFirebase().catch(() => {});
};

export const getSavedPlans = (): LessonPlanData[] => {
  const currentUser = getCurrentUser();
  if (!currentUser) return [];
  const data = localStorage.getItem(PLANS_STORAGE_KEY);
  const allPlans: LessonPlanData[] = data ? JSON.parse(data) : [];
  return allPlans.filter(plan => plan.userId === currentUser.email);
};

export const getAllGlobalPlans = (): LessonPlanData[] => {
  const data = localStorage.getItem(PLANS_STORAGE_KEY);
  return data ? JSON.parse(data) : [];
};

export const deletePlan = (id: string): void => {
  const allPlans = getAllGlobalPlans();
  const updatedPlans = allPlans.filter(p => p.id !== id);
  localStorage.setItem(PLANS_STORAGE_KEY, JSON.stringify(updatedPlans));
};

export const addCommentToPlan = (planId: string, comment: LessonPlanComment): void => {
    const allPlans = getAllGlobalPlans();
    const planIndex = allPlans.findIndex(p => p.id === planId);
    if (planIndex !== -1) {
        if (!allPlans[planIndex].adminComments) allPlans[planIndex].adminComments = [];
        allPlans[planIndex].adminComments!.push(comment);
        localStorage.setItem(PLANS_STORAGE_KEY, JSON.stringify(allPlans));
        const plan = allPlans[planIndex];
        if (plan.userId) createNotification(plan.userId, 'system', 'Admin Feedback', `New feedback on lesson plan: ${plan.topic}`);
    }
};

// --- Classroom Management ---

const generateStudentCode = (): string => {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let result = '';
  for (let i = 0; i < 6; i++) result += chars.charAt(Math.floor(Math.random() * chars.length));
  return result;
};

const isCodeUnique = (code: string, allClassrooms: Classroom[]): boolean => {
  for (const cls of allClassrooms) {
    if (cls.students.some(s => s.code === code)) return false;
  }
  return true;
};

export const createClassroom = (grade: string, stream: string, roll: number, teacherId?: string): Classroom => {
  const currentUser = getCurrentUser();
  if (!currentUser) throw new Error("Must be logged in.");
  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];
  const students: Student[] = [];
  for (let i = 1; i <= roll; i++) {
    let code = generateStudentCode();
    while (!isCodeUnique(code, allClassrooms)) code = generateStudentCode();
    students.push({ index: i, code: code });
  }
  const newClassroom: Classroom = {
    id: crypto.randomUUID(),
    userId: currentUser.email,
    schoolId: currentUser.schoolId,
    teacherId: teacherId || (currentUser.role === 'teacher' ? currentUser.email : undefined),
    grade, stream, subjects: [], students, sharedNotes: [], forumPosts: [], textbooks: []
  };
  allClassrooms.push(newClassroom);
  localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));
  return newClassroom;
};

export const addSubjectToClassroom = (classId: string, subject: string): void => {
  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];
  const clsIndex = allClassrooms.findIndex(c => c.id === classId);
  if (clsIndex !== -1 && !allClassrooms[clsIndex].subjects.includes(subject)) {
    allClassrooms[clsIndex].subjects.push(subject);
    localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));
  }
};

export const removeSubjectFromClassroom = (classId: string, subject: string): void => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];
    const clsIndex = allClassrooms.findIndex(c => c.id === classId);
    if (clsIndex !== -1) {
      allClassrooms[clsIndex].subjects = allClassrooms[clsIndex].subjects.filter(s => s !== subject);
      localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));
    }
};

export const shareNoteToClassroom = (classId: string, note: SharedNote): void => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];
    const clsIndex = allClassrooms.findIndex(c => c.id === classId);
    if (clsIndex !== -1) {
        if (!allClassrooms[clsIndex].sharedNotes) allClassrooms[clsIndex].sharedNotes = [];
        allClassrooms[clsIndex].sharedNotes.push(note);
        localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));
        allClassrooms[clsIndex].students.forEach(s => createNotification(s.code, 'message', 'New Note Shared', `Notes for ${note.title} have been shared.`));
    }
};

export const uploadTextbookToClassroom = (classId: string, textbook: Textbook): void => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];
    const clsIndex = allClassrooms.findIndex(c => c.id === classId);
    if (clsIndex !== -1) {
        if(!allClassrooms[clsIndex].textbooks) allClassrooms[clsIndex].textbooks = [];
        allClassrooms[clsIndex].textbooks.push(textbook);
        localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));
        allClassrooms[clsIndex].students.forEach(s => createNotification(s.code, 'message', 'New Textbook', `A new textbook: ${textbook.title} has been uploaded.`));
    }
};

export const getStudentNotes = (classId: string): SharedNote[] => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];
    const cls = allClassrooms.find(c => c.id === classId);
    return cls && cls.sharedNotes ? cls.sharedNotes.sort((a,b) => new Date(b.dateShared).getTime() - new Date(a.dateShared).getTime()) : [];
};

export const getClassrooms = (): Classroom[] => {
  const currentUser = getCurrentUser();
  if (!currentUser) return [];
  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];
  if (currentUser.role === 'school_admin' && currentUser.schoolId) {
    return allClassrooms.filter(c => c.schoolId === currentUser.schoolId);
  }
  return allClassrooms.filter(c => c.userId === currentUser.email || c.teacherId === currentUser.email);
};

export const getAllClassroomsGlobal = (): Classroom[] => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
};

export const deleteClassroom = (id: string): void => {
  const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
  const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];
  localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms.filter(c => c.id !== id)));
};

export const addStudentsToClassroom = (classId: string, count: number): void => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];
    const clsIndex = allClassrooms.findIndex(c => c.id === classId);
    if (clsIndex !== -1) {
        const currentCount = allClassrooms[clsIndex].students.length;
        for (let i = 1; i <= count; i++) {
            let code = generateStudentCode();
            while (!isCodeUnique(code, allClassrooms)) code = generateStudentCode();
            allClassrooms[clsIndex].students.push({ index: currentCount + i, code: code });
        }
        localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));
    }
};

export const deleteStudentFromClassroom = (classId: string, studentCode: string): void => {
    const data = localStorage.getItem(CLASSROOMS_STORAGE_KEY);
    const allClassrooms: Classroom[] = data ? JSON.parse(data) : [];
    const clsIndex = allClassrooms.findIndex(c => c.id === classId);
    if (clsIndex !== -1) {
        allClassrooms[clsIndex].students = allClassrooms[clsIndex].students.filter(s => s.code !== studentCode);
        localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(allClassrooms));
    }
};

