export const getSchoolTeachers = (schoolId: string): UserProfile[] => {
    return getAllUsers().filter(u => u.schoolId === schoolId && u.role === 'teacher');
};

export const getTeacherPlans = (teacherEmail: string): LessonPlanData[] => {
    return getAllGlobalPlans().filter(p => p.userId === teacherEmail);
};

export const linkTeacherToSchool = (schoolId: string, teacherCode: string): UserProfile => {
  const users = getAllUsers();
  const idx = users.findIndex(u => u.teacherCode === teacherCode);
  if (idx === -1) throw new Error("Invalid Teacher Code.");
  users[idx].schoolId = schoolId;
  localStorage.setItem(USERS_DB_KEY, JSON.stringify(users));
  return users[idx];
};

