                                          managedClassroom.sharedNotes.forEach(note => {
                                              if (!groupedClassroomNotes[note.subject]) groupedClassroomNotes[note.subject] = [];
                                              groupedClassroomNotes[note.subject].push(note);
                                          });
                                          /**
                                           * Fixed argument type 'unknown' error by adding explicit type (subject: string)
                                           * to the map function.
                                           */
                                          return Object.keys(groupedClassroomNotes).map((subject: string) => {
                                              const subjectNotes = groupedClassroomNotes[subject];
                                              return (
