                                          const groupedClassroomNotes: Record<string, SharedNote[]> = {};
                                          // Fix: added explicit type for the forEach callback parameter to prevent 'unknown' issues
                                          managedClassroom.sharedNotes.forEach((note: SharedNote) => {
                                              if (!groupedClassroomNotes[note.subject]) groupedClassroomNotes[note.subject] = [];
                                              groupedClassroomNotes[note.subject].push(note);
                                          });
                                          // Fix: cast Object.keys result to string[] to resolve 'unknown' type assignment to subject in map callback
                                          return (Object.keys(groupedClassroomNotes) as string[]).map((subject: string) => {
                                              const subjectNotes = groupedClassroomNotes[subject];
                                              return (
                                                  <div key={subject} className="mb-6">
