                      <button onClick={() => setSelectedTeacher(null)} className="hover:bg-indigo-800 p-2 rounded-full transition-colors">
                          <ArrowLeft className="w-6 h-6" />
                      </button>
                      <div>
                          <h1 className="text-2xl font-bold">{selectedTeacher.name}</h1>
                          <p className="text-indigo-200 text-sm">{selectedTeacher.email} • {selectedTeacher.phone}</p>
                      </div>
                  </div>
              </div>

              <div className="max-w-7xl mx-auto px-4 mt-8 grid grid-cols-1 lg:grid-cols-3 gap-8">
                  {/* Left Column: Stats & Classes */}
                  <div className="space-y-8">
