                                        <th className="px-6 py-3 text-right no-print">Actions</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {classrooms.find(c => c.id === selectedClassId)?.students.map(s => (
                                        <tr key={s.code} className="hover:bg-slate-50">
                                            <td className="px-6 py-3 font-mono text-slate-500">#{s.index}</td>
                                            <td className="px-6 py-3 font-mono font-bold text-indigo-700 tracking-wider text-base">{s.code}</td>
                                            <td className="px-6 py-3">
                                                {s.name ? <span className="font-medium text-slate-900">{s.name}</span> : <span className="text-slate-400 italic">Not set</span>}
                                            </td>
                                            <td className="px-6 py-3 text-right no-print flex gap-2 justify-end">
                                                <button onClick={() => copyToClipboard(s.code)} className="text-indigo-600 hover:underline text-xs font-bold">Copy Code</button>
                                                <button onClick={() => handleDeleteStudent(selectedClassId, s.code)} className="text-red-500 hover:bg-red-50 p-1 rounded transition-colors"><Trash2 className="w-4 h-4" /></button>
