                      <div className="flex-1 overflow-y-auto">
                          {Array.from(new Set(messages.filter(m => !m.isFromTeacher).map(m => m.senderId))).map(studentId => {
                              const lastMsg = messages.filter(m => m.senderId === studentId || m.receiverId === studentId).pop();
                              const unread = messages.filter(m => m.senderId === studentId && !m.read).length;
                              const studentName = lastMsg?.senderId === studentId ? lastMsg?.senderName : (messages.find(m => m.senderId === studentId)?.senderName || studentId);
                              return (<div key={studentId} onClick={() => handleSelectThread(studentId)} className={`p-4 border-b border-gray-100 hover:bg-slate-50 cursor-pointer transition-colors ${selectedThread === studentId ? 'bg-blue-50' : ''}`}><div className="flex justify-between items-start mb-1"><h4 className={`text-sm ${unread > 0 ? 'font-bold text-slate-900' : 'font-medium text-slate-700'}`}>{studentName}</h4><span className="text-[10px] text-gray-400">{lastMsg ? new Date(lastMsg.timestamp).toLocaleDateString() : ''}</span></div><p className={`text-xs truncate ${unread > 0 ? 'font-bold text-slate-800' : 'text-gray-500'}`}>{lastMsg?.isFromTeacher ? 'You: ' : ''}{lastMsg?.content}</p>{unread > 0 && <span className="inline-block bg-red-500 text-white text-[10px] px-2 rounded-full mt-1">{unread}</span>}</div>);
                          })}
                      </div>
                  </div>
                  <div className={`flex-1 flex flex-col ${!selectedThread ? 'hidden md:flex' : 'flex'}`}>
                      {selectedThread ? (<><div className="p-4 border-b border-gray-200 bg-white flex justify-between items-center"><div className="flex items-center gap-2"><button onClick={() => setSelectedThread(null)} className="md:hidden text-gray-500"><ArrowLeft className="w-5 h-5"/></button><div><h3 className="font-bold text-gray-800">{messages.find(m => m.senderId === selectedThread || m.receiverId === selectedThread)?.senderName || 'Student'}</h3><p className="text-xs text-gray-500 text-teal-600 font-mono">{selectedThread}</p></div></div></div><div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50">{messages.filter(m => m.senderId === selectedThread || m.receiverId === selectedThread).map(msg => (<div key={msg.id} className={`flex ${msg.isFromTeacher ? 'justify-end' : 'justify-start'}`}><div className={`max-w-[70%] rounded-xl p-3 text-sm shadow-sm ${msg.isFromTeacher ? 'bg-blue-600 text-white rounded-br-none' : 'bg-white text-gray-800 border border-gray-200 rounded-bl-none'}`}><p>{msg.content}</p><p className={`text-[10px] mt-1 text-right ${msg.isFromTeacher ? 'text-blue-200' : 'text-gray-400'}`}>{new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p></div></div>))}</div><div className="p-4 border-t border-gray-200 bg-white"><div className="flex gap-2"><input type="text" className="flex-1 border border-gray-300 rounded-lg px-4 py-2 text-sm focus:outline-none focus:border-teal-500" placeholder="Type reply..." value={replyText} onChange={e => setReplyText(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleReplyToStudent(selectedThread!, messages.find(m=>m.senderId===selectedThread)?.senderName || 'Student')} /><button onClick={() => handleReplyToStudent(selectedThread!, messages.find(m=>m.senderId===selectedThread)?.senderName || 'Student')} disabled={!replyText.trim()} className="bg-blue-600 text-white p-2 rounded-lg hover:bg-blue-700 disabled:opacity-50"><Send className="w-5 h-5" /></button></div></div></>) : (<div className="flex-1 flex items-center justify-center text-gray-400 flex-col"><MessageCircle className="w-12 h-12 mb-2 opacity-20" /><p>Select thread</p></div>)}
                  </div>
              </div>
