  const [loading, setLoading] = useState(false);
  const [pendingEmail, setPendingEmail] = useState('');

  // Login Data
  const [loginEmail, setLoginEmail] = useState('');
  const [loginPass, setLoginPass] = useState('');

  // Teacher Signup Data
  const [formData, setFormData] = useState({
    email: '',
    name: '',
    school: '',
    phone: '',
    password: ''
  });

  // School Signup Data
  const [schoolData, setSchoolData] = useState({
      name: '',
      email: '',
      phone: '',
      address: '',
      password: '',
      confirmPassword: ''
  });

  const handleError = (err: any) => {
      console.error(err);
      if (err.code === 'auth/email-already-in-use') {
          setError("User already exists. Please sign in");
      } else if (err.code === 'auth/invalid-credential' || err.code === 'auth/wrong-password' || err.code === 'auth/user-not-found') {
          setError("Email or password is incorrect");
      } else {
          setError(err.message || "An unexpected error occurred.");
      }
  };

  const handleSignUp = async (e: React.FormEvent) => {
      e.preventDefault();
      setError(null);
      setLoading(true);
      try {
          const userCredential = await createUserWithEmailAndPassword(auth, formData.email, formData.password);
          const user = userCredential.user;

          await sendEmailVerification(user);

          // Save metadata locally
          saveUserMetadata({
              email: formData.email,
              name: formData.name,
              school: formData.school,
              phone: formData.phone,
              role: 'teacher'
          });

          setPendingEmail(formData.email);
          await signOut(auth); // Sign out so they must verify and log in
          setView('verify_pending');
      } catch (err: any) {
          handleError(err);
      } finally {
          setLoading(false);
      }
  };

  const handleSchoolSignUp = async (e: React.FormEvent) => {
      e.preventDefault();
      if (schoolData.password !== schoolData.confirmPassword) {
          setError("Passwords do not match.");
          return;
      }
      setError(null);
      setLoading(true);
      try {
          const userCredential = await createUserWithEmailAndPassword(auth, schoolData.email, schoolData.password);
          const user = userCredential.user;

          await sendEmailVerification(user);

          registerSchool(schoolData.name, schoolData.email, schoolData.password, schoolData.phone, schoolData.address);

          setPendingEmail(schoolData.email);
          await signOut(auth);
          setView('verify_pending');
      } catch (err: any) {
          handleError(err);
      } finally {
          setLoading(false);
      }
  };

  const handleLoginSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    // Hardcoded System Admin Check
    const isSpecialAdmin = (loginEmail === 'admin@mwalimuplanner.com' || loginEmail === 'muhigalamacdie@gmail.com') && loginPass === 'admin123';

    if (isSpecialAdmin) {
        const adminProfile: UserProfile = {
            name: 'System Administrator',
            email: loginEmail,
            school: 'HQ',
            phone: '0000000000',
            isAdmin: true,
            role: 'system_admin'
        };
        loginUser(adminProfile);
        onLogin(adminProfile);
        setLoading(false);
        return;
    }

    try {
        const userCredential = await signInWithEmailAndPassword(auth, loginEmail, loginPass);
        const user = userCredential.user;

        if (!user.emailVerified) {
            setPendingEmail(user.email || loginEmail);
            await signOut(auth);
            setView('verify_pending');
            setLoading(false);
            return;
        }

        // Get stored profile data or create basic one
        const metadata = getLocalUserMetadata(user.email!);
        const profile: UserProfile = metadata || {
            email: user.email!,
            name: user.displayName || 'Teacher',
            school: 'Independent',
            phone: '',
            role: 'teacher'
        };

        loginUser(profile);
        onLogin(profile);
    } catch (err: any) {
        handleError(err);
    } finally {
        setLoading(false);
    }
  };

  return (
    <div className="min-h-[80vh] flex flex-col justify-center items-center p-4 bg-gray-50">
      <div className="max-w-md w-full bg-white rounded-xl shadow-xl border border-gray-200 overflow-hidden">

