                )}

                {view === 'signup' && (
                    <form onSubmit={handleSignUp} className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Official Name</label>
                            <input type="text" required value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="Full Name" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">School Name</label>
                            <input type="text" required value={formData.school} onChange={e => setFormData({...formData, school: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="School Name" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Email Address</label>
                            <input type="email" required value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="Email" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Phone</label>
                            <input type="tel" required value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="Phone" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Password</label>
                            <input type="password" required value={formData.password} onChange={e => setFormData({...formData, password: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="••••••••" minLength={6} />
                        </div>
                        <button 
                            type="submit" 
                            disabled={loading}
                            className="w-full bg-teal-600 hover:bg-teal-700 text-white font-bold py-3 px-4 rounded-lg transition-colors shadow-md mt-4 disabled:opacity-50"
                        >
                            {loading ? <Loader2 className="w-5 h-5 animate-spin mx-auto" /> : "Create Teacher Account"}
                        </button>
                    </form>
                )}

                {view === 'school_signup' && (
                    <form onSubmit={handleSchoolSignUp} className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">School Name</label>
                            <input type="text" required value={schoolData.name} onChange={e => setSchoolData({...schoolData, name: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="School Name" />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Admin Email (Login)</label>
                            <input type="email" required value={schoolData.email} onChange={e => setSchoolData({...schoolData, email: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="admin@school.com" />
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Password</label>
                                <input type="password" required value={schoolData.password} onChange={e => setSchoolData({...schoolData, password: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="••••••••" minLength={6} />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Confirm</label>
                                <input type="password" required value={schoolData.confirmPassword} onChange={e => setSchoolData({...schoolData, confirmPassword: e.target.value})} className="w-full rounded-md border-gray-300 p-2 px-3 border" placeholder="••••••••" />
                            </div>
                        </div>
                        <button 
                            type="submit" 
                            disabled={loading}
                            className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 px-4 rounded-lg transition-colors shadow-md mt-4 disabled:opacity-50"
                        >
                            {loading ? <Loader2 className="w-5 h-5 animate-spin mx-auto" /> : "Register School"}
                        </button>
                    </form>
                )}

                <div className="mt-6 text-center space-y-4">
                    {view === 'signin' && (
                        <>
                            <p className="text-sm text-gray-600">
                                Don't have an account?
                                <button onClick={() => setView('signup')} className="ml-2 text-teal-600 hover:text-teal-800 font-semibold focus:outline-none">
                                    Register as Teacher
                                </button>
                            </p>
                            <button onClick={() => setView('school_signup')} className="text-sm text-indigo-600 hover:text-indigo-800 font-semibold flex items-center justify-center gap-1 mx-auto">
                                <Building2 className="w-4 h-4"/> Register a School
                            </button>
                        </>
                    )}

                    {(view === 'signup' || view === 'school_signup') && (
                        <p className="text-sm text-gray-600">
                            Already have an account?
                            <button onClick={() => setView('signin')} className="ml-2 text-teal-600 hover:text-teal-800 font-semibold focus:outline-none">
                                Sign In
                            </button>
                        </p>
                    )}

                    <div className="pt-4 border-t border-gray-100">
                        <button 
                            onClick={onStudentLoginClick}
                            className="inline-flex items-center gap-2 text-sm text-slate-500 hover:text-slate-800 font-medium px-4 py-2 rounded-full bg-slate-50 hover:bg-slate-100 transition-colors"
                        >
                            <Target className="w-4 h-4" />
                            I am a Student
                        </button>
                    </div>
                </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect, useMemo } from 'react';
import { UserProfile, Classroom, Grade, Subject, Assignment, StudentResult, ForumPost, ForumReply, DirectMessage, AppNotification, Textbook, SharedNote } from '../types';
import { 
  User, School, Phone, Mail, Save, Plus, Trash2, 
  BookOpen, Users, Eye, X, Home, FileText, Settings, 
  Menu, Bell, ChevronDown, Check, ArrowLeft, MessageSquare, ChevronRight, MessageCircle, Send, Reply, ChevronLeft, Layers, Bookmark, Sparkles, Upload, FileText as FileIcon, Building2, Key, Clock
} from 'lucide-react';
import { 
    createClassroom, getClassrooms, deleteClassroom, addSubjectToClassroom, 
    removeSubjectFromClassroom, getSavedPlans, getAssignmentsByClassId, 
    getAssignmentResults, updateStudentResultFeedback, createForumPost, 
    addForumReply, sendDirectMessage, getDirectMessages, markMessagesRead, 
