                  <div className="p-6"><label className="block text-sm font-medium text-gray-700 mb-2">Message</label><textarea rows={4} className="w-full rounded-lg border border-gray-300 p-3 text-sm" placeholder="Type message..." value={dmInput} onChange={(e) => setDmInput(e.target.value)} /></div>
                  <div className="p-6 border-t border-gray-100 bg-gray-50 flex justify-end gap-2"><button onClick={() => setDmModal(null)} className="px-4 py-2 text-gray-600 rounded font-medium text-sm">Cancel</button><button onClick={sendDm} className="px-4 py-2 bg-blue-600 text-white rounded font-bold text-sm flex items-center gap-2"><Send className="w-3 h-3" /> Send</button></div>
