                          <button key={tab} onClick={() => { setManageTab(tab as any); if(tab === 'performance') setManageView('subjects'); }} className={`flex-1 py-3 px-4 text-sm font-bold border-b-2 capitalize transition-colors ${manageTab === tab ? 'border-teal-600 text-teal-700 bg-white' : 'border-transparent text-gray-500 hover:text-gray-700'}`}>
                              {tab}
                          </button>
                      ))}
                  </div>
