        deleteClassroom(id);
        loadData();
    }
  };

  const handleAddStudent = () => {
      if (managedClassroom && newStudentName.trim()) {
          addSingleStudentToClassroom(managedClassroom.id, newStudentName);
          setNewStudentName('');
          loadData();
      }
