const Dashboard: React.FC<{ profile: UserProfile; onUpdate: (profile: UserProfile) => void }> = ({ profile, onUpdate }) => {
  const [activeView, setActiveView] = useState<'overview' | 'classrooms' | 'profile' | 'inbox' | 'cat_gen'>('overview');
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [expandedClassId, setExpandedClassId] = useState<string | null>(null);

  const [classrooms, setClassrooms] = useState<Classroom[]>([]);
  const [totalPlans, setTotalPlans] = useState(0);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [showNotifications, setShowNotifications] = useState(false);
  const [messages, setMessages] = useState<DirectMessage[]>([]);

  const [formData, setFormData] = useState<UserProfile>(profile);
  const [message, setMessage] = useState('');

  const [showAddClassModal, setShowAddClassModal] = useState(false);
  const [managedClassroom, setManagedClassroom] = useState<Classroom | null>(null);

  const [manageTab, setManageTab] = useState<'students' | 'performance' | 'forum' | 'resources'>('students');
  const [manageView, setManageView] = useState<'subjects' | 'assignments' | 'results'>('subjects');
  const [selectedSubjectForStats, setSelectedSubjectForStats] = useState<string>('');
  const [currentAssignmentResults, setCurrentAssignmentResults] = useState<StudentResult[]>([]);
  const [assignmentList, setAssignmentList] = useState<Assignment[]>([]);

  const [feedbackModal, setFeedbackModal] = useState<{resultId: string, name: string, currentFeedback: string} | null>(null);
  const [feedbackInput, setFeedbackInput] = useState('');

  const [analysisModal, setAnalysisModal] = useState<{studentName: string, report: string} | null>(null);
  const [dmModal, setDmModal] = useState<{studentName: string, studentCode: string} | null>(null);
  const [dmInput, setDmInput] = useState('');
  const [replyText, setReplyText] = useState('');
  const [selectedThread, setSelectedThread] = useState<string | null>(null);

  const [forumPostTitle, setForumPostTitle] = useState('');
  const [forumPostContent, setForumPostContent] = useState('');
  const [replyContent, setReplyContent] = useState('');
  const [activePostId, setActivePostId] = useState<string | null>(null);

  const [newClassGrade, setNewClassGrade] = useState<Grade>(Grade.GRADE_7);
  const [newClassStream, setNewClassStream] = useState('');
  const [newClassRoll, setNewClassRoll] = useState<number>(40);
  const [addingSubjectTo, setAddingSubjectTo] = useState<string | null>(null);
  const [selectedSubject, setSelectedSubject] = useState<Subject>(Subject.MATHEMATICS);

  const [bulkStudentCount, setBulkStudentCount] = useState(5);
  const [newStudentName, setNewStudentName] = useState('');

  // CAT Generator States
  const [catSubject, setCatSubject] = useState<Subject>(Subject.MATHEMATICS);
  const [catGrade, setCatGrade] = useState<Grade>(Grade.GRADE_7);
  const [selectedLessonsForCAT, setSelectedLessonsForCAT] = useState<LessonDefinition[]>([]);
  const [isGeneratingCAT, setIsGeneratingCAT] = useState(false);
  const [catTargetClass, setCatTargetClass] = useState('');

  useEffect(() => {
    loadData();
    const interval = setInterval(() => {
        setNotifications(getNotifications(profile.email));
        setMessages(getDirectMessages(profile.email));
    }, 10000);
    return () => clearInterval(interval);
  }, []);

  const loadData = () => {
    const cls = getClassrooms();
    setClassrooms(cls);
    const plans = getSavedPlans();
    setTotalPlans(plans.length);
    setNotifications(getNotifications(profile.email));
    setMessages(getDirectMessages(profile.email));

    if (managedClassroom) {
        const updated = cls.find(c => c.id === managedClassroom.id);
        if (updated) setManagedClassroom(updated);
        else setManagedClassroom(null);
    }
  };

  const handleCreateClassroom = (e: React.FormEvent) => {
    e.preventDefault();
    if (newClassStream && newClassRoll > 0) {
        createClassroom(newClassGrade, newClassStream, newClassRoll);
        loadData();
        setShowAddClassModal(false);
        setNewClassStream('');
    }
  };

  const handleDeleteClassroom = (id: string) => {
    if (confirm('Are you sure? All student data will be lost.')) {
        deleteClassroom(id);
        loadData();
    }
  };

  const handleAddStudent = () => {
      if (managedClassroom && newStudentName.trim()) {
          addSingleStudentToClassroom(managedClassroom.id, newStudentName);
          setNewStudentName('');
          loadData();
      }
  };

  const handleDeleteStudent = (studentCode: string) => {
      if (managedClassroom && confirm("Remove this student?")) {
          deleteStudentFromClassroom(managedClassroom.id, studentCode);
          loadData();
      }
  };

  const handleSubmitProfile = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdate(formData);
    setMessage('Profile updated successfully!');
    setTimeout(() => setMessage(''), 3000);
  };

  const handleAddSubject = (classId: string) => {
      addSubjectToClassroom(classId, selectedSubject);
      setAddingSubjectTo(null);
      loadData();
  };

  const handleRemoveSubject = (classId: string, subject: string) => {
      if (confirm(`Remove ${subject}?`)) {
          removeSubjectFromClassroom(classId, subject);
          loadData();
      }
  };

  const openClassroomManager = (cls: Classroom) => {
      setManagedClassroom(cls);
      setManageTab('students');
      setManageView('subjects');
      setActiveView('classrooms');
  };

  const handleSidebarSubjectClick = (cls: Classroom, subject: string) => {
      setManagedClassroom(cls);
      setManageTab('performance');
      loadAssignmentsForSubjectInternal(cls.id, subject);
      setActiveView('classrooms');
      if (window.innerWidth < 1024) setSidebarOpen(false);
  };

  const loadAssignmentsForSubject = (subject: string) => {
      if (!managedClassroom) return;
      loadAssignmentsForSubjectInternal(managedClassroom.id, subject);
  };

  const loadAssignmentsForSubjectInternal = (classId: string, subject: string) => {
      const allAssignments = getAssignmentsByClassId(classId);
      const filtered = allAssignments.filter(a => a.subject === subject);
      setAssignmentList(filtered);
      setSelectedSubjectForStats(subject);
      setManageView('assignments');
  };

  const loadResultsForAssignment = (assignment: Assignment) => {
      const results = getAssignmentResults(assignment.id);
      const highestScoreMap = new Map<string, StudentResult>();
      results.forEach(result => {
        const existing = highestScoreMap.get(result.studentCode);
        if (!existing || result.score > existing.score) {
          highestScoreMap.set(result.studentCode, result);
        }
      });
      setCurrentAssignmentResults(Array.from(highestScoreMap.values()));
      setManageView('results');
  };

  const saveFeedback = () => {
      if (!feedbackModal) return;
      updateStudentResultFeedback(feedbackModal.resultId, feedbackInput);
      loadData();
      setFeedbackModal(null);
  };

  // Added missing openDmModal function
  const openDmModal = (s: Student) => {
      setDmModal({ studentName: s.name || 'Student', studentCode: s.code });
  };

  const sendDm = () => {
      if (!dmModal || !dmInput.trim()) return;
      const msg: DirectMessage = {
          id: crypto.randomUUID(), senderId: profile.email, senderName: profile.name, receiverId: dmModal.studentCode, content: dmInput, timestamp: new Date().toISOString(), read: false, isFromTeacher: true
      };
      sendDirectMessage(msg);
      setDmModal(null);
      loadData();
  };

  const handleReplyToStudent = (studentId: string) => {
      if (!replyText.trim()) return;
      const msg: DirectMessage = {
          id: crypto.randomUUID(), senderId: profile.email, senderName: profile.name, receiverId: studentId, content: replyText, timestamp: new Date().toISOString(), read: false, isFromTeacher: true
      };
      sendDirectMessage(msg);
      setReplyText('');
      loadData();
  };

  const handleTextbookUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file && managedClassroom) {
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64 = typeof reader.result === 'string' ? reader.result : '';
              const newBook: Textbook = {
                  id: crypto.randomUUID(), title: file.name, fileData: base64, fileType: file.type.includes('pdf') ? 'pdf' : 'word', uploadDate: new Date().toISOString(), size: `${(file.size/1024).toFixed(1)} KB`
              };
              uploadTextbookToClassroom(managedClassroom.id, newBook);
              loadData();
          };
          reader.readAsDataURL(file);
      }
  };

  const handleCreateForumPost = (e: React.FormEvent) => {
      e.preventDefault();
      if (!managedClassroom || !forumPostTitle.trim()) return;
      const newPost: ForumPost = { id: crypto.randomUUID(), authorName: profile.name, title: forumPostTitle, content: forumPostContent, timestamp: new Date().toISOString(), replies: [] };
      createForumPost(managedClassroom.id, newPost);
      setForumPostTitle(''); setForumPostContent('');
      loadData();
  };

  const handleReplyToPost = (postId: string) => {
      if (!managedClassroom || !replyContent.trim()) return;
      const reply: ForumReply = { id: crypto.randomUUID(), authorName: profile.name, authorRole: 'teacher', content: replyContent, timestamp: new Date().toISOString() };
      addForumReply(managedClassroom.id, postId, reply);
      setReplyContent(''); setActivePostId(null);
      loadData();
  };

  const handleNotificationClick = (notif: AppNotification) => {
      markNotificationRead(notif.id);
      if (notif.type === 'message') setActiveView('inbox');
      loadData();
  };

  const handleSelectThread = (studentId: string) => {
      setSelectedThread(studentId);
      markMessagesRead(studentId, profile.email);
      loadData();
  };

  // CAT Generator Logic
  const allLessonsForCat = useMemo(() => {
      const getScheme = () => {
          switch(catSubject) {
              case Subject.MATHEMATICS: return SCHEMES_OF_WORK[catGrade] || [];
              case Subject.INTEGRATED_SCIENCE: return INTEGRATED_SCIENCE_SCHEMES[catGrade] || [];
              case Subject.PRETECHNICAL_STUDIES: return PRETECH_SCHEMES[catGrade] || [];
              case Subject.AGRICULTURE_AND_NUTRITION: return AGRICULTURE_NUTRITION_SCHEMES[catGrade] || [];
              case Subject.KISWAHILI: return KISWAHILI_SCHEMES[catGrade] || [];
              case Subject.ENGLISH: return ENGLISH_SCHEMES[catGrade] || [];
              case Subject.SOCIAL_STUDIES: return SOCIAL_STUDIES_SCHEMES[catGrade] || [];
              case Subject.CHRISTIAN_RELIGIOUS_EDUCATION: return CRE_SCHEMES[catGrade] || [];
              case Subject.CREATIVE_ARTS: return CREATIVE_ARTS_SCHEMES[catGrade] || [];
              case Subject.SCIENCE_AND_TECHNOLOGY: return SCIENCE_TECHNOLOGY_SCHEMES[catGrade] || [];
              default: return [];
          }
      };
      return getScheme();
  }, [catSubject, catGrade]);

  const toggleCatLesson = (lesson: LessonDefinition) => {
      setSelectedLessonsForCAT(prev => 
          prev.some(l => l.topic === lesson.topic) 
          ? prev.filter(l => l.topic !== lesson.topic) 
          : [...prev, lesson]
      );
  };

  const handleGenerateCAT = async () => {
      if (selectedLessonsForCAT.length === 0 || !catTargetClass) {
          alert("Please select lessons and a target classroom.");
          return;
      }
      setIsGeneratingCAT(true);
      try {
          const questions = await generateCAT(catSubject, catGrade, selectedLessonsForCAT, 20);
          const topic = `CAT: ${selectedLessonsForCAT.map(l => l.subStrand).slice(0,2).join(", ")}${selectedLessonsForCAT.length > 2 ? '...' : ''}`;
          const assign: Assignment = {
              id: crypto.randomUUID(), classroomId: catTargetClass, subject: catSubject, topic: topic, questions: questions, createdAt: new Date().toISOString(), grade: catGrade
          };
          saveAssignment(assign);
          alert("CAT Generated and assigned successfully!");
          setSelectedLessonsForCAT([]);
          setActiveView('classrooms');
      } catch (err) {
          alert("CAT generation failed.");
