          )}
          {activeView === 'classrooms' && (
            <div className="space-y-6">
                <div className="flex justify-between items-center"><h2 className="text-xl text-gray-600 font-light">My Classrooms</h2><button onClick={() => setShowAddClassModal(true)} className="bg-teal-600 text-white px-4 py-2 rounded text-sm font-bold flex items-center gap-2"><Plus className="w-4 h-4" /> Add Classroom</button></div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {classrooms.map(room => (
                        <div key={room.id} className="bg-white rounded-xl border p-5 shadow-sm">
                            <div className="flex justify-between items-start mb-4"><div><h4 className="text-lg font-bold">{room.grade} - {room.stream}</h4><p className="text-xs text-gray-500">{room.students.length} Students</p></div><div className="flex gap-2"><button onClick={() => openClassroomManager(room)} className="p-2 bg-gray-100 rounded hover:bg-gray-200"><Eye className="w-4 h-4" /></button><button onClick={() => handleDeleteClassroom(room.id)} className="p-2 bg-red-50 text-red-600 rounded hover:bg-red-100"><Trash2 className="w-4 h-4" /></button></div></div>
                            <div className="flex flex-wrap gap-2">{room.subjects.map(s => (<span key={s} className="bg-slate-100 px-2 py-1 rounded text-xs">{s}</span>))}</div>
                        </div>
                    ))}
                </div>
            </div>
          )}
          {activeView === 'cat_gen' && (
            <div className="bg-white rounded-xl border shadow-sm p-8">
                <div className="mb-8 border-b pb-6 flex justify-between items-center"><div><h2 className="text-2xl font-bold text-teal-800">CAT Generator</h2><p className="text-sm text-gray-500">Pick lessons to generate a cumulative quiz.</p></div><button onClick={handleGenerateCAT} disabled={isGeneratingCAT || selectedLessonsForCAT.length === 0} className="bg-teal-600 text-white px-8 py-3 rounded-lg font-bold hover:bg-teal-700 disabled:opacity-50 flex items-center gap-2">{isGeneratingCAT ? <Loader2 className="w-5 h-5 animate-spin" /> : <Sparkles className="w-5 h-5" />} Generate & Assign CAT</button></div>
                <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                    <div className="space-y-4 lg:col-span-1">
                        <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1">Subject</label><select value={catSubject} onChange={e=>setCatSubject(e.target.value as Subject)} className="w-full border rounded p-2 text-sm">{Object.values(Subject).map(s=><option key={s} value={s}>{s}</option>)}</select></div>
                        <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1">Grade</label><select value={catGrade} onChange={e=>setCatGrade(e.target.value as Grade)} className="w-full border rounded p-2 text-sm">{Object.values(Grade).map(g=><option key={g} value={g}>{g}</option>)}</select></div>
                        <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1">Assign to Class</label><select value={catTargetClass} onChange={e=>setCatTargetClass(e.target.value)} className="w-full border rounded p-2 text-sm"><option value="">-- Select --</option>{classrooms.filter(c=>c.grade===catGrade).map(c=>(<option key={c.id} value={c.id}>{c.stream}</option>))}</select></div>
                        <div className="bg-blue-50 p-4 rounded text-xs text-blue-700"><p className="font-bold mb-1">Tip:</p><p>Select 3-5 lessons for a balanced CAT. Gemini will generate 20 diverse MCQs covering all selected topics.</p></div>
                    </div>
                    <div className="lg:col-span-3"><div className="border rounded-xl overflow-hidden"><div className="bg-gray-50 p-3 border-b font-bold text-sm flex justify-between"><span>Lessons in {catGrade} {catSubject}</span><span>{selectedLessonsForCAT.length} Selected</span></div><div className="max-h-[500px] overflow-y-auto divide-y">{allLessonsForCat.map(lesson=>(<label key={lesson.topic} className={`flex items-start gap-3 p-4 cursor-pointer hover:bg-slate-50 transition-colors ${selectedLessonsForCAT.some(l=>l.topic===lesson.topic) ? 'bg-teal-50' : ''}`}><input type="checkbox" className="mt-1 w-4 h-4 rounded text-teal-600" checked={selectedLessonsForCAT.some(l=>l.topic===lesson.topic)} onChange={()=>toggleCatLesson(lesson)} /><div><p className="font-bold text-sm text-slate-800">{lesson.topic.replace(/^Lesson \d+:\s*/i, '')}</p><p className="text-xs text-gray-500">{lesson.strand} / {lesson.subStrand}</p></div></label>))}</div></div></div>
                </div>
            </div>
          )}
          {activeView === 'inbox' && (
              <div className="h-[calc(100vh-12rem)] bg-white rounded-xl border flex overflow-hidden">
                  <div className="w-1/3 border-r overflow-y-auto">
                      <div className="p-4 border-b bg-gray-50 font-bold">Students</div>
                      {/* Fixed type inference by casting to string[] */}
                      {(Array.from(new Set(messages.filter(m => !m.isFromTeacher).map(m => m.senderId))) as string[]).map((sid: string) => {
                          const last = messages.filter(m=>m.senderId===sid || m.receiverId===sid).pop();
                          return (<div key={sid} onClick={()=>handleSelectThread(sid)} className={`p-4 border-b hover:bg-slate-50 cursor-pointer ${selectedThread===sid ? 'bg-teal-50' : ''}`}><p className="font-bold text-sm">{last?.senderId===sid ? last.senderName : (messages.find(m=>m.senderId===sid)?.senderName || sid)}</p><p className="text-xs text-gray-500 truncate">{last?.content}</p></div>);
                      })}
                  </div>
                  <div className="flex-1 flex flex-col">
                      {selectedThread ? (<><div className="p-4 border-b font-bold">{selectedThread}</div><div className="flex-1 overflow-y-auto p-4 space-y-4">{messages.filter(m=>m.senderId===selectedThread || m.receiverId===selectedThread).map(m=>(<div key={m.id} className={`flex ${m.isFromTeacher ? 'justify-end' : 'justify-start'}`}><div className={`p-3 rounded-xl max-w-[70%] text-sm shadow-sm ${m.isFromTeacher ? 'bg-teal-600 text-white' : 'bg-slate-100'}`}><p>{m.content}</p><p className="text-[10px] mt-1 opacity-50">{new Date(m.timestamp).toLocaleTimeString()}</p></div></div>))}</div><form onSubmit={(e)=>{e.preventDefault(); handleReplyToStudent(selectedThread)}} className="p-4 border-t flex gap-2"><input type="text" className="flex-1 border rounded-lg px-4" value={replyText} onChange={e=>setReplyText(e.target.value)} placeholder="Type reply..." /><button className="bg-teal-600 text-white p-2 rounded-lg"><Send className="w-5 h-5" /></button></form></>) : (<div className="flex-1 flex items-center justify-center text-gray-400">Select a message</div>)}
                  </div>
              </div>
          )}
        </main>
      </div>

      {managedClassroom && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-4xl overflow-hidden h-[90vh] flex flex-col">
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white shrink-0">
                      <div><h3 className="font-bold text-lg">{managedClassroom.grade} - {managedClassroom.stream}</h3><p className="text-slate-400 text-xs">Class Manager</p></div>
                      <button onClick={() => setManagedClassroom(null)}><X className="w-5 h-5" /></button>
                  </div>
                  <div className="flex border-b bg-gray-50 overflow-x-auto">
                      {['students', 'performance', 'resources', 'forum'].map(t => (<button key={t} onClick={() => setManageTab(t as any)} className={`flex-1 py-3 px-4 text-sm font-bold capitalize ${manageTab === t ? 'border-b-2 border-teal-600 text-teal-700 bg-white' : 'text-gray-500'}`}>{t}</button>))}
                  </div>
                  <div className="flex-1 overflow-y-auto bg-white">
                      {manageTab === 'students' && (
                          <div className="p-6">
                              <div className="mb-6 flex gap-2"><input type="text" className="flex-1 border rounded p-2 text-sm" value={newStudentName} onChange={e=>setNewStudentName(e.target.value)} placeholder="Enter New Student Name..." /><button onClick={handleAddStudent} className="bg-teal-600 text-white px-4 py-2 rounded text-sm font-bold flex items-center gap-1"><Plus className="w-4 h-4" /> Add Student</button></div>
                              <table className="w-full text-sm text-left">
                                  <thead className="bg-gray-50 font-bold uppercase text-xs"><tr><th className="px-6 py-3">Code</th><th className="px-6 py-3">Name</th><th className="px-6 py-3 text-right">Actions</th></tr></thead>
                                  <tbody className="divide-y">
                                      {managedClassroom.students.map(s => (<tr key={s.code} className="hover:bg-gray-50"><td className="px-6 py-3 font-mono text-teal-700 font-bold">{s.code}</td><td className="px-6 py-3 italic">{s.name || "---"}</td><td className="px-6 py-3 text-right flex gap-2 justify-end"><button onClick={() => openDmModal(s)} className="p-1.5 bg-blue-50 text-blue-600 rounded"><MessageCircle className="w-4 h-4" /></button><button onClick={() => handleDeleteStudent(s.code)} className="p-1.5 bg-red-50 text-red-600 rounded"><Trash2 className="w-4 h-4" /></button></td></tr>))}
                                  </tbody>
                              </table>
                          </div>
                      )}
                      {manageTab === 'performance' && (<div className="p-6">Performance view implementation...</div>)}
                  </div>
              </div>
          </div>
      )}

      {dmModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md p-6"><h3 className="font-bold mb-4">Message {dmModal.studentName}</h3><textarea rows={4} className="w-full border rounded-lg p-3 text-sm mb-4" placeholder="Type message..." value={dmInput} onChange={e=>setDmInput(e.target.value)} /><div className="flex justify-end gap-2"><button onClick={() => setDmModal(null)} className="px-4 py-2 text-gray-500">Cancel</button><button onClick={sendDm} className="px-4 py-2 bg-blue-600 text-white rounded font-bold">Send</button></div></div>
          </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { UserProfile, Classroom, Grade, Subject, Assignment, StudentResult, ForumPost, ForumReply, DirectMessage, AppNotification, Textbook, SharedNote, LessonDefinition, Student } from '../types';
import { SCHEMES_OF_WORK } from '../data/maths';
import { PRETECH_SCHEMES } from '../data/pretech';
import { CREATIVE_ARTS_SCHEMES } from '../data/creative_arts';
import { CRE_SCHEMES } from '../data/cre';
import { INTEGRATED_SCIENCE_SCHEMES } from '../data/integrated_science';
import { SCIENCE_TECHNOLOGY_SCHEMES } from '../data/science_technology';
import { SOCIAL_STUDIES_SCHEMES } from '../data/social_studies';
import { AGRICULTURE_NUTRITION_SCHEMES } from '../data/agriculture_nutrition';
import { ENGLISH_SCHEMES } from '../data/english';
import { KISWAHILI_SCHEMES } from '../data/kiswahili';
import { 
  User, School, Phone, Mail, Save, Plus, Trash2, 
  BookOpen, Users, Eye, X, Home, FileText, Settings, 
  Menu, Bell, ChevronDown, Check, ArrowLeft, MessageSquare, ChevronRight, MessageCircle, Send, Reply, ChevronLeft, Layers, Bookmark, Sparkles, Upload, FileText as FileIcon, Building2, Key, Clock, ListChecks, Filter, CheckSquare, Loader2
} from 'lucide-react';
import { 
    createClassroom, getClassrooms, deleteClassroom, addSubjectToClassroom, 
    removeSubjectFromClassroom, getSavedPlans, getAssignmentsByClassId, 
    getAssignmentResults, updateStudentResultFeedback, createForumPost, 
    addForumReply, sendDirectMessage, getDirectMessages, markMessagesRead, 
    getNotifications, markNotificationRead, uploadTextbookToClassroom,
    addStudentsToClassroom, deleteStudentFromClassroom, addSingleStudentToClassroom,
    saveAssignment
} from '../services/storageService';
import { generateCAT } from '../services/geminiService';

interface StatCardProps {
  icon: any;
  label: string;
  value: string | number;
  color: string;
}

const StatCard = ({ icon: Icon, label, value, color }: StatCardProps) => (
  <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex items-center justify-between transition-transform hover:-translate-y-1 duration-300">
    <div>
      <div className={`p-3 rounded-full w-12 h-12 flex items-center justify-center mb-3 ${color} bg-opacity-10`}>
        <Icon className={`w-6 h-6 ${color.replace('bg-', 'text-')}`} />
      </div>
      <h3 className="text-gray-500 text-sm font-medium uppercase tracking-wider">{label}</h3>
    </div>
    <div className="text-right">
      <span className={`text-4xl font-light ${color.replace('bg-', 'text-')}`}>{value}</span>
    </div>
  </div>
);

const Dashboard: React.FC<{ profile: UserProfile; onUpdate: (profile: UserProfile) => void }> = ({ profile, onUpdate }) => {
  const [activeView, setActiveView] = useState<'overview' | 'classrooms' | 'profile' | 'inbox' | 'cat_gen'>('overview');
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [expandedClassId, setExpandedClassId] = useState<string | null>(null);

  const [classrooms, setClassrooms] = useState<Classroom[]>([]);
  const [totalPlans, setTotalPlans] = useState(0);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [showNotifications, setShowNotifications] = useState(false);
  const [messages, setMessages] = useState<DirectMessage[]>([]);

  const [formData, setFormData] = useState<UserProfile>(profile);
  const [message, setMessage] = useState('');

  const [showAddClassModal, setShowAddClassModal] = useState(false);
  const [managedClassroom, setManagedClassroom] = useState<Classroom | null>(null);

  const [manageTab, setManageTab] = useState<'students' | 'performance' | 'forum' | 'resources'>('students');
  const [manageView, setManageView] = useState<'subjects' | 'assignments' | 'results'>('subjects');
  const [selectedSubjectForStats, setSelectedSubjectForStats] = useState<string>('');
  const [selectedAssignmentForStats, setSelectedAssignmentForStats] = useState<Assignment | null>(null);
  const [currentAssignmentResults, setCurrentAssignmentResults] = useState<StudentResult[]>([]);
  const [assignmentList, setAssignmentList] = useState<Assignment[]>([]);

  const [feedbackModal, setFeedbackModal] = useState<{resultId: string, name: string, currentFeedback: string} | null>(null);
  const [feedbackInput, setFeedbackInput] = useState('');

  const [analysisModal, setAnalysisModal] = useState<{studentName: string, report: string} | null>(null);
  const [dmModal, setDmModal] = useState<{studentName: string, studentCode: string} | null>(null);
  const [dmInput, setDmInput] = useState('');
  const [replyText, setReplyText] = useState('');
  const [selectedThread, setSelectedThread] = useState<string | null>(null);

  const [forumPostTitle, setForumPostTitle] = useState('');
  const [forumPostContent, setForumPostContent] = useState('');
  const [replyContent, setReplyContent] = useState('');
  const [activePostId, setActivePostId] = useState<string | null>(null);

  const [newClassGrade, setNewClassGrade] = useState<Grade>(Grade.GRADE_7);
  const [newClassStream, setNewClassStream] = useState('');
  const [newClassRoll, setNewClassRoll] = useState<number>(40);
  const [addingSubjectTo, setAddingSubjectTo] = useState<string | null>(null);
  const [selectedSubject, setSelectedSubject] = useState<Subject>(Subject.MATHEMATICS);

  const [bulkStudentCount, setBulkStudentCount] = useState(5);
  const [newStudentName, setNewStudentName] = useState('');

  // CAT Generator States
  const [catSubject, setCatSubject] = useState<Subject>(Subject.MATHEMATICS);
  const [catGrade, setCatGrade] = useState<Grade>(Grade.GRADE_7);
  const [selectedLessonsForCAT, setSelectedLessonsForCAT] = useState<LessonDefinition[]>([]);
  const [isGeneratingCAT, setIsGeneratingCAT] = useState(false);
  const [catTargetClass, setCatTargetClass] = useState('');

  useEffect(() => {
    loadData();
    const interval = setInterval(() => {
        setNotifications(getNotifications(profile.email));
        setMessages(getDirectMessages(profile.email));
    }, 10000);
    return () => clearInterval(interval);
  }, []);

  const loadData = () => {
    const cls = getClassrooms();
    setClassrooms(cls);
    const plans = getSavedPlans();
    setTotalPlans(plans.length);
    setNotifications(getNotifications(profile.email));
    setMessages(getDirectMessages(profile.email));

    // Refresh managed classroom if open
    if (managedClassroom) {
        const updated = cls.find(c => c.id === managedClassroom.id);
        if (updated) setManagedClassroom(updated);
        else setManagedClassroom(null); // Just deleted
    }
  };

  const handleCreateClassroom = (e: React.FormEvent) => {
    e.preventDefault();
    if (newClassStream && newClassRoll > 0) {
        createClassroom(newClassGrade, newClassStream, newClassRoll);
        loadData();
        setShowAddClassModal(false);
        setNewClassStream('');
        setNewClassRoll(40);
    }
  };

  const handleDeleteClassroom = (id: string) => {
    if (confirm('Are you sure? All student data will be lost.')) {
        deleteClassroom(id);
        loadData();
    }
  };

  const handleAddBulkStudents = () => {
      if (managedClassroom && bulkStudentCount > 0) {
          addStudentsToClassroom(managedClassroom.id, bulkStudentCount);
          loadData();
          setBulkStudentCount(5);
      }
  };

  const handleAddStudent = () => {
      if (managedClassroom && newStudentName.trim()) {
          addSingleStudentToClassroom(managedClassroom.id, newStudentName);
          setNewStudentName('');
          loadData();
      }
  };

  const handleDeleteStudent = (studentCode: string) => {
      if (managedClassroom && confirm("Remove this student?")) {
          deleteStudentFromClassroom(managedClassroom.id, studentCode);
          loadData();
      }
  };

  const handleSubmitProfile = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdate(formData);
    setMessage('Profile updated successfully!');
    setTimeout(() => setMessage(''), 3000);
  };

  const handleAddSubject = (classId: string) => {
      addSubjectToClassroom(classId, selectedSubject);
      setAddingSubjectTo(null);
      loadData();
  };

  const handleRemoveSubject = (classId: string, subject: string) => {
      if (confirm(`Remove ${subject}?`)) {
          removeSubjectFromClassroom(classId, subject);
          loadData();
      }
  };

  const openClassroomManager = (cls: Classroom) => {
      setManagedClassroom(cls);
      setManageTab('students');
      setManageView('subjects');
      setActiveView('classrooms');
  };

  const handleSidebarSubjectClick = (cls: Classroom, subject: string) => {
      setManagedClassroom(cls);
      setManageTab('performance');
      loadAssignmentsForSubjectInternal(cls.id, subject);
      setActiveView('classrooms');
      if (window.innerWidth < 1024) setSidebarOpen(false);
  };

  const loadAssignmentsForSubject = (subject: string) => {
      if (!managedClassroom) return;
      loadAssignmentsForSubjectInternal(managedClassroom.id, subject);
  };

  const loadAssignmentsForSubjectInternal = (classId: string, subject: string) => {
      const allAssignments = getAssignmentsByClassId(classId);
      const filtered = allAssignments.filter(a => a.subject === subject);
      setAssignmentList(filtered);
      setSelectedSubjectForStats(subject);
      setManageView('assignments');
  };

  const loadResultsForAssignment = (assignment: Assignment) => {
      const results = getAssignmentResults(assignment.id);
      const highestScoreMap = new Map<string, StudentResult>();
      results.forEach(result => {
        const existing = highestScoreMap.get(result.studentCode);
        if (!existing || result.score > existing.score) {
          highestScoreMap.set(result.studentCode, result);
        }
      });
      const filteredResults = Array.from(highestScoreMap.values());
      setCurrentAssignmentResults(filteredResults);
      setSelectedAssignmentForStats(assignment);
      setManageView('results');
  };

  const openFeedbackModal = (result: StudentResult) => {
      setFeedbackInput(result.feedback || '');
      setFeedbackModal({
          resultId: result.id,
          name: result.studentName,
          currentFeedback: result.feedback || ''
      });
  };

  const saveFeedback = () => {
      if (!feedbackModal) return;
      updateStudentResultFeedback(feedbackModal.resultId, feedbackInput);
      const updatedResults = currentAssignmentResults.map(r => 
          r.id === feedbackModal.resultId ? {...r, feedback: feedbackInput} : r
      );
      setCurrentAssignmentResults(updatedResults);
      setFeedbackModal(null);
  };

  const openDmModal = (student: {name?: string, code: string}) => {
      setDmModal({
          studentName: student.name || `Student ${student.code}`,
          studentCode: student.code
      });
      setDmInput('');
  };

  const sendDm = () => {
      if (!dmModal || !dmInput.trim()) return;
      const msg: DirectMessage = {
          id: crypto.randomUUID(),
          senderId: profile.email,
          senderName: profile.name,
          receiverId: dmModal.studentCode,
          content: dmInput,
          timestamp: new Date().toISOString(),
          read: false,
          isFromTeacher: true
      };
      sendDirectMessage(msg);
      setDmModal(null);
      alert("Message sent successfully!");
      setMessages(getDirectMessages(profile.email));
  };

  const handleReplyToStudent = (studentId: string) => {
      if (!replyText.trim()) return;
      const msg: DirectMessage = {
          id: crypto.randomUUID(),
          senderId: profile.email,
          senderName: profile.name,
          receiverId: studentId,
          content: replyText,
          timestamp: new Date().toISOString(),
          read: false,
          isFromTeacher: true
      };
      sendDirectMessage(msg);
      setReplyText('');
      setMessages(prev => [...prev, msg]); 
  };

  const handleTextbookUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file && managedClassroom) {
          if (file.size > 2 * 1024 * 1024) {
              alert("File too large. Please upload files smaller than 2MB.");
              return;
          }
          const reader = new FileReader();
          reader.onloadend = () => {
              const result = reader.result;
              const base64 = typeof result === 'string' ? result : '';
              if (!base64) return;
              const newBook: Textbook = {
                  id: crypto.randomUUID(),
                  title: file.name,
                  fileData: base64,
                  fileType: file.type.includes('pdf') ? 'pdf' : 'word',
                  uploadDate: new Date().toISOString(),
                  size: `${(file.size/1024).toFixed(1)} KB`
              };
              if (managedClassroom) {
                  uploadTextbookToClassroom(managedClassroom.id, newBook);
                  setManagedClassroom(prev => prev ? {...prev, textbooks: [...(prev.textbooks || []), newBook]} : null);
              }
          };
          reader.readAsDataURL(file);
      }
  };

  const handleCreateForumPost = (e: React.FormEvent) => {
      e.preventDefault();
      if (!managedClassroom || !forumPostTitle.trim() || !forumPostContent.trim()) return;
      const newPost: ForumPost = {
          id: crypto.randomUUID(),
          authorName: profile.name,
          title: forumPostTitle,
          content: forumPostContent,
          timestamp: new Date().toISOString(),
          replies: []
      };
      createForumPost(managedClassroom.id, newPost);
      const updatedClass = {
          ...managedClassroom,
          forumPosts: [newPost, ...(managedClassroom.forumPosts || [])]
      };
      setManagedClassroom(updatedClass);
      setForumPostTitle('');
      setForumPostContent('');
  };

  const handleReplyToPost = (postId: string) => {
      if (!managedClassroom || !replyContent.trim()) return;
      const reply: ForumReply = {
          id: crypto.randomUUID(),
          authorName: profile.name,
          authorRole: 'teacher',
          content: replyContent,
          timestamp: new Date().toISOString()
      };
      addForumReply(managedClassroom.id, postId, reply);
      const updatedPosts = managedClassroom.forumPosts.map(p => {
          if (p.id === postId) {
              return { ...p, replies: [...p.replies, reply] };
          }
          return p;
      });
      setManagedClassroom({ ...managedClassroom, forumPosts: updatedPosts });
      setReplyContent('');
      setActivePostId(null);
  };

  const handleNotificationClick = (notif: AppNotification) => {
      markNotificationRead(notif.id);
      setNotifications(prev => prev.map(n => n.id === notif.id ? {...n, read: true} : n));
      if (notif.type === 'message') {
          setActiveView('inbox');
      }
  };

  const handleSelectThread = (studentId: string) => {
      setSelectedThread(studentId);
      markMessagesRead(studentId, profile.email);
      setNotifications(prev => prev.filter(n => !(n.type === 'message' && n.title.includes(studentId))));
      setMessages(prev => prev.map(m => (m.senderId === studentId && m.receiverId === profile.email) ? {...m, read: true} : m));
  };

  // CAT Generator Logic
  const allLessonsForCat = useMemo(() => {
      const getScheme = () => {
          switch(catSubject) {
              case Subject.MATHEMATICS: return SCHEMES_OF_WORK[catGrade] || [];
              case Subject.INTEGRATED_SCIENCE: return INTEGRATED_SCIENCE_SCHEMES[catGrade] || [];
              case Subject.PRETECHNICAL_STUDIES: return PRETECH_SCHEMES[catGrade] || [];
              case Subject.AGRICULTURE_AND_NUTRITION: return AGRICULTURE_NUTRITION_SCHEMES[catGrade] || [];
              case Subject.KISWAHILI: return KISWAHILI_SCHEMES[catGrade] || [];
              case Subject.ENGLISH: return ENGLISH_SCHEMES[catGrade] || [];
              case Subject.SOCIAL_STUDIES: return SOCIAL_STUDIES_SCHEMES[catGrade] || [];
              case Subject.CHRISTIAN_RELIGIOUS_EDUCATION: return CRE_SCHEMES[catGrade] || [];
              case Subject.CREATIVE_ARTS: return CREATIVE_ARTS_SCHEMES[catGrade] || [];
              case Subject.SCIENCE_AND_TECHNOLOGY: return SCIENCE_TECHNOLOGY_SCHEMES[catGrade] || [];
              default: return [];
          }
      };
      return getScheme();
  }, [catSubject, catGrade]);

  const toggleCatLesson = (lesson: LessonDefinition) => {
      setSelectedLessonsForCAT(prev => 
          prev.some(l => l.topic === lesson.topic) 
          ? prev.filter(l => l.topic !== lesson.topic) 
          : [...prev, lesson]
      );
  };

  const handleGenerateCAT = async () => {
      if (selectedLessonsForCAT.length === 0 || !catTargetClass) {
          alert("Please select lessons and a target classroom.");
          return;
      }
      setIsGeneratingCAT(true);
      try {
          const questions = await generateCAT(catSubject, catGrade, selectedLessonsForCAT, 20);
          const topic = `CAT: ${selectedLessonsForCAT.map(l => l.subStrand).slice(0,2).join(", ")}${selectedLessonsForCAT.length > 2 ? '...' : ''}`;
          const assign: Assignment = {
              id: crypto.randomUUID(), classroomId: catTargetClass, subject: catSubject, topic: topic, questions: questions, createdAt: new Date().toISOString(), grade: catGrade
          };
          saveAssignment(assign);
          alert("CAT Generated and assigned successfully!");
          setSelectedLessonsForCAT([]);
          setActiveView('classrooms');
      } catch (err) {
          alert("CAT generation failed.");
      } finally {
          setIsGeneratingCAT(false);
      }
  };

  const unreadMessagesCount = messages.filter(m => !m.read && m.receiverId === profile.email).length;

  return (
    <div className="flex min-h-screen bg-slate-50 font-sans text-slate-800">
      {sidebarOpen && (<div className="fixed inset-0 bg-black/50 z-40 lg:hidden" onClick={() => setSidebarOpen(false)}/>)}
      <aside className={`fixed inset-y-0 left-0 z-50 bg-slate-900 text-slate-300 transition-all duration-300 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 ${isCollapsed ? 'w-20' : 'w-64'} flex flex-col`}>
        <div className="flex items-center h-16 px-4 bg-slate-950 text-white font-bold text-xl border-b border-slate-800">
          {!isCollapsed ? (<div className="flex items-center"><BookOpen className="w-6 h-6 mr-2 text-teal-500" /><span>Admin</span></div>) : (<BookOpen className="w-8 h-8 text-teal-500" />)}
        </div>
        <nav className="flex-1 overflow-y-auto p-3 space-y-1">
          <button onClick={() => setActiveView('overview')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg ${activeView === 'overview' ? 'bg-teal-600 text-white' : 'hover:bg-slate-800'}`}>
            <Home className="w-5 h-5 mr-3" /> {!isCollapsed && "Dashboard"}
          </button>
          <button onClick={() => setActiveView('classrooms')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg ${activeView === 'classrooms' ? 'bg-teal-600 text-white' : 'hover:bg-slate-800'}`}>
            <Layers className="w-5 h-5 mr-3" /> {!isCollapsed && "Classrooms"}
          </button>
          <button onClick={() => setActiveView('cat_gen')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg ${activeView === 'cat_gen' ? 'bg-teal-600 text-white' : 'hover:bg-slate-800'}`}>
            <ListChecks className="w-5 h-5 mr-3" /> {!isCollapsed && "CAT Generator"}
          </button>
          <button onClick={() => setActiveView('inbox')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg ${activeView === 'inbox' ? 'bg-teal-600 text-white' : 'hover:bg-slate-800'}`}>
            <Mail className="w-5 h-5 mr-3" /> {!isCollapsed && "Inbox"} {unreadMessagesCount > 0 && <span className="ml-auto bg-red-500 text-white text-[10px] font-bold px-2 rounded-full">{unreadMessagesCount}</span>}
          </button>
          <button onClick={() => setActiveView('profile')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg ${activeView === 'profile' ? 'bg-teal-600 text-white' : 'hover:bg-slate-800'}`}>
            <User className="w-5 h-5 mr-3" /> {!isCollapsed && "Profile"}
          </button>
        </nav>
        <div className="p-4 border-t border-slate-800">
           <button onClick={() => setIsCollapsed(!isCollapsed)} className="hidden lg:flex w-full items-center justify-center p-2 text-slate-500 hover:text-white hover:bg-slate-800 rounded-lg transition-colors">
              {isCollapsed ? <ChevronRight className="w-5 h-5"/> : <ChevronLeft className="w-5 h-5"/>}
           </button>
        </div>
      </aside>
      <div className={`flex-1 flex flex-col transition-all duration-300 ${isCollapsed ? 'lg:ml-20' : 'lg:ml-64'}`}>
        <header className="h-16 bg-white border-b flex items-center justify-between px-8 sticky top-0 z-40 shadow-sm">
          <div className="flex items-center gap-3">
              <button onClick={() => setSidebarOpen(!sidebarOpen)} className="p-2 text-gray-500 hover:bg-gray-100 rounded-md focus:outline-none lg:hidden"><Menu className="w-6 h-6" /></button>
              <h2 className="text-xl font-bold text-gray-800 hidden sm:block capitalize">{activeView.replace('_', ' ')}</h2>
          </div>
          <div className="flex items-center gap-4 relative">
             {profile.schoolId && <div className="hidden md:flex items-center gap-2 bg-indigo-50 text-indigo-700 px-3 py-1 rounded-full text-xs font-bold border border-indigo-200"><Building2 className="w-3 h-3" />{profile.school}</div>}
             <button onClick={() => setShowNotifications(!showNotifications)} className="p-2 text-gray-400 relative"><Bell className="w-5 h-5" />{notifications.some(n=>!n.read) && <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>}</button>
             {showNotifications && (
                 <div className="absolute right-0 mt-2 w-80 bg-white rounded-xl shadow-xl border border-gray-200 overflow-hidden z-50 top-10">
                     <div className="bg-slate-50 px-4 py-3 border-b border-gray-100 font-bold text-sm text-gray-700 flex justify-between"><span>Notifications</span></div>
                     <div className="max-h-80 overflow-y-auto">
                         {notifications.length === 0 ? <div className="p-4 text-center text-gray-500 text-sm">No new notifications</div> : notifications.map(n => (<div key={n.id} onClick={() => handleNotificationClick(n)} className={`p-4 border-b border-gray-50 hover:bg-slate-50 cursor-pointer ${!n.read ? 'bg-blue-50/50' : ''}`}><p className="text-sm font-bold text-slate-800">{n.title}</p><p className="text-xs text-gray-500 mt-1">{n.message}</p></div>))}
                     </div>
                 </div>
             )}
             <div className="flex items-center gap-2 pl-4 border-l border-gray-200">
               <div className="w-8 h-8 bg-slate-800 rounded-full flex items-center justify-center text-white text-xs font-bold">{profile.name.charAt(0)}</div>
               <span className="text-sm font-medium text-gray-700 hidden md:block">{profile.name}</span>
             </div>
          </div>
        </header>
        <main className="p-4 lg:p-8 max-w-7xl mx-auto w-full">
          {activeView === 'overview' && (
            <div className="space-y-8 animate-fade-in">
                <h2 className="text-xl text-gray-600 font-light uppercase tracking-wide">Overview</h2>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <StatCard icon={FileText} label="Lesson Plans" value={totalPlans} color="bg-teal-500" />
                    <StatCard icon={Users} label="Classrooms" value={classrooms.length} color="bg-blue-500" />
                    <StatCard icon={CheckSquare} label="Assignments" value={assignmentList.length} color="bg-purple-500" />
                </div>
            </div>
          )}
          {activeView === 'classrooms' && (
            <div className="space-y-6 animate-fade-in">
                <div className="flex justify-between items-center mb-4">
                    <h2 className="text-xl text-gray-600 font-light uppercase tracking-wide">My Classrooms</h2>
                    {!profile.schoolId && <button onClick={() => setShowAddClassModal(true)} className="bg-teal-600 text-white px-4 py-2 rounded shadow hover:bg-teal-700 flex items-center gap-2 text-sm font-bold"><Plus className="w-4 h-4" /> Add Classroom</button>}
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {classrooms.map(room => (
                        <div key={room.id} className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                            <div className="p-5 border-b border-gray-100 flex justify-between items-start">
                                <div><h4 className="text-lg font-bold text-slate-800">{room.grade} <span className="text-gray-400">|</span> {room.stream}</h4><div className="flex items-center gap-4 mt-2 text-xs text-gray-500 font-medium uppercase tracking-wide"><span className="flex items-center gap-1"><Users className="w-3 h-3" /> {room.students.length} Students</span></div></div>
                                <div className="flex gap-2"><button onClick={() => openClassroomManager(room)} className="p-2 bg-gray-100 hover:bg-gray-200 rounded text-gray-600"><Eye className="w-4 h-4" /></button>{!profile.schoolId && <button onClick={() => handleDeleteClassroom(room.id)} className="p-2 bg-red-50 hover:bg-red-100 rounded text-red-600"><Trash2 className="w-4 h-4" /></button>}</div>
                            </div>
                            <div className="p-5 bg-slate-50 min-h-[100px]">
                                <div className="flex justify-between items-center mb-3"><h5 className="text-xs font-bold text-gray-400 uppercase">Subjects</h5>{addingSubjectTo === room.id ? (<div className="flex items-center gap-1"><select value={selectedSubject} onChange={(e) => setSelectedSubject(e.target.value as Subject)} className="text-xs border-gray-300 rounded py-1 w-32">{Object.values(Subject).map(s => <option key={s} value={s}>{s}</option>)}</select><button onClick={() => handleAddSubject(room.id)} className="bg-green-600 text-white p-1 rounded"><Check className="w-3 h-3" /></button><button onClick={() => setAddingSubjectTo(null)} className="bg-gray-300 text-gray-700 p-1 rounded"><X className="w-3 h-3" /></button></div>) : (<button onClick={() => setAddingSubjectTo(room.id)} className="text-teal-600 text-xs font-bold hover:underline flex items-center gap-1"><Plus className="w-3 h-3" /> Add</button>)}</div>
                                <div className="flex flex-wrap gap-2">{room.subjects.length > 0 ? room.subjects.map(sub => (<span key={sub} className="inline-flex items-center gap-1 bg-white border border-gray-200 text-gray-600 px-2 py-1 rounded text-xs font-medium">{sub}<button onClick={() => handleRemoveSubject(room.id, sub)} className="text-gray-400 hover:text-red-500"><X className="w-3 h-3" /></button></span>)) : <span className="text-gray-400 text-xs italic">No subjects.</span>}</div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
          )}
          {activeView === 'cat_gen' && (
            <div className="bg-white rounded-xl border border-gray-200 shadow-sm p-8 animate-fade-in">
                <div className="mb-8 border-b border-gray-200 pb-6 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                  <div><h2 className="text-2xl font-bold text-teal-800">CAT Generator</h2><p className="text-sm text-gray-500">Pick lessons to generate a cumulative quiz.</p></div>
                  <button onClick={handleGenerateCAT} disabled={isGeneratingCAT || selectedLessonsForCAT.length === 0} className="bg-teal-600 text-white px-8 py-3 rounded-lg font-bold hover:bg-teal-700 disabled:opacity-50 flex items-center gap-2 shadow-md transition-all">{isGeneratingCAT ? <Loader2 className="w-5 h-5 animate-spin" /> : <Sparkles className="w-5 h-5" />} Generate & Assign CAT</button>
                </div>
                <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                    <div className="space-y-4 lg:col-span-1">
                        <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1">Subject</label><select value={catSubject} onChange={e=>setCatSubject(e.target.value as Subject)} className="w-full border rounded-md p-2.5 text-sm bg-gray-50 focus:border-teal-500 focus:ring-teal-500">{Object.values(Subject).map(s=><option key={s} value={s}>{s}</option>)}</select></div>
                        <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1">Grade</label><select value={catGrade} onChange={e=>setCatGrade(e.target.value as Grade)} className="w-full border rounded-md p-2.5 text-sm bg-gray-50 focus:border-teal-500 focus:ring-teal-500">{Object.values(Grade).map(g=><option key={g} value={g}>{g}</option>)}</select></div>
                        <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1">Assign to Class</label><select value={catTargetClass} onChange={e=>setCatTargetClass(e.target.value)} className="w-full border rounded-md p-2.5 text-sm bg-gray-50 focus:border-teal-500 focus:ring-teal-500"><option value="">-- Select --</option>{classrooms.filter(c=>c.grade===catGrade).map(c=>(<option key={c.id} value={c.id}>{c.stream}</option>))}</select></div>
                        <div className="bg-blue-50 p-4 rounded-lg border border-blue-100 text-xs text-blue-700 leading-relaxed"><p className="font-bold mb-1 flex items-center gap-1"><Sparkles className="w-3 h-3"/> Tip:</p><p>Select 3-5 lessons for a balanced CAT. Gemini will generate 20 diverse MCQs covering all selected topics.</p></div>
                    </div>
                    <div className="lg:col-span-3"><div className="border border-gray-200 rounded-xl overflow-hidden bg-white"><div className="bg-gray-50 px-4 py-3 border-b border-gray-200 font-bold text-sm flex justify-between text-gray-700"><span>Lessons in {catGrade} {catSubject}</span><span className="text-teal-600">{selectedLessonsForCAT.length} Selected</span></div><div className="max-h-[500px] overflow-y-auto divide-y divide-gray-100">{allLessonsForCat.map(lesson=>(<label key={lesson.topic} className={`flex items-start gap-3 p-4 cursor-pointer hover:bg-slate-50 transition-colors ${selectedLessonsForCAT.some(l=>l.topic===lesson.topic) ? 'bg-teal-50' : ''}`}><input type="checkbox" className="mt-1 w-4 h-4 rounded text-teal-600 focus:ring-teal-500 border-gray-300" checked={selectedLessonsForCAT.some(l=>l.topic===lesson.topic)} onChange={()=>toggleCatLesson(lesson)} /><div><p className="font-bold text-sm text-slate-800">{lesson.topic.replace(/^Lesson \d+:\s*/i, '')}</p><p className="text-xs text-gray-500">{lesson.strand} / {lesson.subStrand}</p></div></label>))}</div></div></div>
                </div>
            </div>
          )}
          {activeView === 'inbox' && (
              <div className="h-[calc(100vh-12rem)] bg-white rounded-xl border border-gray-200 shadow-sm flex overflow-hidden animate-fade-in">
                  <div className={`w-full md:w-1/3 border-r border-gray-200 flex flex-col ${selectedThread ? 'hidden md:flex' : 'flex'}`}>
                      <div className="p-4 border-b border-gray-200 bg-gray-50"><h3 className="font-bold text-gray-800">My Inbox</h3><p className="text-xs text-gray-500">Student Messages</p></div>
                      <div className="flex-1 overflow-y-auto">
                          {(Array.from(new Set(messages.filter(m => !m.isFromTeacher).map(m => m.senderId))) as string[]).map((sid: string) => {
                              const last = messages.filter(m=>m.senderId===sid || m.receiverId===sid).pop();
                              return (<div key={sid} onClick={()=>handleSelectThread(sid)} className={`p-4 border-b border-gray-100 hover:bg-slate-50 cursor-pointer transition-colors ${selectedThread===sid ? 'bg-blue-50' : ''}`}><div className="flex justify-between items-start mb-1"><h4 className="font-bold text-sm text-slate-800">{last?.senderId===sid ? last.senderName : (messages.find(m=>m.senderId===sid)?.senderName || sid)}</h4><span className="text-[10px] text-gray-400">{last ? new Date(last.timestamp).toLocaleDateString() : ''}</span></div><p className="text-xs text-gray-500 truncate">{last?.content}</p></div>);
                          })}
                      </div>
                  </div>
                  <div className={`flex-1 flex flex-col ${!selectedThread ? 'hidden md:flex' : 'flex'}`}>
                      {selectedThread ? (<><div className="p-4 border-b border-gray-200 bg-white flex justify-between items-center"><div className="flex items-center gap-2"><button onClick={() => setSelectedThread(null)} className="md:hidden text-gray-500"><ArrowLeft className="w-5 h-5"/></button><div><h3 className="font-bold text-gray-800">{messages.find(m => m.senderId === selectedThread || m.receiverId === selectedThread)?.senderName || 'Student'}</h3><p className="text-xs text-gray-500 text-teal-600 font-mono">{selectedThread}</p></div></div></div><div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50">{messages.filter(m=>m.senderId===selectedThread || m.receiverId===selectedThread).map(m=>(<div key={m.id} className={`flex ${m.isFromTeacher ? 'justify-end' : 'justify-start'}`}><div className={`max-w-[70%] rounded-xl p-3 text-sm shadow-sm ${m.isFromTeacher ? 'bg-blue-600 text-white rounded-br-none' : 'bg-white text-gray-800 border border-gray-200 rounded-bl-none'}`}><p>{m.content}</p><p className={`text-[10px] mt-1 text-right ${m.isFromTeacher ? 'text-blue-200' : 'text-gray-400'}`}>{new Date(m.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p></div></div>))}</div><form onSubmit={(e)=>{e.preventDefault(); handleReplyToStudent(selectedThread)}} className="p-4 border-t border-gray-200 bg-white"><div className="flex gap-2"><input type="text" className="flex-1 border border-gray-300 rounded-lg px-4 py-2 text-sm focus:outline-none focus:border-teal-500" placeholder="Type reply..." value={replyText} onChange={e=>setReplyText(e.target.value)} /><button className="bg-blue-600 text-white p-2 rounded-lg hover:bg-blue-700 transition-colors"><Send className="w-5 h-5" /></button></div></form></>) : (<div className="flex-1 flex items-center justify-center text-gray-400 flex-col"><MessageCircle className="w-12 h-12 mb-2 opacity-20" /><p>Select a message thread</p></div>)}
                  </div>
              </div>
          )}
          {activeView === 'profile' && (
            <div className="max-w-2xl animate-fade-in">
                <h2 className="text-xl text-gray-600 font-light uppercase tracking-wide mb-6">Profile</h2>
                <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
                    <form onSubmit={handleSubmitProfile} className="p-8 space-y-6">
                        {message && <div className="bg-green-50 text-green-700 p-3 rounded text-sm">{message}</div>}
