                                  <div className="animate-fade-in h-full flex flex-col"><button onClick={() => setManageView('subjects')} className="flex items-center text-sm text-gray-500 mb-4 hover:text-teal-600 font-medium transition-colors"><ArrowLeft className="w-4 h-4 mr-1" /> Back to Subjects</button><div className="flex items-center gap-3 mb-6"><h3 className="text-xl font-bold text-gray-800">{selectedSubjectForStats}</h3><span className="bg-teal-100 text-teal-800 text-xs px-2 py-0.5 rounded-full font-bold">{assignmentList.length} Assignments</span></div><div className="overflow-y-auto flex-1">{assignmentList.length === 0 ? (<div className="text-center py-12 text-gray-400 italic bg-slate-50 rounded border border-dashed">No assignments found for this subject.</div>) : (<div className="space-y-3">{assignmentList.map(assign => (<div key={assign.id} onClick={() => loadResultsForAssignment(assign)} className="p-4 bg-white border border-gray-200 rounded-xl hover:border-teal-500 cursor-pointer flex justify-between items-center group transition-all shadow-sm hover:shadow-md"><div><h4 className="font-bold text-slate-800 group-hover:text-teal-700 transition-colors">{assign.topic}</h4><p className="text-xs text-gray-500 mt-1 flex items-center gap-2"><Clock className="w-3 h-3" /> {new Date(assign.createdAt).toLocaleDateString()} <span className="w-1 h-1 bg-gray-300 rounded-full"></span> {assign.questions.length} Questions</p></div><ChevronRight className="w-5 h-5 text-gray-300 group-hover:text-teal-500 transition-colors" /></div>))}</div>)}</div></div>
