eedback ? 'bg-blue-50 text-blue-600 hover:bg-blue-100' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}><MessageSquare className="w-3 h-3" />{res.feedback ? 'Edit' : 'Feedback'}</button></td></tr>))}</tbody></table></div></div>
