                                          if (!currentRoom || !currentRoom.sharedNotes || currentRoom.sharedNotes.length === 0) return <div className="text-center py-8 text-gray-400 italic bg-slate-50 rounded border border-dashed">No notes shared yet.</div>;
                                          const groupedClassroomNotes: Record<string, SharedNote[]> = {};
                                          currentRoom.sharedNotes.forEach((note: SharedNote) => {
                                              const subj = note.subject;
                                              if (!groupedClassroomNotes[subj]) groupedClassroomNotes[subj] = [];
                                              groupedClassroomNotes[subj].push(note);
                                          });
                                          return Object.entries(groupedClassroomNotes).map(([subject, subjectNotes]) => (
