                                          <div key={post.id} className="border border-gray-200 rounded-xl p-5 bg-white shadow-sm">
                                              <div className="flex justify-between items-start mb-2"><div><h4 className="font-bold text-teal-800 text-base">{post.title}</h4><p className="text-xs text-gray-500 mt-1 flex items-center gap-1"><User className="w-3 h-3"/> {post.authorName} • <Clock className="w-3 h-3"/> {new Date(post.timestamp).toLocaleDateString()}</p></div><span className="text-xs bg-gray-100 px-2 py-1 rounded text-gray-600 font-medium">{post.replies.length} replies</span></div>
