                                              {post.replies.length > 0 && (<div className="bg-gray-50 rounded-lg p-3 mb-3 space-y-3 border border-gray-100">{post.replies.map((reply: ForumReply) => (<div key={reply.id} className="text-xs border-l-2 border-gray-300 pl-3"><span className={`font-bold block mb-1 ${reply.authorRole === 'teacher' ? 'text-teal-600' : 'text-blue-600'}`}>{reply.authorName} <span className="text-[10px] text-gray-400 font-normal ml-1">• {new Date(reply.timestamp).toLocaleDateString()}</span></span><p className="text-gray-600">{reply.content}</p></div>))}</div>)}
                                              {activePostId === post.id ? (<div className="flex gap-2 items-center mt-3"><input type="text" className="flex-1 text-sm border border-gray-300 rounded px-3 py-2 focus:ring-1 focus:ring-teal-500" placeholder="Write a reply..." value={replyContent} onChange={(e) => setReplyContent(e.target.value)} /><button onClick={() => handleReplyToPost(post.id)} className="bg-teal-600 text-white px-4 py-2 rounded text-xs font-bold hover:bg-teal-700 transition-colors">Reply</button><button onClick={() => setActivePostId(null)} className="text-gray-500 text-xs hover:text-red-500 font-medium">Cancel</button></div>) : (<button onClick={() => setActivePostId(post.id)} className="text-teal-600 text-xs font-bold flex items-center gap-1 hover:underline mt-2"><Reply className="w-3 h-3" /> Reply</button>)}
                                          </div>
