      {dmModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md p-6 animate-fade-in-up"><h3 className="font-bold mb-4 text-lg">Message {dmModal.studentName}</h3><textarea rows={4} className="w-full border rounded-lg p-3 text-sm mb-4 focus:ring-2 focus:ring-teal-500 focus:border-transparent" placeholder="Type message..." value={dmInput} onChange={e=>setDmInput(e.target.value)} /><div className="flex justify-end gap-2"><button onClick={() => setDmModal(null)} className="px-4 py-2 text-gray-500 hover:bg-gray-100 rounded text-sm font-medium transition-colors">Cancel</button><button onClick={sendDm} className="px-4 py-2 bg-blue-600 text-white rounded font-bold text-sm hover:bg-blue-700 transition-colors flex items-center gap-2"><Send className="w-3 h-3"/> Send</button></div></div>
          </div>
      )}

      {analysisModal && (
        <div className="fixed inset-0 z-[80] flex items-center justify-center bg-black/50 p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-lg overflow-hidden animate-fade-in-up">
                <div className="bg-purple-600 px-6 py-4 flex justify-between items-center text-white"><h3 className="font-bold flex items-center gap-2"><Sparkles className="w-4 h-4"/> AI Analysis</h3><button onClick={() => setAnalysisModal(null)}><X className="w-5 h-5" /></button></div>
                <div className="p-6 max-h-[70vh] overflow-y-auto"><h4 className="font-bold text-gray-800 mb-2 text-lg">{analysisModal.studentName}</h4><div className="prose prose-sm text-gray-600 whitespace-pre-wrap leading-relaxed">{analysisModal.report}</div></div>
                <div className="p-4 border-t border-gray-100 bg-gray-50 text-right"><button onClick={() => setAnalysisModal(null)} className="px-4 py-2 bg-slate-800 text-white rounded text-sm font-bold hover:bg-slate-900 transition-colors">Close</button></div>
            </div>
        </div>
      )}

      {showAddClassModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-md overflow-hidden animate-fade-in-up">
                <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white"><h3 className="font-bold text-lg">New Classroom</h3><button onClick={() => setShowAddClassModal(false)}><X className="w-5 h-5" /></button></div>
                <form onSubmit={handleCreateClassroom} className="p-6 space-y-5">
                    <div><label className="block text-sm font-medium text-gray-700 mb-1">Grade</label><select value={newClassGrade} onChange={(e) => setNewClassGrade(e.target.value as Grade)} className="w-full rounded border-gray-300 p-2.5 border focus:ring-2 focus:ring-teal-500 focus:border-transparent">{Object.values(Grade).map(g => <option key={g} value={g}>{g}</option>)}</select></div>
                    <div><label className="block text-sm font-medium text-gray-700 mb-1">Stream</label><input type="text" required placeholder="e.g. Blue" value={newClassStream} onChange={(e) => setNewClassStream(e.target.value)} className="w-full rounded border-gray-300 p-2.5 border focus:ring-2 focus:ring-teal-500 focus:border-transparent" /></div>
                    <div><label className="block text-sm font-medium text-gray-700 mb-1">Roll (Class Size)</label><input type="number" min="1" max="100" required value={newClassRoll} onChange={(e) => setNewClassRoll(parseInt(e.target.value) || 0)} className="w-full rounded border-gray-300 p-2.5 border focus:ring-2 focus:ring-teal-500 focus:border-transparent" /></div>
                    <button type="submit" className="w-full bg-teal-600 text-white font-bold py-3 rounded hover:bg-teal-700 transition-colors shadow-md">Generate Classroom</button>
                </form>
            </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useMemo } from 'react';
import { Student, Classroom, Assignment, StudentResult, SharedNote, DirectMessage, ForumPost, ForumReply } from '../types';
import { 
    authenticateStudent, updateStudentName, getAssignmentsByClassId, getStudentResults, 
    saveStudentResult, getStudentNotes, getDirectMessages, sendDirectMessage, markMessagesRead, 
    addForumReply
} from '../services/storageService';
import { generateStudentPerformanceReport } from '../services/geminiService';
import { 
    LogIn, BookOpen, CheckCircle, Clock, ChevronRight, FileText, AlertCircle, Play, 
    Loader2, Menu, Home, Layers, Book, List, CheckSquare, BarChart2, Mail, MessageSquare, 
    User, LogOut, X, Send, Reply, ChevronLeft, Download, Calendar, RefreshCw, FileIcon, MessageCircle
} from 'lucide-react';

export default function StudentPortal() {
  const [view, setView] = useState<'login' | 'portal'>('login');
  const [accessCode, setAccessCode] = useState('');
  const [student, setStudent] = useState<Student | null>(null);
  const [classroom, setClassroom] = useState<Classroom | null>(null);
  const [studentName, setStudentName] = useState('');
  const [error, setError] = useState<string | null>(null);

  const [activeSection, setActiveSection] = useState<'dashboard' | 'notes' | 'textbooks' | 'all_assignments' | 'pending' | 'completed' | 'results' | 'inbox' | 'forum' | 'profile'>('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [isCollapsed, setIsCollapsed] = useState(false);

  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [results, setResults] = useState<StudentResult[]>([]);
  const [notes, setNotes] = useState<SharedNote[]>([]);
  const [messages, setMessages] = useState<DirectMessage[]>([]);
  const [forumPosts, setForumPosts] = useState<ForumPost[]>([]);

  const [selectedNote, setSelectedNote] = useState<SharedNote | null>(null);
  const [quizMode, setQuizMode] = useState(false);
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [quizStartTime, setQuizStartTime] = useState<number>(0);
  const [questionStartTime, setQuestionStartTime] = useState<number>(0);
  const [timePerQuestion, setTimePerQuestion] = useState<Record<number, number>>({});
  const [newMessage, setNewMessage] = useState('');
  const [newForumReply, setNewForumReply] = useState('');
  const [activeForumPostId, setActiveForumPostId] = useState<string | null>(null);
  const [hasViewedForum, setHasViewedForum] = useState(false);

  // Safe checks for array methods to prevent crashes
  const safeAssignments = assignments || [];
  const safeResults = results || [];
  const safeMessages = messages || [];

  const pendingCount = safeAssignments.filter(a => !safeResults.some(r => r.assignmentId === a.id)).length;
  const unreadMsgCount = safeMessages.filter(m => !m.read && m.receiverId === student?.code).length;

  useEffect(() => {
      if (student && view === 'portal') {
          // Initial load
          if (classroom) loadStudentData(student.code, classroom.id);

          const interval = setInterval(() => {
              if (classroom) loadStudentData(student.code, classroom.id);
          }, 10000);
          return () => clearInterval(interval);
      }
  }, [student, view, classroom]);

  useEffect(() => {
      if (activeSection === 'inbox' && safeMessages.length > 0 && student && classroom) {
           const unread = safeMessages.some(m => !m.read && m.receiverId === student.code);
           if (unread) {
               markMessagesRead(classroom.userId, student.code);
               setMessages(prev => prev.map(m => m.receiverId === student.code ? {...m, read: true} : m));
           }
      }
  }, [activeSection, safeMessages, student, classroom]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!accessCode) return;
    const result = authenticateStudent(accessCode.toUpperCase());
    if (result) {
      setStudent(result.student);
      setClassroom(result.classroom);
      // Load data immediately
      loadStudentData(result.student.code, result.classroom.id);

      if (result.student.name) {
        setView('portal');
      }
    } else setError("Invalid Access Code.");
  };

  const handleNameUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (student && classroom && studentName.trim()) {
      const updated = updateStudentName(classroom.id, student.code, studentName);
      if (updated) {
        setStudent(updated);
        loadStudentData(updated.code, classroom.id);
        setView('portal');
      }
    }
  };

  const loadStudentData = (code: string, classId: string) => {
    const classAssignments = getAssignmentsByClassId(classId);
    const studentResults = getStudentResults(code);
    const classNotes = getStudentNotes(classId);
    const msgs = getDirectMessages(code);

    // Refresh classroom data to get latest forum posts
    const refreshed = authenticateStudent(code);
    if (refreshed) {
        setClassroom(refreshed.classroom);
        setForumPosts(refreshed.classroom.forumPosts || []);
    }

    setAssignments(classAssignments || []);
    setResults(studentResults || []);
    setNotes(classNotes || []);
    setMessages(msgs || []);
  };

  const groupedNotes = useMemo(() => {
      const groups: Record<string, SharedNote[]> = {};
      notes.forEach(note => {
          if (!groups[note.subject]) groups[note.subject] = [];
          groups[note.subject].push(note);
      });
      return groups;
  }, [notes]);

  const startQuiz = (assignment: Assignment) => {
    const pastAttempts = results.filter(r => r.assignmentId === assignment.id).length;
    if (pastAttempts >= 3) {
        alert("Maximum number of attempts (3) reached.");
        return;
    }
    setActiveAssignment(assignment);
    setCurrentQuestionIndex(0);
    setSelectedAnswers({});
    setTimePerQuestion({});
    const now = Date.now();
    setQuizStartTime(now);
    setQuestionStartTime(now);
    setQuizMode(true);
    if(window.innerWidth < 1024) setSidebarOpen(false);
  };

  const handleNextQuestion = () => {
      const now = Date.now();
      const timeSpent = (now - questionStartTime) / 1000;
      setTimePerQuestion(prev => ({ ...prev, [currentQuestionIndex]: (prev[currentQuestionIndex] || 0) + timeSpent }));
      setQuestionStartTime(now);
      setCurrentQuestionIndex(prev => prev + 1);
  };

  const submitQuiz = async () => {
      if (!student || !activeAssignment) return;
      const now = Date.now();
      const lastSpent = (now - questionStartTime) / 1000;
      const finalTPQ = { ...timePerQuestion, [currentQuestionIndex]: (timePerQuestion[currentQuestionIndex] || 0) + lastSpent };
      const totalTimeTaken = (now - quizStartTime) / 1000;
      setIsSubmitting(true);
      let score = 0;
      activeAssignment.questions.forEach((q, idx) => {
          const userAnswer = selectedAnswers[idx];
          if (userAnswer === q.correctAnswer) score++;
          else if (q.type === 'structured' && userAnswer?.toLowerCase().trim() === q.correctAnswer.toLowerCase().trim()) score++;
      });
      let aiReport = "";
      try {
          aiReport = await generateStudentPerformanceReport(activeAssignment, selectedAnswers, score, totalTimeTaken, finalTPQ);
      } catch (err) { aiReport = "Analysis could not be generated."; }
      const result: StudentResult = {
          id: crypto.randomUUID(), assignmentId: activeAssignment.id, studentCode: student.code, studentName: student.name || 'Student', score: score, total: activeAssignment.questions.length, attempts: 1, answers: selectedAnswers, dateTaken: new Date().toISOString(), timeTaken: totalTimeTaken, timePerQuestion: finalTPQ, aiAnalysis: aiReport
      };
      saveStudentResult(result);
      const submissionMsg: DirectMessage = {
          id: crypto.randomUUID(), senderId: student.code, senderName: student.name || 'Student', receiverId: classroom?.userId || '', content: `I submitted: ${activeAssignment.topic}. Score: ${score}/${activeAssignment.questions.length}.`, timestamp: new Date().toISOString(), read: false, isFromTeacher: false
      };
      if (classroom?.userId) sendDirectMessage(submissionMsg);
      if (classroom) loadStudentData(student.code, classroom.id);
      setIsSubmitting(false); setQuizMode(false); setActiveSection('results'); setActiveAssignment(null);
  };

  const handleSendMessage = (e: React.FormEvent) => {
      e.preventDefault();
      if (!newMessage.trim() || !student || !classroom) return;
      const msg: DirectMessage = { id: crypto.randomUUID(), senderId: student.code, senderName: student.name || 'Student', receiverId: classroom.userId, content: newMessage, timestamp: new Date().toISOString(), read: false, isFromTeacher: false };
      sendDirectMessage(msg);
      setNewMessage('');
      loadStudentData(student.code, classroom.id);
  };

  const handleForumReply = (postId: string) => {
      if (!newForumReply.trim() || !student || !classroom) return;
      const reply: ForumReply = { id: crypto.randomUUID(), authorName: student.name || 'Student', authorRole: 'student', content: newForumReply, timestamp: new Date().toISOString() };
      addForumReply(classroom.id, postId, reply);
      setNewForumReply('');
      loadStudentData(student.code, classroom.id);
  };

  if (view === 'login') return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-gray-50 font-sans">
      <div className="bg-white p-8 rounded-xl shadow-xl w-full max-w-md border border-gray-200">
        <div className="text-center mb-8">
          <div className="bg-teal-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4"><BookOpen className="w-8 h-8 text-teal-600" /></div>
          <h2 className="text-2xl font-bold text-gray-800">Student Portal</h2>
        </div>
        {student && !student.name ? (
          <form onSubmit={handleNameUpdate} className="space-y-6">
            <div className="bg-blue-50 p-4 rounded text-sm text-blue-700">Update your full name.</div>
            <input type="text" required className="w-full rounded border-gray-300 py-2.5 border px-3" value={studentName} onChange={e => setStudentName(e.target.value)} placeholder="Full Name" />
            <button type="submit" className="w-full bg-teal-600 text-white py-2.5 rounded hover:bg-teal-700">Update Profile</button>
          </form>
        ) : (
          <form onSubmit={handleLogin} className="space-y-6">
            {error && <div className="bg-red-50 text-red-700 p-3 rounded text-sm border border-red-200">{error}</div>}
            <input type="text" required className="w-full rounded border-gray-300 py-2.5 border px-3 text-center uppercase font-mono" value={accessCode} onChange={e => setAccessCode(e.target.value)} placeholder="XXXXXX" maxLength={6} />
            <button type="submit" className="w-full bg-teal-600 text-white py-2.5 rounded hover:bg-teal-700 flex justify-center items-center gap-2"><LogIn className="w-4 h-4" /> Enter</button>
          </form>
        )}
      </div>
    </div>
  );

  if (quizMode && activeAssignment) {
      const q = activeAssignment.questions[currentQuestionIndex];
      const progress = ((currentQuestionIndex + 1) / activeAssignment.questions.length) * 100;
      return (
        <div className="min-h-screen bg-gray-50 text-slate-800 font-sans pb-12">
          <div className="bg-white border-b border-gray-200 px-4 py-4 sticky top-0 z-10 shadow-sm"><div className="max-w-3xl mx-auto flex justify-between items-center"><div><h2 className="font-bold text-gray-800">{activeAssignment.topic}</h2></div><div className="text-sm font-medium text-gray-500">Question {currentQuestionIndex + 1} of {activeAssignment.questions.length}</div></div></div>
          <div className="w-full h-1 bg-gray-200"><div className="h-full bg-teal-600" style={{ width: `${progress}%` }}></div></div>
          <div className="max-w-3xl mx-auto p-6 mt-6">
            {isSubmitting ? (<div className="flex flex-col items-center justify-center py-20"><Loader2 className="w-12 h-12 text-teal-600 animate-spin mb-4" /><h3 className="text-xl font-bold text-gray-800">Submitting...</h3></div>) : (
              <>
                <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-8"><p className="text-lg font-medium text-gray-900 mb-6">{q.question}</p>{q.type === 'mcq' ? (<div className="space-y-3">{q.options?.map(opt => (<label key={opt} className={`flex items-center p-4 rounded-lg border cursor-pointer ${selectedAnswers[currentQuestionIndex] === opt ? 'border-teal-500 bg-teal-50' : 'border-gray-200'}`}><input type="radio" name="q" className="hidden" value={opt} checked={selectedAnswers[currentQuestionIndex] === opt} onChange={() => setSelectedAnswers({ ...selectedAnswers, [currentQuestionIndex]: opt })} /><span>{opt}</span></label>))}</div>) : (<textarea className="w-full p-4 rounded-lg border border-gray-300 min-h-[150px]" value={selectedAnswers[currentQuestionIndex] || ''} onChange={e => setSelectedAnswers({ ...selectedAnswers, [currentQuestionIndex]: e.target.value })} />)}</div>
                <div className="mt-8 flex justify-between items-center"><button onClick={() => setQuizMode(false)} className="text-gray-500">Quit</button><div className="flex gap-3">{currentQuestionIndex > 0 && <button onClick={() => setCurrentQuestionIndex(prev => prev - 1)} className="px-4 py-2 bg-white border rounded">Prev</button>}{currentQuestionIndex < activeAssignment.questions.length - 1 ? (<button onClick={handleNextQuestion} className="px-6 py-2 bg-teal-600 text-white rounded">Next</button>) : (<button onClick={submitQuiz} className="px-6 py-2 bg-green-600 text-white rounded">Submit</button>)}</div></div>
              </>
            )}
          </div>
        </div>
      );
  }

  const processedResults = useMemo(() => {
    const map = new Map<string, StudentResult>();
    // Handle potential duplicate result entries or missing data safely
    if (results) {
        results.forEach(r => { 
            const existing = map.get(r.assignmentId); 
            if (!existing || r.score > existing.score) map.set(r.assignmentId, r); 
        });
    }
    return Array.from(map.values()).sort((a,b) => new Date(b.dateTaken).getTime() - new Date(a.dateTaken).getTime());
  }, [results]);

  const SidebarItem = ({ id, icon: Icon, label, badgeCount }: any) => (
    <button onClick={() => { setActiveSection(id); if (id === 'forum') setHasViewedForum(true); if(window.innerWidth < 1024) setSidebarOpen(false); }} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors group relative ${activeSection === id ? 'bg-teal-600 text-white shadow-md' : 'text-slate-300 hover:bg-slate-800 hover:text-white'}`}>
        <Icon className={`w-5 h-5 flex-shrink-0 ${!isCollapsed && 'mr-3'}`} />
        {!isCollapsed && <span>{label}</span>}
        {badgeCount > 0 && <span className="ml-auto bg-red-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full">{badgeCount}</span>}
    </button>
  );

  return (
      <div className="flex min-h-screen bg-slate-50 font-sans text-slate-800">
          {sidebarOpen && (<div className="fixed inset-0 bg-black/50 z-40 lg:hidden" onClick={() => setSidebarOpen(false)}/>)}
          <aside className={`fixed inset-y-0 left-0 z-50 bg-slate-900 text-slate-300 transition-all duration-300 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 ${isCollapsed ? 'w-20' : 'w-64'} flex flex-col`}>
              <div className="flex items-center h-16 px-4 bg-slate-950 text-white font-bold text-xl tracking-tight border-b border-slate-800 justify-between">
                  {!isCollapsed ? (<div className="flex items-center"><BookOpen className="w-6 h-6 mr-2 text-teal-500" /><span>Portal</span></div>) : (<BookOpen className="w-8 h-8 text-teal-500" />)}
              </div>
              <nav className="flex-1 overflow-y-auto p-3 space-y-1">
                  <SidebarItem id="dashboard" icon={Home} label="Dashboard" />
                  <SidebarItem id="notes" icon={FileText} label="Notes" />
                  <SidebarItem id="textbooks" icon={Book} label="Books" />
                  <SidebarItem id="all_assignments" icon={List} label="Assignments" />
                  <SidebarItem id="pending" icon={Clock} label="Pending" badgeCount={pendingCount} />
                  <SidebarItem id="results" icon={BarChart2} label="Results" />
                  <SidebarItem id="inbox" icon={Mail} label="Inbox" badgeCount={unreadMsgCount} />
                  <SidebarItem id="forum" icon={MessageSquare} label="Forum" badgeCount={!hasViewedForum && forumPosts.length > 0 ? 1 : 0} />
                  <SidebarItem id="profile" icon={User} label="Profile" />
              </nav>
              <div className="p-4 border-t border-slate-800"><button onClick={() => setView('login')} className="flex items-center w-full px-4 py-2.5 text-sm font-medium rounded-lg text-red-400 hover:bg-slate-800"><LogOut className="w-5 h-5 mr-3" />{!isCollapsed && "Sign Out"}</button></div>
          </aside>
          <div className={`flex-1 flex flex-col transition-all duration-300 ${isCollapsed ? 'lg:ml-20' : 'lg:ml-64'}`}>
              <header className="h-16 bg-white border-b border-gray-200 flex items-center justify-between px-4 sticky top-0 z-40 shadow-sm">
                  <button onClick={() => setSidebarOpen(!sidebarOpen)} className="lg:hidden p-2 text-gray-500"><Menu className="w-6 h-6" /></button>
                  <h1 className="text-xl font-bold text-gray-800 hidden sm:block capitalize">{activeSection.replace('_', ' ')}</h1>
                  <div className="ml-auto flex items-center gap-4"><div className="text-right hidden md:block"><p className="text-sm font-bold text-gray-800">{student?.name}</p></div><div className="w-8 h-8 bg-teal-100 text-teal-700 rounded-full flex items-center justify-center font-bold">{student?.name?.charAt(0)}</div></div>
              </header>
              <main className="p-4 lg:p-8 max-w-7xl mx-auto w-full">
                  {activeSection === 'dashboard' && (<div className="space-y-6"><h2 className="text-2xl font-bold">Overview</h2><div className="grid grid-cols-1 md:grid-cols-3 gap-6"><div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm"><h3 className="font-bold">Pending</h3><p className="text-3xl font-black">{pendingCount}</p></div><div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm"><h3 className="font-bold">Completed</h3><p className="text-3xl font-black">{processedResults.length}</p></div></div></div>)}
                  {activeSection === 'notes' && (
                      <div className="space-y-8 animate-fade-in">
                          <h2 className="text-2xl font-bold text-gray-800">Lesson Notes</h2>
                          {Object.keys(groupedNotes).length === 0 ? (<p className="text-gray-500 italic">No notes.</p>) : (
                              Object.entries(groupedNotes).map(([subject, subjectNotes]: [string, SharedNote[]]) => (
                                  <div key={subject}><h3 className="text-lg font-bold text-teal-800 mb-4 flex items-center gap-2"><span className="w-2 h-8 bg-teal-500 rounded-full"></span>{subject}</h3><div className="grid grid-cols-1 md:grid-cols-2 gap-4">{subjectNotes.map(note => (<div key={note.id} className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition-shadow"><h4 className="font-bold text-lg text-gray-900 mb-2">{note.title}</h4><p className="text-sm text-gray-600 line-clamp-3 mb-4">{note.content.replace(/\*\*/g, '')}</p><button onClick={() => setSelectedNote(note)} className="text-teal-600 text-sm font-bold hover:underline flex items-center gap-1">Read Full <ChevronRight className="w-4 h-4"/></button></div>))}</div></div>
                              ))
                          )}
                      </div>
                  )}
                  {activeSection === 'textbooks' && (
                      <div className="space-y-6">
                          <h2 className="text-2xl font-bold text-gray-800">Class Textbooks</h2>
                          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                              {classroom?.textbooks && classroom.textbooks.length > 0 ? (
                                  classroom.textbooks.map(book => (
                                      <div key={book.id} className="bg-white p-4 rounded-xl border border-gray-200 flex items-start gap-3 shadow-sm hover:shadow-md transition-all">
                                          <div className="p-3 bg-red-50 text-red-600 rounded-lg shrink-0"><FileIcon className="w-6 h-6" /></div>
                                          <div className="flex-1 min-w-0">
                                              <h4 className="font-bold text-slate-700 truncate text-sm" title={book.title}>{book.title}</h4>
                                              <p className="text-xs text-gray-500 mt-1">{new Date(book.uploadDate).toLocaleDateString()}</p>
                                              <a href={book.fileData} download={book.title} className="text-xs text-teal-600 font-bold hover:underline mt-2 inline-flex items-center gap-1"><Download className="w-3 h-3"/> Download</a>
                                          </div>
                                      </div>
                                  ))
                              ) : (<p className="text-gray-500 italic">No textbooks available.</p>)}
                          </div>
                      </div>
                  )}
                  {(activeSection === 'all_assignments' || activeSection === 'pending' || activeSection === 'completed') && (
                      <div className="space-y-6">
                          <h2 className="text-2xl font-bold text-gray-800">Assignments</h2>
                          <div className="grid grid-cols-1 gap-4">
                              {safeAssignments
                                  .filter(a => activeSection === 'all_assignments' || (activeSection === 'pending' ? !safeResults.some(r => r.assignmentId === a.id) : safeResults.some(r => r.assignmentId === a.id)))
                                  .map(assign => {
                                      const isCompleted = safeResults.some(r => r.assignmentId === assign.id);
                                      return (
                                          <div key={assign.id} className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                                              <div>
                                                  <div className="flex items-center gap-2 mb-1">
                                                      <span className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded ${isCompleted ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-orange-700'}`}>{isCompleted ? 'Completed' : 'Pending'}</span>
                                                      <span className="text-xs text-gray-500">{new Date(assign.createdAt).toLocaleDateString()}</span>
                                                  </div>
                                                  <h4 className="text-lg font-bold text-gray-900">{assign.topic}</h4>
                                                  <p className="text-sm text-gray-600">{assign.subject} • {assign.questions.length} Questions</p>
                                              </div>
                                              {!isCompleted ? (
                                                  <button onClick={() => startQuiz(assign)} className="px-6 py-2 bg-teal-600 text-white rounded-lg font-bold hover:bg-teal-700 transition-colors flex items-center gap-2"><Play className="w-4 h-4"/> Start Quiz</button>
                                              ) : (
                                                  <div className="text-right">
                                                      <p className="text-2xl font-black text-slate-800">{safeResults.find(r => r.assignmentId === assign.id)?.score}/{assign.questions.length}</p>
                                                      <p className="text-xs text-gray-500 font-bold uppercase">Score</p>
                                                  </div>
                                              )}
                                          </div>
                                      );
                                  })
                              }
                              {safeAssignments.length === 0 && <p className="text-gray-500 italic">No assignments found.</p>}
                          </div>
                      </div>
                  )}
                  {activeSection === 'inbox' && (
                      <div className="h-[600px] bg-white rounded-xl border border-gray-200 flex flex-col shadow-sm overflow-hidden">
                          <div className="p-4 border-b border-gray-200 bg-gray-50 font-bold text-gray-700">Messages with Teacher</div>
                          <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-50">
                              {messages.length === 0 ? (
                                  <div className="flex flex-col items-center justify-center h-full text-gray-400">
                                      <MessageCircle className="w-12 h-12 mb-2 opacity-20" />
                                      <p>No messages yet.</p>
                                  </div>
                              ) : (
                                  messages.map(msg => (
                                      <div key={msg.id} className={`flex ${msg.senderId === student?.code ? 'justify-end' : 'justify-start'}`}>
                                          <div className={`max-w-[75%] p-3 rounded-xl text-sm shadow-sm ${msg.senderId === student?.code ? 'bg-teal-600 text-white rounded-br-none' : 'bg-white text-gray-800 border border-gray-200 rounded-bl-none'}`}>
                                              <p>{msg.content}</p>
                                              <p className={`text-[10px] mt-1 text-right ${msg.senderId === student?.code ? 'text-teal-200' : 'text-gray-400'}`}>{new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                                          </div>
                                      </div>
                                  ))
                              )}
                          </div>
                          <form onSubmit={handleSendMessage} className="p-4 bg-white border-t border-gray-200 flex gap-2">
                              <input type="text" className="flex-1 border border-gray-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-teal-500 focus:border-transparent outline-none transition-shadow" placeholder="Type a message..." value={newMessage} onChange={e => setNewMessage(e.target.value)} />
                              <button type="submit" className="bg-teal-600 text-white p-2 rounded-lg hover:bg-teal-700 transition-colors"><Send className="w-5 h-5" /></button>
                          </form>
                      </div>
                  )}
                  {activeSection === 'forum' && (
                      <div className="space-y-6">
                          <h2 className="text-2xl font-bold text-gray-800">Class Forum</h2>
                          <div className="space-y-4">
                              {forumPosts.length === 0 ? <p className="text-gray-500 italic p-8 text-center bg-white rounded-xl border border-dashed border-gray-300">No discussions yet.</p> : forumPosts.map(post => (
                                  <div key={post.id} className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                                      <div className="p-6 border-b border-gray-100">
                                          <h3 className="font-bold text-lg text-teal-900 mb-1">{post.title}</h3>
                                          <p className="text-xs text-gray-500 mb-3 flex items-center gap-2"><User className="w-3 h-3"/> {post.authorName} • {new Date(post.timestamp).toLocaleDateString()}</p>
                                          <p className="text-gray-700 leading-relaxed text-sm">{post.content}</p>
                                      </div>
                                      <div className="bg-gray-50 p-4">
                                          {post.replies.length > 0 && (
                                              <div className="space-y-3 mb-4">
                                                  {post.replies.map(reply => (
                                                      <div key={reply.id} className="bg-white p-3 rounded border border-gray-200 text-sm shadow-sm">
                                                          <span className={`font-bold text-xs block mb-1 ${reply.authorRole === 'teacher' ? 'text-teal-600' : 'text-blue-600'}`}>{reply.authorName} <span className="text-gray-400 font-normal">• {new Date(reply.timestamp).toLocaleDateString()}</span></span>
                                                          <p className="text-gray-600">{reply.content}</p>
                                                      </div>
                                                  ))}
                                              </div>
                                          )}
                                          {activeForumPostId === post.id ? (
                                              <div className="flex gap-2">
                                                  <input type="text" className="flex-1 border rounded px-3 py-2 text-sm" placeholder="Write a reply..." value={newForumReply} onChange={e => setNewForumReply(e.target.value)} />
                                                  <button onClick={() => handleForumReply(post.id)} className="bg-teal-600 text-white px-4 py-2 rounded text-xs font-bold">Reply</button>
                                                  <button onClick={() => setActiveForumPostId(null)} className="text-gray-500 text-xs">Cancel</button>
                                              </div>
                                          ) : (
                                              <button onClick={() => setActiveForumPostId(post.id)} className="text-teal-600 text-xs font-bold hover:underline flex items-center gap-1"><Reply className="w-3 h-3"/> Reply</button>
                                          )}
                                      </div>
                                  </div>
                              ))}
                          </div>
                      </div>
                  )}
                  {activeSection === 'profile' && student && classroom && (
                      <div className="max-w-md mx-auto bg-white rounded-xl shadow-md border border-gray-200 overflow-hidden">
                          <div className="bg-slate-900 p-6 text-center">
                              <div className="w-20 h-20 bg-teal-500 rounded-full flex items-center justify-center text-white text-3xl font-bold mx-auto mb-3 shadow-lg border-4 border-slate-800">{student.name?.charAt(0)}</div>
                              <h2 className="text-white font-bold text-xl">{student.name}</h2>
                              <p className="text-teal-200 text-sm">{student.code}</p>
                          </div>
                          <div className="p-6 space-y-4">
                              <div className="flex justify-between border-b py-2"><span className="text-gray-500 text-sm">Class</span><span className="font-bold text-gray-800">{classroom.grade} - {classroom.stream}</span></div>
                              <div className="flex justify-between border-b py-2"><span className="text-gray-500 text-sm">School Code</span><span className="font-bold text-gray-800 font-mono">{classroom.schoolId ? 'Registered' : 'N/A'}</span></div>
                              <div className="flex justify-between border-b py-2"><span className="text-gray-500 text-sm">Assignments</span><span className="font-bold text-gray-800">{processedResults.length} Completed</span></div>
                          </div>
                      </div>
                  )}
                  {activeSection === 'results' && (<div className="bg-white rounded-xl border border-gray-200 overflow-hidden"><table className="w-full text-sm text-left"><thead className="bg-gray-50 border-b"><tr><th className="px-6 py-4">Assignment</th><th className="px-6 py-4">Score</th><th className="px-6 py-4">Feedback</th></tr></thead><tbody className="divide-y">{processedResults.map(r => (<tr key={r.id} className="hover:bg-gray-50"><td className="px-6 py-4">{assignments.find(a=>a.id===r.assignmentId)?.topic}</td><td className="px-6 py-4"><span className="font-bold">{r.score}/{r.total}</span></td><td className="px-6 py-4 italic text-gray-500">{r.feedback || 'None'}</td></tr>))}</tbody></table></div>)}
              </main>
          </div>
          {selectedNote && (
              <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"><div className="bg-white rounded-xl shadow-xl w-full max-w-2xl max-h-[80vh] overflow-hidden flex flex-col animate-fade-in-up"><div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white shrink-0"><h3 className="font-bold text-lg">{selectedNote.title}</h3><button onClick={() => setSelectedNote(null)}><X className="w-5 h-5" /></button></div><div className="p-6 overflow-y-auto whitespace-pre-wrap">{selectedNote.content}</div></div></div>
          )}
      </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import { Student, Classroom, Assignment, StudentResult, SharedNote, DirectMessage, ForumPost, ForumReply } from '../types';
import { 
    authenticateStudent, updateStudentName, getAssignmentsByClassId, getStudentResults, 
    saveStudentResult, getStudentNotes, getDirectMessages, sendDirectMessage, markMessagesRead, 
    addForumReply
} from '../services/storageService';
import { generateStudentPerformanceReport } from '../services/geminiService';
import { 
    LogIn, BookOpen, Clock, ChevronRight, FileText, Play, 
    Loader2, Menu, Home, Book, List, BarChart2, Mail, MessageSquare, 
    User, LogOut, X, Send, Reply, Download, FileIcon, MessageCircle
} from 'lucide-react';

export default function StudentPortal() {
  const [view, setView] = useState<'login' | 'portal'>('login');
  const [accessCode, setAccessCode] = useState('');
  const [student, setStudent] = useState<Student | null>(null);
  const [classroom, setClassroom] = useState<Classroom | null>(null);
  const [studentName, setStudentName] = useState('');
  const [error, setError] = useState<string | null>(null);

  const [activeSection, setActiveSection] = useState<'dashboard' | 'notes' | 'textbooks' | 'all_assignments' | 'pending' | 'completed' | 'results' | 'inbox' | 'forum' | 'profile'>('dashboard');
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [isCollapsed, setIsCollapsed] = useState(false);

  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [results, setResults] = useState<StudentResult[]>([]);
  const [notes, setNotes] = useState<SharedNote[]>([]);
  const [messages, setMessages] = useState<DirectMessage[]>([]);
  const [forumPosts, setForumPosts] = useState<ForumPost[]>([]);

  const [selectedNote, setSelectedNote] = useState<SharedNote | null>(null);
  const [quizMode, setQuizMode] = useState(false);
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswers, setSelectedAnswers] = useState<Record<number, string>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [quizStartTime, setQuizStartTime] = useState<number>(0);
  const [questionStartTime, setQuestionStartTime] = useState<number>(0);
  const [timePerQuestion, setTimePerQuestion] = useState<Record<number, number>>({});
  const [newMessage, setNewMessage] = useState('');
  const [newForumReply, setNewForumReply] = useState('');
  const [activeForumPostId, setActiveForumPostId] = useState<string | null>(null);
  const [hasViewedForum, setHasViewedForum] = useState(false);

  // Safe checks for array methods to prevent crashes
  const safeAssignments = assignments || [];
  const safeResults = results || [];
  const safeMessages = messages || [];

  const pendingCount = safeAssignments.filter(a => !safeResults.some(r => r.assignmentId === a.id)).length;
  const unreadMsgCount = safeMessages.filter(m => !m.read && m.receiverId === student?.code).length;

  useEffect(() => {
      if (student && view === 'portal') {
          if (classroom) loadStudentData(student.code, classroom.id);
          const interval = setInterval(() => {
              if (classroom) loadStudentData(student.code, classroom.id);
          }, 10000);
          return () => clearInterval(interval);
      }
  }, [student, view, classroom]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    if (!accessCode) return;
    const result = authenticateStudent(accessCode.toUpperCase());
    if (result) {
      setStudent(result.student);
      setClassroom(result.classroom);
      loadStudentData(result.student.code, result.classroom.id);
      if (result.student.name) {
        setView('portal');
      }
    } else setError("Invalid Access Code.");
  };

  const handleNameUpdate = (e: React.FormEvent) => {
    e.preventDefault();
    if (student && classroom && studentName.trim()) {
      const updated = updateStudentName(classroom.id, student.code, studentName);
      if (updated) {
        setStudent(updated);
        loadStudentData(updated.code, classroom.id);
        setView('portal');
      }
    }
  };

  const loadStudentData = (code: string, classId: string) => {
    const classAssignments = getAssignmentsByClassId(classId);
    const studentResults = getStudentResults(code);
    const classNotes = getStudentNotes(classId);
    const msgs = getDirectMessages(code);
    const refreshed = authenticateStudent(code);
    if (refreshed) {
        setClassroom(refreshed.classroom);
        setForumPosts(refreshed.classroom.forumPosts || []);
    }
    setAssignments(classAssignments || []);
    setResults(studentResults || []);
    setNotes(classNotes || []);
    setMessages(msgs || []);
  };

  const groupedNotes = useMemo(() => {
      const groups: Record<string, SharedNote[]> = {};
      notes.forEach(note => {
          if (!groups[note.subject]) groups[note.subject] = [];
          groups[note.subject].push(note);
      });
      return groups;
  }, [notes]);

  const startQuiz = (assignment: Assignment) => {
    const pastAttempts = results.filter(r => r.assignmentId === assignment.id).length;
    if (pastAttempts >= 3) {
        alert("Maximum number of attempts (3) reached.");
        return;
    }
    setActiveAssignment(assignment);
    setCurrentQuestionIndex(0);
    setSelectedAnswers({});
    setTimePerQuestion({});
    const now = Date.now();
    setQuizStartTime(now);
    setQuestionStartTime(now);
    setQuizMode(true);
    if(window.innerWidth < 1024) setSidebarOpen(false);
  };

  const handleNextQuestion = () => {
      const now = Date.now();
      const timeSpent = (now - questionStartTime) / 1000;
      setTimePerQuestion(prev => ({ ...prev, [currentQuestionIndex]: (prev[currentQuestionIndex] || 0) + timeSpent }));
      setQuestionStartTime(now);
      setCurrentQuestionIndex(prev => prev + 1);
  };

  const submitQuiz = async () => {
      if (!student || !activeAssignment) return;
      const now = Date.now();
      const lastSpent = (now - questionStartTime) / 1000;
      const finalTPQ = { ...timePerQuestion, [currentQuestionIndex]: (timePerQuestion[currentQuestionIndex] || 0) + lastSpent };
      const totalTimeTaken = (now - quizStartTime) / 1000;
      setIsSubmitting(true);
      let score = 0;
      activeAssignment.questions.forEach((q, idx) => {
          const userAnswer = selectedAnswers[idx];
          if (userAnswer === q.correctAnswer) score++;
          else if (q.type === 'structured' && userAnswer?.toLowerCase().trim() === q.correctAnswer.toLowerCase().trim()) score++;
      });
      let aiReport = "";
      try {
          aiReport = await generateStudentPerformanceReport(activeAssignment, selectedAnswers, score, totalTimeTaken, finalTPQ);
      } catch (err) { aiReport = "Analysis could not be generated."; }
      const result: StudentResult = {
          id: crypto.randomUUID(), assignmentId: activeAssignment.id, studentCode: student.code, studentName: student.name || 'Student', score: score, total: activeAssignment.questions.length, attempts: 1, answers: selectedAnswers, dateTaken: new Date().toISOString(), timeTaken: totalTimeTaken, timePerQuestion: finalTPQ, aiAnalysis: aiReport
      };
      saveStudentResult(result);
      const submissionMsg: DirectMessage = {
          id: crypto.randomUUID(), senderId: student.code, senderName: student.name || 'Student', receiverId: classroom?.userId || '', content: `I submitted: ${activeAssignment.topic}. Score: ${score}/${activeAssignment.questions.length}.`, timestamp: new Date().toISOString(), read: false, isFromTeacher: false
      };
      if (classroom?.userId) sendDirectMessage(submissionMsg);
      if (classroom) loadStudentData(student.code, classroom.id);
      setIsSubmitting(false); setQuizMode(false); setActiveSection('results'); setActiveAssignment(null);
  };

  const handleSendMessage = (e: React.FormEvent) => {
      e.preventDefault();
      if (!newMessage.trim() || !student || !classroom) return;
      const msg: DirectMessage = { id: crypto.randomUUID(), senderId: student.code, senderName: student.name || 'Student', receiverId: classroom.userId, content: newMessage, timestamp: new Date().toISOString(), read: false, isFromTeacher: false };
      sendDirectMessage(msg);
      setNewMessage('');
      loadStudentData(student.code, classroom.id);
  };

  const handleForumReply = (postId: string) => {
      if (!newForumReply.trim() || !student || !classroom) return;
      const reply: ForumReply = { id: crypto.randomUUID(), authorName: student.name || 'Student', authorRole: 'student', content: newForumReply, timestamp: new Date().toISOString() };
      addForumReply(classroom.id, postId, reply);
      setNewForumReply('');
      loadStudentData(student.code, classroom.id);
  };

  if (view === 'login') return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-gray-50 font-sans">
      <div className="bg-white p-8 rounded-xl shadow-xl w-full max-w-md border border-gray-200">
        <div className="text-center mb-8">
          <div className="bg-teal-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4"><BookOpen className="w-8 h-8 text-teal-600" /></div>
          <h2 className="text-2xl font-bold text-gray-800">Student Portal</h2>
        </div>
        {student && !student.name ? (
          <form onSubmit={handleNameUpdate} className="space-y-6">
            <div className="bg-blue-50 p-4 rounded text-sm text-blue-700">Update your full name.</div>
            <input type="text" required className="w-full rounded border-gray-300 py-2.5 border px-3" value={studentName} onChange={e => setStudentName(e.target.value)} placeholder="Full Name" />
            <button type="submit" className="w-full bg-teal-600 text-white py-2.5 rounded hover:bg-teal-700">Update Profile</button>
          </form>
        ) : (
          <form onSubmit={handleLogin} className="space-y-6">
            {error && <div className="bg-red-50 text-red-700 p-3 rounded text-sm border border-red-200">{error}</div>}
            <input type="text" required className="w-full rounded border-gray-300 py-2.5 border px-3 text-center uppercase font-mono" value={accessCode} onChange={e => setAccessCode(e.target.value)} placeholder="XXXXXX" maxLength={6} />
            <button type="submit" className="w-full bg-teal-600 text-white py-2.5 rounded hover:bg-teal-700 flex justify-center items-center gap-2"><LogIn className="w-4 h-4" /> Enter</button>
          </form>
        )}
      </div>
    </div>
  );

  if (quizMode && activeAssignment) {
      const q = activeAssignment.questions[currentQuestionIndex];
      const progress = ((currentQuestionIndex + 1) / activeAssignment.questions.length) * 100;
      return (
        <div className="min-h-screen bg-gray-50 text-slate-800 font-sans pb-12">
          <div className="bg-white border-b border-gray-200 px-4 py-4 sticky top-0 z-10 shadow-sm"><div className="max-w-3xl mx-auto flex justify-between items-center"><div><h2 className="font-bold text-gray-800">{activeAssignment.topic}</h2></div><div className="text-sm font-medium text-gray-500">Question {currentQuestionIndex + 1} of {activeAssignment.questions.length}</div></div></div>
          <div className="w-full h-1 bg-gray-200"><div className="h-full bg-teal-600" style={{ width: `${progress}%` }}></div></div>
          <div className="max-w-3xl mx-auto p-6 mt-6">
            {isSubmitting ? (<div className="flex flex-col items-center justify-center py-20"><Loader2 className="w-12 h-12 text-teal-600 animate-spin mb-4" /><h3 className="text-xl font-bold text-gray-800">Submitting...</h3></div>) : (
              <>
                <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-8"><p className="text-lg font-medium text-gray-900 mb-6">{q.question}</p>{q.type === 'mcq' ? (<div className="space-y-3">{q.options?.map(opt => (<label key={opt} className={`flex items-center p-4 rounded-lg border cursor-pointer ${selectedAnswers[currentQuestionIndex] === opt ? 'border-teal-500 bg-teal-50' : 'border-gray-200'}`}><input type="radio" name="q" className="hidden" value={opt} checked={selectedAnswers[currentQuestionIndex] === opt} onChange={() => setSelectedAnswers({ ...selectedAnswers, [currentQuestionIndex]: opt })} /><span>{opt}</span></label>))}</div>) : (<textarea className="w-full p-4 rounded-lg border border-gray-300 min-h-[150px]" value={selectedAnswers[currentQuestionIndex] || ''} onChange={e => setSelectedAnswers({ ...selectedAnswers, [currentQuestionIndex]: e.target.value })} />)}</div>
                <div className="mt-8 flex justify-between items-center"><button onClick={() => setQuizMode(false)} className="text-gray-500">Quit</button><div className="flex gap-3">{currentQuestionIndex > 0 && <button onClick={() => setCurrentQuestionIndex(prev => prev - 1)} className="px-4 py-2 bg-white border rounded">Prev</button>}{currentQuestionIndex < activeAssignment.questions.length - 1 ? (<button onClick={handleNextQuestion} className="px-6 py-2 bg-teal-600 text-white rounded">Next</button>) : (<button onClick={submitQuiz} className="px-6 py-2 bg-green-600 text-white rounded">Submit</button>)}</div></div>
              </>
            )}
          </div>
        </div>
      );
  }

  const processedResults = useMemo(() => {
    const map = new Map<string, StudentResult>();
    if (results) {
        results.forEach(r => { 
            const existing = map.get(r.assignmentId); 
            if (!existing || r.score > existing.score) map.set(r.assignmentId, r); 
        });
    }
    return Array.from(map.values()).sort((a,b) => new Date(b.dateTaken).getTime() - new Date(a.dateTaken).getTime());
  }, [results]);

  const SidebarItem = ({ id, icon: Icon, label, badgeCount }: any) => (
    <button onClick={() => { setActiveSection(id); if (id === 'forum') setHasViewedForum(true); if(window.innerWidth < 1024) setSidebarOpen(false); }} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg transition-colors group relative ${activeSection === id ? 'bg-teal-600 text-white shadow-md' : 'text-slate-300 hover:bg-slate-800 hover:text-white'}`}>
        <Icon className={`w-5 h-5 flex-shrink-0 ${!isCollapsed && 'mr-3'}`} />
        {!isCollapsed && <span>{label}</span>}
        {badgeCount > 0 && <span className="ml-auto bg-red-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-full">{badgeCount}</span>}
    </button>
  );

  return (
      <div className="flex min-h-screen bg-slate-50 font-sans text-slate-800">
          {sidebarOpen && (<div className="fixed inset-0 bg-black/50 z-40 lg:hidden" onClick={() => setSidebarOpen(false)}/>)}
          <aside className={`fixed inset-y-0 left-0 z-50 bg-slate-900 text-slate-300 transition-all duration-300 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 ${isCollapsed ? 'w-20' : 'w-64'} flex flex-col`}>
              <div className="flex items-center h-16 px-4 bg-slate-950 text-white font-bold text-xl tracking-tight border-b border-slate-800 justify-between">
                  {!isCollapsed ? (<div className="flex items-center"><BookOpen className="w-6 h-6 mr-2 text-teal-500" /><span>Portal</span></div>) : (<BookOpen className="w-8 h-8 text-teal-500" />)}
              </div>
              <nav className="flex-1 overflow-y-auto p-3 space-y-1">
                  <SidebarItem id="dashboard" icon={Home} label="Dashboard" />
                  <SidebarItem id="notes" icon={FileText} label="Notes" />
                  <SidebarItem id="textbooks" icon={Book} label="Books" />
                  <SidebarItem id="all_assignments" icon={List} label="Assignments" />
                  <SidebarItem id="pending" icon={Clock} label="Pending" badgeCount={pendingCount} />
                  <SidebarItem id="results" icon={BarChart2} label="Results" />
