                                <tbody className="divide-y divide-gray-50">
                                    {classrooms.find(c=>c.id===selectedClassId)?.students.map(s=>(
                                        <tr key={s.code} className="hover:bg-slate-50 transition-colors">
                                            <td className="px-8 py-5 font-mono font-bold text-indigo-700">{s.code}</td>
                                            <td className="px-8 py-5 italic text-slate-600">{s.name || 'Account Pending Update'}</td>
                                            <td className="px-8 py-5 text-right">
                                                <button onClick={()=>handleDeleteStudent(selectedClassId, s.code)} className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors">
                                                    <Trash2 className="w-4 h-4" />
                                                </button>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    ) : (
                        <div className="text-center py-32 bg-white rounded-3xl border-2 border-dashed border-gray-200 shadow-sm">
                            <Users className="w-16 h-16 mx-auto mb-4 text-gray-200" />
                            <p className="text-gray-400 font-bold uppercase tracking-widest">Select a classroom above to manage the student roster</p>
                        </div>
                    )}
                </div>
            )}
        </div>

        {/* --- MODALS --- */}

        {/* Link Teacher Modal */}
        {showLinkTeacher && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
                <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-fade-in-up">
                    <div className="bg-indigo-900 px-8 py-6 text-white flex justify-between items-center">
                        <h3 className="font-black text-xl uppercase tracking-tight">Link Teacher</h3>
                        <button onClick={()=>setShowLinkTeacher(false)}><X className="w-6 h-6"/></button>
                    </div>
                    <form onSubmit={handleLinkTeacher} className="p-8 space-y-6">
                        <p className="text-slate-500 text-sm leading-relaxed">Enter the 6-character <strong>Teacher Code</strong> provided by the teacher to link their existing account to your school.</p>
                        <div>
                            <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Teacher Code</label>
                            <input 
                                type="text" required maxLength={6}
                                value={teacherCode} onChange={e=>setTeacherCode(e.target.value)}
                                className="w-full bg-slate-50 border border-gray-200 rounded-2xl p-5 text-2xl font-black text-center text-indigo-700 font-mono tracking-[0.5em] outline-none focus:ring-4 focus:ring-indigo-500/20" 
                                placeholder="XXXXXX"
                            />
                        </div>
                        <button type="submit" className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-5 rounded-2xl font-bold shadow-lg transition-all active:scale-[0.98]">
                            Link Faculty Member
                        </button>
                    </form>
                </div>
            </div>
        )}

        {/* Create Teacher Modal */}
        {showCreateTeacher && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
                <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-fade-in-up">
                    <div className="bg-teal-700 px-8 py-6 text-white flex justify-between items-center">
                        <h3 className="font-black text-xl uppercase tracking-tight">Create Faculty Account</h3>
                        <button onClick={()=>setShowCreateTeacher(false)}><X className="w-6 h-6"/></button>
                    </div>
                    <form onSubmit={handleCreateTeacher} className="p-8 space-y-4">
                        <div className="grid grid-cols-1 gap-4">
                            <div><label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Full Name</label><input type="text" required value={newTeacherForm.name} onChange={e=>setNewTeacherForm({...newTeacherForm, name: e.target.value})} className="w-full bg-slate-50 border border-gray-200 rounded-xl p-3 text-sm outline-none focus:ring-2 focus:ring-teal-500" placeholder="e.g. John Doe"/></div>
                            <div><label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Email Address</label><input type="email" required value={newTeacherForm.email} onChange={e=>setNewTeacherForm({...newTeacherForm, email: e.target.value})} className="w-full bg-slate-50 border border-gray-200 rounded-xl p-3 text-sm outline-none focus:ring-2 focus:ring-teal-500" placeholder="teacher@school.com"/></div>
                            <div><label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Phone Number</label><input type="tel" required value={newTeacherForm.phone} onChange={e=>setNewTeacherForm({...newTeacherForm, phone: e.target.value})} className="w-full bg-slate-50 border border-gray-200 rounded-xl p-3 text-sm outline-none focus:ring-2 focus:ring-teal-500" placeholder="07..."/></div>
                            <div><label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Initial Password</label><input type="password" required minLength={6} value={newTeacherForm.password} onChange={e=>setNewTeacherForm({...newTeacherForm, password: e.target.value})} className="w-full bg-slate-50 border border-gray-200 rounded-xl p-3 text-sm outline-none focus:ring-2 focus:ring-teal-500" placeholder="Min 6 chars"/></div>
                        </div>
                        <button type="submit" className="w-full bg-teal-600 hover:bg-teal-700 text-white py-4 rounded-xl font-bold shadow-lg transition-all mt-4">
                            Register Teacher
                        </button>
                    </form>
                </div>
            </div>
        )}

        {/* Add Class Modal */}
        {showAddClass && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
                <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-fade-in-up">
                    <div className="bg-indigo-900 px-8 py-6 text-white flex justify-between items-center">
                        <h3 className="font-black text-xl uppercase tracking-tight">New Classroom</h3>
                        <button onClick={()=>setShowAddClass(false)}><X className="w-6 h-6"/></button>
                    </div>
                    <form onSubmit={handleCreateClass} className="p-8 space-y-5">
                        <div>
                            <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Grade Level</label>
                            <select 
                                value={newClassData.grade} 
                                onChange={e=>setNewClassData({...newClassData, grade: e.target.value as Grade})} 
                                className="w-full bg-slate-50 border border-gray-200 rounded-xl p-4 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                            >
                                {Object.values(Grade).map(g => <option key={g} value={g}>{g}</option>)}
                            </select>
                        </div>
                        <div><label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Stream / Name</label><input type="text" required placeholder="e.g. Blue, North, 7A" value={newClassData.stream} onChange={e=>setNewClassData({...newClassData, stream: e.target.value})} className="w-full bg-slate-50 border border-gray-200 rounded-xl p-4 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"/></div>
                        <div>
                            <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Assign Teacher</label>
                            <select 
                                value={newClassData.teacherId} 
                                onChange={e=>setNewClassData({...newClassData, teacherId: e.target.value})} 
                                className="w-full bg-slate-50 border border-gray-200 rounded-xl p-4 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"
                            >
                                <option value="">-- Select Teacher --</option>
                                {teachers.map(t => <option key={t.id} value={t.email}>{t.name}</option>)}
                            </select>
                        </div>
                        <div><label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Starting Student Roll</label><input type="number" min="1" max="100" value={newClassData.roll} onChange={e=>setNewClassData({...newClassData, roll: parseInt(e.target.value) || 40})} className="w-full bg-slate-50 border border-gray-200 rounded-xl p-4 text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500"/></div>
                        <button type="submit" className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-5 rounded-2xl font-bold shadow-lg transition-all active:scale-[0.98]">
                            Generate Classroom
                        </button>
                    </form>
                </div>
            </div>
        )}
    </div>
  );
};

export default SchoolDashboard;

import React, { useState, useEffect } from 'react';
import { UserProfile, Classroom, Grade, Subject, Student, LessonPlanData, LessonPlanComment } from '../types';
import { 
    getClassrooms, createClassroom, getSchoolTeachers, linkTeacherToSchool, createTeacherAccount,
    addStudentsToClassroom, updateStudentName, getTeacherPlans, deleteStudentFromClassroom, addCommentToPlan,
    deleteClassroom
} from '../services/storageService';
import LessonPlanDisplay from './LessonPlanDisplay';
// Added missing FileText and Home imports
import { 
    Users, BookOpen, UserPlus, Plus, GraduationCap, School as SchoolIcon, 
    ChevronRight, Copy, Check, Search, Mail, Phone, Lock, Eye, Trash2, Link, ArrowLeft, MessageSquare, Send, X, FileText, Home
} from 'lucide-react';

interface Props {
  profile: UserProfile;
}

const SchoolDashboard: React.FC<Props> = ({ profile }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'teachers' | 'classes' | 'students'>('overview');
  const [teachers, setTeachers] = useState<UserProfile[]>([]);
  const [classrooms, setClassrooms] = useState<Classroom[]>([]);

  const [showLinkTeacher, setShowLinkTeacher] = useState(false);
  const [showCreateTeacher, setShowCreateTeacher] = useState(false);
  const [teacherCode, setTeacherCode] = useState('');
  const [newTeacherForm, setNewTeacherForm] = useState({ name: '', email: '', phone: '', password: '' });

  const [showAddClass, setShowAddClass] = useState(false);
  const [newClassData, setNewClassData] = useState({ grade: Grade.GRADE_7, stream: '', teacherId: '', roll: 40 });

  const [selectedClassId, setSelectedClassId] = useState<string | null>(null);
  const [bulkStudentCount, setBulkStudentCount] = useState(5);

  const [selectedTeacher, setSelectedTeacher] = useState<UserProfile | null>(null);
  const [selectedPlan, setSelectedPlan] = useState<LessonPlanData | null>(null);
  const [newComment, setNewComment] = useState('');

  useEffect(() => { loadData(); }, [profile.schoolId]);

  const loadData = () => {
      if (profile.schoolId) {
          setTeachers(getSchoolTeachers(profile.schoolId));
          setClassrooms(getClassrooms());
      }
  };

  const handleLinkTeacher = (e: React.FormEvent) => {
      e.preventDefault();
      try {
          if (profile.schoolId) {
            linkTeacherToSchool(profile.schoolId, teacherCode.toUpperCase());
            setShowLinkTeacher(false); 
            setTeacherCode('');
            loadData(); 
            alert("Teacher linked successfully!");
          }
      } catch (e: any) { alert(e.message); }
  };

  const handleCreateTeacher = (e: React.FormEvent) => {
      e.preventDefault();
      if (profile.schoolId) {
          createTeacherAccount(profile.schoolId, newTeacherForm.name, newTeacherForm.email, newTeacherForm.phone, newTeacherForm.password);
          setShowCreateTeacher(false); 
          setNewTeacherForm({ name: '', email: '', phone: '', password: '' });
          loadData(); 
          alert("Teacher account created!");
      }
  };

  const handleCreateClass = (e: React.FormEvent) => {
      e.preventDefault();
      createClassroom(newClassData.grade, newClassData.stream, newClassData.roll, newClassData.teacherId);
      setShowAddClass(false); 
      setNewClassData({ grade: Grade.GRADE_7, stream: '', teacherId: '', roll: 40 });
      loadData();
  };

  const handleDeleteClass = (id: string) => {
      if (confirm("Delete this class? All associated student records and assignments will be removed.")) {
          deleteClassroom(id);
          loadData();
      }
  };

  const handleAddBulkStudents = (classId: string) => {
      if (bulkStudentCount > 0) {
          addStudentsToClassroom(classId, bulkStudentCount);
          loadData(); 
          setBulkStudentCount(5);
      }
  };

  const handleDeleteStudent = (classId: string, studentCode: string) => {
      if (confirm("Remove this student from the class?")) {
          deleteStudentFromClassroom(classId, studentCode);
          loadData();
      }
  };

  const handleAddComment = () => {
      if (!selectedPlan || !selectedPlan.id || !newComment.trim()) return;
      const comment: LessonPlanComment = { 
          id: crypto.randomUUID(), 
          authorName: profile.name, 
          date: new Date().toISOString(), 
          content: newComment 
      };
      addCommentToPlan(selectedPlan.id, comment);
      setNewComment('');
      setSelectedPlan({ ...selectedPlan, adminComments: [...(selectedPlan.adminComments || []), comment] });
  };

  const totalStudents = classrooms.reduce((acc, c) => acc + c.students.length, 0);

  if (selectedPlan) {
      return (
          <div className="min-h-screen bg-gray-100 flex flex-col">
              <div className="bg-white border-b px-6 py-4 sticky top-0 z-40 flex items-center justify-between shadow-sm">
                  <button onClick={() => setSelectedPlan(null)} className="flex items-center text-slate-600 font-bold hover:text-teal-600 transition-colors">
                      <ArrowLeft className="w-5 h-5 mr-2" /> Back to Dashboard
                  </button>
                  <h2 className="font-bold text-slate-800 hidden md:block">{selectedPlan.topic}</h2>
                  <div className="w-24"></div>
              </div>
              <div className="flex-1 overflow-y-auto">
                  <div className="flex flex-col lg:flex-row max-w-7xl mx-auto gap-8 p-6">
                      <div className="flex-1 bg-white rounded-2xl shadow-lg border border-gray-200 overflow-hidden">
                          <LessonPlanDisplay plan={selectedPlan} onBack={() => setSelectedPlan(null)} />
                      </div>
                      <div className="w-full lg:w-96 shrink-0 space-y-6">
                          <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-200">
                              <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                                  <MessageSquare className="w-5 h-5 text-teal-600" /> Admin Feedback
                              </h3>
                              <div className="space-y-4 max-h-[500px] overflow-y-auto mb-6 pr-2">
                                  {selectedPlan.adminComments?.length ? selectedPlan.adminComments.map(c => (
                                      <div key={c.id} className="bg-slate-50 p-4 rounded-xl text-sm border border-slate-100 shadow-sm">
                                          <div className="flex justify-between items-center mb-2">
                                              <span className="font-bold text-teal-700">{c.authorName}</span>
                                              <span className="text-[10px] text-gray-400">{new Date(c.date).toLocaleDateString()}</span>
                                          </div>
                                          <p className="text-slate-600 leading-relaxed">{c.content}</p>
                                      </div>
                                  )) : (
                                      <div className="text-center py-10 text-gray-400 italic">No feedback comments yet.</div>
                                  )}
                              </div>
                              <div className="relative">
                                  <textarea 
                                      className="w-full p-4 border border-gray-200 rounded-xl mb-3 text-sm focus:ring-2 focus:ring-teal-500 focus:border-transparent outline-none transition-all" 
                                      rows={4} 
                                      value={newComment} 
                                      onChange={e=>setNewComment(e.target.value)} 
                                      placeholder="Write your review or instructions for the teacher..." 
                                  />
                                  <button 
                                      onClick={handleAddComment} 
                                      disabled={!newComment.trim()}
                                      className="w-full bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white py-3 rounded-xl font-bold transition-all shadow-md flex items-center justify-center gap-2"
                                  >
                                      <Send className="w-4 h-4" /> Post Feedback
                                  </button>
                              </div>
                          </div>
                      </div>
                  </div>
              </div>
          </div>
      );
  }

  if (selectedTeacher) {
      const teacherPlans = getTeacherPlans(selectedTeacher.email);
      const teacherClasses = classrooms.filter(c => c.teacherId === selectedTeacher.email);
      return (
          <div className="min-h-screen bg-slate-50 p-6 lg:p-12 animate-fade-in">
              <button onClick={() => setSelectedTeacher(null)} className="mb-6 flex items-center gap-2 text-slate-500 hover:text-teal-600 font-bold">
                  <ArrowLeft className="w-5 h-5" /> Back to Faculty List
              </button>

              <div className="bg-white rounded-3xl p-8 shadow-xl border border-gray-100 mb-8 flex flex-col md:flex-row items-center gap-8">
                  <div className="w-24 h-24 bg-teal-600 rounded-full flex items-center justify-center text-white text-4xl font-black shadow-lg">
                      {selectedTeacher.name.charAt(0)}
                  </div>
                  <div className="text-center md:text-left flex-1">
                      <h1 className="text-3xl font-black text-slate-900 mb-1">{selectedTeacher.name}</h1>
                      <p className="text-teal-600 font-bold mb-4">{selectedTeacher.email}</p>
                      <div className="flex flex-wrap justify-center md:justify-start gap-3">
                          <span className="bg-slate-100 text-slate-600 px-4 py-1 rounded-full text-xs font-bold border border-slate-200">Phone: {selectedTeacher.phone}</span>
                          <span className="bg-indigo-100 text-indigo-700 px-4 py-1 rounded-full text-xs font-bold border border-indigo-200">Code: {selectedTeacher.teacherCode}</span>
                      </div>
                  </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                  <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-xl">
                      <h3 className="font-black text-slate-800 mb-6 flex items-center gap-2 text-xl">
                          <FileText className="w-6 h-6 text-teal-500" /> Lesson Plans
                      </h3>
                      <div className="space-y-4 max-h-[500px] overflow-y-auto pr-2">
                        {teacherPlans.length ? teacherPlans.map(p=>(
                            <div key={p.id} onClick={()=>setSelectedPlan(p)} className="p-4 rounded-2xl border border-gray-100 hover:border-teal-200 hover:bg-teal-50/30 transition-all cursor-pointer group flex justify-between items-center shadow-sm">
                                <div>
                                    <h4 className="font-bold text-slate-800 group-hover:text-teal-700">{p.topic}</h4>
                                    <p className="text-xs text-gray-400 mt-1">{p.subject} • {p.grade}</p>
                                </div>
                                <ChevronRight className="w-5 h-5 text-gray-300 group-hover:text-teal-500" />
                            </div>
                        )) : (
                            <div className="text-center py-20 text-gray-400 italic">This teacher hasn't generated any plans yet.</div>
                        )}
                      </div>
                  </div>
                  <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-xl">
                      <h3 className="font-black text-slate-800 mb-6 flex items-center gap-2 text-xl">
                          <Users className="w-6 h-6 text-indigo-500" /> Assigned Classes
                      </h3>
                      <div className="grid grid-cols-1 gap-4">
                        {teacherClasses.length ? teacherClasses.map(c=>(
                            <div key={c.id} className="p-5 rounded-2xl border border-gray-100 bg-slate-50 flex justify-between items-center shadow-sm">
                                <div className="flex items-center gap-4">
                                    <div className="bg-white p-3 rounded-xl text-indigo-600 shadow-sm"><SchoolIcon className="w-6 h-6" /></div>
                                    <div>
                                        <h4 className="font-bold text-slate-800">{c.grade} - {c.stream}</h4>
                                        <p className="text-xs text-gray-500 font-medium">Class ID: {c.id.substring(0,8)}</p>
                                    </div>
                                </div>
                                <div className="text-right">
                                    <p className="text-2xl font-black text-indigo-700">{c.students.length}</p>
                                    <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Enrolled</p>
                                </div>
                            </div>
                        )) : (
                            <div className="text-center py-20 text-gray-400 italic">No classes currently assigned to this teacher.</div>
                        )}
                      </div>
                  </div>
              </div>
          </div>
      );
  }

  return (
    <div className="min-h-screen bg-slate-50 font-sans pb-10">
        <div className="bg-indigo-900 text-white px-8 py-12 shadow-xl flex justify-between items-center overflow-hidden relative">
            <div className="relative z-10">
                <h1 className="text-4xl font-black uppercase tracking-tight mb-2">{profile.school}</h1>
                <p className="text-indigo-200 text-lg font-medium">Academic Management & Quality Control</p>
            </div>
            <SchoolIcon className="w-48 h-48 absolute -right-12 -bottom-12 text-white opacity-5 rotate-12" />
        </div>

        <div className="max-w-7xl mx-auto px-4 -mt-10 relative z-20">
            <div className="bg-white rounded-2xl shadow-2xl border border-gray-100 p-2 flex flex-wrap md:flex-nowrap gap-2">
                {[
                    { id: 'overview', icon: Home, label: 'Overview' },
                    { id: 'teachers', icon: Users, label: 'Faculty' },
                    { id: 'classes', icon: SchoolIcon, label: 'Classrooms' },
                    { id: 'students', icon: GraduationCap, label: 'Students' }
                ].map(t => (
                    <button 
                        key={t.id} 
                        onClick={() => setActiveTab(t.id as any)} 
                        className={`flex-1 flex items-center justify-center gap-2 py-4 px-6 rounded-xl font-bold text-sm transition-all ${activeTab === t.id ? 'bg-indigo-600 text-white shadow-lg scale-[1.02]' : 'text-slate-500 hover:bg-slate-50 hover:text-indigo-600'}`}
                    >
                        <t.icon className="w-4 h-4" /> {t.label}
                    </button>
                ))}
            </div>
        </div>

        <div className="max-w-7xl mx-auto px-4 mt-12">
            {activeTab === 'overview' && (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8 animate-fade-in-up">
                    <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-xl flex items-center justify-between transition-transform hover:-translate-y-1">
                        <div>
                            <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Active Teachers</p>
                            <h3 className="text-5xl font-black text-slate-800">{teachers.length}</h3>
                        </div>
                        <div className="bg-blue-50 p-6 rounded-3xl text-blue-600 shadow-inner"><Users className="w-10 h-10" /></div>
                    </div>
                    <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-xl flex items-center justify-between transition-transform hover:-translate-y-1">
                        <div>
                            <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Total Classes</p>
                            <h3 className="text-5xl font-black text-slate-800">{classrooms.length}</h3>
                        </div>
                        <div className="bg-teal-50 p-6 rounded-3xl text-teal-600 shadow-inner"><SchoolIcon className="w-10 h-10" /></div>
                    </div>
                    <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-xl flex items-center justify-between transition-transform hover:-translate-y-1">
                        <div>
                            <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Students Enrolled</p>
                            <h3 className="text-5xl font-black text-slate-800">{totalStudents}</h3>
                        </div>
                        <div className="bg-orange-50 p-6 rounded-3xl text-orange-600 shadow-inner"><GraduationCap className="w-10 h-10" /></div>
                    </div>
                </div>
            )}

            {activeTab === 'teachers' && (
                <div className="animate-fade-in">
                    <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
                        <div>
                            <h2 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Faculty Management</h2>
                            <p className="text-gray-500 text-sm">Monitor performance and manage accounts</p>
                        </div>
                        <div className="flex gap-3 w-full md:w-auto">
                            <button onClick={()=>setShowCreateTeacher(true)} className="flex-1 md:flex-none bg-teal-600 hover:bg-teal-700 text-white px-6 py-3 rounded-xl font-bold text-sm shadow-md transition-all flex items-center justify-center gap-2">
                                <Plus className="w-4 h-4" /> New Account
                            </button>
                            <button onClick={()=>setShowLinkTeacher(true)} className="flex-1 md:flex-none bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-3 rounded-xl font-bold text-sm shadow-md transition-all flex items-center justify-center gap-2">
                                <Link className="w-4 h-4" /> Link Existing
                            </button>
                        </div>
                    </div>
