const Dashboard: React.FC<{ profile: UserProfile; onUpdate: (profile: UserProfile) => void }> = ({ profile, onUpdate }) => {
  const [activeView, setActiveView] = useState<'overview' | 'classrooms' | 'profile' | 'inbox' | 'cat_gen'>('overview');
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [isCollapsed, setIsCollapsed] = useState(false);

  const [classrooms, setClassrooms] = useState<Classroom[]>([]);
  const [totalPlans, setTotalPlans] = useState(0);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [showNotifications, setShowNotifications] = useState(false);
  const [messages, setMessages] = useState<DirectMessage[]>([]);

  const [formData, setFormData] = useState<UserProfile>(profile);
  const [message, setMessage] = useState('');

  const [showAddClassModal, setShowAddClassModal] = useState(false);
  const [managedClassroom, setManagedClassroom] = useState<Classroom | null>(null);

  const [manageTab, setManageTab] = useState<'students' | 'performance' | 'forum' | 'resources'>('students');
  const [manageView, setManageView] = useState<'subjects' | 'assignments' | 'results'>('subjects');
  const [selectedSubjectForStats, setSelectedSubjectForStats] = useState<string>('');
  const [currentAssignmentResults, setCurrentAssignmentResults] = useState<StudentResult[]>([]);
  const [assignmentList, setAssignmentList] = useState<Assignment[]>([]);

  const [feedbackModal, setFeedbackModal] = useState<{resultId: string, name: string, currentFeedback: string} | null>(null);
  const [feedbackInput, setFeedbackInput] = useState('');

  const [dmModal, setDmModal] = useState<{studentName: string, studentCode: string} | null>(null);
  const [dmInput, setDmInput] = useState('');
  const [selectedThread, setSelectedThread] = useState<string | null>(null);
  const [replyText, setReplyText] = useState('');

  const [newClassGrade, setNewClassGrade] = useState<Grade>(Grade.GRADE_7);
  const [newClassStream, setNewClassStream] = useState('');
  const [newClassRoll, setNewClassRoll] = useState<number>(40);
  const [newStudentName, setNewStudentName] = useState('');

  const [catSubject, setCatSubject] = useState<Subject>(Subject.MATHEMATICS);
  const [catGrade, setCatGrade] = useState<Grade>(Grade.GRADE_7);
  const [selectedLessonsForCAT, setSelectedLessonsForCAT] = useState<LessonDefinition[]>([]);
  const [isGeneratingCAT, setIsGeneratingCAT] = useState(false);
  const [catTargetClass, setCatTargetClass] = useState('');

  useEffect(() => {
    loadData();
    const interval = setInterval(() => {
        setNotifications(getNotifications(profile.email));
        setMessages(getDirectMessages(profile.email));
    }, 10000);
    return () => clearInterval(interval);
  }, []);

  const loadData = () => {
    const cls = getClassrooms();
    setClassrooms(cls);
    const plans = getSavedPlans();
    setTotalPlans(plans.length);
    setNotifications(getNotifications(profile.email));
    setMessages(getDirectMessages(profile.email));

    if (managedClassroom) {
        const updated = cls.find(c => c.id === managedClassroom.id);
        if (updated) setManagedClassroom(updated);
        else setManagedClassroom(null);
    }
  };

  const handleCreateClassroom = (e: React.FormEvent) => {
    e.preventDefault();
    if (newClassStream && newClassRoll > 0) {
        createClassroom(newClassGrade, newClassStream, newClassRoll);
        loadData();
        setShowAddClassModal(false);
        setNewClassStream('');
    }
  };

  const handleDeleteClassroom = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm('Are you sure? All student data will be lost.')) {
        deleteClassroom(id);
        loadData();
    }
  };

  const handleAddStudent = () => {
      if (managedClassroom && newStudentName.trim()) {
          addSingleStudentToClassroom(managedClassroom.id, newStudentName);
          setNewStudentName('');
          loadData();
      }
  };

  const handleDeleteStudent = (studentCode: string) => {
      if (managedClassroom && confirm("Remove this student?")) {
          deleteStudentFromClassroom(managedClassroom.id, studentCode);
          loadData();
      }
  };

  const openClassroomManager = (cls: Classroom) => {
      setManagedClassroom(cls);
      setManageTab('students');
      setActiveView('classrooms');
  };

  const openDmModal = (s: Student) => {
      setDmModal({ studentName: s.name || 'Student', studentCode: s.code });
  };

  const sendDm = () => {
      if (!dmModal || !dmInput.trim()) return;
      const msg: DirectMessage = { id: crypto.randomUUID(), senderId: profile.email, senderName: profile.name, receiverId: dmModal.studentCode, content: dmInput, timestamp: new Date().toISOString(), read: false, isFromTeacher: true };
      sendDirectMessage(msg);
      setDmModal(null);
      setDmInput('');
      loadData();
  };

  const handleReplyToStudent = (studentId: string) => {
      if (!replyText.trim()) return;
      const msg: DirectMessage = { id: crypto.randomUUID(), senderId: profile.email, senderName: profile.name, receiverId: studentId, content: replyText, timestamp: new Date().toISOString(), read: false, isFromTeacher: true };
      sendDirectMessage(msg);
      setReplyText('');
      loadData();
  };

  const handleSelectThread = (studentId: string) => {
      setSelectedThread(studentId);
      markMessagesRead(studentId, profile.email);
      loadData();
  };

  const handleNotificationClick = (notif: AppNotification) => {
      markNotificationRead(notif.id);
      if (notif.type === 'message') setActiveView('inbox');
      loadData();
  };

  // Performance Tab Implementation
  const classPerformance = useMemo(() => {
      if (!managedClassroom) return { avg: 0, byStudent: [] };
      const results = getAllResultsGlobal();
      const classAssignments = getAssignmentsByClassId(managedClassroom.id);
      const studentData = managedClassroom.students.map(s => {
          const studentResults = results.filter(r => r.studentCode === s.code);
          const totalScore = studentResults.reduce((acc, curr) => acc + (curr.score / curr.total), 0);
          const avg = studentResults.length > 0 ? (totalScore / studentResults.length) * 100 : 0;
          return { name: s.name || 'Student', code: s.code, avg: avg.toFixed(1), attempts: studentResults.length };
      });
      return { byStudent: studentData };
  }, [managedClassroom]);

  const handleGenerateCAT = async () => {
      if (selectedLessonsForCAT.length === 0 || !catTargetClass) {
          alert("Please select lessons and a target classroom.");
          return;
      }
      setIsGeneratingCAT(true);
      try {
          const questions = await generateCAT(catSubject, catGrade, selectedLessonsForCAT, 20);
          const topic = `CAT: ${selectedLessonsForCAT.map(l => l.subStrand).slice(0,2).join(", ")}`;
          const assign: Assignment = { id: crypto.randomUUID(), classroomId: catTargetClass, subject: catSubject, topic: topic, questions: questions, createdAt: new Date().toISOString(), grade: catGrade };
          saveAssignment(assign);
          alert("CAT Generated and assigned successfully!");
          setSelectedLessonsForCAT([]);
          setActiveView('classrooms');
      } catch (err) {
          alert("CAT generation failed.");
      } finally {
          setIsGeneratingCAT(false);
      }
  };

  const unreadMessagesCount = messages.filter(m => !m.read && m.receiverId === profile.email).length;

  return (
    <div className="flex min-h-screen bg-slate-50 font-sans text-slate-800">
      {sidebarOpen && (<div className="fixed inset-0 bg-black/50 z-40 lg:hidden" onClick={() => setSidebarOpen(false)}/>)}
      <aside className={`fixed inset-y-0 left-0 z-50 bg-slate-900 text-slate-300 transition-all duration-300 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0 ${isCollapsed ? 'w-20' : 'w-64'} flex flex-col`}>
        <div className="flex items-center h-16 px-4 bg-slate-950 text-white font-bold text-xl border-b border-slate-800">
          {!isCollapsed ? (<div className="flex items-center"><BookOpen className="w-6 h-6 mr-2 text-teal-500" /><span>Admin</span></div>) : (<BookOpen className="w-8 h-8 text-teal-500" />)}
        </div>
        <nav className="flex-1 overflow-y-auto p-3 space-y-1">
          <button onClick={() => setActiveView('overview')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg ${activeView === 'overview' ? 'bg-teal-600 text-white' : 'hover:bg-slate-800'}`}>
            <Home className="w-5 h-5 mr-3" /> {!isCollapsed && "Dashboard"}
          </button>
          <button onClick={() => setActiveView('classrooms')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg ${activeView === 'classrooms' ? 'bg-teal-600 text-white' : 'hover:bg-slate-800'}`}>
            <Layers className="w-5 h-5 mr-3" /> {!isCollapsed && "Classrooms"}
          </button>
          <button onClick={() => setActiveView('cat_gen')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg ${activeView === 'cat_gen' ? 'bg-teal-600 text-white' : 'hover:bg-slate-800'}`}>
            <ListChecks className="w-5 h-5 mr-3" /> {!isCollapsed && "CAT Generator"}
          </button>
          <button onClick={() => setActiveView('inbox')} className={`flex items-center w-full px-4 py-3 text-sm font-medium rounded-lg ${activeView === 'inbox' ? 'bg-teal-600 text-white' : 'hover:bg-slate-800'}`}>
            <Mail className="w-5 h-5 mr-3" /> {!isCollapsed && "Inbox"} {unreadMessagesCount > 0 && <span className="ml-auto bg-red-500 text-white text-[10px] font-bold px-2 rounded-full">{unreadMessagesCount}</span>}
          </button>
        </nav>
      </aside>
      <div className={`flex-1 flex flex-col transition-all duration-300 ${isCollapsed ? 'lg:ml-20' : 'lg:ml-64'}`}>
        <header className="h-16 bg-white border-b flex items-center justify-between px-8 sticky top-0 z-40 shadow-sm">
          <h2 className="text-xl font-bold text-gray-800 capitalize">{activeView.replace('_', ' ')}</h2>
          <div className="flex items-center gap-4 relative">
             <button onClick={() => setShowNotifications(!showNotifications)} className="p-2 text-gray-400 relative"><Bell className="w-5 h-5" />{notifications.some(n=>!n.read) && <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full"></span>}</button>
             {showNotifications && (
                 <div className="absolute right-0 mt-2 w-80 bg-white rounded-xl shadow-xl border z-50 top-10">
                     <div className="bg-slate-50 p-3 border-b font-bold text-sm">Notifications</div>
                     <div className="max-h-80 overflow-y-auto">
                         {notifications.map(n => (<div key={n.id} onClick={() => handleNotificationClick(n)} className={`p-4 border-b hover:bg-slate-50 cursor-pointer ${!n.read ? 'bg-blue-50/30' : ''}`}><p className="text-sm font-bold">{n.title}</p><p className="text-xs text-gray-500">{n.message}</p></div>))}
                     </div>
                 </div>
             )}
             <div className="w-8 h-8 bg-slate-800 rounded-full flex items-center justify-center text-white text-xs font-bold">{profile.name.charAt(0)}</div>
          </div>
        </header>
        <main className="p-8 max-w-7xl mx-auto w-full">
          {activeView === 'overview' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <StatCard icon={FileText} label="Lesson Plans" value={totalPlans} color="bg-teal-500" />
                <StatCard icon={Users} label="Classrooms" value={classrooms.length} color="bg-blue-500" />
                <StatCard icon={CheckSquare} label="Pending Tasks" value={unreadMessagesCount} color="bg-purple-500" />
            </div>
          )}
          {activeView === 'classrooms' && (
            <div className="space-y-6">
                <div className="flex justify-between items-center"><h2 className="text-xl text-gray-600 font-light">My Classrooms</h2><button onClick={() => setShowAddClassModal(true)} className="bg-teal-600 text-white px-4 py-2 rounded text-sm font-bold flex items-center gap-2"><Plus className="w-4 h-4" /> Add Classroom</button></div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {classrooms.map(room => (
                        <div key={room.id} onClick={() => openClassroomManager(room)} className="bg-white rounded-xl border p-5 shadow-sm hover:shadow-md cursor-pointer transition-all">
                            <div className="flex justify-between items-start mb-4">
                                <div><h4 className="text-lg font-bold">{room.grade} - {room.stream}</h4><p className="text-xs text-gray-500">{room.students.length} Students</p></div>
                                <div className="flex gap-2">
                                    <button onClick={(e) => { e.stopPropagation(); openClassroomManager(room); }} className="p-2 bg-gray-100 rounded hover:bg-gray-200"><Eye className="w-4 h-4" /></button>
                                    <button onClick={(e) => handleDeleteClassroom(e, room.id)} className="p-2 bg-red-50 text-red-600 rounded hover:bg-red-100"><Trash2 className="w-4 h-4" /></button>
                                </div>
                            </div>
                            <div className="flex flex-wrap gap-2">{room.subjects.map(s => (<span key={s} className="bg-slate-100 px-2 py-1 rounded text-xs">{s}</span>))}</div>
                        </div>
                    ))}
                </div>
            </div>
          )}
          {activeView === 'cat_gen' && (
            <div className="bg-white rounded-xl border shadow-sm p-8">
                <div className="mb-8 border-b pb-6 flex justify-between items-center"><div><h2 className="text-2xl font-bold text-teal-800">CAT Generator</h2><p className="text-sm text-gray-500">Pick lessons to generate a cumulative quiz.</p></div><button onClick={handleGenerateCAT} disabled={isGeneratingCAT || selectedLessonsForCAT.length === 0} className="bg-teal-600 text-white px-8 py-3 rounded-lg font-bold hover:bg-teal-700 disabled:opacity-50 flex items-center gap-2">{isGeneratingCAT ? <Loader2 className="w-5 h-5 animate-spin" /> : <Sparkles className="w-5 h-5" />} Generate & Assign CAT</button></div>
                {/* ... existing CAT Generator UI ... */}
            </div>
          )}
          {activeView === 'inbox' && (
              <div className="h-[calc(100vh-12rem)] bg-white rounded-xl border flex overflow-hidden">
                  <div className="w-1/3 border-r overflow-y-auto">
                      <div className="p-4 border-b bg-gray-50 font-bold">Student Conversations</div>
                      {(Array.from(new Set(messages.filter(m => !m.isFromTeacher).map(m => m.senderId))) as string[]).map((sid: string) => {
                          const last = messages.filter(m=>m.senderId===sid || m.receiverId===sid).pop();
                          return (<div key={sid} onClick={()=>handleSelectThread(sid)} className={`p-4 border-b hover:bg-slate-50 cursor-pointer ${selectedThread===sid ? 'bg-teal-50' : ''}`}><p className="font-bold text-sm">{last?.senderName || sid}</p><p className="text-xs text-gray-500 truncate">{last?.content}</p></div>);
                      })}
                  </div>
                  <div className="flex-1 flex flex-col">
                      {selectedThread ? (<><div className="p-4 border-b font-bold">Chat with {selectedThread}</div><div className="flex-1 overflow-y-auto p-4 space-y-4">{messages.filter(m=>m.senderId===selectedThread || m.receiverId===selectedThread).map(m=>(<div key={m.id} className={`flex ${m.isFromTeacher ? 'justify-end' : 'justify-start'}`}><div className={`p-3 rounded-xl max-w-[70%] text-sm shadow-sm ${m.isFromTeacher ? 'bg-teal-600 text-white' : 'bg-slate-100'}`}><p>{m.content}</p><p className="text-[10px] mt-1 opacity-50">{new Date(m.timestamp).toLocaleTimeString()}</p></div></div>))}</div><form onSubmit={(e)=>{e.preventDefault(); handleReplyToStudent(selectedThread)}} className="p-4 border-t flex gap-2"><input type="text" className="flex-1 border rounded-lg px-4" value={replyText} onChange={e=>setReplyText(e.target.value)} placeholder="Type reply..." /><button className="bg-teal-600 text-white p-2 rounded-lg"><Send className="w-5 h-5" /></button></form></>) : (<div className="flex-1 flex items-center justify-center text-gray-400">Select a thread to start messaging</div>)}
                  </div>
              </div>
          )}
        </main>
      </div>

      {managedClassroom && (
          <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-4xl overflow-hidden h-[90vh] flex flex-col animate-fade-in-up">
                  <div className="bg-slate-900 px-6 py-4 flex justify-between items-center text-white shrink-0">
                      <div><h3 className="font-bold text-lg">{managedClassroom.grade} - {managedClassroom.stream}</h3><p className="text-slate-400 text-xs">Classroom Management Hub</p></div>
                      <button onClick={() => setManagedClassroom(null)}><X className="w-5 h-5" /></button>
                  </div>
                  <div className="flex border-b bg-gray-50 overflow-x-auto">
                      {[
                          { id: 'students', label: 'Student Roster', icon: Users },
                          { id: 'performance', label: 'Analytics', icon: BarChart2 },
                          { id: 'forum', label: 'Discussions', icon: MessageSquare },
                          { id: 'resources', label: 'Resources', icon: Book }
                      ].map(t => (<button key={t.id} onClick={() => setManageTab(t.id as any)} className={`flex-1 py-3 px-4 text-sm font-bold flex items-center justify-center gap-2 ${manageTab === t.id ? 'border-b-2 border-teal-600 text-teal-700 bg-white' : 'text-gray-500'}`}><t.icon className="w-4 h-4"/> {t.label}</button>))}
                  </div>
                  <div className="flex-1 overflow-y-auto bg-white">
                      {manageTab === 'students' && (
                          <div className="p-6">
                              <div className="mb-6 flex gap-2"><input type="text" className="flex-1 border rounded p-2 text-sm" value={newStudentName} onChange={e=>setNewStudentName(e.target.value)} placeholder="Full Name..." /><button onClick={handleAddStudent} className="bg-teal-600 text-white px-4 py-2 rounded text-sm font-bold flex items-center gap-1"><Plus className="w-4 h-4" /> Add Student</button></div>
                              <table className="w-full text-sm text-left">
                                  <thead className="bg-gray-50 font-bold uppercase text-xs"><tr><th className="px-6 py-3">Access Code</th><th className="px-6 py-3">Full Name</th><th className="px-6 py-3 text-right">Actions</th></tr></thead>
                                  <tbody className="divide-y">
                                      {managedClassroom.students.map(s => (<tr key={s.code} className="hover:bg-gray-50"><td className="px-6 py-3 font-mono text-teal-700 font-bold">{s.code}</td><td className="px-6 py-3 italic">{s.name || "Pending Registration"}</td><td className="px-6 py-3 text-right flex gap-2 justify-end"><button onClick={() => openDmModal(s)} className="p-1.5 bg-blue-50 text-blue-600 rounded" title="Send DM"><MessageCircle className="w-4 h-4" /></button><button onClick={() => handleDeleteStudent(s.code)} className="p-1.5 bg-red-50 text-red-600 rounded" title="Remove Student"><Trash2 className="w-4 h-4" /></button></td></tr>))}
                                  </tbody>
                              </table>
                          </div>
                      )}
                      {manageTab === 'performance' && (
                          <div className="p-6 space-y-8">
                              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                  <div className="bg-slate-50 p-6 rounded-xl border border-slate-200">
                                      <h4 className="font-bold text-slate-800 mb-4 flex items-center gap-2"><BarChart2 className="w-5 h-5 text-teal-600" /> Class Ranking</h4>
                                      <div className="space-y-3">
                                          {classPerformance.byStudent.sort((a,b) => parseFloat(b.avg) - parseFloat(a.avg)).map((s, i) => (
                                              <div key={s.code} className="flex items-center justify-between p-2 bg-white rounded border">
                                                  <div className="flex items-center gap-2"><span className="text-xs text-gray-400 font-bold">{i+1}</span><p className="text-sm font-medium">{s.name}</p></div>
                                                  <span className="text-sm font-black text-teal-600">{s.avg}%</span>
                                              </div>
                                          ))}
                                      </div>
                                  </div>
                                  <div className="bg-slate-50 p-6 rounded-xl border border-slate-200">
                                      <h4 className="font-bold text-slate-800 mb-4 flex items-center gap-2"><Clock className="w-5 h-5 text-blue-600" /> Engagement Stats</h4>
                                      <div className="space-y-4">
                                          <div className="bg-white p-4 rounded-lg border flex justify-between items-center"><span className="text-sm text-gray-600">Total Quiz Attempts</span><span className="text-lg font-black text-blue-600">{classPerformance.byStudent.reduce((acc,curr) => acc + curr.attempts, 0)}</span></div>
                                          <div className="bg-white p-4 rounded-lg border flex justify-between items-center"><span className="text-sm text-gray-600">Active Students</span><span className="text-lg font-black text-green-600">{classPerformance.byStudent.filter(s => s.attempts > 0).length}</span></div>
                                      </div>
                                  </div>
                              </div>
                          </div>
                      )}
                  </div>
              </div>
          </div>
      )}

      {dmModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4">
              <div className="bg-white rounded-xl shadow-xl w-full max-w-md p-6"><h3 className="font-bold mb-4">Direct Message to {dmModal.studentName}</h3><textarea rows={4} className="w-full border rounded-lg p-3 text-sm mb-4" placeholder="Type your message to the student..." value={dmInput} onChange={e=>setDmInput(e.target.value)} /><div className="flex justify-end gap-2"><button onClick={() => setDmModal(null)} className="px-4 py-2 text-gray-500">Cancel</button><button onClick={sendDm} className="px-4 py-2 bg-blue-600 text-white rounded font-bold hover:bg-blue-700">Send Message</button></div></div>
          </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { UserProfile, Classroom, Grade, Subject, Student, LessonPlanData, LessonPlanComment } from '../types';
import { 
    getClassrooms, createClassroom, getSchoolTeachers, linkTeacherToSchool, createTeacherAccount,
    addStudentsToClassroom, updateStudentName, getTeacherPlans, deleteStudentFromClassroom, addCommentToPlan,
    deleteClassroom
} from '../services/storageService';
import LessonPlanDisplay from './LessonPlanDisplay';
import { 
    Users, BookOpen, UserPlus, Plus, GraduationCap, School as SchoolIcon, 
    ChevronRight, Copy, Check, Search, Mail, Phone, Lock, Eye, Trash2, Link, ArrowLeft, MessageSquare, Send, X, FileText, Home
} from 'lucide-react';

interface Props {
  profile: UserProfile;
}

const SchoolDashboard: React.FC<Props> = ({ profile }) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'teachers' | 'classes' | 'students'>('overview');
  const [teachers, setTeachers] = useState<UserProfile[]>([]);
  const [classrooms, setClassrooms] = useState<Classroom[]>([]);

  const [showLinkTeacher, setShowLinkTeacher] = useState(false);
  const [showCreateTeacher, setShowCreateTeacher] = useState(false);
  const [teacherCode, setTeacherCode] = useState('');
  const [newTeacherForm, setNewTeacherForm] = useState({ name: '', email: '', phone: '', password: '' });

  const [showAddClass, setShowAddClass] = useState(false);
  const [newClassData, setNewClassData] = useState({ grade: Grade.GRADE_7, stream: '', teacherId: '', roll: 40 });

  const [selectedClassId, setSelectedClassId] = useState<string | null>(null);
  const [bulkStudentCount, setBulkStudentCount] = useState(5);

  const [selectedTeacher, setSelectedTeacher] = useState<UserProfile | null>(null);
  const [selectedPlan, setSelectedPlan] = useState<LessonPlanData | null>(null);
  const [newComment, setNewComment] = useState('');

  useEffect(() => { loadData(); }, [profile.schoolId]);

  const loadData = () => {
      if (profile.schoolId) {
          setTeachers(getSchoolTeachers(profile.schoolId));
          setClassrooms(getClassrooms());
      }
  };

  const handleLinkTeacher = (e: React.FormEvent) => {
      e.preventDefault();
      try {
          if (profile.schoolId) {
            linkTeacherToSchool(profile.schoolId, teacherCode.toUpperCase());
            setShowLinkTeacher(false); 
            setTeacherCode('');
            loadData(); 
            alert("Teacher linked successfully!");
          }
      } catch (e: any) { alert(e.message); }
  };

  const handleCreateTeacher = (e: React.FormEvent) => {
      e.preventDefault();
      if (profile.schoolId) {
          createTeacherAccount(profile.schoolId, newTeacherForm.name, newTeacherForm.email, newTeacherForm.phone, newTeacherForm.password);
          setShowCreateTeacher(false); 
          setNewTeacherForm({ name: '', email: '', phone: '', password: '' });
          loadData(); 
          alert("Teacher account created!");
      }
  };

  const handleCreateClass = (e: React.FormEvent) => {
      e.preventDefault();
      createClassroom(newClassData.grade, newClassData.stream, newClassData.roll, newClassData.teacherId);
      setShowAddClass(false); 
      setNewClassData({ grade: Grade.GRADE_7, stream: '', teacherId: '', roll: 40 });
      loadData();
  };

  const handleDeleteClass = (e: React.MouseEvent, id: string) => {
      e.stopPropagation();
      if (confirm("Delete this class? All associated student records and assignments will be removed.")) {
          deleteClassroom(id);
          loadData();
      }
  };

  const handleAddBulkStudents = (classId: string) => {
      if (bulkStudentCount > 0) {
          addStudentsToClassroom(classId, bulkStudentCount);
          loadData(); 
          setBulkStudentCount(5);
      }
  };

  const handleDeleteStudent = (classId: string, studentCode: string) => {
      if (confirm("Remove this student from the class?")) {
          deleteStudentFromClassroom(classId, studentCode);
          loadData();
      }
  };

  const handleAddComment = () => {
      if (!selectedPlan || !selectedPlan.id || !newComment.trim()) return;
      const comment: LessonPlanComment = { 
          id: crypto.randomUUID(), 
          authorName: profile.name, 
          date: new Date().toISOString(), 
          content: newComment 
      };
      addCommentToPlan(selectedPlan.id, comment);
      setNewComment('');
      setSelectedPlan({ ...selectedPlan, adminComments: [...(selectedPlan.adminComments || []), comment] });
  };

  const totalStudents = classrooms.reduce((acc, c) => acc + c.students.length, 0);

  if (selectedPlan) {
      return (
          <div className="min-h-screen bg-gray-100 flex flex-col">
              <div className="bg-white border-b px-6 py-4 sticky top-0 z-40 flex items-center justify-between shadow-sm">
                  <button onClick={() => setSelectedPlan(null)} className="flex items-center text-slate-600 font-bold hover:text-teal-600 transition-colors">
                      <ArrowLeft className="w-5 h-5 mr-2" /> Back to Dashboard
                  </button>
                  <h2 className="font-bold text-slate-800 hidden md:block">{selectedPlan.topic}</h2>
                  <div className="w-24"></div>
              </div>
              <div className="flex-1 overflow-y-auto">
                  <div className="flex flex-col lg:flex-row max-w-7xl mx-auto gap-8 p-6">
                      <div className="flex-1 bg-white rounded-2xl shadow-lg border border-gray-200 overflow-hidden">
                          <LessonPlanDisplay plan={selectedPlan} onBack={() => setSelectedPlan(null)} />
                      </div>
                      <div className="w-full lg:w-96 shrink-0 space-y-6">
                          <div className="bg-white p-6 rounded-2xl shadow-lg border border-gray-200">
                              <h3 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                                  <MessageSquare className="w-5 h-5 text-teal-600" /> Admin Feedback
                              </h3>
                              <div className="space-y-4 max-h-[500px] overflow-y-auto mb-6 pr-2">
                                  {selectedPlan.adminComments?.length ? selectedPlan.adminComments.map(c => (
                                      <div key={c.id} className="bg-slate-50 p-4 rounded-xl text-sm border border-slate-100 shadow-sm">
                                          <div className="flex justify-between items-center mb-2">
                                              <span className="font-bold text-teal-700">{c.authorName}</span>
                                              <span className="text-[10px] text-gray-400">{new Date(c.date).toLocaleDateString()}</span>
                                          </div>
                                          <p className="text-slate-600 leading-relaxed">{c.content}</p>
                                      </div>
                                  )) : (
                                      <div className="text-center py-10 text-gray-400 italic">No feedback comments yet.</div>
                                  )}
                              </div>
                              <div className="relative">
                                  <textarea 
                                      className="w-full p-4 border border-gray-200 rounded-xl mb-3 text-sm focus:ring-2 focus:ring-teal-500 focus:border-transparent outline-none transition-all" 
                                      rows={4} 
                                      value={newComment} 
                                      onChange={e=>setNewComment(e.target.value)} 
                                      placeholder="Write your review..." 
                                  />
                                  <button onClick={handleAddComment} disabled={!newComment.trim()} className="w-full bg-teal-600 hover:bg-teal-700 disabled:opacity-50 text-white py-3 rounded-xl font-bold transition-all shadow-md flex items-center justify-center gap-2">
                                      <Send className="w-4 h-4" /> Post Feedback
                                  </button>
                              </div>
                          </div>
                      </div>
                  </div>
              </div>
          </div>
      );
  }

  return (
    <div className="min-h-screen bg-slate-50 font-sans pb-10">
        <div className="bg-indigo-900 text-white px-8 py-12 shadow-xl flex justify-between items-center overflow-hidden relative">
            <div className="relative z-10">
                <h1 className="text-4xl font-black uppercase tracking-tight mb-2">{profile.school}</h1>
                <p className="text-indigo-200 text-lg font-medium">Academic Management Console</p>
            </div>
            <SchoolIcon className="w-48 h-48 absolute -right-12 -bottom-12 text-white opacity-5 rotate-12" />
        </div>

        <div className="max-w-7xl mx-auto px-4 -mt-10 relative z-20">
            <div className="bg-white rounded-2xl shadow-2xl border border-gray-100 p-2 flex flex-wrap md:flex-nowrap gap-2">
                {[
                    { id: 'overview', icon: Home, label: 'Overview' },
                    { id: 'teachers', icon: Users, label: 'Faculty' },
                    { id: 'classes', icon: SchoolIcon, label: 'Classrooms' },
                    { id: 'students', icon: GraduationCap, label: 'Students' }
                ].map(t => (
                    <button key={t.id} onClick={() => setActiveTab(t.id as any)} className={`flex-1 flex items-center justify-center gap-2 py-4 px-6 rounded-xl font-bold text-sm transition-all ${activeTab === t.id ? 'bg-indigo-600 text-white shadow-lg scale-[1.02]' : 'text-slate-500 hover:bg-slate-50 hover:text-indigo-600'}`}>
                        <t.icon className="w-4 h-4" /> {t.label}
                    </button>
                ))}
            </div>
        </div>

        <div className="max-w-7xl mx-auto px-4 mt-12">
            {activeTab === 'overview' && (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8 animate-fade-in-up">
                    <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-xl flex items-center justify-between"><div><p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Teachers</p><h3 className="text-5xl font-black text-slate-800">{teachers.length}</h3></div><div className="bg-blue-50 p-6 rounded-3xl text-blue-600 shadow-inner"><Users className="w-10 h-10" /></div></div>
                    <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-xl flex items-center justify-between"><div><p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Classes</p><h3 className="text-5xl font-black text-slate-800">{classrooms.length}</h3></div><div className="bg-teal-50 p-6 rounded-3xl text-teal-600 shadow-inner"><SchoolIcon className="w-10 h-10" /></div></div>
                    <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-xl flex items-center justify-between"><div><p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Total Students</p><h3 className="text-5xl font-black text-slate-800">{totalStudents}</h3></div><div className="bg-orange-50 p-6 rounded-3xl text-orange-600 shadow-inner"><GraduationCap className="w-10 h-10" /></div></div>
                </div>
            )}

            {activeTab === 'classes' && (
                <div className="animate-fade-in">
                    <div className="flex justify-between items-center mb-8"><div><h2 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Classrooms</h2><p className="text-gray-500 text-sm">Organize and assign teachers</p></div><button onClick={()=>setShowAddClass(true)} className="bg-indigo-600 hover:bg-indigo-700 text-white px-6 py-3 rounded-xl font-bold text-sm shadow-md flex items-center gap-2"><Plus className="w-4 h-4" /> Create Class</button></div>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                        {classrooms.map(c=>(
                            <div key={c.id} className="bg-white rounded-3xl border border-gray-100 p-8 shadow-xl hover:shadow-2xl transition-all group">
                                <div className="flex justify-between items-start mb-6">
                                    <div className="bg-indigo-50 p-4 rounded-2xl text-indigo-600 group-hover:bg-indigo-600 group-hover:text-white transition-colors"><SchoolIcon className="w-8 h-8" /></div>
                                    <button onClick={(e)=>handleDeleteClass(e, c.id)} className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"><Trash2 className="w-5 h-5" /></button>
                                </div>
                                <h3 className="text-2xl font-black text-slate-800 mb-1">{c.grade} - {c.stream}</h3>
