export type GenerationStatus = 'idle' | 'loading' | 'success' | 'error';

import React, { useState, useEffect, useMemo } from 'react';
import { Grade, Term, LessonDefinition, LessonPlanData, Subject, UserProfile, GenerationStatus } from '../types';
import { SCHEMES_OF_WORK } from '../data/maths';
import { PRETECH_SCHEMES } from '../data/pretech';
import { CREATIVE_ARTS_SCHEMES } from '../data/creative_arts';
import { CRE_SCHEMES } from '../data/cre';
import { INTEGRATED_SCIENCE_SCHEMES } from '../data/integrated_science';
import { SCIENCE_TECHNOLOGY_SCHEMES } from '../data/science_technology';
import { SOCIAL_STUDIES_SCHEMES } from '../data/social_studies';
import { AGRICULTURE_NUTRITION_SCHEMES } from '../data/agriculture_nutrition';
import { ENGLISH_SCHEMES } from '../data/english';
import { KISWAHILI_SCHEMES } from '../data/kiswahili';
import { generateLessonPlan, generateSimplifiedNotes, generatePracticeQuestions } from '../services/geminiService';
import { savePlan } from '../services/storageService';
import { Loader2, BookOpen, AlertCircle, Upload, Paperclip, X, Plus, Trash2, CheckCircle2, Zap } from 'lucide-react';

interface BulkRow {
  id: string;
  subject: Subject;
  grade: Grade;
  strand: string;
  subStrand: string;
  lesson: LessonDefinition | null;
  status: GenerationStatus;
}

interface Props {
  userProfile?: UserProfile | null;
  onPlanGenerated: (data: LessonPlanData) => void;
}

const LessonGenerator: React.FC<Props> = ({ userProfile, onPlanGenerated }) => {
  const [isBulkMode, setIsBulkMode] = useState(false);
  const [formData, setFormData] = useState({
    teacherName: userProfile?.name || '',
    schoolName: userProfile?.school || '',
    date: new Date().toISOString().split('T')[0],
    grade: Grade.GRADE_7,
    term: Term.TERM_1,
    roll: 40,
    subject: Subject.MATHEMATICS,
    customContext: '',
    images: [] as string[]
  });

  const [bulkRows, setBulkRows] = useState<BulkRow[]>([
    { id: crypto.randomUUID(), subject: Subject.MATHEMATICS, grade: Grade.GRADE_7, strand: '', subStrand: '', lesson: null, status: 'idle' }
  ]);

  // Sync profile
  useEffect(() => {
    if (userProfile) {
      setFormData(prev => ({
        ...prev,
        teacherName: userProfile.name,
        schoolName: userProfile.school
      }));
    }
  }, [userProfile]);

  const [selectedStrand, setSelectedStrand] = useState<string>('');
  const [selectedSubStrand, setSelectedSubStrand] = useState<string>('');
  const [selectedLesson, setSelectedLesson] = useState<LessonDefinition | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const cleanTopic = (topic: string) => topic.replace(/^Lesson \d+:\s*/i, '');

  const getSchemes = (subject: Subject, grade: Grade) => {
    switch (subject) {
      case Subject.MATHEMATICS: return SCHEMES_OF_WORK[grade] || [];
      case Subject.PRETECHNICAL_STUDIES: return PRETECH_SCHEMES[grade] || [];
      case Subject.CREATIVE_ARTS: return CREATIVE_ARTS_SCHEMES[grade] || [];
      case Subject.CHRISTIAN_RELIGIOUS_EDUCATION: return CRE_SCHEMES[grade] || [];
      case Subject.INTEGRATED_SCIENCE: return INTEGRATED_SCIENCE_SCHEMES[grade] || [];
      case Subject.SCIENCE_AND_TECHNOLOGY: return SCIENCE_TECHNOLOGY_SCHEMES[grade] || [];
      case Subject.SOCIAL_STUDIES: return SOCIAL_STUDIES_SCHEMES[grade] || [];
      case Subject.AGRICULTURE_AND_NUTRITION: return AGRICULTURE_NUTRITION_SCHEMES[grade] || [];
      case Subject.ENGLISH: return ENGLISH_SCHEMES[grade] || [];
      case Subject.KISWAHILI: return KISWAHILI_SCHEMES[grade] || [];
      default: return [];
    }
  };

  const gradeData = useMemo(() => getSchemes(formData.subject, formData.grade), [formData.grade, formData.subject]);
  const strands = useMemo(() => Array.from(new Set(gradeData.map(l => l.strand))), [gradeData]);
  const subStrands = useMemo(() => Array.from(new Set(gradeData.filter(l => l.strand === selectedStrand).map(l => l.subStrand))), [gradeData, selectedStrand]);
  const lessons = useMemo(() => gradeData.filter(l => l.strand === selectedStrand && l.subStrand === selectedSubStrand), [gradeData, selectedStrand, selectedSubStrand]);

  useEffect(() => { setSelectedStrand(''); setSelectedSubStrand(''); setSelectedLesson(null); }, [formData.grade, formData.subject]);
  useEffect(() => { setSelectedSubStrand(''); setSelectedLesson(null); }, [selectedStrand]);
  useEffect(() => { setSelectedLesson(null); }, [selectedSubStrand]);

  const addBulkRow = () => {
    if (bulkRows.length < 6) {
      setBulkRows([...bulkRows, { id: crypto.randomUUID(), subject: Subject.MATHEMATICS, grade: Grade.GRADE_7, strand: '', subStrand: '', lesson: null, status: 'idle' }]);
    }
  };

  const removeBulkRow = (id: string) => {
    if (bulkRows.length > 1) {
      setBulkRows(bulkRows.filter(r => r.id !== id));
    }
  };

  const updateBulkRow = (id: string, updates: Partial<BulkRow>) => {
    setBulkRows(prev => prev.map(r => r.id === id ? { ...r, ...updates } : r));
  };

  const handleBulkGenerate = async () => {
    const validRows = bulkRows.filter(r => r.lesson);
    if (validRows.length === 0) {
      setError("Please select at least one valid lesson for bulk generation.");
      return;
    }
    setLoading(true);
    setError(null);

    const generateTask = async (row: BulkRow) => {
      if (!row.lesson) return;
      updateBulkRow(row.id, { status: 'loading' });
      try {
        const rowFormData = { ...formData, subject: row.subject, grade: row.grade };
        const cleanLessonDef = { ...row.lesson, topic: cleanTopic(row.lesson.topic) };

        const plan = await generateLessonPlan(rowFormData, cleanLessonDef);
        const [notes, questions] = await Promise.all([
          generateSimplifiedNotes(plan, 500),
          generatePracticeQuestions(plan)
        ]);

        const completePlan: LessonPlanData = {
          ...plan,
          learnerNotes: notes,
          structuredQuestions: questions,
          topic: cleanTopic(plan.topic),
          id: crypto.randomUUID(),
          createdAt: new Date().toISOString(),
          userId: userProfile?.email
        };

        savePlan(completePlan);
        updateBulkRow(row.id, { status: 'success' });
      } catch (err) {
        console.error(err);
        updateBulkRow(row.id, { status: 'error' });
      }
    };

    await Promise.allSettled(validRows.map(row => generateTask(row)));
    setLoading(false);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files) {
      if (formData.images.length + files.length > 5) {
        alert("You can upload a maximum of 5 images.");
        return;
      }
      Array.from(files).forEach((file: File) => {
        const reader = new FileReader();
        reader.onloadend = () => {
          if (typeof reader.result === 'string') {
            setFormData(prev => ({ ...prev, images: [...prev.images, reader.result as string] }));
          }
        };
        reader.readAsDataURL(file);
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isBulkMode) {
      handleBulkGenerate();
      return;
    }

    if (!selectedLesson) {
      setError("Please select a specific lesson.");
      return;
    }
    setError(null);
    setLoading(true);

    try {
      const cleanLessonDef = { ...selectedLesson, topic: cleanTopic(selectedLesson.topic) };
      const plan = await generateLessonPlan(formData, cleanLessonDef);
      const [notes, questions] = await Promise.all([
        generateSimplifiedNotes(plan, 500),
        generatePracticeQuestions(plan)
      ]);
      const completePlan = {
        ...plan,
        learnerNotes: notes,
        structuredQuestions: questions,
        topic: cleanTopic(plan.topic),
        id: crypto.randomUUID(),
        createdAt: new Date().toISOString()
      };
      if (userProfile) savePlan(completePlan);
      onPlanGenerated(completePlan);
    } catch (err: any) {
      setError(err.message || "An error occurred generating the plan.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-md border border-gray-200 overflow-hidden no-print">
      <div className="bg-gray-50 px-6 py-4 border-b border-gray-200 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <BookOpen className="text-teal-600 w-5 h-5" />
          <h2 className="text-lg font-semibold text-gray-800">Lesson Plan Generator</h2>
        </div>
        {userProfile && (
          <div className="flex items-center gap-3">
            <span className="text-xs font-bold text-gray-500 uppercase">Mode:</span>
            <div className="flex bg-gray-200 p-1 rounded-lg">
              <button 
                onClick={() => setIsBulkMode(false)}
                className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${!isBulkMode ? 'bg-white text-teal-700 shadow-sm' : 'text-gray-500'}`}
              >
                Single
              </button>
              <button 
                onClick={() => setIsBulkMode(true)}
                className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${isBulkMode ? 'bg-teal-600 text-white shadow-sm' : 'text-gray-500'}`}
              >
                Bulk Produce
              </button>
            </div>
          </div>
        )}
      </div>

      <form onSubmit={handleSubmit} className="p-6 md:p-8 space-y-8">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-6">
          <div className="space-y-4">
            <div className="flex flex-col md:flex-row md:items-center gap-2">
              <label className="text-sm font-medium text-gray-600 w-24">Teacher</label>
              <input required type="text" value={formData.teacherName} onChange={e => setFormData({ ...formData, teacherName: e.target.value })} className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border bg-gray-50" placeholder="Enter Name" />
            </div>
            <div className="flex flex-col md:flex-row md:items-center gap-2">
              <label className="text-sm font-medium text-gray-600 w-24">School</label>
              <input required type="text" value={formData.schoolName} onChange={e => setFormData({ ...formData, schoolName: e.target.value })} readOnly={!!userProfile?.schoolId} className={`flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border ${!!userProfile?.schoolId ? 'bg-gray-100 text-gray-500 cursor-not-allowed' : 'bg-gray-50'}`} placeholder="Enter School" />
            </div>
          </div>
          <div className="space-y-4">
            <div className="flex flex-col md:flex-row md:items-center gap-2">
              <label className="text-sm font-medium text-gray-600 w-24">Date</label>
              <input type="date" value={formData.date} onChange={e => setFormData({ ...formData, date: e.target.value })} className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border" />
            </div>
            {!isBulkMode && (
              <div className="flex flex-col md:flex-row md:items-center gap-2">
                <label className="text-sm font-medium text-gray-600 w-24">Subject</label>
                <select value={formData.subject} onChange={e => setFormData({ ...formData, subject: e.target.value as Subject })} className="flex-1 rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border">
                  {Object.values(Subject).map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
            )}
          </div>
        </div>

        <div className="h-px bg-gray-200 w-full"></div>

        {!isBulkMode ? (
          <>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
              <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Grade</label>
                <select value={formData.grade} onChange={e => setFormData({ ...formData, grade: e.target.value as Grade })} className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border">
                  {Object.values(Grade).map(g => <option key={g} value={g}>{g}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Term</label>
                <select value={formData.term} onChange={e => setFormData({ ...formData, term: e.target.value as Term })} className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border">
                  {Object.values(Term).map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Roll</label>
                <input type="number" value={formData.roll} onChange={e => setFormData({ ...formData, roll: parseInt(e.target.value) })} className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2 px-3 border" />
              </div>
              <div className="space-y-1">
                <label className="block text-xs font-medium text-gray-500 uppercase">Time</label>
                <div className="w-full py-2 px-3 bg-gray-100 rounded-md text-gray-700 border border-gray-200">40 Minutes</div>
              </div>
            </div>

            <div className="bg-teal-50 p-6 rounded-lg border border-teal-100 space-y-6">
              <h3 className="text-teal-800 font-medium border-b border-teal-200 pb-2">Curriculum Content Selector</h3>
              {gradeData.length === 0 ? (
                <div className="text-center text-gray-500 py-4">No lesson data available</div>
              ) : (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                      <label className="block text-sm font-medium text-teal-800 mb-2">Strand</label>
                      <select value={selectedStrand} onChange={e => setSelectedStrand(e.target.value)} className="w-full rounded-md border-teal-200 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 px-3 border bg-white">
                        <option value="">-- Choose Strand --</option>
                        {strands.map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-teal-800 mb-2">Sub-strand</label>
                      <select value={selectedSubStrand} onChange={e => setSelectedSubStrand(e.target.value)} className="w-full rounded-md border-teal-200 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 px-3 border bg-white" disabled={!selectedStrand}>
                        <option value="">-- Choose Sub-strand --</option>
                        {subStrands.map(ss => <option key={ss} value={ss}>{ss}</option>)}
                      </select>
                    </div>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-teal-800 mb-2">Lesson</label>
                    <select value={selectedLesson ? JSON.stringify(selectedLesson) : ""} onChange={e => e.target.value && setSelectedLesson(JSON.parse(e.target.value))} className="w-full rounded-md border-teal-200 shadow-sm focus:border-teal-500 focus:ring-teal-500 py-2.5 px-3 border bg-white" disabled={!selectedSubStrand}>
                      <option value="">-- Choose Lesson --</option>
                      {lessons.map((l, idx) => <option key={idx} value={JSON.stringify(l)}>{cleanTopic(l.topic)}</option>)}
                    </select>
                  </div>
                </>
              )}
            </div>
          </>
        ) : (
          <div className="space-y-6">
            <div className="flex justify-between items-center">
              <h3 className="text-lg font-bold text-gray-800 uppercase tracking-tight">Bulk Production List</h3>
              <button type="button" onClick={addBulkRow} disabled={bulkRows.length >= 6} className="text-xs font-black bg-slate-800 text-white px-4 py-2 rounded-full flex items-center gap-1 hover:bg-slate-700 disabled:opacity-50">
                <Plus className="w-3 h-3" /> Add Lesson
              </button>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm text-left border-collapse">
                <thead className="bg-slate-50 border-b border-gray-200">
                  <tr>
                    <th className="px-4 py-3 font-bold text-gray-500 uppercase text-[10px]">Subject</th>
                    <th className="px-4 py-3 font-bold text-gray-500 uppercase text-[10px]">Class</th>
                    <th className="px-4 py-3 font-bold text-gray-500 uppercase text-[10px]">Strand</th>
                    <th className="px-4 py-3 font-bold text-gray-500 uppercase text-[10px]">Sub-strand</th>
                    <th className="px-4 py-3 font-bold text-gray-500 uppercase text-[10px]">Lesson</th>
                    <th className="px-4 py-3 text-center"></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {bulkRows.map((row) => {
                    const rowData = getSchemes(row.subject, row.grade);
                    const rowStrands = Array.from(new Set(rowData.map(l => l.strand)));
                    const rowSubStrands = Array.from(new Set(rowData.filter(l => l.strand === row.strand).map(l => l.subStrand)));
                    const rowLessons = rowData.filter(l => l.strand === row.strand && l.subStrand === row.subStrand);

                    return (
                      <tr key={row.id} className="hover:bg-gray-50/50">
                        <td className="p-2">
                          <select value={row.subject} onChange={e => updateBulkRow(row.id, { subject: e.target.value as Subject, strand: '', subStrand: '', lesson: null })} className="w-full border-gray-200 rounded text-xs p-1.5 focus:ring-teal-500">
                            {Object.values(Subject).map(s => <option key={s} value={s}>{s}</option>)}
                          </select>
                        </td>
                        <td className="p-2">
                          <select value={row.grade} onChange={e => updateBulkRow(row.id, { grade: e.target.value as Grade, strand: '', subStrand: '', lesson: null })} className="w-full border-gray-200 rounded text-xs p-1.5 focus:ring-teal-500">
                            {Object.values(Grade).map(g => <option key={g} value={g}>{g}</option>)}
                          </select>
                        </td>
                        <td className="p-2">
                          <select value={row.strand} onChange={e => updateBulkRow(row.id, { strand: e.target.value, subStrand: '', lesson: null })} className="w-full border-gray-200 rounded text-xs p-1.5 focus:ring-teal-500">
                            <option value="">--</option>
                            {rowStrands.map(s => <option key={s} value={s}>{s}</option>)}
                          </select>
                        </td>
                        <td className="p-2">
                          <select value={row.subStrand} onChange={e => updateBulkRow(row.id, { subStrand: e.target.value, lesson: null })} className="w-full border-gray-200 rounded text-xs p-1.5 focus:ring-teal-500" disabled={!row.strand}>
                            <option value="">--</option>
                            {rowSubStrands.map(ss => <option key={ss} value={ss}>{ss}</option>)}
                          </select>
                        </td>
                        <td className="p-2">
                          <select value={row.lesson ? JSON.stringify(row.lesson) : ""} onChange={e => updateBulkRow(row.id, { lesson: e.target.value ? JSON.parse(e.target.value) : null })} className="w-full border-gray-200 rounded text-xs p-1.5 focus:ring-teal-500" disabled={!row.subStrand}>
                            <option value="">--</option>
                            {rowLessons.map((l, idx) => <option key={idx} value={JSON.stringify(l)}>{cleanTopic(l.topic)}</option>)}
                          </select>
                        </td>
                        <td className="p-2 text-right">
                          <div className="flex items-center justify-end gap-2">
                            {row.status === 'loading' && <Loader2 className="w-4 h-4 text-teal-600 animate-spin" />}
                            {row.status === 'success' && <CheckCircle2 className="w-4 h-4 text-green-500" />}
                            {row.status === 'error' && <AlertCircle className="w-4 h-4 text-red-500" />}
                            <button type="button" onClick={() => removeBulkRow(row.id)} className="p-1.5 text-gray-300 hover:text-red-500"><Trash2 className="w-4 h-4" /></button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )}

        <div className="border border-gray-200 rounded-lg p-6 bg-gray-50">
          <h3 className="text-gray-800 font-medium mb-4 flex items-center gap-2"><Paperclip className="w-4 h-4 text-gray-500" /> Context & Resources (Optional)</h3>
          <div className="space-y-4">
            <div>
              <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Common Context for Batch</label>
              <textarea className="w-full rounded-md border-gray-300 shadow-sm focus:border-teal-500 focus:ring-teal-500 p-3 text-sm" rows={2} placeholder="Any specific requirements for these plans..." value={formData.customContext} onChange={(e) => setFormData({ ...formData, customContext: e.target.value })}></textarea>
            </div>
            {!isBulkMode && (
              <div>
                <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Upload Photos (Max 5)</label>
                <div className="flex items-center gap-4">
                  <label className="cursor-pointer bg-white border border-gray-300 hover:bg-gray-50 px-4 py-2 rounded-md shadow-sm text-sm font-medium text-gray-700 flex items-center gap-2 transition-colors">
                    <Upload className="w-4 h-4" /> Select Images
                    <input type="file" accept="image/*" multiple className="hidden" onChange={handleImageUpload} disabled={formData.images.length >= 5} />
                  </label>
                  <span className="text-xs text-gray-500">{formData.images.length} / 5 uploaded</span>
                </div>
              </div>
            )}
          </div>
        </div>

        {error && (
          <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded flex items-center gap-3">
            <AlertCircle className="text-red-500" />
            <p className="text-red-700 text-sm font-medium">{error}</p>
          </div>
        )}

        <div className="flex gap-4 pt-2">
          <button type="button" className="px-6 py-3 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50" onClick={() => { setBulkRows([{ id: crypto.randomUUID(), subject: Subject.MATHEMATICS, grade: Grade.GRADE_7, strand: '', subStrand: '', lesson: null, status: 'idle' }]); setFormData({ ...formData, customContext: '', images: [] }); }}>
            Reset Form
          </button>
          <button type="submit" disabled={loading} className="flex-1 flex justify-center items-center gap-2 px-6 py-3 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-teal-600 hover:bg-teal-700 disabled:opacity-50 transition-all">
            {loading ? (
              <>
                <Loader2 className="animate-spin h-5 w-5" />
                {isBulkMode ? "Generating Batch..." : "Generating Plan..."}
              </>
            ) : (
              <>
                {isBulkMode ? <Zap className="w-4 h-4" /> : <BookOpen className="w-4 h-4" />}
                {isBulkMode ? "Generate All Lesson Plans" : "Generate Lesson Plan"}
              </>
            )}
          </button>
        </div>
      </form>
    </div>
  );
};

export default LessonGenerator;

import React, { useState, useEffect, useMemo } from 'react';
import { Grade, Term, LessonDefinition, LessonPlanData, Subject, UserProfile, GenerationStatus } from '../types';
import { SCHEMES_OF_WORK } from '../data/maths';
import { PRETECH_SCHEMES } from '../data/pretech';
import { CREATIVE_ARTS_SCHEMES } from '../data/creative_arts';
import { CRE_SCHEMES } from '../data/cre';
import { INTEGRATED_SCIENCE_SCHEMES } from '../data/integrated_science';
import { SCIENCE_TECHNOLOGY_SCHEMES } from '../data/science_technology';
import { SOCIAL_STUDIES_SCHEMES } from '../data/social_studies';
import { AGRICULTURE_NUTRITION_SCHEMES } from '../data/agriculture_nutrition';
import { ENGLISH_SCHEMES } from '../data/english';
import { KISWAHILI_SCHEMES } from '../data/kiswahili';
import { generateLessonPlan, generateSimplifiedNotes, generatePracticeQuestions } from '../services/geminiService';
import { savePlan } from '../services/storageService';
import { Loader2, BookOpen, AlertCircle, Upload, Paperclip, X, Plus, Trash2, CheckCircle2, Zap, Users as UsersIcon } from 'lucide-react';

interface BulkRow {
  id: string;
  subject: Subject;
  grade: Grade;
  strand: string;
  subStrand: string;
  lesson: LessonDefinition | null;
  status: GenerationStatus;
  roll: number;
}

interface Props {
  userProfile?: UserProfile | null;
  onPlanGenerated: (data: LessonPlanData) => void;
}

const LessonGenerator: React.FC<Props> = ({ userProfile, onPlanGenerated }) => {
  const [isBulkMode, setIsBulkMode] = useState(false);
  const [formData, setFormData] = useState({
    teacherName: userProfile?.name || '',
    schoolName: userProfile?.school || '',
    date: new Date().toISOString().split('T')[0],
    grade: Grade.GRADE_7,
    term: Term.TERM_1,
    roll: 40,
    subject: Subject.MATHEMATICS,
    customContext: '',
    images: [] as string[]
  });

  const [bulkRows, setBulkRows] = useState<BulkRow[]>([
    { id: crypto.randomUUID(), subject: Subject.MATHEMATICS, grade: Grade.GRADE_7, strand: '', subStrand: '', lesson: null, status: 'idle', roll: 40 }
  ]);

  // Sync profile
  useEffect(() => {
    if (userProfile) {
      setFormData(prev => ({
        ...prev,
        teacherName: userProfile.name,
        schoolName: userProfile.school
      }));
    }
  }, [userProfile]);

  const [selectedStrand, setSelectedStrand] = useState<string>('');
  const [selectedSubStrand, setSelectedSubStrand] = useState<string>('');
  const [selectedLesson, setSelectedLesson] = useState<LessonDefinition | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const cleanTopic = (topic: string) => topic.replace(/^Lesson \d+:\s*/i, '');

  const getSchemes = (subject: Subject, grade: Grade) => {
    switch (subject) {
      case Subject.MATHEMATICS: return SCHEMES_OF_WORK[grade] || [];
      case Subject.PRETECHNICAL_STUDIES: return PRETECH_SCHEMES[grade] || [];
      case Subject.CREATIVE_ARTS: return CREATIVE_ARTS_SCHEMES[grade] || [];
      case Subject.CHRISTIAN_RELIGIOUS_EDUCATION: return CRE_SCHEMES[grade] || [];
      case Subject.INTEGRATED_SCIENCE: return INTEGRATED_SCIENCE_SCHEMES[grade] || [];
      case Subject.SCIENCE_AND_TECHNOLOGY: return SCIENCE_TECHNOLOGY_SCHEMES[grade] || [];
      case Subject.SOCIAL_STUDIES: return SOCIAL_STUDIES_SCHEMES[grade] || [];
      case Subject.AGRICULTURE_AND_NUTRITION: return AGRICULTURE_NUTRITION_SCHEMES[grade] || [];
      case Subject.ENGLISH: return ENGLISH_SCHEMES[grade] || [];
      case Subject.KISWAHILI: return KISWAHILI_SCHEMES[grade] || [];
      default: return [];
    }
  };

  const gradeData = useMemo(() => getSchemes(formData.subject, formData.grade), [formData.grade, formData.subject]);
  const strands = useMemo(() => Array.from(new Set(gradeData.map(l => l.strand))), [gradeData]);
  const subStrands = useMemo(() => Array.from(new Set(gradeData.filter(l => l.strand === selectedStrand).map(l => l.subStrand))), [gradeData, selectedStrand]);
  const lessons = useMemo(() => gradeData.filter(l => l.strand === selectedStrand && l.subStrand === selectedSubStrand), [gradeData, selectedStrand, selectedSubStrand]);

  useEffect(() => { setSelectedStrand(''); setSelectedSubStrand(''); setSelectedLesson(null); }, [formData.grade, formData.subject]);
  useEffect(() => { setSelectedSubStrand(''); setSelectedLesson(null); }, [selectedStrand]);
  useEffect(() => { setSelectedLesson(null); }, [selectedSubStrand]);

  const addBulkRow = () => {
    if (bulkRows.length < 6) {
      setBulkRows([...bulkRows, { id: crypto.randomUUID(), subject: Subject.MATHEMATICS, grade: Grade.GRADE_7, strand: '', subStrand: '', lesson: null, status: 'idle', roll: formData.roll }]);
    }
  };

  const removeBulkRow = (id: string) => {
    if (bulkRows.length > 1) {
      setBulkRows(bulkRows.filter(r => r.id !== id));
    }
  };

  const updateBulkRow = (id: string, updates: Partial<BulkRow>) => {
    setBulkRows(prev => prev.map(r => r.id === id ? { ...r, ...updates } : r));
  };

  const handleBulkGenerate = async () => {
    const validRows = bulkRows.filter(r => r.lesson);
    if (validRows.length === 0) {
      setError("Please select at least one valid lesson for bulk generation.");
      return;
    }
    setLoading(true);
    setError(null);

    const generateTask = async (row: BulkRow) => {
      if (!row.lesson) return;
      updateBulkRow(row.id, { status: 'loading' });
      try {
        const rowFormData = { ...formData, subject: row.subject, grade: row.grade, roll: row.roll };
        const cleanLessonDef = { ...row.lesson, topic: cleanTopic(row.lesson.topic) };

        const plan = await generateLessonPlan(rowFormData, cleanLessonDef);
        const [notes, questions] = await Promise.all([
          generateSimplifiedNotes(plan, 500),
          generatePracticeQuestions(plan)
        ]);

        const completePlan: LessonPlanData = {
          ...plan,
          learnerNotes: notes,
          structuredQuestions: questions,
          topic: cleanTopic(plan.topic),
          id: crypto.randomUUID(),
          createdAt: new Date().toISOString(),
          userId: userProfile?.email
        };

        savePlan(completePlan);
        updateBulkRow(row.id, { status: 'success' });
      } catch (err) {
        console.error(err);
        updateBulkRow(row.id, { status: 'error' });
      }
    };

    await Promise.allSettled(validRows.map(row => generateTask(row)));
    setLoading(false);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files) {
      if (formData.images.length + files.length > 5) {
        alert("You can upload a maximum of 5 images.");
        return;
      }
      Array.from(files).forEach((file: File) => {
        const reader = new FileReader();
        reader.onloadend = () => {
          if (typeof reader.result === 'string') {
            setFormData(prev => ({ ...prev, images: [...prev.images, reader.result as string] }));
          }
        };
        reader.readAsDataURL(file);
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isBulkMode) {
      handleBulkGenerate();
      return;
    }

    if (!selectedLesson) {
      setError("Please select a specific lesson.");
      return;
    }
    setError(null);
    setLoading(true);

    try {
      const cleanLessonDef = { ...selectedLesson, topic: cleanTopic(selectedLesson.topic) };
      const plan = await generateLessonPlan(formData, cleanLessonDef);
      const [notes, questions] = await Promise.all([
        generateSimplifiedNotes(plan, 500),
        generatePracticeQuestions(plan)
      ]);
      const completePlan = {
        ...plan,
        learnerNotes: notes,
        structuredQuestions: questions,
        topic: cleanTopic(plan.topic),
        id: crypto.randomUUID(),
        createdAt: new Date().toISOString()
      };
      if (userProfile) savePlan(completePlan);
      onPlanGenerated(completePlan);
    } catch (err: any) {
      setError(err.message || "An error occurred generating the plan.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-md border border-gray-200 overflow-hidden no-print">
      <div className="bg-gray-50 px-6 py-4 border-b border-gray-200 flex items-center justify-between">
        <div className="flex items-center gap-2">
