export const uploadUserFile = async (file: File): Promise<UserFile> => {
    const user = auth.currentUser;
    if (!user) throw new Error("Authentication required");

    const fileId = crypto.randomUUID();
    const filePath = `user_uploads/${user.uid}/${file.name}`;
    const storageRef = ref(storage, filePath);

    // Upload to Storage
    await uploadBytes(storageRef, file);
    const downloadUrl = await getDownloadURL(storageRef);

    const fileMeta: UserFile = {
        id: fileId,
        name: file.name,
        url: downloadUrl,
        path: filePath,
        size: file.size,
        type: file.type,
        createdAt: new Date().toISOString()
    };

    // Save metadata to Firestore: users/{uid}/files/{fileId}
    const metaRef = doc(db, "users", user.uid, "files", fileId);
    await setDoc(metaRef, fileMeta);

    return fileMeta;
};

export const deleteUserFile = async (file: UserFile): Promise<void> => {
    const user = auth.currentUser;
    if (!user) throw new Error("Authentication required");

    // Delete from Storage
    const storageRef = ref(storage, file.path);
    try {
        await deleteObject(storageRef);
    } catch (err) {
        console.warn("Storage object might already be deleted or inaccessible:", err);
    }

    // Delete metadata from Firestore
    const metaRef = doc(db, "users", user.uid, "files", file.id);
    await deleteDoc(metaRef);
};

export const getUserFiles = async (): Promise<UserFile[]> => {
    const user = auth.currentUser;
    if (!user) return [];

    try {
        const filesRef = collection(db, "users", user.uid, "files");
        const q = query(filesRef, orderBy("createdAt", "desc"));
        const querySnapshot = await getDocs(q);
        return querySnapshot.docs.map(doc => doc.data() as UserFile);
    } catch (err) {
        console.error("Error fetching files:", err);
        return [];
    }
};

// --- Firestore User Sync ---

export const syncUserProfileToFirestore = async (user: UserProfile): Promise<void> => {
    if (!user.email) return;
    try {
        const userRef = doc(db, "users", user.email.toLowerCase());
        await setDoc(userRef, {
            ...user,
            lastSynced: new Date().toISOString()
        }, { merge: true });
    } catch (error) {
        console.error("Error syncing user to Firestore:", error);
    }
};

export const fetchUserProfileFromFirestore = async (email: string): Promise<UserProfile | null> => {
    try {
        const userRef = doc(db, "users", email.toLowerCase());
        const docSnap = await getDoc(userRef);
        if (docSnap.exists()) {
            const data = docSnap.data() as UserProfile;
            saveUserMetadata(data); // Sync back to local
            return data;
        }
    } catch (error) {
        console.error("Error fetching user from Firestore:", error);
    }
    return null;
};

