                                <button className="bg-teal-600 text-white p-3 rounded-full hover:bg-teal-700 transition-colors shadow-md"><Send className="w-5 h-5" /></button>
                            </form>
                        </>
                      ) : (
                        <div className="flex-1 flex flex-col items-center justify-center text-gray-400 bg-slate-50/30">
                            <Mail className="w-16 h-16 opacity-10 mb-4" />
                            <p className="font-bold uppercase tracking-widest text-xs">Select a student thread to start</p>
                        </div>
                      )}
                  </div>
              </div>
          )}
        </main>
      </div>

      {/* Upload Modal */}
      {showUploadModal && (
          <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
              <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md overflow-hidden animate-fade-in-up">
                  <div className="bg-slate-900 px-8 py-6 text-white flex justify-between items-center">
                      <h3 className="font-black text-xl uppercase tracking-tight">Upload Resource</h3>
                      <button onClick={() => setShowUploadModal(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X className="w-6 h-6"/></button>
                  </div>
                  <form onSubmit={handleFileUpload} className="p-8 space-y-6">
                      <div className="border-2 border-dashed border-slate-200 rounded-2xl p-10 flex flex-col items-center justify-center bg-slate-50 hover:bg-white transition-colors cursor-pointer relative">
                          <input 
                            type="file" 
                            required 
                            onChange={e => setFileToUpload(e.target.files?.[0] || null)}
