    if (classrooms.some(c => c.id === demoClassId)) return;

    const demoClass: Classroom = {
        id: demoClassId,
        userId: "demo@mwalimu.com",
        grade: "Grade 7",
        stream: "Virtual Demo",
        subjects: ["Mathematics"],
        students: [{ index: 1, code: "DEMO12", name: "Guest Student" }],
        sharedNotes: [{
            id: "note-1",
            title: "Welcome to MwalimuHub",
            content: "Welcome to your student portal! Here you can find your assignments, shared notes, and digital library. Try taking the sample quiz below.",
            dateShared: new Date().toISOString(),
            subject: "General"
        }],
        forumPosts: [],
        textbooks: []
    };

    const demoAssignment: Assignment = {
        id: "assign-1",
        classroomId: demoClassId,
        subject: "Mathematics",
        topic: "Demo Quiz: Introduction to Numbers",
        createdAt: new Date().toISOString(),
        grade: "Grade 7",
        questions: [
            { id: 1, type: 'mcq', question: "What is the place value of 7 in 7,432?", options: ["Units", "Tens", "Hundreds", "Thousands"], correctAnswer: "Thousands" },
            { id: 2, type: 'mcq', question: "Which of these is a prime number?", options: ["4", "9", "11", "15"], correctAnswer: "11" }
        ]
    };

    classrooms.push(demoClass);
    localStorage.setItem(CLASSROOMS_STORAGE_KEY, JSON.stringify(classrooms));
