    const newNotif: AppNotification = { id: crypto.randomUUID(), userId, type, title, message, read: false, timestamp: new Date().toISOString(), linkTo };
    all.push(newNotif);
    localStorage.setItem(NOTIFICATIONS_STORAGE_KEY, JSON.stringify(all));
