                          <select 
                            value={newClassGrade} 
                            onChange={e => setNewClassGrade(e.target.value as Grade)} 
                            className="w-full bg-slate-50 border border-slate-200 rounded-xl p-4 text-sm font-bold focus:ring-2 focus:ring-teal-500 outline-none"
                          >
