                          </select>
                      </div>
                      <div>
                          <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2">Stream / Class Name</label>
                          <input 
                            type="text" 
                            required 
                            placeholder="e.g. West, Alpha, Blue" 
