                      <button type="submit" className="w-full bg-teal-600 hover:bg-teal-700 text-white py-5 rounded-2xl font-black uppercase tracking-widest shadow-lg transition-all active:scale-95">
                          Create Class & Generate Codes
                      </button>
                  </form>
