          setClassrooms(getClassrooms());
      }
  };

  const handleLinkTeacher = (e: React.FormEvent) => {
      e.preventDefault();
      try {
          if (profile.schoolId) {
            linkTeacherToSchool(profile.schoolId, teacherCode.toUpperCase());
